def _photo_sentinel(m):
    """🔬 2026-08-10 diagnostika: BIRINCHI ro'yxatdagi handler — har
    kelgan rasmni dispatch boshidayoq qayd etadi (False qaytarib
    ushlamaydi, oqim keyingi handlerlarga o'tadi). Agar rasm kelib shu
    log chiqmasa — update botga umuman yetib kelmayapti (Telegram/
    tarmoq), kod ichida yo'qolmayapti."""
    try:
        print(f"SENTINEL PHOTO: uid={m.from_user.id} chat={m.chat.id} "
              f"msg_id={m.message_id}", flush=True)
    except Exception:
        pass
    return False


@bot.message_handler(content_types=['photo'], func=_photo_sentinel)
def _photo_sentinel_handler(message):
    pass  # hech qachon ishlamaydi (func doim False)


