# Modul darajasidagi thread'lar darhol emas, fayl to'liq yuklangach
# ishga tushadi (o'shanda tenant sxemasi va registri tayyor bo'ladi).
_BOOT_THREADS = []


def _boot_thread(fn, name=None, module=None, every=None):
    _BOOT_THREADS.append((fn, name or getattr(fn, '__name__', '?'),
                          module, every))



def _raw_update_listener(messages):
    """🔬 Dispatchdan ham OLDIN: telebot qabul qilgan har bir xabar
    xom holda loglanadi — content_type bilan. SENTINEL'dan farqi:
    bu filtrlar zanjiriga umuman bog'liq emas."""
    for m in messages:
        try:
            print(f"RAW UPDATE: ct={m.content_type} uid={m.from_user.id if m.from_user else '?'} "
                  f"msg_id={m.message_id}", flush=True)
        except Exception as e:
            print(f"RAW UPDATE ERR: {str(e)[:80]}", flush=True)


bot.set_update_listener(_raw_update_listener)

