# Helpers
def now_dt(): return datetime.now(UZT)
def now_str(): return now_dt().strftime("%Y-%m-%d %H:%M:%S")
def today_str(): return now_dt().strftime("%Y-%m-%d")

# --- Bito API helperlari ---
def _bito_emp_name(it):
    """Javobdan xodim/mas'ul shaxs nomini xavfsiz oladi (turli endpoint formatlariga moslashtirilgan)."""
    if not it: return "—"
    resp = it.get("responsible")
    if isinstance(resp, dict) and resp.get("full_name"):
        return resp["full_name"]
    return it.get("employee_name") or it.get("full_name") or "—"

def bito_sales_by_employee(date_from_iso, date_to_iso):
    """Bito'dan berilgan sana oralig'i uchun MAS'UL SHAXS bo'yicha savdoni oladi.
    dashboard/top/responsible + from_date/to_date → aniq sana filtri ishlaydi."""
    if not CFG.BITO_API_KEY:
        print("BITO ERR: CFG.BITO_API_KEY o'rnatilmagan", flush=True)
        return None
    url = BITO_BASE_URL + "reports/dashboard/top/responsible"
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    body = {"from_date": date_from_iso, "to_date": date_to_iso,
            "sort_by": "gross_sales", "sort_order": "desc"}
    try:
        r = requests.post(url, json=body, headers=headers, timeout=20)
        r.raise_for_status()
        j = r.json()
        data = j.get("data", j)
        if isinstance(data, dict):
            items = data.get("data", data.get("list", []))
        else:
            items = data
        # responsible.full_name → employee_name ga ko'chirish
        result = []
        for it in (items or []):
            resp = it.get("responsible", {}) or {}
            name = resp.get("full_name") or it.get("employee_name") or "—"
            it["employee_name"] = name
            result.append(it)
        return result
    except Exception as e:
        print("BITO ERR:", str(e)[:200], flush=True)
        return None

def bito_period_utc(date_str=None):
    """Mahalliy kun (00:00 - kechagi 23:59:59.999, UZT) chegaralarini UTC ISO formatga o'tkazadi."""
    if not date_str:
        date_str = today_str()
    d = datetime.strptime(date_str, "%Y-%m-%d").replace(tzinfo=UZT)
    start = d
    end = d + timedelta(days=1) - timedelta(milliseconds=1)
    fmt = "%Y-%m-%dT%H:%M:%S.%f"
    return start.astimezone(timezone.utc).strftime(fmt)[:-3]+"Z", end.astimezone(timezone.utc).strftime(fmt)[:-3]+"Z"

def h(text):
    """HTML uchun xavfsiz: &, <, > belgilarini escaping qiladi."""
    return str(text).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")

def fmt_bito_employee_report(items, title):
    if items is None:
        return f"⚠️ <b>{h(title)}</b>\n\nBito bilan bog'lanishda xatolik yuz berdi."
    if not items:
        return f"📊 <b>{h(title)}</b>\n\nHali savdo qayd etilmagan."
    text = f"📊 <b>{h(title)}</b>\n\n"
    total_gross = 0
    for it in items:
        name = _bito_emp_name(it)
        gross = it.get("gross_sales", 0) or 0
        receipts = it.get("receipts", 0) or 0
        total_gross += gross
        text += f"👤 <b>{h(name)}</b>\n   💰 {h(fmt_money(gross))} | 🧾 {receipts} chek\n"
    text += f"\n💵 <b>Jami:</b> {h(fmt_money(total_gross))}"
    return text

def send_bito_employee_report(period_label, date_from_iso, date_to_iso):
    items = bito_sales_by_employee(date_from_iso, date_to_iso)
    text = fmt_bito_employee_report(items, f"Savdo hisoboti — {period_label}")
    for (aid,) in qall("SELECT tg_id FROM users WHERE role IN ('boss','manager')"):
        try:
            bot.send_message(aid, text, parse_mode="HTML")
        except Exception as e:
            print("BITO SEND ERR:", str(e)[:150], flush=True)

def bito_sale_thread():
    TIMES = ["12:00", "18:00", "22:00"]
    sent_today = set()
    last_date = today_str()
    while True:
        try:
            if not BITO_BONUS_ENABLED:
                time.sleep(30)
                continue
            cur_date = today_str()
            if cur_date != last_date:
                sent_today = set()
                last_date = cur_date
            ct = now_dt().strftime("%H:%M")
            if ct in TIMES and ct not in sent_today:
                sent_today.add(ct)
                df, dt_ = bito_period_utc(cur_date)
                send_bito_employee_report(f"{cur_date} ({ct} holatida)", df, dt_)
        except Exception as e:
            print("BITO THREAD ERR:", str(e)[:150], flush=True)
        time.sleep(30)

