BITO_NAME_CACHE = TDict(template={"v": []})

def bito_range_utc(date_from_str, date_to_str):
    """Ikki mahalliy sana (UZT) oralig'ini — kunning boshidan ikkinchi kunning oxirigacha — UTC ISO ga o'tkazadi."""
    d1 = datetime.strptime(date_from_str, "%Y-%m-%d").replace(tzinfo=UZT)
    d2 = datetime.strptime(date_to_str, "%Y-%m-%d").replace(tzinfo=UZT) + timedelta(days=1) - timedelta(milliseconds=1)
    fmt = "%Y-%m-%dT%H:%M:%S.%f"
    return d1.astimezone(timezone.utc).strftime(fmt)[:-3]+"Z", d2.astimezone(timezone.utc).strftime(fmt)[:-3]+"Z"

def get_bito_bonus_rate():
    try: return float(get_setting("bito_bonus_rate", "0.005"))
    except: return 0.005
def get_stale_bonus_rate():
    """Turib qolgan mahsulotlarni sotgani uchun QO'SHIMCHA bonus foizi (asosiy bonusdan tashqari)."""
    try: return float(get_setting("stale_bonus_rate", "0.02"))
    except: return 0.02

def get_bito_map():
    """tg_id -> bito_name lug'atini qaytaradi."""
    return {r[0]: r[1] for r in qall("SELECT tg_id,bito_name FROM bito_employee_map")}

def get_bito_sales_dict(date_from_iso, date_to_iso):
    items = bito_sales_by_employee(date_from_iso, date_to_iso)
    if items is None: return None
    return {_bito_emp_name(it): it for it in items}

def compute_auto_sales_data():
    """Bito'dan TO'G'RIDAN-TO'G'RI (qo'lda kiritilmasdan) bugungi va oylik savdoni oladi:
    - bugungi jami + xodimlar bo'yicha reyting (eng ko'p sotgan birinchi)
    - oylik jami + reja bajarilish foizi
    Qaytaradi: dict yoki None (Bito bilan bog'lanmasa)."""
    try:
        df_today, dt_today = bito_period_utc(today_str())
        today_items = bito_sales_by_employee(df_today, dt_today)
        if today_items is None:
            return None
        today_total = sum((it.get("gross_sales", 0) or 0) for it in today_items)
        leaderboard = sorted(today_items, key=lambda x: -(x.get("gross_sales", 0) or 0))

        month_start = now_dt().strftime("%Y-%m-01")
        df_month, dt_month = bito_range_utc(month_start, today_str())
        month_items = bito_sales_by_employee(df_month, dt_month) or []
        month_total = sum((it.get("gross_sales", 0) or 0) for it in month_items)
        month_plan = get_month_plan()

        return {
            "today_total": today_total,
            "leaderboard": [{"name": _bito_emp_name(it), "amount": it.get("gross_sales", 0) or 0,
                              "receipts": it.get("receipts", 0) or 0} for it in leaderboard],
            "month_total": month_total,
            "month_plan": float(month_plan) if month_plan else None,
            "checked_at": now_dt().strftime("%d.%m.%Y %H:%M"),
        }
    except Exception as e:
        print("AUTO SALES ERR:", str(e)[:150], flush=True)
        return None

DASH_SALES_CACHE = TDict(template={"ts": 0, "data": None})
DASH_SALES_TTL = 120  # 2 daqiqa — tez-tez o'zgaradi, lekin sahifa tezligi uchun baribir keshlanadi

def get_auto_sales_data_cached(force=False):
    now_ts = time.time()
    if not force and DASH_SALES_CACHE["data"] is not None and (now_ts - DASH_SALES_CACHE["ts"]) < DASH_SALES_TTL:
        return DASH_SALES_CACHE["data"]
    data = compute_auto_sales_data()
    if data is not None:
        DASH_SALES_CACHE["ts"] = now_ts
        DASH_SALES_CACHE["data"] = data
    return data or DASH_SALES_CACHE["data"]

def get_bito_employee_names(days_back=365):
    """✅ TUZATILGAN: Bito'dagi barcha mas'ul shaxslar nomini qaytaradi (from_date/to_date bilan).
    Ikkita manbadan birlashtiradi:
    1) reports/dashboard/top/responsible — savdo qilgan xodimlar (tarixiy)
    2) employee/get-paging — HAQIQIY xodimlar bazasi (savdo qilmagan yangi xodimlar ham shu yerda bo'ladi)
    """
    names = set()
    try:
        headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}

        # Sana oralig'ini hisoblash
        today = datetime.now(UZT)
        date_from = (today - timedelta(days=days_back)).replace(hour=0, minute=0, second=0, microsecond=0)
        date_to = today.replace(hour=23, minute=59, second=59, microsecond=999999)

        # UTC ga konversiya
        fmt = "%Y-%m-%dT%H:%M:%S.%f"
        from_iso = date_from.astimezone(timezone.utc).strftime(fmt)[:-3] + "Z"
        to_iso = date_to.astimezone(timezone.utc).strftime(fmt)[:-3] + "Z"

        # 1) Savdo qilgan xodimlar (eski, ishlaydigan usul)
        r = requests.post(BITO_BASE_URL + "reports/dashboard/top/responsible",
                          json={"from_date": from_iso, "to_date": to_iso},
                          headers=headers, timeout=15)
        r.raise_for_status()
        j = r.json()
        data = j.get("data", j)
        items = (data.get("data", data.get("list", [])) if isinstance(data, dict) else data) or []
        for it in items:
            resp = it.get("responsible", {}) or {}
            name = resp.get("full_name") or it.get("employee_name") or "—"
            if name != "—":
                names.add(name)
    except Exception as e:
        print("BITO ERR (get_names/responsible):", str(e)[:150], flush=True)

    try:
        # 2) Haqiqiy xodimlar bazasi — savdo qilmagan YANGI xodimlar ham shu yerda ko'rinadi
        headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
        r2 = requests.post(BITO_BASE_URL + "employee/get-paging",
                           json={"page": 1, "limit": 200}, headers=headers, timeout=15)
        if r2.status_code == 200:
            j2 = r2.json(); d2 = j2.get("data", {})
            emp_items = d2.get("data", []) if isinstance(d2, dict) else (d2 or [])
            for it in emp_items:
                if isinstance(it, dict):
                    name = it.get("full_name") or it.get("name")
                    if name:
                        names.add(name)
        else:
            print(f"BITO ERR (get_names/employee): HTTP {r2.status_code}", flush=True)
    except Exception as e:
        print("BITO ERR (get_names/employee):", str(e)[:150], flush=True)

    return sorted(names)

def fmt_employee_bonus_report(name, item, period_label, rate):
    gross = (item.get("gross_sales", 0) if item else 0) or 0
    receipts = (item.get("receipts", 0) if item else 0) or 0
    bonus = round(gross * rate)
    return (f"📊 <b>Savdo hisoboti — {h(period_label)}</b>\n\n"
            f"💰 Savdo: {h(fmt_money(gross))}\n"
            f"🧾 Cheklar: {receipts}\n"
            f"🎁 Bonus ({rate*100:.2f}%): <b>{h(fmt_money(bonus))}</b>")

def bito_employee_bonus_thread():
    """Har bir bog'langan xodimga shaxsiy savdo+bonus hisobotini kuniga yuboradi.
    Asosiy vaqt boshliq tomonidan sozlanadi (⚙️ Sozlamalar → ⏰ Xodim hisobot vaqti),
    standart: 18:00. Kun yakuni (23:59) har doim qo'shimcha ravishda yuboriladi."""
    sent_today = set()
    last_date = today_str()
    while True:
        try:
            if not BITO_BONUS_ENABLED:
                time.sleep(30)
                continue
            cur_date = today_str()
            if cur_date != last_date:
                sent_today = set()
                last_date = cur_date
            main_times_raw = get_setting("emp_report_time", "18:00")
            main_times = [t.strip() for t in main_times_raw.split(",") if t.strip()]
            TIMES = sorted(set(main_times + ["23:59"]))
            ct = now_dt().strftime("%H:%M")
            if ct in TIMES and ct not in sent_today:
                sent_today.add(ct)
                bmap = get_bito_map()
                if bmap:
                    df, dt_ = bito_period_utc(cur_date)
                    sales_dict = get_bito_sales_dict(df, dt_)
                    rate = get_bito_bonus_rate()
                    label = f"{cur_date} ({'kun yakuni' if ct=='23:59' else ct+' holatida'})"
                    for tg_id, bname in bmap.items():
                        item = sales_dict.get(bname) if sales_dict is not None else None
                        text = fmt_employee_bonus_report(bname, item, label, rate)
                        try:
                            bot.send_message(tg_id, text, parse_mode="HTML")
                        except Exception as e:
                            # ⚠️ "bot was blocked" / "chat not found" — xodim botni
                            # bloklagan yoki hech qachon ochmagan. Bu doimiy holat,
                            # har siklda logga yozish shovqin bo'ladi. Bir marta
                            # yozamiz-u, keyin jim o'tamiz.
                            _m = str(e)
                            _perm = ("blocked by the user" in _m
                                     or "chat not found" in _m
                                     or "user is deactivated" in _m)
                            if not _perm:
                                print("BITO EMP SEND ERR:", _m[:150], flush=True)
                            elif tg_id not in _BLOCKED_LOGGED:
                                _BLOCKED_LOGGED.add(tg_id)
                                print(f"BITO EMP: {tg_id} botni bloklagan yoki ochmagan "
                                      f"— boshqa eslatilmaydi", flush=True)
        except Exception as e:
            print("BITO EMP THREAD ERR:", str(e)[:150], flush=True)
        time.sleep(30)
