def bito_supplier_credit():
    """💰 Firmalarga qarzimiz — Bito'dan (jonli tekshirilgan endpoint).

    Qaytaradi: [{"id","name","amount"}, ...] — kamayish tartibida.
    ⚠️ Bito FAQAT summani beradi, qaytarish MUDDATINI saqlamaydi —
    muddat debt_due jadvalidan qo'shiladi."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    out, page = [], 1
    while page <= 5:
        try:
            r = requests.post(BITO_BASE_URL + "reports/pos/summary/credit/paging",
                              json={"organization_ids": [CFG.BITO_ORG_ID],
                                    "limit": 200, "page": page},
                              headers=headers, timeout=25)
            if r.status_code != 200:
                print(f"SUPPLIER CREDIT: HTTP {r.status_code} — {(r.text or '')[:150]}", flush=True)
                break
            items = _bito_rows(r.json() or {})
            if page == 1 and items:
                print(f"SUPPLIER CREDIT: 1-yozuv maydonlari: {sorted(items[0].keys())[:20]}",
                      flush=True)
        except Exception as e:
            print("SUPPLIER CREDIT ERR:", str(e)[:120], flush=True)
            break
        if not items:
            break
        for it in items:
            # ⚠️ Bito ba'zan ro'yxatda lug'at emas, matn qaytaradi — tekshirmasak
            # .get() yiqiladi va butun sahifa 500 beradi (amalda ko'rilgan).
            if not isinstance(it, dict):
                continue
            sup = it.get("supplier") or it.get("person") or {}
            if not isinstance(sup, dict):
                sup = {}
            sid = sup.get("_id") or it.get("_id")
            try:
                amt = float(it.get("total_amount") or 0)
            except (TypeError, ValueError):
                amt = 0.0
            if sid and amt:
                out.append({"id": sid, "name": sup.get("name") or "—",
                            "amount": amt})
        if len(items) < 200:
            break
        page += 1
    out.sort(key=lambda x: -x["amount"])
    return out


def supplier_plan_all():
    """Firma jadvallarini lug'at ko'rinishida qaytaradi: {supplier_id: {...}}"""
    rows = qall("SELECT supplier_id, supplier_name, visit_days, pay_term_days, "
                "is_cash, note, takes_credit, debt_swap FROM supplier_plan") or []
    return {r[0]: {"name": r[1], "visit_days": r[2] or "", "pay_term_days": r[3] or 0,
                   "is_cash": bool(r[4]), "note": r[5] or "",
                   "takes_credit": bool(r[6] if len(r) > 6 else 0),
                   "debt_swap": bool(r[7] if len(r) > 7 else 0)} for r in rows}


def supplier_plan_save(sid, name, visit_days, pay_term_days, is_cash, note="",
                       takes_credit=0, debt_swap=0):
    q("""INSERT INTO supplier_plan
         (supplier_id, supplier_name, visit_days, pay_term_days, is_cash, note,
          takes_credit, debt_swap, updated_at)
         VALUES (?,?,?,?,?,?,?,?,?)
         ON CONFLICT(supplier_id) DO UPDATE SET
           supplier_name=excluded.supplier_name, visit_days=excluded.visit_days,
           pay_term_days=excluded.pay_term_days, is_cash=excluded.is_cash,
           note=excluded.note, takes_credit=excluded.takes_credit,
           debt_swap=excluded.debt_swap, updated_at=excluded.updated_at""",
      (sid, name, visit_days, int(pay_term_days or 0), 1 if is_cash else 0, note,
       1 if takes_credit else 0, 1 if debt_swap else 0, now_str()))


def debt_due_all():
    rows = qall("SELECT supplier_id, due_date, amount_at_entry, note FROM debt_due") or []
    return {r[0]: {"due_date": r[1], "amount_at_entry": r[2] or 0, "note": r[3] or ""}
            for r in rows}


def debt_due_save(sid, name, due_date, amount, note=""):
    q("""INSERT INTO debt_due
         (supplier_id, supplier_name, due_date, amount_at_entry, note, updated_at)
         VALUES (?,?,?,?,?,?)
         ON CONFLICT(supplier_id) DO UPDATE SET
           supplier_name=excluded.supplier_name, due_date=excluded.due_date,
           amount_at_entry=excluded.amount_at_entry, note=excluded.note,
           updated_at=excluded.updated_at""",
      (sid, name, due_date, float(amount or 0), note, now_str()))


def fixed_expense_all(active_only=True):
    sql = ("SELECT id, name, amount, payee, period, day_of_month, day_of_week, "
           "once_date, is_active, bito_type_id, employee_tg_id, auto_percent, "
           "percent_base FROM fixed_expense")
    if active_only:
        sql += " WHERE is_active=1"
    rows = qall(sql + " ORDER BY amount DESC") or []
    return [{"id": r[0], "name": r[1], "amount": r[2] or 0, "payee": r[3] or "",
             "period": r[4] or "monthly", "day_of_month": r[5] or 1,
             "day_of_week": r[6] or 1, "once_date": r[7] or "",
             "is_active": bool(r[8]), "bito_type_id": (r[9] if len(r) > 9 else "") or "",
             "employee_tg_id": (r[10] if len(r) > 10 else 0) or 0,
             "auto_percent": (r[11] if len(r) > 11 else 0) or 0,
             "percent_base": (r[12] if len(r) > 12 else "") or ""}
            for r in rows]


def bito_cash_from_transaction():
    """💰 Kassa qoldig'ini OXIRGI TRANZAKSIYADAN oladi.

    Har tranzaksiya yozuvida `cashbox_after_balance` bor — o'sha amaldan keyingi
    kassa holati, to'lov usuli bo'yicha ajratilgan. `transaction/get-paging`
    ishlashi tasdiqlangan, shuning uchun bu ishonchli zaxira yo'l."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.post(BITO_BASE_URL + "transaction/get-paging",
                          json={"page": 1, "limit": 200, "sort": "-created_at"},
                          headers=headers, timeout=30)
        if r.status_code != 200:
            print(f"CASH (tranzaksiya): HTTP {r.status_code}", flush=True)
            return 0.0, []
        rows = _bito_rows(r.json() or {})
    except Exception as e:
        print("CASH (tranzaksiya) ERR:", str(e)[:120], flush=True)
        return 0.0, []
    if not rows:
        return 0.0, []
    # ⚠️ Bitta tranzaksiya FAQAT o'z kassasining holatini ko'rsatadi. Shuning uchun
    # har bir kassa bo'yicha ENG OXIRGI tranzaksiyani olamiz va ularni qo'shamiz.
    latest = {}
    for tr in rows:
        cb = tr.get("cashbox_id")
        if cb and cb not in latest:
            latest[cb] = tr
    names = {}
    try:
        rm = requests.post(BITO_BASE_URL + "payment-method/get-all", json={},
                           headers=headers, timeout=20)
        if rm.status_code == 200:
            for m in _bito_rows(rm.json() or {}):
                if m.get("_id"):
                    names[m["_id"]] = m.get("name") or "—"
    except Exception:
        pass
    per_method, total = {}, 0.0
    for tr in latest.values():
        for b in (tr.get("cashbox_after_balance") or []):
            if not isinstance(b, dict):
                continue
            amt = float(b.get("amount") or 0)
            if not amt:
                continue
            pm = b.get("payment_method_id") or ""
            key = names.get(pm, pm[:8] or "—")
            per_method[key] = per_method.get(key, 0.0) + amt
            total += amt
    boxes = [{"name": k, "amount": v} for k, v in per_method.items()]
    boxes.sort(key=lambda x: -x["amount"])
    print(f"CASH (tranzaksiya): {len(latest)} ta kassa, "
          f"{len(boxes)} to'lov usuli, jami {int(total)}", flush=True)
    return total, boxes


def bito_cash_on_hand():
    """💰 Kassalardagi jami pul — Bito balansidan (jonli tekshirilgan).

    Qaytaradi: (jami_summa, [{"name","amount"}, ...])"""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    # 2026-08-09 MCP jonli tekshiruv: balans bo'limi kassalarni NOM va
    # haqiqiy summa bilan qaytaradi (Naqd 31.2M...), eski tranzaksiya-
    # taxmini esa 10.7M ko'rsatib xato edi. To'g'ri yo'l birinchi.
    cands = ["reports/balance/get",
             "reports/balance",
             "reports/finance/balance/get",
             "reports/finance/balance",
             "reports/balance/get-all",
             "cashbox/get-all"]
    try:
        j, _p = _bito_try_paths("bito_balance_endpoint", cands,
                                {"organization_ids": [CFG.BITO_ORG_ID]},
                                headers, "CASH ON HAND")
        if j is None:
            # ⚠️ Balans hisoboti manzili topilmadi — kassa qoldig'ini oxirgi
            # tranzaksiyadagi `cashbox_after_balance` dan olamiz.
            return bito_cash_from_transaction()
        data = (j or {}).get("data") or j or {}
        # ikki qavatli bo'lsa ichkariga tushamiz
        while isinstance(data, dict) and "data" in data and "cashbox" not in data:
            data = data["data"]
        if not isinstance(data, dict):
            print(f"CASH ON HAND: kutilmagan shakl: {type(data).__name__}", flush=True)
            return 0.0, []
    except Exception as e:
        print("CASH ON HAND ERR:", str(e)[:120], flush=True)
        return 0.0, []
    # Javob shakli manzilga qarab farq qiladi: {"cashbox":[...]} yoki to'g'ridan
    # to'g'ri kassalar ro'yxati. Ikkalasini ham qabul qilamiz.
    if isinstance(data, dict):
        boxes_raw = data.get("cashbox") or data.get("cashboxes") or []
    elif isinstance(data, list):
        boxes_raw = data
    else:
        boxes_raw = []
    boxes, total = [], 0.0
    for b in boxes_raw:
        if not isinstance(b, dict):
            continue
        amt = 0.0
        for c in (b.get("currencies") or []):
            if isinstance(c, dict):
                amt += float(c.get("amount") or 0)
        if not amt:
            amt = float(b.get("amount") or b.get("balance") or 0)
        if amt:
            boxes.append({"name": b.get("name") or "—", "amount": amt})
            total += amt
    boxes.sort(key=lambda x: -x["amount"])
    return total, boxes



def bito_expense_types():
    """💸 Bito'dagi FAOL xarajat turlari.

    Bito'da xarajat turlari `payment_type` deb saqlanadi (jonli tekshirilgan
    2026-07-31). Bizga kerakligi: chiqim, faol, va foydalanuvchiga ko'rinadigan
    turlar — texnik/ichki turlar (inventarizatsiya, ayirboshlash, qaytim va h.k.)
    chiqarib tashlanadi.

    Qaytaradi: [{"id","name","used"}, ...] — ko'p ishlatilgani tepada."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.post(BITO_BASE_URL + "payment-type/get-all", json={},
                          headers=headers, timeout=25)
        if r.status_code != 200:
            print(f"EXPENSE TYPES: HTTP {r.status_code} — {(r.text or '')[:150]}", flush=True)
            return []
        rows = _bito_rows(r.json() or {})
    except Exception as e:
        print("EXPENSE TYPES ERR:", str(e)[:150], flush=True)
        return []
    out = []
    for t in rows:
        if t.get("transaction_type") != "expense":
            continue
        if not t.get("is_active") or not t.get("is_visible"):
            continue
        if t.get("is_deleted") or t.get("is_archived"):
            continue
        if t.get("_id") and t.get("name"):
            # ⚖️ Ish haqiga oid turlar alohida belgilanadi — ular tanlansa
            # oynada xodim tanlash va foiz maydonlari ochiladi.
            is_salary = (t.get("user_type") == "employee"
                         or str(t.get("payment_type") or "") == "PAYMENT_FOR_EMPLOYEE")
            out.append({"id": t["_id"], "name": t["name"],
                        "used": int(t.get("used_count") or 0),
                        "is_salary": 1 if is_salary else 0})
    out.sort(key=lambda x: -x["used"])
    print(f"EXPENSE TYPES: {len(out)} ta faol xarajat turi "
          f"({sum(x['is_salary'] for x in out)} tasi ish haqi)", flush=True)
    return out


def employees_for_picker():
    """Ish haqi biriktirish uchun xodimlar ro'yxati."""
    rows = qall("SELECT tg_id, full_name FROM users WHERE full_name IS NOT NULL "
                "ORDER BY full_name") or []
    return [{"tg_id": r[0], "name": r[1]} for r in rows if r[0] and r[1]]


def calc_auto_expense(exp, date_from, date_to):
    """💸 Savdoga bog'langan xarajat summasini hisoblaydi.

    exp: fixed_expense yozuvi (auto_percent, percent_base, employee_tg_id).
    percent_base:
      'employee' → faqat shu xodimning savdosidan foiz
      'shop'     → butun do'kon savdosidan foiz
    Foiz belgilanmagan bo'lsa, kiritilgan aniq summa qaytariladi."""
    pct = float(exp.get("auto_percent") or 0)
    base = exp.get("percent_base") or ""
    if pct <= 0 or not base:
        return float(exp.get("amount") or 0), "qo'lda kiritilgan"
    try:
        sales_dict = get_bito_sales_dict(date_from, date_to) or {}
    except Exception as e:
        print("AUTO EXPENSE ERR:", str(e)[:120], flush=True)
        return float(exp.get("amount") or 0), "savdo olinmadi — qo'lda summa"
    if base == "employee":
        bname = get_bito_map().get(int(exp.get("employee_tg_id") or 0))
        if not bname:
            return 0.0, "xodim Bito bilan bog'lanmagan"
        item = sales_dict.get(bname) or {}
        gross = float(item.get("gross_sales") or 0)
        who = bname
    else:
        gross = sum(float((v or {}).get("gross_sales") or 0)
                    for v in sales_dict.values())
        who = "do'kon"
    return round(gross * pct / 100.0), f"{who}: {fmt_money(gross)} × {pct}%"


def bito_suppliers_with_balance():
    """🏢 Firmalar ro'yxati + qarz miqdori — HAQIQIY manbadan.

    ⚠️ MUHIM: ilgari ro'yxat qarz hisobotidan (`reports/pos/summary/credit/paging`)
    olinardi, lekin u yerdagi `supplier._id` mahsulot kartochkasidagi
    `supplier_ids` bilan MOS KELMAYDI — shuning uchun zakaz tavsiyasi hech qachon
    firma topa olmasdi (amalda ko'rilgan: 114 mahsulot bog'langan, 0 moslik).
    `supplier/get-paging` esa to'g'ri `_id` va `balance` (qarz) ni birga beradi."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    out, page = [], 1
    while page <= 20:
        try:
            r = requests.post(BITO_BASE_URL + "supplier/get-paging",
                              json={"page": page, "limit": 200},
                              headers=headers, timeout=30)
            if r.status_code != 200:
                print(f"SUPPLIERS: HTTP {r.status_code}", flush=True)
                break
            rows = _bito_rows(r.json() or {})
        except Exception as e:
            print("SUPPLIERS ERR:", str(e)[:150], flush=True)
            break
        if not rows:
            break
        for it in rows:
            if it.get("_id") and it.get("name"):
                out.append({"id": it["_id"], "name": it["name"],
                            "amount": float(it.get("balance") or 0)})
        if len(rows) < 200:
            break
        page += 1
    out.sort(key=lambda x: -x["amount"])
    print(f"SUPPLIERS: {len(out)} ta firma, "
          f"{sum(1 for x in out if x['amount'] > 0)} tasida qarz bor", flush=True)
    return out


def migrate_supplier_plans(suppliers):
    """Eski (noto'g'ri ID bilan saqlangan) firma jadvallarini NOM bo'yicha
    to'g'ri ID'ga ko'chiradi. Bir marta ishlaydi, keyin jim o'tadi."""
    by_name = {s["name"].strip().lower(): s["id"] for s in suppliers}
    valid = {s["id"] for s in suppliers}
    moved = 0
    for sid, p in list(supplier_plan_all().items()):
        if sid in valid:
            continue
        new_id = by_name.get((p.get("name") or "").strip().lower())
        if not new_id or new_id == sid:
            continue
        supplier_plan_save(new_id, p.get("name") or "", p.get("visit_days") or "",
                           p.get("pay_term_days") or 0, p.get("is_cash"),
                           p.get("note") or "", p.get("takes_credit"),
                           p.get("debt_swap"))
        q("DELETE FROM supplier_plan WHERE supplier_id=?", (sid,))
        d = debt_due_all().get(sid)
        if d:
            debt_due_save(new_id, p.get("name") or "", d.get("due_date") or "",
                          d.get("amount_at_entry") or 0)
            q("DELETE FROM debt_due WHERE supplier_id=?", (sid,))
        moved += 1
    if moved:
        print(f"🔄 FIRMA: {moved} ta jadval to'g'ri ID'ga ko'chirildi", flush=True)
    return moved


def firms_merged_list():
    """💰 Firmalar ro'yxati: Bito'dagi qarz + botda saqlangan jadval.

    Qarzi bor firmalar tepada. Qaytaradi:
    [{"id","name","debt","visit_days","pay_term_days","is_cash","due_date"}, ...]"""
    credit = bito_suppliers_with_balance()
    migrate_supplier_plans(credit)      # eski noto'g'ri ID'larni bir marta tuzatadi
    plans = supplier_plan_all()
    dues = debt_due_all()
    seen, out = set(), []
    for c in credit:
        p = plans.get(c["id"], {})
        d = dues.get(c["id"], {})
        seen.add(c["id"])
        out.append({"id": c["id"], "name": c["name"], "debt": c["amount"],
                    "visit_days": p.get("visit_days", ""),
                    "pay_term_days": p.get("pay_term_days", 0),
                    "is_cash": 1 if p.get("is_cash") else 0,
                    "takes_credit": 1 if p.get("takes_credit") else 0,
                    "debt_swap": 1 if p.get("debt_swap") else 0,
                    "due_date": d.get("due_date", "")})
    # Qarzi yo'q, lekin jadvali kiritilgan firmalar ham ko'rinsin
    for sid, p in plans.items():
        if sid in seen:
            continue
        d = dues.get(sid, {})
        out.append({"id": sid, "name": p.get("name") or "—", "debt": 0,
                    "visit_days": p.get("visit_days", ""),
                    "pay_term_days": p.get("pay_term_days", 0),
                    "is_cash": 1 if p.get("is_cash") else 0,
                    "takes_credit": 1 if p.get("takes_credit") else 0,
                    "debt_swap": 1 if p.get("debt_swap") else 0,
                    "due_date": d.get("due_date", "")})
    return out


FIRMA_TOKENS = TDict()  # uid -> oxirgi 8 ta token (eski tugmalar ham ishlasin)


def firma_token_new(uid):
    import secrets as _secrets
    tok = _secrets.token_urlsafe(16)
    lst = FIRMA_TOKENS.setdefault(uid, [])
    lst.append(tok)
    del lst[:-8]
    return tok


def firma_token_ok(uid, tok):
    return bool(tok) and tok in (FIRMA_TOKENS.get(uid) or [])


GOAL_DEFS = [
    {"code": "sales_profit", "title": "Savdo hajmini oshirish + foydani ko'paytirish",
     "unit": "%", "hint": "oxirgi 30 kunlik o'rtacha savdoga nisbatan o'sish"},
    {"code": "stock_up", "title": "Mahsulotlar omborini ko'paytirish",
     "unit": "%", "hint": "ombordagi tovar qiymatini oshirish"},
    {"code": "premium_shift", "title": "Arzon mahsulotlardan qimmatroqqa o'tish",
     "unit": "%", "hint": "o'rtacha chek summasini oshirish"},
    {"code": "debt_free", "title": "Yetkazib beruvchilar qarzidan qutilish",
     "unit": "%", "hint": "joriy qarzning necha foizini yopish"},
]


def goal_baselines():
    """🎯 Maqsadlar uchun HOZIRGI holat — AI tavsiyasi shu raqamlarga tayanadi."""
    b = {}
    try:
        b["daily_sales"] = avg_daily_sales(30)
    except Exception:
        b["daily_sales"] = 0
    try:
        b["debt"] = sum(s["amount"] for s in bito_suppliers_with_balance() if s["amount"] > 0)
    except Exception:
        b["debt"] = 0
    try:
        b["cash"] = bito_cash_on_hand()[0]
    except Exception:
        b["cash"] = 0
    try:
        st = bito_stock_and_cost()
        # 🎭 soxta ~2000 va minus qoldiqlarni chiqarib tashlaymiz —
        # aks holda ombor qiymati bir necha mlrd ga shishadi (goal_facts
        # bilan bir xil filtr)
        real = {k: v for k, v in st.items()
                if (v.get("stock") or 0) > 0
                and not (INV_FAKE_MIN <= (v.get("stock") or 0) <= INV_FAKE_MAX)}
        b["stock_value"] = sum(v["stock"] * v["cost"] for v in real.values())
        b["stock_items"] = len(real)
    except Exception:
        b["stock_value"], b["stock_items"] = 0, 0
    return b


def goal_ai_suggestion(code, base):
    """Har maqsad uchun qavs ichida ko'rsatiladigan real tavsiya.

    Sun'iy raqam o'ylab topmaymiz — hozirgi holatdan kelib chiqamiz."""
    if code == "sales_profit":
        if not base.get("daily_sales"):
            return "savdo ma'lumoti yo'q"
        oy = base["daily_sales"] * 30
        return (f"hozir oyiga ~{fmt_money(oy)}. "
                f"3 oyda 10–15% real, 25%+ juda shiddatli")
    if code == "debt_free":
        if not base.get("debt"):
            return "hozir qarz yo'q"
        kunlik = base.get("daily_sales") or 0
        if kunlik:
            kun = base["debt"] / max(1, kunlik * 0.15)   # kunlik savdoning ~15% i
            return (f"qarz {fmt_money(base['debt'])}. Kunlik savdoning 15% ini "
                    f"ajratsangiz ~{int(kun)} kunda yopiladi")
        return f"qarz {fmt_money(base['debt'])}"
    if code == "stock_up":
        if not base.get("stock_value"):
            return "ombor qiymati o'qilmadi"
        return (f"hozir ~{fmt_money(base['stock_value'])}, {base.get('stock_items', 0)} nom. "
                f"Pul yetishmasa avval qotib qolgan tovarni sotish kerak")
    if code == "premium_shift":
        return "o'rtacha chekni 10–20% oshirish 2–3 oyda real"
    return "muddat va darajani o'zingiz belgilang"


def goal_facts(limit=12):
    """📊 AI uchun ANIQ FAKTLAR — umumiy maslahat o'rniga real ro'yxatlar.

    Qaytaradi:
      dead      — qoldig'i bor, lekin 30 kunda umuman sotilmagan (pul qotib qolgan)
      slow      — sotilyapti, lekin qoldiq 60 kundan ortiqqa yetadi
      top       — eng ko'p daromad keltiradiganlar
      low_margin— ustamasi past, lekin ko'p sotiladiganlar
      debt_top  — eng katta qarzli firmalar
    """
    f = {"dead": [], "slow": [], "top": [], "low_margin": [], "debt_top": []}
    try:
        stock = bito_stock_and_cost()
        vel = sales_velocity(30)
    except Exception as e:
        print("GOAL FACTS ERR:", str(e)[:150], flush=True)
        return f
    # 📏 O'lchov birligi katalogdan olinadi — kg mahsulotni "dona" deb ko'rsatmaslik uchun
    units = {}
    for p in NAK_CATALOG_CACHE.get("products") or []:
        units[p["id"]] = ("kg" if p.get("is_kg")
                          else (p.get("measure_name") or "dona"))
    for pid, st in stock.items():
        qty = st.get("stock") or 0
        cost = st.get("cost") or 0
        if qty <= 0 or cost <= 0:
            continue
        # 🎭 SOXTA QOLDIQ FILTRI (2026-08-03 xatosidan): ~2000 atrofidagi
        # qoldiqlar minusга sotмаслик uchun QO'LDA qo'yilgan fantomlar —
        # real tovar EMAS. Filtrsiz ular "o'lik tovar" ro'yxatiga kirib,
        # AI yo'q 950+ mln so'mni sotish strategiyasini tuzgan edi
        # (Sevaverek 2000 dona, Zara Orchid 1999 dona...).
        # Chegara inventar moduli bilan bir xil (INV_FAKE_MIN/MAX).
        if INV_FAKE_MIN <= qty <= INV_FAKE_MAX:
            continue
        trapped = qty * cost
        rate = vel.get(pid, 0.0)
        unit = units.get(pid, "dona")
        row = {"name": st.get("name") or "?", "stock": qty, "cost": cost,
               "unit": unit, "trapped": trapped, "rate": round(rate, 2)}
        if rate <= 0:
            f["dead"].append(row)
        else:
            days = qty / rate
            row["days"] = int(days)
            if days > 60:
                f["slow"].append(row)
            f["top"].append({**row, "revenue": rate * 30 * cost})
    f["dead"].sort(key=lambda x: -x["trapped"])
    f["slow"].sort(key=lambda x: -x["trapped"])
    f["top"].sort(key=lambda x: -x["revenue"])
    f["dead"] = f["dead"][:limit]
    f["slow"] = f["slow"][:limit]
    f["top"] = f["top"][:limit]
    try:
        sup = [s for s in bito_suppliers_with_balance() if s["amount"] > 0]
        f["debt_top"] = sup[:limit]
    except Exception:
        pass
    print(f"GOAL FACTS: {len(f['dead'])} o'lik, {len(f['slow'])} sekin, "
          f"{len(f['top'])} top, {len(f['debt_top'])} qarzdor", flush=True)
    return f


def _facts_text(f):
    """Faktlarni AI o'qiy oladigan qisqa matnga aylantiradi."""
    def rows(lst, fields):
        out = []
        for x in lst:
            parts = [x["name"]]
            u = x.get("unit") or "dona"
            for k, lbl in fields:
                if k in x:
                    v = x[k]
                    if k in ("trapped", "cost", "revenue", "amount"):
                        parts.append(f"{lbl}={fmt_money(v)}")
                    elif k in ("stock", "rate"):
                        # 📏 miqdor har doim O'LCHOV BIRLIGI bilan
                        parts.append(f"{lbl}={round(v, 2)} {u}")
                    else:
                        parts.append(f"{lbl}={v}")
            out.append("  • " + ", ".join(parts))
        return "\n".join(out) or "  (yo'q)"
    t = []
    t.append("O'LIK TOVAR (30 kunda umuman sotilmagan, pul qotib qolgan):")
    t.append(rows(f["dead"], [("stock", "qoldiq"), ("cost", "tannarx"), ("trapped", "qotgan_pul")]))
    t.append("\nSEKIN AYLANADIGAN (qoldiq 60 kundan ortiqqa yetadi):")
    t.append(rows(f["slow"], [("stock", "qoldiq"), ("days", "kun"), ("trapped", "qotgan_pul")]))
    t.append("\nENG DAROMADLI TOVARLAR:")
    t.append(rows(f["top"], [("rate", "kunlik_sotuv"), ("stock", "qoldiq")]))
    t.append("\nENG KATTA QARZLAR:")
    t.append(rows(f["debt_top"], [("amount", "qarz")]))
    return "\n".join(t)


def _ai_json(prompt, max_tokens=4000, tries=2):
    """Claude'dan JSON oladi. Kesilib qolsa yoki buzilsa — qayta uriniladi.

    ⚠️ Ilgari max_tokens=1500 edi va uzun rejalar KESILIB qolib, JSON buzilardi
    (amalda ko'rilgan: bitta maqsad uchun strategiya chiqmadi)."""
    headers = {"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01",
               "content-type": "application/json"}
    import json as _j
    import re as _re
    last = ""
    for attempt in range(tries):
        try:
            r = requests.post("https://api.anthropic.com/v1/messages", headers=headers,
                              json={"model": "claude-sonnet-4-6", "max_tokens": max_tokens,
                                    "messages": [{"role": "user", "content": prompt}]},
                              timeout=120)
            if r.status_code != 200:
                print(f"AI JSON: HTTP {r.status_code} — {(r.text or '')[:200]}", flush=True)
                continue
            body = r.json()
            txt = "".join(b.get("text", "") for b in body.get("content", [])
                          if b.get("type") == "text")
            stop = body.get("stop_reason")
            if stop == "max_tokens":
                print("AI JSON: javob KESILDI (max_tokens) — qayta urinilyapti", flush=True)
                max_tokens = min(8000, max_tokens * 2)
                continue
            last = txt
            m = _re.search(r"\{.*\}", txt, _re.S)
            if not m:
                print(f"AI JSON: JSON topilmadi. Javob boshi: {txt[:150]}", flush=True)
                continue
            return _j.loads(m.group(0))
        except Exception as e:
            print(f"AI JSON urinish {attempt+1}: {str(e)[:150]}", flush=True)
    if last:
        print(f"AI JSON: yakuniy javob o'qilmadi. Boshi: {last[:200]}", flush=True)
    return None



def goals_all():
    rows = qall("SELECT id, code, title, is_active, target_value, target_unit, "
                "deadline, baseline, strategy, approved FROM goals ORDER BY id") or []
    return [{"id": r[0], "code": r[1], "title": r[2], "is_active": bool(r[3]),
             "target_value": r[4] or 0, "target_unit": r[5] or "%",
             "deadline": r[6] or "", "baseline": r[7] or 0,
             "strategy": r[8] or "", "approved": bool(r[9])} for r in rows]


def goal_steps(goal_id):
    rows = qall("SELECT id, step_no, title, detail, status, note FROM goal_steps "
                "WHERE goal_id=? ORDER BY step_no", (goal_id,)) or []
    return [{"id": r[0], "step_no": r[1], "title": r[2], "detail": r[3] or "",
             "status": r[4] or "pending", "note": r[5] or ""} for r in rows]


def goal_generate_strategy(goal, base, facts=None):
    """🤖 Maqsad uchun ANIQ FAKTLARGA tayangan strategiya va kunlik reja.

    Umumiy maslahat emas: AI'ga aniq mahsulot nomlari, qoldiqlar, qotib qolgan
    pul va qarzdor firmalar ro'yxati beriladi. Shuning uchun javobda ham aniq
    nomlar bo'ladi."""
    facts = facts if facts is not None else goal_facts()
    ctx = (f"DO'KON: supermarket.\n"
           f"O'rtacha kunlik savdo: {fmt_money(base.get('daily_sales', 0))}\n"
           f"Kassadagi pul: {fmt_money(base.get('cash', 0))}\n"
           f"Firmalarga qarz: {fmt_money(base.get('debt', 0))}\n"
           f"Ombordagi tovar: {fmt_money(base.get('stock_value', 0))} "
           f"({base.get('stock_items', 0)} nom)\n\n"
           f"{_facts_text(facts)}\n")
    prompt = (
        f"{ctx}\n"
        f"MAQSAD: {goal['title']}\n"
        f"Ko'rsatkich: {goal['target_value']}{goal['target_unit']}\n"
        f"Muddat: {goal['deadline'] or 'belgilanmagan'}\n\n"
        "QAT'IY TALABLAR:\n"
        "1. Har bosqichda AYNAN yuqoridagi ro'yxatdagi mahsulot yoki firma "
        "NOMLARINI yoz. Umumiy gap yozma.\n"
        "1a. MIQDORNI faqat ro'yxatda ko'rsatilgan O'LCHOV BIRLIGIDA yoz "
        "(kg bo'lsa kg, dona bo'lsa dona). Kilogramli tovarni 'dona' deb yozma.\n"
        "2. Har bosqichda o'lchanadigan raqam bo'lsin (nechta, qancha so'm, necha kun).\n"
        "3. Pul tanqisligini hisobga ol — avval qotib qolgan puldan foydalan.\n"
        "4. Bosqichlar ketma-ket bajariladigan bo'lsin, birinchisi eng tez natija beradigani.\n\n"
        "FAQAT JSON qaytar:\n"
        '{"strategy":"2-3 jumla",'
        '"steps":[{"title":"qisqa nom","detail":"aniq nomlar va raqamlar bilan",'
        '"metric":"qanday o\'lchanadi","days":7}]}\n'
        "5-7 ta bosqich."
    )
    d = _ai_json(prompt)
    if not d:
        return None, []
    steps = [x for x in (d.get("steps") or []) if isinstance(x, dict) and x.get("title")]
    return (d.get("strategy") or ""), steps


def goal_daily_plan(goal, facts=None, yesterday=None):
    """📅 Maqsad bo'yicha BUGUNGI aniq vazifalar.

    yesterday: kechagi natijalar ro'yxati — AI shunga qarab moslashadi
    (yaxshi ketgan bo'lsa davom ettiradi, yomon bo'lsa boshqa yo'l taklif qiladi)."""
    facts = facts if facts is not None else goal_facts()
    base = goal_baselines()
    steps = goal_steps(goal["id"])
    done = [s["title"] for s in steps if s["status"] == "done"]
    pending = [s["title"] for s in steps if s["status"] == "pending"]
    hist = ""
    if yesterday:
        hist = "\nKECHAGI NATIJALAR:\n" + "\n".join(
            f"  • {y['task']} — {'BAJARILDI' if y['status']=='done' else 'BAJARILMADI'}"
            + (f" ({y['result_note']})" if y.get("result_note") else "")
            for y in yesterday) + "\n"
    prompt = (
        f"DO'KON: supermarket. Kunlik savdo {fmt_money(base.get('daily_sales',0))}, "
        f"kassada {fmt_money(base.get('cash',0))}, qarz {fmt_money(base.get('debt',0))}.\n\n"
        f"{_facts_text(facts)}\n\n"
        f"MAQSAD: {goal['title']} — {goal['target_value']}{goal['target_unit']}, "
        f"{goal['deadline'] or 'muddatsiz'}\n"
        f"Strategiya: {goal.get('strategy') or ''}\n"
        f"Bajarilgan bosqichlar: {', '.join(done) or 'yo`q'}\n"
        f"Qolgan bosqichlar: {', '.join(pending) or 'yo`q'}\n"
        f"{hist}\n"
        "BUGUN uchun 2-4 ta ANIQ vazifa yoz. Har biri:\n"
        "• aynan qaysi mahsulot yoki qaysi firma haqida ekani ko'rsatilsin (nom bilan)\n"
        "• miqdor ro'yxatdagi o'lchov birligida bo'lsin (kg/dona) — aralashtirma\n"
        "• bugun bajarish mumkin bo'lsin (bir kunlik hajm)\n"
        "• o'lchanadigan natijasi bo'lsin\n"
        "Kechagi natija yomon bo'lsa — boshqa yondashuv taklif qil, o'shani takrorlama.\n\n"
        "FAQAT JSON:\n"
        '{"tasks":[{"task":"qisqa nom","detail":"aniq nom va raqam bilan",'
        '"metric":"qanday tekshiriladi"}]}'
    )
    d = _ai_json(prompt, max_tokens=2000)
    if not d:
        return []
    return [x for x in (d.get("tasks") or []) if isinstance(x, dict) and x.get("task")]


def avg_daily_sales(days=30):
    """O'rtacha kunlik savdo (so'm). Oxirgi `days` kun bo'yicha.

    ⚠️ Bu YALPI savdo — naqd va karta kassaga tushadi, qarzga berilgani esa
    tushmaydi. Shuning uchun taqvimdagi kirim biroz optimistik bo'lishi mumkin;
    hisobotda shu haqda eslatib o'tiladi."""
    try:
        end = now_dt()
        start = end - timedelta(days=days)
        df = start.strftime("%Y-%m-%dT00:00:00Z")
        dt_ = end.strftime("%Y-%m-%dT23:59:59Z")
        items = bito_sales_by_employee(df, dt_)
        if not items:
            return 0.0
        total = sum(float(it.get("gross_sales") or 0) for it in items)
        return round(total / max(1, days))
    except Exception as e:
        print("AVG DAILY SALES ERR:", str(e)[:120], flush=True)
        return 0.0


def expense_events(days=30):
    """Majburiy xarajatlarni kelgusi `days` kunga SANA bo'yicha yoyadi.

    Qaytaradi: [{"date": date, "name", "amount", "kind": "xarajat"}, ...]"""
    out = []
    today = now_dt().date()
    for e in fixed_expense_all(active_only=True):
        amount = float(e.get("amount") or 0)
        note = ""
        if e.get("percent_base"):
            # savdoga bog'langan — oxirgi 30 kun savdosidan hisoblanadi
            end = now_dt()
            start = end - timedelta(days=30)
            amount, note = calc_auto_expense(
                e, start.strftime("%Y-%m-%dT00:00:00Z"),
                end.strftime("%Y-%m-%dT23:59:59Z"))
        if amount <= 0:
            continue
        for i in range(days + 1):
            d = today + timedelta(days=i)
            hit = False
            if e["period"] == "monthly":
                hit = (d.day == int(e.get("day_of_month") or 1))
            elif e["period"] == "weekly":
                hit = (d.isoweekday() == int(e.get("day_of_week") or 1))
            elif e["period"] == "once":
                hit = (str(e.get("once_date") or "") == d.strftime("%Y-%m-%d"))
            if hit:
                out.append({"date": d, "name": e["name"], "amount": amount,
                            "kind": "xarajat", "note": note})
    return out


def debt_events(days=30):
    """Firmalarga qarz qaytarish sanalari.

    ⚠️ 2026-08-09 tuzatish: summa endi Bito'dan JONLI olinadi — qo'lda
    kiritilgandagi summa (amount_at_entry) qotib qolib, qisman to'langan
    qarzlarni eski summada ko'rsatib xato berardi. Muddat (sana) bazadan,
    summa Bito qarz hisobotidan; Bito'da topilmasa kiritilgandagi summa
    «(kiritilgandagi)» belgisi bilan qoladi. Bito'da qarzi 0 bo'lib
    qolganlar ro'yxatga umuman kirmaydi (to'lab bo'lingan)."""
    out = []
    today = now_dt().date()
    limit = today + timedelta(days=days)
    rows = qall("SELECT supplier_name, due_date, amount_at_entry FROM debt_due "
                "WHERE due_date IS NOT NULL AND due_date != ''") or []
    if not rows:
        return out
    # Jonli qarzlar xaritasi (nom kichik harfda).
    # `live_ok` — Bito ro'yxati muvaffaqiyatli olindimi. Bu farq MUHIM:
    # ro'yxat olingan bo'lsa, undagi YO'Q firma — qarzi to'liq yopilgan degani
    # (Bito faqat qarzi borlarni qaytaradi). Ro'yxat umuman olinmagan bo'lsa —
    # bu tarmoq nosozligi, u holda kiritilgandagi summa bilan ishlanadi.
    live, live_ok = {}, False
    try:
        rows_live = bito_supplier_credit() or []
        for c in rows_live:
            live[(c.get("name") or "").strip().lower()] = float(c.get("amount") or 0)
        live_ok = bool(rows_live)
    except Exception as e:
        print("DEBT LIVE ERR:", str(e)[:100], flush=True)
    def _live_amount(nm):
        k = (nm or "").strip().lower()
        if k in live:
            return live[k]
        # qisman moslik: kiritilgan nom Bito nomining bo'lagi yoki aksincha
        for lk, lv in live.items():
            if k and (k in lk or lk in k):
                return lv
        return None
    for name, due, amt in rows:
        try:
            d = datetime.strptime(due, "%Y-%m-%d").date()
        except Exception:
            continue
        la = _live_amount(name)
        if la is not None and la <= 0:
            continue  # Bito bo'yicha qarz yopilgan
        if la is None and live_ok:
            # ⚠️ Bito ro'yxati olindi, lekin bu firma unda YO'Q → qarz to'langan.
            # Ilgari bu holatda kiritilgandagi eski summa ko'rsatilardi va
            # to'lab bo'lingan qarz "muddati o'tgan" bo'lib osilib qolardi
            # (masalan Sherin — Bito'da qoldiq yo'q, lekin 5 050 000 ko'rinardi).
            continue
        amount = la if la is not None else float(amt or 0)
        if amount <= 0:
            continue
        tag = "" if la is not None else " (kiritilgandagi)"
        if d < today:
            # muddati o'tib ketgan — bugunga qo'yamiz, ko'zdan qochmasin
            out.append({"date": today,
                        "name": f"{name} (muddati o'tgan!){tag}",
                        "amount": amount, "kind": "qarz", "note": due})
        elif d <= limit:
            out.append({"date": d, "name": name + tag, "amount": amount,
                        "kind": "qarz", "note": ""})
    return out


def cash_calendar(days=30):
    """💰 Pul taqvimi: bugundan `days` kun oldinga kunlik qoldiq.

    Qaytaradi: (kunlar, xulosa). Kunlar: [{"date","in","out","items","balance"}]"""
    cash, boxes = bito_cash_on_hand()
    daily_in = avg_daily_sales(30)
    events = expense_events(days) + debt_events(days)
    by_day = {}
    for ev in events:
        by_day.setdefault(ev["date"], []).append(ev)

    today = now_dt().date()
    bal = float(cash)
    out_days, worst = [], None
    for i in range(days + 1):
        d = today + timedelta(days=i)
        items = by_day.get(d, [])
        out_sum = sum(x["amount"] for x in items)
        in_sum = daily_in if i > 0 else 0     # bugungi tushum allaqachon kassada
        bal = bal + in_sum - out_sum
        row = {"date": d, "in": in_sum, "out": out_sum, "items": items, "balance": bal}
        out_days.append(row)
        if bal < 0 and (worst is None or bal < worst["balance"]):
            worst = row
    summary = {"cash": cash, "boxes": boxes, "daily_in": daily_in,
               "total_out": sum(x["out"] for x in out_days),
               "end_balance": bal, "worst": worst,
               "events": sorted(events, key=lambda x: x["date"])}
    return out_days, summary


def bito_recent_purchases(days=30):
    """📥 So'nggi `days` kundagi xaridlar (zakazlar) ro'yxati.

    Manba: `purchase/get-paging` (jonli tekshirilgan) — `sort=-date` bilan
    yangisidan eskisiga qarab o'qiymiz va sana chegaradan o'tganda to'xtaymiz.
    Har yozuvdagi `total_to_pay` — o'sha xarid uchun TO'LANISHI kerak summa."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    cutoff = now_dt().date() - timedelta(days=days)
    out, page = [], 1
    while page <= 10:                       # 2000 xaridgacha — 30 kunga yetarli
        try:
            r = requests.post(BITO_BASE_URL + "purchase/get-paging",
                              json={"page": page, "limit": 200, "sort": "-date",
                                    "organization_id": CFG.BITO_ORG_ID},
                              headers=headers, timeout=40)
            if r.status_code != 200:
                print(f"PURCHASES: HTTP {r.status_code}", flush=True)
                break
            rows = _bito_rows(r.json() or {})
        except Exception as e:
            print("PURCHASES ERR:", str(e)[:150], flush=True)
            break
        if not rows:
            break
        stop = False
        for p in rows:
            ds = str(p.get("date") or p.get("created_at") or "")[:10]
            try:
                d = datetime.strptime(ds, "%Y-%m-%d").date()
            except Exception:
                continue
            if d < cutoff:
                stop = True
                break
            if str(p.get("state") or "") in ("canceled", "cancelled", "draft"):
                continue
            out.append({"date": d,
                        "amount": float(p.get("total_to_pay") or p.get("total_cost") or 0),
                        "supplier": (p.get("supplier") or {}).get("name") or ""})
        if stop or len(rows) < 200:
            break
        page += 1
    return out


def zakaz_limit(horizon=None):
    """🎯 ERTANGI ZAKAZ UCHUN XAVFSIZ SUMMA.

    Mantiq (pul harakati asosida, taxmin emas):
      Bor pul      = hozirgi kassa qoldig'i + kutilayotgan tushum (o'rtacha
                     kunlik savdo × ufq kunlari)
      Bandi        = shu ufq ichida to'lanishi SHART bo'lgan summa
                     (firmalarga qarzlar + ish haqi + doimiy xarajatlar)
      Zaxira       = kutilmagan holatlar uchun ushlab turiladigan pul
                     (sozlanadi; standart — 3 kunlik majburiy xarajat)
      LIMIT        = Bor pul − Bandi − Zaxira

    Ufq (`horizon`) — necha kunga oldinga qaraladi. Standart 7 kun: haftalik
    to'lov aylanmasi. Sozlamalarda o'zgartiriladi.
    Qaytaradi: barcha oraliq raqamlar bilan dict (hisobni ko'rsatish uchun)."""
    horizon = int(horizon or get_setting("zakaz_limit_horizon", "7") or 7)
    cash, boxes = bito_cash_on_hand()
    daily_in = avg_daily_sales(30)
    events = expense_events(horizon) + debt_events(horizon)
    today = now_dt().date()
    limit_date = today + timedelta(days=horizon)
    due = [e for e in events if today <= e["date"] <= limit_date]
    obligations = sum(e["amount"] for e in due)
    expected_in = daily_in * horizon

    # Zaxira: sozlangan bo'lsa o'sha, aks holda 3 kunlik majburiy xarajat
    reserve_set = float(get_setting("zakaz_limit_reserve", "0") or 0)
    reserve = reserve_set if reserve_set > 0 else (obligations / max(horizon, 1)) * 3

    # 💡 MUHIM: bu ayirma — UFQ DAVOMIDAGI (masalan 7 kunlik) bo'sh pul.
    # Uni to'g'ridan-to'g'ri "ertangi limit" deb bersak, bir kunlik zakazga
    # butun haftalik byudjet ruxsat berilgan bo'lardi (stub-testda 20 mln
    # bir kunga chiqib, "567% ko'paytiring" degan bema'ni tavsiya bergan edi).
    # Shuning uchun kunlik ulushga bo'lamiz.
    available = cash + expected_in - obligations - reserve
    limit = available / max(horizon, 1)

    # 📊 Odatdagi zakaz sur'ati — tavsiyani shunga nisbatan beramiz
    purch = bito_recent_purchases(30)
    avg_daily_purchase = (sum(p["amount"] for p in purch) / 30.0) if purch else 0.0

    # Eng katta to'lovlar (nima pulni band qilayotgani ko'rinib tursin)
    top = sorted(due, key=lambda x: -x["amount"])[:5]

    if limit <= 0:
        advice, level = ("Ertaga yangi zakaz BERMANG — faqat to'xtab qolmaslik uchun "
                         "zarur bo'lganini oling. Avval joriy to'lovlarni yoping."), "stop"
    elif avg_daily_purchase > 0 and limit < avg_daily_purchase * 0.8:
        pct = int(round((1 - limit / avg_daily_purchase) * 100))
        advice, level = (f"Zakazni odatdagidan ~{pct}% KAMAYTIRING.", "down")
    elif avg_daily_purchase > 0 and limit > avg_daily_purchase * 1.2:
        pct = int(round((limit / avg_daily_purchase - 1) * 100))
        advice, level = (f"Bo'sh pul bor — zakazni ~{pct}% ko'paytirsangiz bo'ladi.", "up")
    else:
        advice, level = ("Odatdagi sur'atda davom eting.", "ok")

    return {"horizon": horizon, "available": available,
            "cash": cash, "boxes": boxes, "daily_in": daily_in,
            "expected_in": expected_in, "obligations": obligations, "due": due,
            "top": top, "reserve": reserve, "reserve_manual": reserve_set > 0,
            "limit": max(0.0, limit), "raw_limit": limit,
            "avg_daily_purchase": avg_daily_purchase,
            "advice": advice, "level": level}


def zakaz_limit_text(z):
    """Zakaz limitini o'qiladigan xabarga aylantiradi."""
    icon = {"stop": "🔴", "down": "🟠", "up": "🟢", "ok": "🔵"}.get(z["level"], "🔵")
    t = [f"🎯 <b>Ertangi zakaz limiti</b>", ""]
    t.append(f"{icon} <b>{fmt_money(z['limit'])}</b> gacha zakaz bering")
    t.append(f"<i>{h(z['advice'])}</i>")
    t.append("")
    t.append(f"<b>Hisob ({z['horizon']} kunlik ufq):</b>")
    t.append(f"🏦 Kassada hozir: {fmt_money(z['cash'])}")
    t.append(f"📈 Kutilayotgan tushum: +{fmt_money(z['expected_in'])} "
             f"({fmt_money(z['daily_in'])}/kun)")
    t.append(f"📉 To'lanishi shart: −{fmt_money(z['obligations'])}")
    t.append(f"🛡 Zaxira{' (qo`lda)' if z['reserve_manual'] else ''}: −{fmt_money(z['reserve'])}")
    t.append(f"= {z['horizon']} kunga bo'sh pul: <b>{fmt_money(max(0, z['available']))}</b> "
             f"→ kuniga {fmt_money(z['limit'])}")
    if z["avg_daily_purchase"]:
        t.append(f"📥 Odatdagi zakaz: {fmt_money(z['avg_daily_purchase'])}/kun (30 kun o'rtachasi)")
    if z["top"]:
        t.append("")
        t.append("<b>Pulni band qilayotgan to'lovlar:</b>")
        for e in z["top"]:
            t.append(f"   • {e['date'].strftime('%d-%m')} — {h(e['name'])}: "
                     f"{fmt_money(e['amount'])}")
    return "\n".join(t)


def _bito_try_paths(setting_key, candidates, body, headers, label):
    """Bir nechta ehtimoliy manzilni sinab, ishlaganini QAYTARADI va eslab qoladi.

    ⚠️ Bito manzillari izchil emas: ba'zilari `-pagin`, ba'zilari `-paging`,
    ba'zilari `/get` bilan tugaydi. Bir marta taxmin qilib 404 olgandan ko'ra,
    sinab ko'rib to'g'risini saqlab qo'ygan afzal (amalda ko'rilgan).
    Qaytaradi: (javob_json, ishlagan_manzil) yoki (None, None)."""
    known = get_setting(setting_key, "")
    order = ([known] + [c for c in candidates if c != known]) if known else list(candidates)
    for path in order:
        try:
            r = requests.post(BITO_BASE_URL + path, json=body, headers=headers, timeout=40)
        except Exception as e:
            print(f"{label}: {path} → xato {str(e)[:80]}", flush=True)
            continue
        if r.status_code == 200:
            if path != known:
                set_setting(setting_key, path)
                print(f"✅ {label}: ishlaydigan manzil topildi va saqlandi → {path}", flush=True)
            try:
                return r.json(), path
            except Exception:
                return None, None
        print(f"{label}: {path} → HTTP {r.status_code}", flush=True)
    print(f"❌ {label}: hech qaysi manzil ishlamadi ({len(order)} ta sinaldi)", flush=True)
    return None, None


def bito_stock_and_cost():
    """📦 Har mahsulotning qoldig'i va TANNARXI.

    Manba: reports/dashboard/summary/product/chart-paging — qoldiq (`in_stock`)
    va birlik tannarxi (`cost`) birga keladi (jonli tekshirilgan 2026-07-31).
    Qaytaradi: {product_id: {"name","stock","cost"}}"""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    cands = ["reports/dashboard/summary/product/chart-pagin",
             "reports/dashboard/summary/product/chart-paging",
             "reports/dashboard/summary/product/pagin",
             "reports/dashboard/summary/product/paging",
             "reports/pos/summary/product/chart-pagin",
             "reports/pos/summary/product/chart-paging"]
    out, page = {}, 1
    while page <= 40:                       # ~8000 mahsulotgacha
        j, _p = _bito_try_paths("bito_stockcost_endpoint", cands,
                                {"organization_ids": [CFG.BITO_ORG_ID],
                                 "page": page, "limit": 200},
                                headers, "STOCK+COST")
        if j is None:
            break
        try:
            rows = _bito_rows(j)
        except Exception as e:
            print("STOCK+COST ERR:", str(e)[:150], flush=True)
            break
        if not rows:
            break
        for it in rows:
            pid = it.get("_id")
            if not pid:
                continue
            out[pid] = {"name": it.get("name") or "?",
                        "stock": float(it.get("in_stock") or it.get("amount") or 0),
                        "cost": float(it.get("cost") or 0)}
        if len(rows) < 200:
            break
        page += 1
    print(f"STOCK+COST: {len(out)} ta mahsulot o'qildi", flush=True)
    return out


def sales_velocity(days=30):
    """📈 Mahsulot bo'yicha kunlik o'rtacha sotuv (dona/kg).

    ⚠️ sales/by-item-pagin FAQAT sotilganlarni qaytaradi — umuman sotilmagan
    mahsulot ro'yxatda bo'lmaydi (bu ilgari aniqlangan). Ular uchun tezlik 0."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    start = (now_dt() - timedelta(days=days)).strftime("%Y-%m-%dT00:00:00.000Z")
    out, page = {}, 1
    while page <= 30:
        try:
            r = requests.post(BITO_BASE_URL + "sales/by-item-pagin",
                              json={"page": page, "limit": 200, "from_date": start,
                                    "organization_ids": [CFG.BITO_ORG_ID]},
                              headers=headers, timeout=60)
            if r.status_code != 200:
                print(f"VELOCITY: HTTP {r.status_code}", flush=True)
                break
            rows = _bito_rows(r.json() or {})
        except Exception as e:
            print("VELOCITY ERR:", str(e)[:150], flush=True)
            break
        if not rows:
            break
        for it in rows:
            pid = it.get("product_id") or it.get("_id")
            sold = float(it.get("items_sold") or 0)
            if pid and sold > 0:
                out[pid] = out.get(pid, 0.0) + sold / days
        if len(rows) < 200:
            break
        page += 1
    print(f"VELOCITY: {len(out)} ta sotilgan mahsulot, {days} kun", flush=True)
    return out


def next_visit(visit_days, frm=None):
    """Firmaning keyingi kelish sanasi va undan keyingisigacha necha kun.

    visit_days: "1,4" ko'rinishida (1=Dushanba ... 7=Yakshanba).
    Qaytaradi: (keyingi_sana, qamrov_kunlari) yoki (None, None)."""
    ds = sorted({int(x) for x in str(visit_days or "").split(",") if x.strip().isdigit()})
    if not ds:
        return None, None
    base = frm or now_dt().date()
    nxt = None
    for i in range(1, 15):
        d = base + timedelta(days=i)
        if d.isoweekday() in ds:
            nxt = d
            break
    if not nxt:
        return None, None
    after = None
    for i in range(1, 15):
        d = nxt + timedelta(days=i)
        if d.isoweekday() in ds:
            after = d
            break
    cover = (after - nxt).days if after else 7
    return nxt, cover


def order_recommendation(buffer_ratio=0.2):
    """🛒 Firma bo'yicha zakaz tavsiyasi.

    Har firma uchun: keyingi kelish sanasi, o'sha kundan keyingi kelishigacha
    yetadigan miqdor + zaxira, joriy qoldiqdan ayirilgan holda.
    Qaytaradi: [{"supplier","date","cover","items":[...],"total"}]"""
    refresh_nak_catalog()
    # ⚠️ Eski (noto'g'ri ID bilan saqlangan) jadvallarni SHU YERDA ham ko'chiramiz.
    # Ilgari bu faqat /firmalar sahifasi ochilganda bajarilardi va foydalanuvchi
    # sahifani ochmaguncha zakaz bo'sh chiqaverardi (amalda ko'rilgan).
    try:
        migrate_supplier_plans(bito_suppliers_with_balance())
    except Exception as e:
        print("ZAKAZ: ko'chirishda xato:", str(e)[:120], flush=True)
    plans = supplier_plan_all()
    if not plans:
        return []
    stock = bito_stock_and_cost()
    vel = sales_velocity(30)

    # mahsulot → firma bog'lanishi katalogdan
    by_supplier = {}
    for p in NAK_CATALOG_CACHE["products"]:
        for sid in (p.get("supplier_ids") or []):
            if sid in plans:
                by_supplier.setdefault(sid, []).append(p)

    dues = debt_due_all()
    credit = {c["id"]: c["amount"] for c in bito_suppliers_with_balance()}
    # 🩺 Diagnostika: nega bo'sh chiqayotganini aniqlash uchun
    with_days = sum(1 for p in plans.values() if p.get("visit_days"))
    linked = sum(1 for p in NAK_CATALOG_CACHE["products"] if p.get("supplier_ids"))
    print(f"ZAKAZ: {len(plans)} firma ({with_days} tasida kelish kuni bor), "
          f"katalogda {linked} mahsulotga firma biriktirilgan, "
          f"{len(by_supplier)} firma mahsulotga ega", flush=True)
    if not by_supplier and linked:
        # 🩺 Mos kelmasa — ikkala tomondan namuna ID ko'rsatamiz
        prod_ids = set()
        for pr in NAK_CATALOG_CACHE["products"]:
            prod_ids.update(pr.get("supplier_ids") or [])
        print(f"ZAKAZ: mahsulotdagi firma ID namunasi: {list(prod_ids)[:3]}", flush=True)
        print(f"ZAKAZ: jadvaldagi firma ID namunasi: {list(plans.keys())[:3]}", flush=True)
        both = prod_ids & set(credit.keys())
        print(f"ZAKAZ: Bito firmalari bilan mahsulotlar kesishmasi: {len(both)} ta", flush=True)

    out = []
    for sid, plan in plans.items():
        nxt, cover = next_visit(plan.get("visit_days"))
        if not nxt:
            continue                       # kelish kuni kiritilmagan
        need_days = cover * (1 + buffer_ratio)
        items = []
        for p in by_supplier.get(sid, []):
            pid = p["id"]
            rate = vel.get(pid, 0.0)
            if rate <= 0:
                continue                   # sotilmayapti — zakaz qilmaymiz
            st = stock.get(pid, {})
            have = float(st.get("stock") or 0)
            need = rate * need_days - have
            if need <= 0:
                continue
            # 📏 kg mahsulotni butun songa yaxlitlash noto'g'ri — 0.1 gacha aniqlik
            is_kg = bool(p.get("is_kg"))
            unit = "kg" if is_kg else (p.get("measure_name") or "dona")
            qty = round(need, 1) if is_kg else (int(need) + (1 if need % 1 else 0))
            cost = float(st.get("cost") or 0)
            items.append({"name": st.get("name") or p["name"], "qty": qty,
                          "unit": unit, "cost": cost, "sum": round(qty * cost),
                          "have": round(have, 1) if is_kg else int(have),
                          "rate": round(rate, 2)})
        if not items:
            continue
        items.sort(key=lambda x: -x["sum"])
        total = sum(x["sum"] for x in items)
        debt = float(credit.get(sid) or 0)

        # 💡 O'sha kuni HAQIQATAN qancha naqd pul kerakligi:
        #   • qarzni qaytarib yana qarzga olsa → eski QARZ miqdori
        #   • shunchaki qarzga bersa        → 0 (keyin to'lanadi)
        #   • naqd bo'lsa                   → zakaz summasi
        if plan.get("debt_swap") and debt > 0:
            cash_need, scheme = debt, "qarz almashish"
        elif plan.get("takes_credit"):
            cash_need, scheme = 0.0, "qarzga"
        else:
            cash_need, scheme = total, "naqd"

        out.append({"supplier": plan.get("name") or "—", "supplier_id": sid,
                    "date": nxt, "cover": cover,
                    "is_cash": plan.get("is_cash"),
                    "takes_credit": plan.get("takes_credit"),
                    "debt_swap": plan.get("debt_swap"),
                    "pay_term": plan.get("pay_term_days") or 0,
                    "debt": debt, "cash_need": cash_need, "scheme": scheme,
                    "due_date": (dues.get(sid) or {}).get("due_date", ""),
                    "items": items, "total": total})
    out.sort(key=lambda x: x["date"])
    return out


@bot.message_handler(commands=['zakaz_tavsiya'])
def order_advice_cmd(message):
    """🛒 Firma kelish kunlariga qarab zakaz tavsiyasi + pul tekshiruvi."""
    if message.from_user.id != CFG.SUPER_ADMIN_ID:
        return
    chat_id = message.chat.id

    def run():
        note = bot.send_message(chat_id, "⏳ Zakaz tavsiyasi hisoblanmoqda "
                                         "(qoldiq, sotuv tezligi, pul)...")
        try:
            orders = order_recommendation()
            days, cal = cash_calendar(30)
            bal_by_day = {r["date"]: r["balance"] for r in days}
        except Exception as e:
            print("ORDER ADVICE ERR:", repr(e)[:300], flush=True)
            bot.send_message(chat_id, f"⚠️ Xatolik: {str(e)[:200]}"); return
        try: bot.delete_message(chat_id, note.message_id)
        except Exception: pass

        if not orders:
            bot.send_message(chat_id,
                "Zakaz tavsiyasi chiqmadi. Sabablari:\n"
                "• firmalarga kelish kunlari kiritilmagan (/firmalar)\n"
                "• yoki mahsulotlar Bito'da firmaga biriktirilmagan")
            return

        t = ["🛒 <b>Zakaz tavsiyasi</b>", ""]
        running = float(cal["cash"])
        for o in orders:
            bal = bal_by_day.get(o["date"], running)
            kun = o["date"].strftime("%d-%m")
            hafta = WEEKDAY_NAMES[o["date"].weekday()]
            t.append(f"🏢 <b>{h(o['supplier'])}</b> — {kun} ({hafta})")
            t.append(f"   {o['cover']} kunlik zaxira, {len(o['items'])} ta mahsulot")
            for it in o["items"][:12]:
                u = it.get("unit") or "dona"
                t.append(f"   • {h(it['name'])} — <b>{it['qty']} {u}</b> "
                         f"(qoldiq {it['have']} {u}, kuniga {it['rate']} {u}) "
                         f"= {fmt_money(it['sum'])}")
            if len(o["items"]) > 12:
                t.append(f"   ... va yana {len(o['items'])-12} ta")
            t.append(f"   💵 <b>Zakaz summasi: {fmt_money(o['total'])}</b>")
            if o["scheme"] == "qarz almashish":
                t.append(f"   🔄 <b>Qarz almashish:</b> o'sha kuni eski qarz "
                         f"<b>{fmt_money(o['debt'])}</b> to'lanadi, "
                         f"yangi tovar qarzga olinadi.")
                t.append(f"   💰 Kerak bo'lgan naqd: <b>{fmt_money(o['cash_need'])}</b>")
                if bal < o["cash_need"]:
                    t.append(f"   🔴 <b>Pul yetmaydi!</b> O'sha kuni kassada "
                             f"~{fmt_money(bal)}. "
                             f"{fmt_money(o['cash_need'] - bal)} kam.")
                    t.append("   Zakazni kamaytiring yoki qarzning bir qismini oldinroq to'lang.")
            elif o["scheme"] == "qarzga":
                t.append("   📝 Qarzga olinadi — o'sha kuni naqd kerak emas.")
                if o["pay_term"]:
                    due = o["date"] + timedelta(days=int(o["pay_term"]))
                    t.append(f"   📅 Qaytarish: {o['pay_term']} kundan keyin → "
                             f"<b>{due.strftime('%d-%m')}</b>")
                if o["debt"] > 0:
                    t.append(f"   ⚠️ Bu firmada mavjud qarz: {fmt_money(o['debt'])}")
            else:
                t.append(f"   💰 Naqd to'lanadi: <b>{fmt_money(o['cash_need'])}</b>")
                if bal < o["cash_need"]:
                    t.append(f"   🔴 <b>Pul yetmaydi!</b> O'sha kuni kassada "
                             f"~{fmt_money(bal)}. "
                             f"{fmt_money(o['cash_need'] - bal)} kam.")
            t.append("")
        t.append(f"📊 Jami zakaz: <b>{fmt_money(sum(o['total'] for o in orders))}</b>")
        t.append(f"💰 Shundan naqd kerak: <b>"
                 f"{fmt_money(sum(o['cash_need'] for o in orders))}</b>")
        t.append("")
        t.append("<i>Miqdor oxirgi 30 kunlik sotuv tezligidan hisoblangan, "
                 "ustiga 20% zaxira qo'shilgan. Sotilmayotgan mahsulot zakazga kirmaydi.</i>")
