def daily_rows(goal_id, date_str):
    rows = qall("SELECT id, task, detail, metric, status, result_note FROM goal_daily "
                "WHERE goal_id=? AND plan_date=? ORDER BY id", (goal_id, date_str)) or []
    return [{"id": r[0], "task": r[1], "detail": r[2] or "", "metric": r[3] or "",
             "status": r[4] or "pending", "result_note": r[5] or ""} for r in rows]


def ensure_daily_plan(goal, date_str=None, facts=None):
    """Berilgan kunga reja bor bo'lsa qaytaradi, bo'lmasa AI bilan yaratadi."""
    date_str = date_str or now_dt().strftime("%Y-%m-%d")
    have = daily_rows(goal["id"], date_str)
    if have:
        return have
    ydate = (datetime.strptime(date_str, "%Y-%m-%d").date() - timedelta(days=1)).strftime("%Y-%m-%d")
    yesterday = daily_rows(goal["id"], ydate)
    tasks = goal_daily_plan(goal, facts=facts, yesterday=yesterday)
    for tk in tasks:
        q("INSERT INTO goal_daily (goal_id, plan_date, task, detail, metric, created_at) "
          "VALUES (?,?,?,?,?,?)",
          (goal["id"], date_str, tk.get("task") or "", tk.get("detail") or "",
           tk.get("metric") or "", now_str()))
    return daily_rows(goal["id"], date_str)


def send_daily_plan(chat_id, date_str=None):
    """📅 Bugungi rejani barcha faol maqsadlar bo'yicha yuboradi."""
    date_str = date_str or now_dt().strftime("%Y-%m-%d")
    gs = [g for g in goals_all() if g["is_active"] and g["approved"]]
    if not gs:
        bot.send_message(chat_id, "Tasdiqlangan maqsad yo'q. /maqsad orqali belgilang.")
        return
    # ⚠️ Faktlar HAR SAFAR yangidan o'qiladi — kechagi qoldiqqa tayanmaslik uchun.
    facts = goal_facts()
    by_name, units = _stock_index()
    any_task = False
    for g in gs:
        rows = ensure_daily_plan(g, date_str, facts)
        if not rows:
            continue
        any_task = True
        t = [f"🎯 <b>{h(g['title'])}</b>", f"📅 {date_str}", ""]
        m = types.InlineKeyboardMarkup()
        for r in rows:
            icon = {"done": "✅", "failed": "❌", "pending": "⬜"}.get(r["status"], "⬜")
            t.append(f"{icon} <b>{h(r['task'])}</b>")
            if r["detail"]:
                t.append(f"   {h(r['detail'])}")
            if r["metric"]:
                t.append(f"   📏 <i>{h(r['metric'])}</i>")
            # 📊 Vazifada tilga olingan tovarlarning HOZIRGI qoldig'i
            live = _live_stock_note(r["task"] + " " + r["detail"], by_name, units)
            if live:
                t.append("   📊 <b>Hozir:</b> "
                         + ", ".join(f"{h(n)} — {round(q, 1)} {u}" for n, q, u in live))
            if r["status"] == "pending":
                m.add(
                    types.InlineKeyboardButton(f"✅ {r['task'][:20]}",
                                               callback_data=f"gd_ok_{r['id']}"),
                    types.InlineKeyboardButton("❌", callback_data=f"gd_no_{r['id']}"))
            t.append("")
        send_long_message(chat_id, "\n".join(t), parse_mode="HTML",
                          reply_markup=m if m.keyboard else None)
    if not any_task:
        bot.send_message(chat_id, "Bugunga vazifa tayyorlanmadi. Qayta urinib ko'ring.")


