def _live_stock_note(text, stock_by_name, units_by_name, limit=6):
    """📊 Matnda tilga olingan mahsulotlarning BUGUNGI qoldig'ini qaytaradi.

    ⚠️ Strategiya va bosqichlar bir marta yoziladi va matn ichidagi raqamlar
    o'sha kunda qotib qoladi. Kechagi "2000 dona" bugun 0 bo'lishi mumkin
    (amalda ko'rilgan). Shuning uchun bosqich ko'rsatilganda joriy qoldiqni
    yonida chiqaramiz — foydalanuvchi eskirgan raqamga ishonib qolmasin."""
    if not text or not stock_by_name:
        return []
    low = text.lower()
    hits = []
    for nm, qty in stock_by_name.items():
        if len(nm) < 4:
            continue
        if nm.lower() in low:
            hits.append((nm, qty, units_by_name.get(nm, "dona")))
    hits.sort(key=lambda x: -len(x[0]))
    # bir mahsulot boshqasining ichida bo'lsa (masalan "Coca-Cola" va
    # "Coca-Cola 2L") — uzunrog'i qoladi
    picked, seen = [], []
    for nm, qty, u in hits:
        if any(nm.lower() in s for s in seen):
            continue
        seen.append(nm.lower())
        picked.append((nm, qty, u))
        if len(picked) >= limit:
            break
    return picked


def _stock_index():
    """Mahsulot nomi → (qoldiq, birlik). Bosqichlarda joriy holatni ko'rsatish uchun."""
    try:
        stock = bito_stock_and_cost()
    except Exception:
        return {}, {}
    units = {}
    for p in NAK_CATALOG_CACHE.get("products") or []:
        units[p["id"]] = "kg" if p.get("is_kg") else (p.get("measure_name") or "dona")
    by_name, unit_by_name = {}, {}
    for pid, st in stock.items():
        nm = st.get("name") or ""
        if nm:
            by_name[nm] = st.get("stock") or 0
            unit_by_name[nm] = units.get(pid, "dona")
    return by_name, unit_by_name


MAQSAD_TOKENS = TDict()


def maqsad_token_new(uid):
    import secrets as _secrets
    tok = _secrets.token_urlsafe(16)
    lst = MAQSAD_TOKENS.setdefault(uid, [])
    lst.append(tok)
    del lst[:-8]
    return tok


def maqsad_token_ok(uid, tok):
    return bool(tok) and tok in (MAQSAD_TOKENS.get(uid) or [])


