@bot.callback_query_handler(func=lambda c: c.data == "maqsad_holat")
def maqsad_holat_cb(call):
    _ack(call)
    chat_id = call.message.chat.id
    gs = [g for g in goals_all() if g["is_active"]]
    if not gs:
        bot.send_message(chat_id, "Hali maqsad belgilanmagan."); return
    t = ["📊 <b>Maqsadlar holati</b>", ""]
    for g in gs:
        steps = goal_steps(g["id"])
        done = sum(1 for s in steps if s["status"] == "done")
        pct = int(done * 100 / len(steps)) if steps else 0
        bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
        t.append(f"🎯 <b>{h(g['title'])}</b>")
        t.append(f"   Maqsad: {g['target_value']}{g['target_unit']}"
                 + (f", {g['deadline']} gacha" if g["deadline"] else ""))
        if not g["approved"]:
            t.append("   ⏳ Strategiya hali tasdiqlanmagan")
        elif steps:
            t.append(f"   {bar} {pct}% ({done}/{len(steps)})")
            nxt = next((s for s in steps if s["status"] == "pending"), None)
            if nxt:
                t.append(f"   ▶️ Keyingi: {h(nxt['title'])}")
        t.append("")
    m = types.InlineKeyboardMarkup()
    for g in gs:
        if g["approved"]:
            m.add(types.InlineKeyboardButton(f"▶️ {g['title'][:28]}",
                                             callback_data=f"mq_step_{g['id']}"))
    send_long_message(chat_id, "\n".join(t), parse_mode="HTML",
                      reply_markup=m if m.keyboard else None)


@bot.callback_query_handler(func=lambda c: c.data.startswith("mq_step_"))
def maqsad_steps_cb(call):
    _ack(call)
    gid = int(call.data.split("_")[-1])
    g = next((x for x in goals_all() if x["id"] == gid), None)
    if not g:
        return
    steps = goal_steps(gid)
    by_name, units = _stock_index()      # 📊 BUGUNGI qoldiqlar
