        icon = {"done": "✅", "skipped": "⏭", "pending": "⬜"}.get(s["status"], "⬜")
        t.append(f"{icon} <b>{s['step_no']}. {h(s['title'])}</b>")
        if s["detail"]:
            t.append(f"   {h(s['detail'])}")
        live = _live_stock_note(s["title"] + " " + s["detail"], by_name, units)
