def build_goal_strategy(chat_id, g, base):
    """Maqsad uchun strategiya yozib, tasdiqlash tugmalari bilan yuboradi."""
    strat, steps = goal_generate_strategy(g, base)
    if not strat:
        bot.send_message(chat_id, f"⚠️ '{g['title']}' uchun strategiya tayyorlanmadi. "
                                  f"Qayta urinib ko'ring.")
        return
    # ⚠️ Bajarilgan bosqichlar YO'QOLMASIN — ular tarix, qayta yozilmaydi.
    done_titles = [s["title"] for s in goal_steps(g["id"]) if s["status"] == "done"]
    q("UPDATE goals SET strategy=?, approved=0, updated_at=? WHERE id=?",
      (strat, now_str(), g["id"]))
    q("DELETE FROM goal_steps WHERE goal_id=? AND status!='done'", (g["id"],))
    base_no = len(done_titles)
    kept = 0
    for st in steps:
        ttl = st.get("title") or ""
        if ttl in done_titles:
            kept += 1
            continue                  # allaqachon bajarilgan — takrorlamaymiz
        kept += 1
        q("INSERT INTO goal_steps (goal_id, step_no, title, detail) VALUES (?,?,?,?)",
          (g["id"], base_no + kept, ttl, st.get("detail") or ""))
    t = [f"🎯 <b>{h(g['title'])}</b>",
         f"Maqsad: {g['target_value']}{g['target_unit']}"
         + (f", {g['deadline']} gacha" if g["deadline"] else ""), "",
         f"<b>Strategiya:</b> {h(strat)}", "", "<b>Bosqichlar:</b>"]
    for i, st in enumerate(steps, 1):
        t.append(f"{i}. <b>{h(st.get('title') or '')}</b>")
        if st.get("detail"):
            t.append(f"   {h(st['detail'])}")
    m = types.InlineKeyboardMarkup()
    m.add(types.InlineKeyboardButton("✅ Tasdiqlash", callback_data=f"mq_ok_{g['id']}"))
    m.add(types.InlineKeyboardButton("🔄 Boshqa variant", callback_data=f"mq_redo_{g['id']}"))
    send_long_message(chat_id, "\n".join(t), parse_mode="HTML", reply_markup=m)


