def bito_search_products(query, limit=10):
    """Mahsulot nomini qidirib topadi (product/get-paging orqali)."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.post(BITO_BASE_URL + "product/get-paging",
                         json={"page": 1, "limit": limit, "search": query},
                         headers=headers, timeout=15)
        r.raise_for_status()
        j = r.json()
        # ⚠️ 2026-08-09 tuzatish: bu endpoint data'ni ba'zan BIR, ba'zan
        # IKKI qavat qaytaradi ({"data":[...]} yoki {"data":{"data":[...]}}).
        # Bir qavatga qattiq bog'lanish "hech narsa topilmadi"ga olib kelgan.
        d = j.get("data", [])
        items = d.get("data", []) if isinstance(d, dict) else (d or [])
        if not isinstance(items, list):
            items = []
        print(f"BITO SEARCH '{query[:30]}': {len(items)} ta", flush=True)
        result = []
        for it in items:
            if not isinstance(it, dict):
                continue
            # Qoldiq javobning o'zida bor (organizations[].amount) —
            # har mahsulotga alohida so'rov shart emas
            stock = 0
            for org in (it.get("organizations") or []):
                if org.get("organization_id") == CFG.BITO_ORG_ID:
                    stock = org.get("amount", 0) or 0
                    break
            result.append({"_id": it.get("_id"), "name": it.get("name", "?"),
                           "amount": stock, "in_stock": stock,
                           "measure": it.get("measure", {})})
        return result
    except Exception as e:
        print("STOCK SEARCH ERR:", str(e)[:150], flush=True)
        return []

def bito_get_stock_for_product(product_id):
    """Bitta mahsulotning joriy qoldig'ini oladi."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.post(BITO_BASE_URL + "product-warehouse/get-paging",
                         json={"page": 1, "limit": 20},
                         headers=headers, timeout=15)
        r.raise_for_status()
        items = r.json().get("data", [])
        total = 0
        found = False
        for it in items:
            if isinstance(it, dict) and it.get("product_id") == product_id:
                total += it.get("amount", 0) or 0
                found = True
        return total if found else None
    except Exception as e:
        print("STOCK GET ERR:", str(e)[:150], flush=True)
        return None

def bito_get_stock_by_name(product_name, product_id):
    """Mahsulot nomi bo'yicha qidirib, product_id bilan moslashtiradi va qoldig'ini qaytaradi."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.post(BITO_BASE_URL + "product-warehouse/get-paging",
                         json={"search": product_name, "limit": 10, "page": 1},
                         headers=headers, timeout=15)
        r.raise_for_status()
        items = r.json().get("data", [])
        total = sum((it.get("amount", 0) or 0) for it in items
                   if isinstance(it, dict) and it.get("product_id") == product_id)
        return total
    except Exception as e:
        print("STOCK NAME ERR:", str(e)[:100], flush=True)
        return None

# ===== KUNLIK AI SAVDO TAVSIYASI (xodimlarga cross-sell, boshliqqa narx/skidka) =====
def bito_get_items_sorted(from_iso, to_iso, limit=50, ascending=False):
    """sales/by-item-pagin dan items_sold bo'yicha saralangan ro'yxatni oladi."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        body = {"page": 1, "limit": limit, "from_date": from_iso, "to_date": to_iso,
                "organization_ids": [CFG.BITO_ORG_ID], "sort_by": "items_sold",
                "sort_order": "asc" if ascending else "desc"}
        r = requests.post(BITO_BASE_URL + "sales/by-item-pagin", json=body, headers=headers, timeout=30)
        r.raise_for_status()
        j = r.json(); d = j.get("data", {})
        items = d.get("data", []) if isinstance(d, dict) else (d or [])
        return items if isinstance(items, list) else []
    except Exception as e:
        print("BITO ITEMS SORT ERR:", str(e)[:150], flush=True)
        return []

def bito_get_sold_product_ids(days, page_limit=300, max_pages=15):
    """Berilgan necha kun ichida KAMIDA BIR MARTA sotilgan mahsulot ID'lari to'plamini qaytaradi.
    MUHIM: sales/by-item-pagin faqat SOTILGAN mahsulotlarni ko'rsatadi — umuman
    sotilmagan mahsulotlar bu hisobotda ko'rinmaydi, shuning uchun ularni aniqlash
    uchun butun katalogdan AYIRIB tashlash kerak (pastdagi funksiyaga qarang)."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    period_start = (now_dt() - timedelta(days=days)).strftime("%Y-%m-%d")
    df, dt_ = bito_range_utc(period_start, today_str())
    sold_ids = set()
    page = 1
    while page <= max_pages:
        try:
            body = {"page": page, "limit": page_limit, "from_date": df, "to_date": dt_,
                    "organization_ids": [CFG.BITO_ORG_ID]}
            r = requests.post(BITO_BASE_URL + "sales/by-item-pagin", json=body, headers=headers, timeout=30)
            r.raise_for_status()
            j = r.json(); d = j.get("data", {})
            items = d.get("data", []) if isinstance(d, dict) else (d or [])
            total = d.get("total", 0) if isinstance(d, dict) else 0
            if not items:
                break
            for it in items:
                if isinstance(it, dict):
                    pid = it.get("product_id") or it.get("_id")
                    sold = it.get("items_sold", 0) or 0
                    if pid and sold > 0:
                        sold_ids.add(str(pid))
            if page * page_limit >= total:
                break
            page += 1
        except Exception as e:
            print("SOLD IDS ERR:", str(e)[:120], flush=True)
            break
    return sold_ids

def bito_get_all_products_with_stock(page_limit=200, max_pages=30, min_stock=1):
    """Butun mahsulot katalogini (nomi, id, ombordagi qoldig'i) qaytaradi — faqat
    qoldig'i min_stock dan ko'p bo'lganlar (ombordan tugab qolgan mahsulotlar
    'turib qolgan' hisoblanmaydi, chunki sotib bo'lingan bo'lishi mumkin)."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    result = []
    page = 1
    while page <= max_pages:
        try:
            r = requests.post(BITO_BASE_URL + "product/get-paging",
                               json={"page": page, "limit": page_limit},
                               headers=headers, timeout=30)
            r.raise_for_status()
            j = r.json(); d = j.get("data", {})
            items = d.get("data", []) if isinstance(d, dict) else (d or [])
            total = d.get("total", 0) if isinstance(d, dict) else 0
            if not items:
                break
            for p in items:
                if not isinstance(p, dict):
                    continue
                whs = p.get("_warehouses") or {}
                stock = 0
                if isinstance(whs, dict):
                    stock = sum((v.get("amount", 0) or 0) for v in whs.values() if isinstance(v, dict))
                elif isinstance(whs, list):
                    stock = sum((w.get("amount", 0) or 0) for w in whs if isinstance(w, dict))
                if stock >= min_stock:
                    result.append({"id": str(p.get("_id")), "name": p.get("name", "?"), "stock": stock})
            if page * page_limit >= total:
                break
            page += 1
        except Exception as e:
            print("ALL PRODUCTS ERR:", str(e)[:120], flush=True)
            break
    return result

# ══════════════════════════════════════════════════════════════════
# 👥 MIJOZLAR ABC-XYZ TAHLILI + AVTOMATIK VAZIFA QOIDALARI
# ABC = xarid summasi bo'yicha ahamiyat (A=eng ko'p, C=eng kam)
# XYZ = xarid muntazamligi (X=barqaror, Z=tartibsiz/kamdan-kam)
# ══════════════════════════════════════════════════════════════════
ABC_SEGMENTS = ["AX","AY","AZ","BX","BY","BZ","CX","CY","CZ"]
ABC_SEGMENT_DESC = {
    "AX": "Eng qimmatli va barqaror mijozlar",
    "AY": "Qimmatli, o'rtacha barqaror",
    "AZ": "Qimmatli, lekin tartibsiz xarid qiladi",
    "BX": "O'rtacha qiymat, barqaror",
    "BY": "O'rtacha qiymat, o'rtacha barqaror",
    "BZ": "O'rtacha qiymat, tartibsiz",
    "CX": "Kam xarid, lekin barqaror",
    "CY": "Kam xarid, o'rtacha barqaror",
    "CZ": "Kam xarid VA tartibsiz — yo'qotish xavfi yuqori",
}

def bito_get_customers_abc_xyz(from_date, to_date, max_pages=5, page_limit=200):
    """Bito'dan barcha mijozlarning ABC-XYZ segmentini oladi (sahifalab)."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    all_items = []
    page = 1
    while page <= max_pages:
        try:
            r = requests.post(BITO_BASE_URL + "reports/analysis/customers/abc-xyz",
                              json={"from_date": from_date, "to_date": to_date,
                                    "organization_ids": [CFG.BITO_ORG_ID],
                                    "page": page, "limit": page_limit},
                              headers=headers, timeout=30)
            if r.status_code != 200:
                print(f"ABC-XYZ ERR: HTTP {r.status_code} | {r.text[:200]}", flush=True)
                break
            d = r.json().get("data", {})
            items = d.get("data", []) if isinstance(d, dict) else (d or [])
            total = d.get("total", 0) if isinstance(d, dict) else 0
            if not items:
                break
            all_items.extend(items)
            if page * page_limit >= total:
                break
            page += 1
        except Exception as e:
            print("ABC-XYZ FETCH ERR:", str(e)[:150], flush=True)
            break
    return all_items

def _abc_period_month():
    """Joriy oy boshidan bugungacha (standart tahlil davri)."""
    start = now_dt().replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    return start.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z"), \
           now_dt().astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")

@bot.message_handler(commands=['mijozlar_abc'])
def mijozlar_abc_cmd(message):
    if not is_boss_or_mgr(message.from_user.id): return
    bot.send_message(message.chat.id, "⏳ Bito'dan mijozlar tahlili olinmoqda...")
    def run():
        df, dt_ = _abc_period_month()
        items = bito_get_customers_abc_xyz(df, dt_)
        if not items:
            bot.send_message(message.chat.id, "⚠️ Ma'lumot topilmadi yoki xatolik yuz berdi."); return
        counts = {seg: 0 for seg in ABC_SEGMENTS}
        revenue = {seg: 0 for seg in ABC_SEGMENTS}
        for it in items:
            seg = it.get("segment", "")
            if seg in counts:
                counts[seg] += 1
                revenue[seg] += it.get("revenue", 0) or 0
        lines = [f"👥 <b>Mijozlar ABC-XYZ tahlili</b>", f"Jami: {len(items)} mijoz\n"]
        for seg in ABC_SEGMENTS:
            if counts[seg]:
                lines.append(f"<b>{seg}</b> ({counts[seg]} ta, {fmt_money(int(revenue[seg]))}) — {ABC_SEGMENT_DESC[seg]}")
        send_long_message(message.chat.id, "\n".join(lines), parse_mode="HTML")
        mk = types.InlineKeyboardMarkup()
        for seg in ABC_SEGMENTS:
            if counts[seg]:
                mk.add(types.InlineKeyboardButton(f"{seg} ro'yxati ({counts[seg]})", callback_data=f"abcseg_{seg}"))
        bot.send_message(message.chat.id, "Qaysi segment mijozlarini ko'rmoqchisiz?", reply_markup=mk)
    threading.Thread(target=run, daemon=True).start()

@bot.callback_query_handler(func=lambda c: c.data.startswith("abcseg_"))
def abc_segment_list(call):
    if not is_boss_or_mgr(call.from_user.id): return
    seg = call.data.replace("abcseg_", "")
    _ack(call)
    def run():
        df, dt_ = _abc_period_month()
        items = bito_get_customers_abc_xyz(df, dt_)
        seg_items = [it for it in items if it.get("segment") == seg]
        seg_items.sort(key=lambda x: -(x.get("revenue") or 0))
        lines = [f"👥 <b>{seg} — {h(ABC_SEGMENT_DESC.get(seg,''))}</b>\n"]
        for it in seg_items[:40]:
            cust = it.get("customer", {}) or {}
            lines.append(f"• {h(cust.get('name','?'))} ({h(cust.get('phone_number','—'))}) — "
                        f"{fmt_money(int(it.get('revenue',0) or 0))}")
        if len(seg_items) > 40:
            lines.append(f"\n... va yana {len(seg_items)-40} ta")
        send_long_message(call.message.chat.id, "\n".join(lines), parse_mode="HTML")
    threading.Thread(target=run, daemon=True).start()

