def abc_auto_task_thread():
    """Har kuni bir marta: barcha faol qoidalarni tekshirib, mos segmentdagi
    mijozlar uchun (oyiga 1 marta) avtomatik vazifa yaratadi."""
    last_run_date = None
    while True:
        try:
            cur_date = today_str()
            if cur_date != last_run_date and now_dt().strftime("%H:%M") == "09:30":
                last_run_date = cur_date
                rules = qall("SELECT id, segment, employee_tg_id, task_template FROM abc_rules WHERE enabled=1")
                if rules:
                    df, dt_ = _abc_period_month()
                    items = bito_get_customers_abc_xyz(df, dt_)
                    month = now_dt().strftime("%Y-%m")
                    for rid, seg, emp_id, tmpl in rules:
                        seg_items = [it for it in items if it.get("segment") == seg]
                        for it in seg_items:
                            cust = it.get("customer", {}) or {}
                            cust_id = cust.get("_id") or it.get("_id")
                            already = qone("SELECT id FROM abc_task_log WHERE customer_id=? AND rule_id=? AND month=?",
                                          (cust_id, rid, month))
                            if already:
                                continue
                            task_text = (tmpl.replace("{ism}", cust.get("name","?"))
                                             .replace("{telefon}", cust.get("phone_number","—"))
                                             .replace("{summa}", fmt_money(int(it.get("revenue",0) or 0))))
                            emp = get_user(emp_id)
                            emp_name = emp[1] if emp else "?"
                            cur = q("INSERT INTO tasks (given_by,employee_tg_id,employee_name,task,status,reminder_interval,last_reminded,created_at) "
                                    "VALUES (?,?,?,?,'Jarayonda',120,?,?)",
                                    (CFG.SUPER_ADMIN_ID, emp_id, emp_name, task_text, now_str(), now_str()))
                            task_id = cur.lastrowid if cur else 0
                            q("INSERT OR IGNORE INTO abc_task_log (customer_id, segment, month, rule_id, created_at) VALUES (?,?,?,?,?)",
                              (cust_id, seg, month, rid, now_str()))
                            markup = types.InlineKeyboardMarkup()
                            markup.add(types.InlineKeyboardButton("✅ Bajarildi", callback_data=f"done_task_{task_id}"))
                            try:
                                bot.send_message(emp_id, f"📋 <b>Yangi vazifa (ABC-XYZ, {seg}):</b>\n\n{h(task_text)}",
                                                 parse_mode="HTML", reply_markup=markup)
                            except Exception as e:
                                print("ABC TASK SEND ERR:", str(e)[:120], flush=True)
        except Exception as e:
            print("ABC AUTO TASK THREAD ERR:", str(e)[:150], flush=True)
        time.sleep(300)  # har 5 daqiqada tekshiradi (faqat 09:30 da ishga tushadi)
