@bot.message_handler(func=lambda m: W_JOB_CREATE.get(m.from_user.id, {}).get("step") == "requirements")
def hr_new_requirements(message):
    uid = message.from_user.id
    state = W_JOB_CREATE.get(uid)
    if message.text in MENU_TEXTS:
        W_JOB_CREATE.pop(uid, None); return
    bot.send_message(uid, "🧠 AI talablarni tahlil qilib, to'liq savollar ro'yxatini tayyorlamoqda...")
    def run():
        draft = job_ai_draft(state["title"], message.text.strip())
        state["requirements"] = draft.get("requirements_clean", "")
        state["questions"] = draft.get("questions", [])
        state["target_lat"] = draft.get("target_lat")
        state["target_lon"] = draft.get("target_lon")
        state["radius_km"] = draft.get("radius_km")
        state["needs_photo"] = draft.get("needs_photo", False)
        state["needs_location"] = draft.get("needs_location", False)
        state["gender_requirement"] = draft.get("gender_requirement", "")
        state["step"] = "review"
        q_text = "\n".join(f"{i+1}. {qq}" for i, qq in enumerate(state["questions"]))
        extras = []
        if state["target_lat"] and state["target_lon"]:
            extras.append(f"📍 Lokatsiya tekshiruvi: {state['target_lat']:.6f}, {state['target_lon']:.6f}"
                          f" (radius: {state['radius_km'] or '—'} km)")
        if state["needs_photo"]: extras.append("📷 Rasm talab qilinadi")
        if state["gender_requirement"]: extras.append(f"👤 Jins talabi: {state['gender_requirement']}")
        extras_text = ("\n" + "\n".join(extras) + "\n") if extras else ""
        text = (f"🧑‍💼 <b>Vakansiya loyihasi</b>\n\n"
                f"📌 Lavozim: <b>{h(state['title'])}</b>\n\n"
                f"📋 Talablar:\n{h(state['requirements'])}\n"
                f"{h(extras_text)}\n"
                f"❓ Skrining savollari:\n{h(q_text)}\n\n"
                f"To'g'rimi?")
        mk = types.InlineKeyboardMarkup()
        mk.add(types.InlineKeyboardButton("✅ Tasdiqlash va e'lon qilish", callback_data="hr_approve"))
        mk.add(types.InlineKeyboardButton("🔄 Qaytadan yozish", callback_data="hr_restart"))
        mk.add(types.InlineKeyboardButton("❌ Bekor qilish", callback_data="hr_cancel"))
        send_long_message(uid, text, parse_mode="HTML")
        bot.send_message(uid, "Tasdiqlaysizmi?", reply_markup=mk)
    threading.Thread(target=run, daemon=True).start()

@bot.callback_query_handler(func=lambda c: c.data in ("hr_approve", "hr_restart", "hr_cancel"))
def hr_review_cb(call):
    uid = call.from_user.id
    state = W_JOB_CREATE.get(uid)
    _ack(call)
    if not state: return
    if call.data == "hr_cancel":
        W_JOB_CREATE.pop(uid, None)
        bot.send_message(call.message.chat.id, "❌ Bekor qilindi."); return
    if call.data == "hr_restart":
        W_JOB_CREATE[uid] = {"step": "title"}
        bot.send_message(call.message.chat.id, "Lavozim nomini qayta yozing:"); return
    # hr_approve
    import json as _json
    cur = q("INSERT INTO job_postings (title, requirements, questions, status, created_by, approved_by, "
            "created_at, approved_at, target_lat, target_lon, radius_km) VALUES (?,?,?,'approved',?,?,?,?,?,?,?)",
            (state["title"], state["requirements"], _json.dumps(state["questions"], ensure_ascii=False),
             uid, uid, now_str(), now_str(), state.get("target_lat"), state.get("target_lon"), state.get("radius_km")))
    if not cur or not cur.lastrowid:
        W_JOB_CREATE.pop(uid, None)
        bot.send_message(call.message.chat.id,
            "⚠️ Vakansiyani saqlashda xatolik yuz berdi. Railway loglarida <code>DB ERR</code> "
            "qatorini tekshiring va dasturchiga xabar bering.", parse_mode="HTML")
        return
    job_id = cur.lastrowid
    W_JOB_CREATE.pop(uid, None)
    link = f"https://t.me/{_bot_username()}?start=job_{job_id}"
    bot.send_message(call.message.chat.id,
        f"✅ <b>Vakansiya e'lon qilindi!</b>\n\n"
        f"📌 {h(state['title'])}\n\n"
        f"🔗 Shu havolani reklama/kanalga joylashtiring:\n<code>{h(link)}</code>\n\n"
        f"Nomzodlar shu havola orqali botga kirib, ariza topshiradi. "
        f"AI ular bilan suhbatlashib baholaydi, natijalarni sizga yuboradi.",
        parse_mode="HTML")

