@bot.callback_query_handler(func=lambda c: c.data.startswith("hrcands_"))
def hr_candidates_cb(call):
    if not is_boss_or_mgr(call.from_user.id): return
    job_id = int(call.data.replace("hrcands_", ""))
    _ack(call)
    job = qone("SELECT title FROM job_postings WHERE id=?", (job_id,))
    rows = qall("SELECT id, full_name, phone, ai_score, ai_summary, tg_id, "
                "photo_file_id, loc_lat, loc_lon, loc_distance_km FROM job_applicants "
                "WHERE job_id=? AND status='completed' ORDER BY ai_score DESC", (job_id,))
    if not rows:
        bot.send_message(call.message.chat.id, "📭 Hali baholangan nomzod yo'q."); return
    chat_id = call.message.chat.id
    bot.send_message(chat_id,
        f"📊 <b>{h(job[0] if job else '?')} — Nomzodlar (reyting bo'yicha)</b>",
        parse_mode="HTML")
    # 2026-08-08 so'rov: har nomzod rasmi va lokatsiyasi bilan alohida karta
    for i, (aid, name, phone, score, summary, atg,
            photo_fid, lat, lon, dist) in enumerate(rows, 1):
        medal = {1:"🥇",2:"🥈",3:"🥉"}.get(i, f"{i}.")
        loc_line = ""
        if lat and lon:
            d = f"{dist:.1f} km uzoqlikda" if dist is not None else "lokatsiya bor"
            loc_line = (f"\n📍 {d} — "
                        f"<a href=\"https://maps.google.com/?q={lat},{lon}\">"
                        f"xaritada ko'rish</a>")
        head = (f"{medal} <b>{h(name)}</b> — {score:.0f}/100\n"
                f"📞 {h(phone)}{loc_line}")
        body = f"{head}\n💬 {h(summary)}"
        if photo_fid:
            # Telegram rasm izohi 1024 belgidan oshsa jimgina rad etadi —
            # sig'sa birga, sig'masa rasm alohida, matn alohida
            if len(body) <= 1000:
                try:
                    bot.send_photo(chat_id, photo_fid, caption=body,
                                   parse_mode="HTML")
                    continue
                except Exception:
                    pass
            try:
                bot.send_photo(chat_id, photo_fid)
            except Exception:
                pass
        bot.send_message(chat_id, body, parse_mode="HTML",
                         disable_web_page_preview=True)

# ===== Nomzod: ariza topshirish va AI intervyu =====
def _job_get(job_id):
    row = qone("SELECT id, title, requirements, questions, status, target_lat, target_lon, radius_km "
              "FROM job_postings WHERE id=?", (job_id,))
    if not row: return None
    import json as _json
    return {"id": row[0], "title": row[1], "requirements": row[2],
            "questions": _json.loads(row[3] or "[]"), "status": row[4],
            "target_lat": row[5], "target_lon": row[6], "radius_km": row[7]}

def job_interview_reply(job, history):
    """Claude navbatdagi intervyu javobini yozadi. Suhbat tugagan bo'lsa
    javob oxirida [INTERVYU_TUGADI] belgisini qo'shadi."""
    loc_note = ""
    if job.get("target_lat") and job.get("target_lon"):
        loc_note = (f"\n\nMANZIL TEKSHIRUVI KERAK: suhbat davomida nomzoddan YASHASH manzili "
                    f"lokatsiyasini yuborishni ALOHIDA so'ra (Telegram'ning 📎 lokatsiya yuborish "
                    f"tugmasi orqali). U yuborgach, tizim sizga masofani avtomatik xabar qiladi — "
                    f"o'sha xabarni ko'rib, agar radius doirasidan tashqarida bo'lsa buni nomzodga "
                    f"ochiq va muloyim tarzda ayting; agar ichkarida bo'lsa, ijobiy izoh bering. "
                    f"Lokatsiya bir marta qabul qilingach, qayta so'rama.")
    system = (f"Sen \"{job['title']}\" lavozimiga ishga qabul qiluvchi samimiy, professional va "
              f"OGOH (diqqatli) HR-intervyuerisisan. Suhbatni savdo/xizmat sohasiga xos iliqlik va "
              f"hurmat bilan olib bor.\n\n"
              f"TALABLAR:\n{job['requirements']}\n\n"
              f"SO'RASH KERAK BO'LGAN SAVOLLAR (barchasini, birma-bir so'ra, birortasini o'tkazib "
              f"yubormaslikka harakat qil):\n" + "\n".join(f"- {qq}" for qq in job['questions']) +
              f"{loc_note}\n\n"
              "QOIDALAR:\n"
              "1. Bir vaqtda FAQAT bitta savol ber — hech qachon ikkita savolni bitta xabarda birlashtirma.\n"
              "2. Nomzodning oldingi ish joyi/tajribasi haqida ALBATTA so'ra (agar ro'yxatda bo'lmasa ham).\n"
              "3. Javobga qarab kerak bo'lsa qisqa aniqlashtiruvchi savol ber, lekin suhbatni cho'zib yuborma.\n"
              "4. Agar tizim sizga \"[Nomzod rasmini yubordi]\" yoki \"[Nomzod lokatsiyasini yubordi]\" "
              "degan xabar bersa — buni ALLAQACHON qabul qilingan deb bil, qayta so'rama, faqat qisqa "
              "tabriq/tasdiq bilan keyingi savolga o't.\n"
              "5. Barcha savollarga javob olingach (odatda 8-12 xabar), nomzodga vaqt ajratgani "
              "uchun samimiy rahmat ayt va suhbatni yakunla. YAKUNLASH XABARINGNI albatta "
              "[INTERVYU_TUGADI] belgisi bilan tugat (foydalanuvchi buni ko'rmaydi).")
    headers = {"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01",
               "content-type": "application/json"}
    resp = requests.post("https://api.anthropic.com/v1/messages", headers=headers,
                         json={"model": "claude-sonnet-4-6", "max_tokens": 500,
                               "system": system, "messages": history}, timeout=60)
    resp.raise_for_status()
    content = resp.json().get("content", [])
    return "".join(b.get("text", "") for b in content if b.get("type") == "text")

def job_score_candidate(job, history):
    """Intervyu tugagach, Claude nomzodni baholaydi."""
    import json as _json
    transcript = "\n".join(f"{'Nomzod' if m['role']=='user' else 'HR'}: "
                           f"{m['content'] if isinstance(m['content'],str) else ''}" for m in history)
    prompt = f"""Quyidagi ish suhbati (intervyu) transkriptini talablarga solishtirib baholang.

LAVOZIM: {job['title']}
TALABLAR: {job['requirements']}

SUHBAT:
{transcript}

FAQAT JSON qaytar: {{"score": <0-100 son>, "summary": "<2-3 gapli qisqa xulosa>", "strengths": "<kuchli tomonlari>", "concerns": "<xavotirli/yetishmayotgan tomonlari>"}}"""
    raw = _call_claude(prompt, max_tokens=600)
    try:
        clean = raw.strip()
        if clean.startswith("```"):
            clean = clean.strip("`").replace("json", "", 1).strip()
        return _json.loads(clean)
    except Exception as e:
        print("JOB SCORE ERR:", str(e)[:150], flush=True)
        return {"score": 50, "summary": "Baholab bo'lmadi.", "strengths": "-", "concerns": "-"}

def _apply_interrupted(message):
    """Ariza jarayonini TO'XTATISH kerakmi?

    Muammo: ariza handlerlari har qanday matnni javob deb qabul qilardi. Shu sababli
    menyu tugmasi bosilsa ("⬅️ Asosiy menyu") u ISM sifatida, /start esa TELEFON
    sifatida saqlanib, boshliqning o'zi nomzodga aylanib qolgan edi.
    Endi buyruq yoki menyu tugmasi kelsa — ariza bekor qilinadi va menyu ochiladi."""
    txt = (message.text or "").strip()
    if not txt:
        return False
    if txt.startswith("/") or txt in ALL_MENU_BTNS or txt in _menu_group_names():
        uid = message.from_user.id
        W_APPLY.pop(uid, None)
        u = get_user(uid)
        if u:
            bot.send_message(uid, "↩️ Ariza to'ldirish bekor qilindi.",
                             reply_markup=(admin_kb() if is_boss_or_mgr(uid) else emp_kb()))
        else:
            bot.send_message(uid, "↩️ Ariza to'ldirish bekor qilindi. Qayta boshlash uchun "
                                  "vakansiya havolasini qayta oching.")
        return True
    return False


def _menu_group_names():
    """Menyu papkalari nomlari — ular ham matnli tugma, ariza javobi emas."""
    try:
        import json as _json
        return set((_json.loads(get_setting("menu_groups", "{}") or "{}") or {}).keys())
    except Exception:
        return set()


def start_job_application(message, job_id):
    tg_id = message.from_user.id
    job = _job_get(job_id)
    if not job or job["status"] != "approved":
        bot.send_message(tg_id, "⚠️ Bu vakansiya faol emas yoki topilmadi."); return
    # 🚫 Ro'yxatdan o'tgan xodim/boshliq ariza topshira olmaydi — bu havolani sinash
    # uchun bosganda o'z akkauntini nomzodga aylantirib yuborardi.
    u = get_user(tg_id)
    if u:
        bot.send_message(tg_id,
            "ℹ️ Siz allaqachon tizimda ro'yxatdan o'tgansiz — ariza topshirish shart emas.\n"
            "Bu havola yangi nomzodlar uchun.",
            reply_markup=(admin_kb() if is_boss_or_mgr(tg_id) else emp_kb()))
        return
    existing = qone("SELECT id, status FROM job_applicants WHERE job_id=? AND tg_id=?", (job_id, tg_id))
    if existing and existing[1] == "completed":
        bot.send_message(tg_id, "✅ Siz bu vakansiyaga allaqachon ariza topshirgansiz. Natijangiz ko'rib chiqilmoqda, tez orada bog'lanamiz."); return
    W_APPLY[tg_id] = {"job_id": job_id, "step": "name"}
    bot.send_message(tg_id,
        f"👋 Assalomu alaykum!\n\n🧑‍💼 <b>{h(job['title'])}</b> lavozimiga arizangiz uchun rahmat.\n\n"
        f"Avval to'liq ismingizni yozing:", parse_mode="HTML")

@bot.message_handler(func=lambda m: W_APPLY.get(m.from_user.id, {}).get("step") == "name")
def apply_name(message):
    if _apply_interrupted(message): return
    uid = message.from_user.id
    W_APPLY[uid]["full_name"] = message.text.strip()
    W_APPLY[uid]["step"] = "phone"
    bot.send_message(uid, "📞 Telefon raqamingizni yozing (masalan: +998901234567):")

@bot.message_handler(func=lambda m: W_APPLY.get(m.from_user.id, {}).get("step") == "phone")
def apply_phone(message):
    if _apply_interrupted(message): return
    uid = message.from_user.id
    state = W_APPLY[uid]
    state["phone"] = message.text.strip()
    job = _job_get(state["job_id"])
    q("INSERT OR REPLACE INTO job_applicants (job_id, tg_id, full_name, phone, status, created_at) "
      "VALUES (?,?,?,?,'in_progress',?)",
      (state["job_id"], uid, state["full_name"], state["phone"], now_str()))
    state["step"] = "interview"
    state["history"] = []
    bot.send_message(uid, f"✅ Rahmat, {h(state['full_name'])}!\n\nEndi bir nechta savol beraman — tabiiy suhbat kabi javob bering 🙂", parse_mode="HTML")
    def run():
        reply = job_interview_reply(job, [{"role":"user","content":"Salom, suhbatni boshlang."}])
        state["history"] = [{"role":"user","content":"Salom, suhbatni boshlang."},
                            {"role":"assistant","content":reply}]
        clean = reply.replace("[INTERVYU_TUGADI]", "").strip()
        bot.send_message(uid, clean)
    threading.Thread(target=run, daemon=True).start()

def _finish_interview(uid, state, job):
    """Intervyu yakunlanganda: baholaydi, saqlaydi va boshliq/menejerga rasm+lokatsiya+matnni ALOHIDA yuboradi."""
    try:
        result = job_score_candidate(job, state["history"])
        import json as _json
        q("UPDATE job_applicants SET transcript=?, ai_score=?, ai_summary=?, ai_strengths=?, ai_concerns=?, "
          "status='completed', completed_at=? WHERE job_id=? AND tg_id=?",
          (_json.dumps(state["history"], ensure_ascii=False), result.get("score", 50),
           result.get("summary",""), result.get("strengths",""), result.get("concerns",""),
           now_str(), state["job_id"], uid))
        row = qone("SELECT photo_file_id, loc_lat, loc_lon, loc_distance_km FROM job_applicants WHERE job_id=? AND tg_id=?",
                  (state["job_id"], uid))
        photo_id, loc_lat, loc_lon, dist_km = row if row else (None, None, None, None)
        W_APPLY.pop(uid, None)
        dist_txt = f"\n📍 Manzil masofasi: <b>{dist_km:.1f} km</b>" if dist_km is not None else ""
        notif = (f"🆕 <b>Yangi nomzod baholandi!</b>\n\n"
                 f"🧑‍💼 {h(job['title'])}\n👤 {h(state['full_name'])} — {h(state['phone'])}\n"
                 f"⭐ Ball: <b>{result.get('score',50):.0f}/100</b>{dist_txt}\n"
                 f"💬 {h(result.get('summary',''))}\n"
                 f"✅ Kuchli: {h(result.get('strengths',''))}\n"
                 f"⚠️ Xavotir: {h(result.get('concerns',''))}")
        boss_ids = qall("SELECT tg_id FROM users WHERE role IN ('boss','manager')")
        print(f"HR FINISH: {len(boss_ids)} ta boshliq/menejerga yuborilmoqda, photo={bool(photo_id)}, loc={loc_lat is not None}", flush=True)
        for (bid,) in boss_ids:
            # ⚠️ Rasm caption'i 1024 belgidan oshsa Telegram jimgina rad etadi —
            # shuning uchun rasm/xarita va TO'LIQ matnni ALOHIDA yuboramiz.
            try:
                if photo_id:
                    bot.send_photo(bid, photo_id, caption=f"👤 {h(state['full_name'])} — {h(job['title'])}", parse_mode="HTML")
            except Exception as e:
                print("HR NOTIFY PHOTO ERR:", str(e)[:150], flush=True)
            try:
                if loc_lat is not None and loc_lon is not None:
                    bot.send_location(bid, loc_lat, loc_lon)
            except Exception as e:
                print("HR NOTIFY LOCATION ERR:", str(e)[:150], flush=True)
            try:
                send_long_message(bid, notif, parse_mode="HTML")
            except Exception as e:
                print("HR NOTIFY TEXT ERR:", str(e)[:150], flush=True)
    except Exception as e:
        print("HR FINISH INTERVIEW CRASH:", str(e)[:300], flush=True)
        try:
            for (bid,) in qall("SELECT tg_id FROM users WHERE role IN ('boss','manager')"):
                bot.send_message(bid, f"⚠️ Nomzod baholashda xatolik yuz berdi: {h(str(e)[:150])}", parse_mode="HTML")
        except Exception:
            pass

@bot.message_handler(content_types=['photo'],
                     func=lambda m: W_APPLY.get(m.from_user.id, {}).get("step") == "interview")
def apply_interview_photo(message):
    uid = message.from_user.id
    state = W_APPLY.get(uid)
    if not state: return
    job = _job_get(state["job_id"])
    file_id = message.photo[-1].file_id
    q("UPDATE job_applicants SET photo_file_id=? WHERE job_id=? AND tg_id=?", (file_id, state["job_id"], uid))
    state["history"].append({"role": "user", "content": "[Nomzod rasmini yubordi — rasm muvaffaqiyatli qabul qilindi.]"})
    def run():
        reply = job_interview_reply(job, state["history"])
        state["history"].append({"role": "assistant", "content": reply})
        finished = "[INTERVYU_TUGADI]" in reply
        clean = reply.replace("[INTERVYU_TUGADI]", "").strip()
        bot.send_message(uid, f"✅ Rasmingiz qabul qilindi.\n\n{clean}")
        if finished:
            _finish_interview(uid, state, job)
    threading.Thread(target=run, daemon=True).start()

@bot.message_handler(content_types=['location'],
                     func=lambda m: W_APPLY.get(m.from_user.id, {}).get("step") == "interview")
def apply_interview_location(message):
    uid = message.from_user.id
    state = W_APPLY.get(uid)
    if not state: return
    job = _job_get(state["job_id"])
    lat, lon = message.location.latitude, message.location.longitude
    # Vakansiyaga xos manzil bo'lsa o'shani, bo'lmasa do'konning standart manzilini ishlatamiz
    target_lat = job.get("target_lat") or CFG.SHOP_LAT
    target_lon = job.get("target_lon") or CFG.SHOP_LON
    radius = job.get("radius_km")
    dist_km = calc_dist(lat, lon, target_lat, target_lon) / 1000.0
    q("UPDATE job_applicants SET loc_lat=?, loc_lon=?, loc_distance_km=? WHERE job_id=? AND tg_id=?",
      (lat, lon, dist_km, state["job_id"], uid))
    if radius:
        within = dist_km <= radius
        radius_note = (f"Belgilangan radius: {radius} km. Bu masofa radius ICHIDA "
                       f"({'✅ mos keladi' if within else '❌ RADIUSDAN TASHQARIDA'})."
                       ) 
    else:
        radius_note = "Radius chegarasi belgilanmagan — shunchaki ma'lumot uchun."
    state["history"].append({"role": "user",
        "content": f"[Nomzod lokatsiyasini yubordi. Belgilangan manzildan haqiqiy masofa: {dist_km:.1f} km. "
                    f"{radius_note} Buni nomzodga muloyim tarzda ayt.]"})
    def run():
        reply = job_interview_reply(job, state["history"])
        state["history"].append({"role": "assistant", "content": reply})
        finished = "[INTERVYU_TUGADI]" in reply
        clean = reply.replace("[INTERVYU_TUGADI]", "").strip()
        bot.send_message(uid, f"✅ Lokatsiyangiz qabul qilindi (masofa: {dist_km:.1f} km).\n\n{clean}")
        if finished:
            _finish_interview(uid, state, job)
    threading.Thread(target=run, daemon=True).start()

@bot.message_handler(func=lambda m: W_APPLY.get(m.from_user.id, {}).get("step") == "interview")
def apply_interview(message):
    if _apply_interrupted(message): return
    uid = message.from_user.id
    state = W_APPLY.get(uid)
    if not state: return
    job = _job_get(state["job_id"])
    state["history"].append({"role": "user", "content": message.text})
    def run():
        reply = job_interview_reply(job, state["history"])
        state["history"].append({"role": "assistant", "content": reply})
        finished = "[INTERVYU_TUGADI]" in reply
        clean = reply.replace("[INTERVYU_TUGADI]", "").strip()
        bot.send_message(uid, clean)
        if finished:
            _finish_interview(uid, state, job)
    threading.Thread(target=run, daemon=True).start()
