def get_total_stock_value():
    """Ombordagi BARCHA mahsulotning umumiy tannarx qiymatini (so'mda) qaytaradi.
    Bito'da bu uchun aniq bitta hujjatlashtirilgan endpoint yo'q — shuning uchun bir nechta
    ehtimoliy manzil sinaladi va ISHLAGANI keyingi safarlar uchun sozlamalarda eslab qolinadi
    (xuddi nakladnoy supplier_id/supliaer_id muammosidagi kabi usul)."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    candidates = [
        "reports/pos/summary/product/get-summary",
        "reports/pos/product-stock-summary",
        "reports/pos/summary/product-stock",
        "reports/dashboard/summary/product/get-summary",
    ]
    known = get_setting("stock_value_endpoint", "")
    if known:
        candidates = [known] + [c for c in candidates if c != known]
    for path in candidates:
        try:
            # ⚠️ Bito bu endpointda `organization_id` (BITTA matn) talab qiladi.
            # Faqat `organization_ids` yuborilsa → code 10001, data:"organization_id".
            # Ikkalasini ham yuboramiz — boshqa variantlar uchun ham mos kelsin.
            r = requests.post(BITO_BASE_URL + path,
                             json={"organization_id": CFG.BITO_ORG_ID,
                                   "organization_ids": [CFG.BITO_ORG_ID]},
                             headers=headers, timeout=15)
            if r.status_code != 200:
                continue
            j = r.json()
            data = j.get("data", j) if isinstance(j, dict) else j
            if isinstance(data, dict):
                # Maydon nomi versiyaga qarab farq qilishi mumkin — bir nechtasi sinaladi
                for _k in ("total_cost", "total_stock_cost", "stock_cost", "total", "cost", "sum"):
                    _v = data.get(_k)
                    if isinstance(_v, (int, float)):
                        if path != known:
                            set_setting("stock_value_endpoint", path)
                            print(f"STOCK VALUE: ishlaydigan endpoint topildi va saqlandi: {path} ({_k})", flush=True)
                        return float(_v)
                # Mos maydon topilmadi — keyingi safar tuzatish oson bo'lishi uchun
                # javobdagi kalitlarni logga chiqaramiz
                print(f"STOCK VALUE: {path} javob berdi, lekin kerakli maydon yo'q. "
                      f"Kalitlar: {list(data.keys())[:12]}", flush=True)
        except Exception as e:
            print(f"STOCK VALUE ERR ({path}):", str(e)[:100], flush=True)
            continue
    print("STOCK VALUE: hech qaysi endpoint ishlamadi", flush=True)
    return None

DASH_STOCKVAL_CACHE = TDict(template={"ts": 0, "data": None})
DASH_STOCKVAL_TTL = 600  # 10 daqiqa — og'ir emas, lekin baribir keshlaymiz

def get_total_stock_value_cached(force=False):
    now_ts = time.time()
    if not force and DASH_STOCKVAL_CACHE["data"] is not None and (now_ts - DASH_STOCKVAL_CACHE["ts"]) < DASH_STOCKVAL_TTL:
        return DASH_STOCKVAL_CACHE["data"]
    val = get_total_stock_value()
    if val is not None:
        DASH_STOCKVAL_CACHE["ts"] = now_ts
        DASH_STOCKVAL_CACHE["data"] = val
    return val if val is not None else DASH_STOCKVAL_CACHE["data"]

def get_daily_ai_data():
    """Eng ko'p sotilgan mahsulotlar (oxirgi 30 kun) + HAQIQIY turib qolgan mahsulotlar
    (butun katalog bilan solishtirib topilgan, 2 ta chegara bilan):
    - 'medium': oxirgi 14 kunda sotilmagan, lekin 15-30 kun oralig'ida sotilgan (o'rtacha turib qolgan)
    - 'severe': oxirgi 30 kunda UMUMAN sotilmagan (jiddiy turib qolgan)."""
    today = now_dt()
    period_start = (today - timedelta(days=30)).strftime("%Y-%m-%d")
    df, dt_ = bito_range_utc(period_start, today_str())
    best_raw = bito_get_items_sorted(df, dt_, limit=20, ascending=False)
    best_list = []
    for it in best_raw:
        if not isinstance(it, dict): continue
        name = it.get("product_name") or it.get("name") or "?"
        sold = it.get("items_sold", 0) or 0
        if name != "?" and sold > 0:
            best_list.append({"name": name, "sold": sold})

    all_products = bito_get_all_products_with_stock(page_limit=200, max_pages=30, min_stock=3)
    sold_14 = bito_get_sold_product_ids(14)
    sold_30 = bito_get_sold_product_ids(30)

    medium, severe = [], []
    for p in all_products:
        pid = p["id"]
        if pid in sold_30:
            if pid not in sold_14:
                medium.append(p)
        else:
            severe.append(p)
    # eng ko'p qoldig'i borlarini birinchi ko'rsatamiz
    medium.sort(key=lambda x: -x["stock"]); severe.sort(key=lambda x: -x["stock"])
    print(f"AI ADVICE: jami mahsulot={len(all_products)}, 14kunlik sotilgan={len(sold_14)}, "
          f"30kunlik sotilgan={len(sold_30)}, medium={len(medium)}, severe={len(severe)}", flush=True)
    return best_list, medium[:15], severe[:15]

def get_stale_product_ids_full():
    """get_daily_ai_data bilan bir xil mantiq, lekin TO'LIQ ro'yxatni (kesilmagan)
    {product_id: name} lug'ati sifatida qaytaradi — xodim bo'yicha sotuvni
    tekshirishda barcha turib qolgan mahsulotlarni hisobga olish uchun kerak."""
    all_products = bito_get_all_products_with_stock(page_limit=200, max_pages=30, min_stock=3)
    sold_30 = bito_get_sold_product_ids(30)
    stale = {}
    for p in all_products:
        if p["id"] not in sold_30:
            stale[p["id"]] = p["name"]
    return stale

def bito_get_trades_for_employee(bname, from_iso, to_iso, max_pages=20, page_limit=100):
    """Berilgan mas'ul shaxs (xodim) nomi bo'yicha davr ichidagi tugallangan
    savdolarni (trade) topadi. API 'responsible' bo'yicha ishonchli filtrlamasligi
    mumkin bo'lgani uchun, natijalarni CLIENT-SIDE ham tekshiramiz."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    trades = []
    page = 1
    while page <= max_pages:
        try:
            body = {"page": page, "limit": page_limit, "from_date": from_iso, "to_date": to_iso,
                    "organization_id": CFG.BITO_ORG_ID, "organization_ids": [CFG.BITO_ORG_ID]}
            r = requests.post(BITO_BASE_URL + "trade/get-paging", json=body, headers=headers, timeout=30)
            if r.status_code != 200:
                print(f"TRADE PAGING ERR: HTTP {r.status_code}", flush=True)
                break
            j = r.json(); d = j.get("data", {})
            items = d.get("data", []) if isinstance(d, dict) else (d or [])
            total = d.get("total", 0) if isinstance(d, dict) else 0
            if not items:
                break
            for it in items:
                if not isinstance(it, dict):
                    continue
                resp = it.get("responsible") or {}
                rname = resp.get("full_name") or it.get("employee_name") or it.get("responsible_name")
                if rname == bname:
                    trades.append(it)
            if page * page_limit >= total:
                break
            page += 1
        except Exception as e:
            print("TRADE EMP ERR:", str(e)[:120], flush=True)
            break
    return trades

def bito_get_trade_full(trade_id):
    """Bitta savdo (trade) hujjatining to'liq tafsilotini oladi (mahsulotlar bilan)."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.get(BITO_BASE_URL + f"trade/get-by-id/{trade_id}", headers=headers, timeout=15)
        if r.status_code == 200:
            return r.json().get("data", {})
    except Exception as e:
        print("TRADE DETAIL ERR:", str(e)[:120], flush=True)
    return {}

def get_employee_stale_sales_report(tg_id, from_date_str, to_date_str):
    """Muayyan xodimning belgilangan davrda TURIB QOLGAN mahsulotlardan qanchasini
    sotganini hisoblaydi. Natija: (list of {name, qty, gross}, error_msg_or_None)."""
    bmap = get_bito_map()
    bname = bmap.get(tg_id)
    if not bname:
        return None, "Bu xodim Bito bilan bog'lanmagan."

    stale_ids = get_stale_product_ids_full()
    if not stale_ids:
        return [], None

    df, dt_ = bito_range_utc(from_date_str, to_date_str)
    trades = bito_get_trades_for_employee(bname, df, dt_, max_pages=20, page_limit=100)
    print(f"[STALE-EMP] {bname}: topilgan savdolar soni = {len(trades)}", flush=True)

    sold = {}  # pid -> {"qty":.., "gross":..}
    debug_printed = False
    for tr in trades:
        tid = tr.get("_id")
        if not tid:
            continue
        full = bito_get_trade_full(tid)
        if not debug_printed:
            print(f"[STALE-EMP-DEBUG] trade.keys() = {list(full.keys())}", flush=True)
            debug_printed = True
        # Mumkin bo'lgan tuzilmalar: orders[].products[] (purchase'dagidek) YOKI to'g'ridan-to'g'ri items[]/products[]
        line_items = []
        orders = full.get("orders") or []
        if orders:
            for order in orders:
                if isinstance(order, dict):
                    line_items.extend(order.get("products") or [])
        else:
            line_items = full.get("items") or full.get("products") or []
        for item in line_items:
            if not isinstance(item, dict):
                continue
            prod = item.get("product") or {}
            pid = (prod.get("_id") if isinstance(prod, dict) else None) or item.get("product_id")
            pid = str(pid) if pid else None
            if pid and pid in stale_ids:
                qty = item.get("amount") or item.get("quantity") or 0
                gross = item.get("total_to_pay") or item.get("total_cost") or item.get("cost") or 0
                rec = sold.setdefault(pid, {"name": stale_ids[pid], "qty": 0, "gross": 0})
                rec["qty"] += (qty or 0)
                rec["gross"] += (gross or 0)

    result = sorted(sold.values(), key=lambda x: -x["qty"])
    return result, None

def _call_claude(prompt, max_tokens=500):
    try:
        resp = requests.post(
            "https://api.anthropic.com/v1/messages",
            headers={"x-api-key": ANTHROPIC_API_KEY,
                     "anthropic-version": "2023-06-01",
                     "content-type": "application/json"},
            json={"model": "claude-sonnet-4-6", "max_tokens": max_tokens,
                  "messages": [{"role": "user", "content": prompt}]},
            timeout=60
        )
        resp.raise_for_status()
        return resp.json().get("content", [{}])[0].get("text", "")
    except Exception as e:
        print("CLAUDE AI ERR:", str(e)[:150], flush=True)
        return ""

def _fmt_stale_list(items):
    return "\n".join(f"- {p['name']} (omborda {p['stock']:.0f} ta)" for p in items) or "Yo'q"

