def compute_stock_alerts(top_n=None, days_threshold=None):
    """Top N eng ko'p sotiladigan mahsulotlarni tekshirib, kam qolganlar ro'yxatini QAYTARADI
    (xabar yubormaydi — buni ham Telegram eslatmasi, ham web dashboard ishlatadi).
    Qaytaradi: {"urgent": [...], "warning": [...], "top_n": int, "checked_at": str} yoki None (xato bo'lsa)."""
    try:
        if top_n is None:
            top_n = int(get_setting("stock_top_count", "30"))
        if days_threshold is None:
            days_threshold = float(get_setting("stock_days_threshold", "1"))
        headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}

        # 1. Top N eng ko'p sotiladigan mahsulotlar (bu oy)
        month_start = now_dt().replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        import datetime as _dt
        month_start_utc = month_start.astimezone(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")
        r = requests.post(BITO_BASE_URL + "sales/by-item-pagin",
                         json={"page": 1, "limit": top_n,
                               "from_date": month_start_utc,
                               "organization_ids": [CFG.BITO_ORG_ID]},
                         headers=headers, timeout=60)
        r.raise_for_status()
        resp_json = r.json()
        if not isinstance(resp_json, dict):
            print("STOCK ERR: top javob dict emas", flush=True); return None
        inner = resp_json.get("data", {})
        top_items = inner.get("data", []) if isinstance(inner, dict) else inner
        if not isinstance(top_items, list) or not top_items:
            print("STOCK: top mahsulotlar bo'sh", flush=True); return None

        # 2. Barcha omborlarni sahifalab o'qib, product_id → amount map quramiz
        target_pids = {(it.get("product_id") or it.get("_id")) for it in top_items if isinstance(it, dict)}
        stock_map = {}
        found_count = 0
        for page in range(1, 70):  # max ~13800 ta
            try:
                rw = requests.post(BITO_BASE_URL + "product-warehouse/get-paging",
                                  json={"page": page, "limit": 200},
                                  headers=headers, timeout=20)
                rw.raise_for_status()
                j = rw.json()
                d = j.get("data", j)
                items = d.get("data", []) if isinstance(d, dict) else (d if isinstance(d, list) else [])
                if not items:
                    break
                for it in items:
                    if not isinstance(it, dict): continue
                    pid = it.get("product_id")
                    if pid:
                        stock_map[pid] = stock_map.get(pid, 0) + (it.get("amount", 0) or 0)
                        if pid in target_pids:
                            found_count += 1
                if len(items) < 200:
                    break
                if found_count >= len(target_pids) * 3:  # har pid uchun avg 3 omborni topgan
                    break
            except Exception as e:
                print(f"STOCK MAP ERR page {page}:", str(e)[:100], flush=True)
                break
        print(f"STOCK: {len(stock_map)} ombor yozuvi o'qildi, {len(target_pids)} mahsulot kuzatildi", flush=True)

        # 3. Kunlik o'rtacha va solishtirish
        today = now_dt()
        days_passed = max(1, (today - today.replace(day=1, hour=0, minute=0, second=0, microsecond=0)).days + 1)
        urgent = []
        warning = []
        for item in top_items:
            if not isinstance(item, dict): continue
            pid = item.get("product_id") or item.get("_id")
            pname = item.get("product_name", "?")
            items_sold = item.get("items_sold", 0) or 0
            measure = item.get("measure")
            unit = "kg" if isinstance(measure, dict) and measure.get("code") == "kg" else "ta"
            daily_avg = items_sold / days_passed if days_passed > 0 else 0
            if daily_avg <= 0 or not pid: continue
            if pid not in stock_map: continue
            current_stock = stock_map[pid]
            days_left = current_stock / daily_avg if daily_avg > 0 else 999
            row = {"name": pname, "stock": current_stock, "unit": unit, "days_left": days_left, "daily_avg": daily_avg}
            if current_stock <= 0:
                row["days_left"] = 0
                urgent.append(row)
            elif days_left < days_threshold:
                urgent.append(row)
            elif days_left < days_threshold * 2:
                warning.append(row)
        return {"urgent": urgent, "warning": warning, "top_n": top_n,
                "checked_at": now_dt().strftime("%d.%m.%Y %H:%M")}
    except Exception as e:
        print("STOCK COMPUTE ERR:", str(e)[:200], flush=True)
        return None

# 🔄 Dashboard uchun oddiy kesh — har safar sahifa ochilganda Bito'ga 70 tagacha
# so'rov yubormaslik uchun (bu og'ir operatsiya). TTL: 5 daqiqa.
DASH_STOCK_CACHE = TDict(template={"ts": 0, "data": None})
DASH_STOCK_TTL = 300

def get_stock_alerts_cached(force=False):
    now_ts = time.time()
    if not force and DASH_STOCK_CACHE["data"] is not None and (now_ts - DASH_STOCK_CACHE["ts"]) < DASH_STOCK_TTL:
        return DASH_STOCK_CACHE["data"]
    data = compute_stock_alerts()
    if data is not None:
        DASH_STOCK_CACHE["ts"] = now_ts
        DASH_STOCK_CACHE["data"] = data
    return data or DASH_STOCK_CACHE["data"]

def check_and_send_stock_alerts():
    """Kam qolgan mahsulotlarni hisoblab, Telegram orqali tegishli rollarga xabar yuboradi."""
    try:
        roles_str = get_setting("stock_alert_roles", "boss,manager")
        roles = [r.strip() for r in roles_str.split(",") if r.strip()]
        data = compute_stock_alerts()
        if not data:
            return
        urgent, warning, top_n = data["urgent"], data["warning"], data["top_n"]
        if not urgent and not warning:
            print("STOCK: hamma mahsulot yetarli", flush=True); return
        dt = data["checked_at"]
        text = f"📦 <b>Ombor eslatmasi — Top {top_n} | {dt}</b>"
        if urgent:
            text += "\n\n🔴 <b>TEZDA OLIB KELING:</b>\n" + "\n".join(
                (f"🚨 <b>{h(x['name'])}</b> — qolmagan! (kunlik: {x['daily_avg']:.1f} {x['unit']})" if x["stock"] <= 0
                 else f"🔴 <b>{h(x['name'])}</b> — {x['stock']:.1f} {x['unit']} qoldi (~{x['days_left']:.1f} kun)")
                for x in urgent)
        if warning:
            text += "\n\n⚠️ <b>Kam qoldi:</b>\n" + "\n".join(
                f"🟡 <b>{h(x['name'])}</b> — {x['stock']:.1f} {x['unit']} qoldi (~{x['days_left']:.1f} kun)"
                for x in warning)
        if roles:
            placeholders = ",".join("?" * len(roles))
            for (uid,) in qall(f"SELECT tg_id FROM users WHERE role IN ({placeholders})", tuple(roles)):
                try:
                    bot.send_message(uid, text, parse_mode="HTML")
                except Exception as e:
                    print("STOCK SEND ERR:", str(e)[:100], flush=True)
    except Exception as e:
        print("STOCK CHECK ERR:", str(e)[:200], flush=True)

def stock_alert_thread():
    sent_today = set()
    last_date = today_str()
    while True:
        try:
            if get_setting("stock_alert_enabled", "1") != "1":
                time.sleep(60)
                continue
            cur_date = today_str()
            if cur_date != last_date:
                sent_today = set()
                last_date = cur_date
            alert_times = [t.strip() for t in get_setting("stock_alert_times", "09:00").split(",")]
            ct = now_dt().strftime("%H:%M")
            if ct in alert_times and ct not in sent_today:
                sent_today.add(ct)
                check_and_send_stock_alerts()
        except Exception as e:
            print("STOCK THREAD ERR:", str(e)[:150], flush=True)
        time.sleep(30)
