def display_time(s): 
    if not s: return "--:--"
    return str(s)[11:16] if len(str(s)) > 10 else str(s)
def minutes_to_str(m):
    if not m: return "0 daqiqa"
    h, mi = divmod(int(m), 60)
    return f"{h}s {mi}d" if h else f"{mi} daqiqa"
def fmt_money(a): return f"{int(a):,} so'm".replace(",", " ")
def stars(r):
    r = int(round(float(r or 0)))
    return "⭐"*r + "☆"*(5-r)
def calc_dist(lat1,lon1,lat2,lon2):
    R=6371000; lat1,lon1,lat2,lon2=map(radians,[lat1,lon1,lat2,lon2])
    a=sin((lat2-lat1)/2)**2+cos(lat1)*cos(lat2)*sin((lon2-lon1)/2)**2
    return R*2*atan2(sqrt(a),sqrt(1-a))

def get_user(tg_id):
    return qone("SELECT tg_id,full_name,role,position,hourly_rate,approved_by FROM users WHERE tg_id=?", (tg_id,))
def _ack(call, text=None):
    """Telegram'ning "callback ack" so'rovi — TARMOQ NOSOZLIGIDA HANDLERNI YIQITMASIN.
    ⚠️ Amalda kuzatilgan: api.telegram.org javob bermay qolganda
    bot.answer_callback_query() ReadTimeout tashlab, butun ishlovchi to'xtab qolgan
    (tugma bosilgan-u, hech narsa bajarilmagan). Bu chaqiruv shunchaki tugmadagi
    "soat" belgisini o'chiradi — u muvaffaqiyatsiz bo'lsa ham ish davom etishi kerak."""
    try:
        # ⚠️ To'g'ridan-to'g'ri API chaqiruvi — o'zini chaqirib qolmasin
        if text:
            bot.answer_callback_query(call.id, text)
        else:
            bot.answer_callback_query(call.id)
    except Exception as e:
        print("ACK ERR (e'tiborsiz qoldirildi):", str(e)[:100], flush=True)

def send_long_message(chat_id, text, parse_mode=None, chunk_size=3800, reply_markup=None):
    """Telegram xabar uzunligi chegarasi (4096 belgi) dan oshib ketishining oldini
    oladi — matnni xavfsiz bo'laklarga bo'lib, ketma-ket yuboradi.

    reply_markup berilsa, u faqat OXIRGI bo'lakka biriktiriladi — aks holda
    tugmalar har bir bo'lakda takrorlanib ketardi."""
    if len(text) <= chunk_size:
        bot.send_message(chat_id, text, parse_mode=parse_mode, reply_markup=reply_markup)
        return
    paragraphs = text.split("\n\n")
    chunk = ""
    for p in paragraphs:
        candidate = (chunk + "\n\n" + p) if chunk else p
        if len(candidate) > chunk_size:
            if chunk:
                bot.send_message(chat_id, chunk, parse_mode=parse_mode)
                chunk = ""
            if len(p) > chunk_size:
                # bitta paragraf ham juda uzun bo'lsa — qatorlar bo'yicha bo'lamiz
                lines = p.split("\n")
                sub = ""
                for line in lines:
                    sub_candidate = (sub + "\n" + line) if sub else line
                    if len(sub_candidate) > chunk_size:
                        if sub:
                            bot.send_message(chat_id, sub, parse_mode=parse_mode)
                        sub = line
                    else:
                        sub = sub_candidate
                if sub:
                    chunk = sub
            else:
                chunk = p
        else:
            chunk = candidate
    if chunk:
        bot.send_message(chat_id, chunk, parse_mode=parse_mode, reply_markup=reply_markup)
    elif reply_markup is not None:
        # Matn aniq bo'laklarga bo'lindi-yu, oxirgi bo'lak bo'sh qoldi —
        # tugmalar yo'qolib qolmasligi uchun alohida yuboramiz.
        bot.send_message(chat_id, "⬆️", reply_markup=reply_markup)

def get_role(tg_id):
    u = get_user(tg_id); return u[2] if u else None
def is_boss_or_mgr(tg_id): return get_role(tg_id) in ('boss','manager')
def get_setting(k, default=""):
    r = qone("SELECT value FROM settings WHERE key=?", (k,)); return r[0] if r else default
def set_setting(k, v):
    q("INSERT OR REPLACE INTO settings (key,value,updated_at) VALUES (?,?,?)", (k,str(v),now_str()))

# ===== 🏢 SaaS LITSENZIYA/OBUNA TIZIMI =====
# Bu deploy (bitta do'kon)ning obuna holatini boshqaradi. SAAS_OWNER_ID
# o'rnatilmagan bo'lsa (o'z do'koningiz uchun ishlatilsa), tekshiruv o'chirilgan.
LICENSE_GRACE_DAYS = 3  # muddat tugagach, qulflashdan oldingi "iltimos to'lang" kunlari

def get_license_expiry():
    """Litsenziya tugash sanasini (YYYY-MM-DD) qaytaradi. Agar hali o'rnatilmagan
    bo'lsa, birinchi ishga tushishda 14 kunlik SINOV MUDDATI beriladi."""
    val = get_setting("license_expires_at", "")
    if not val:
        trial_end = (now_dt() + timedelta(days=14)).strftime("%Y-%m-%d")
        set_setting("license_expires_at", trial_end)
        return trial_end
    return val

def get_license_days_left():
    try:
        exp = datetime.strptime(get_license_expiry(), "%Y-%m-%d").replace(tzinfo=UZT)
        return (exp - now_dt()).days
    except Exception:
        return 9999

def is_license_locked():
    """Litsenziya muddati + grace davri ham tugagan bo'lsa True qaytaradi."""
    if not SAAS_OWNER_ID:
        return False  # shaxsiy foydalanish uchun — tekshiruv yo'q
    return get_license_days_left() < -LICENSE_GRACE_DAYS

def license_status_text():
    days = get_license_days_left()
    exp = get_license_expiry()
    if days < 0:
        return f"🔴 Litsenziya MUDDATI TUGAGAN ({exp}, {abs(days)} kun oldin)"
    elif days <= 5:
        return f"🟡 Litsenziya {days} kundan keyin tugaydi ({exp})"
    else:
        return f"🟢 Litsenziya faol, {exp} gacha ({days} kun qoldi)"

def license_guard(message_or_call, is_callback=False):
    """Har bir og'ir/muhim amaldan oldin chaqiriladi. Agar qulflangan bo'lsa,
    True qaytaradi VA foydalanuvchiga eslatma yuboradi — chaqiruvchi shu holda
    davom etmasligi kerak."""
    if not is_license_locked():
        return False
    chat_id = message_or_call.message.chat.id if is_callback else message_or_call.chat.id
    try:
        bot.send_message(chat_id,
            "🔒 <b>Botning obuna muddati tugagan.</b>\n\n"
            "Xizmatdan foydalanishni davom ettirish uchun to'lovni amalga oshiring "
            "va bot egasi bilan bog'laning.", parse_mode="HTML")
    except Exception:
        pass
    return True

def license_check_thread():
    """Har kuni bir marta boshliqqa litsenziya holatini eslatib turadi."""
    last_notified_date = None
    while True:
        try:
            if SAAS_OWNER_ID:
                days = get_license_days_left()
                cur_date = today_str()
                if days <= 7 and cur_date != last_notified_date:
                    last_notified_date = cur_date
                    text = f"💳 <b>Obuna eslatmasi</b>\n\n{h(license_status_text())}\n\nTo'lovni amalga oshirib, obunani uzaytiring."
                    for (bid,) in qall("SELECT tg_id FROM users WHERE role='boss'"):
                        try: bot.send_message(bid, text, parse_mode="HTML")
                        except Exception: pass
        except Exception as e:
            print("LICENSE THREAD ERR:", str(e)[:150], flush=True)
        time.sleep(6 * 3600)  # kuniga 4 marta tekshiradi (yetarli)

def get_points(tg_id):
    month = now_dt().strftime("%Y-%m")
    r = qone("SELECT points FROM points WHERE tg_id=? AND month=?", (tg_id,month)); return r[0] if r else 0
def add_points(tg_id, name, pts):
    month = now_dt().strftime("%Y-%m")
    r = qone("SELECT id,points FROM points WHERE tg_id=? AND month=?", (tg_id,month))
    if r: q("UPDATE points SET points=? WHERE id=?", (r[1]+pts, r[0]))
    else: q("INSERT INTO points (tg_id,employee_name,points,month) VALUES (?,?,?,?)", (tg_id,name,pts,month))
def salary_for_minutes(tg_id, mins):
    r = qone("SELECT hourly_rate FROM users WHERE tg_id=?", (tg_id,))
    return round(float(r[0])*mins/60) if r and r[0] else 0

# ===== ISH HAQI HISOBLASH TURI (soatiga / savdosiga / ball — istalgan kombinatsiya) =====
SALARY_COMPONENTS = ["hourly", "sales", "points"]
SALARY_COMPONENT_LABEL = {"hourly": "⏰ Soatiga", "sales": "💵 Savdosiga", "points": "🎯 Ballga"}

def get_salary_mode(tg_id):
    """Vergul bilan ajratilgan komponentlar ro'yxatini qaytaradi, masalan 'hourly,points'."""
    r = qone("SELECT salary_mode FROM users WHERE tg_id=?", (tg_id,))
    val = (r[0] if r and r[0] else "hourly")
    parts = [p.strip() for p in val.split(",") if p.strip() in SALARY_COMPONENTS]
    return parts or ["hourly"]
def set_salary_mode(tg_id, components):
    """components: list yoki set, masalan ['hourly','points']."""
    ordered = [c for c in SALARY_COMPONENTS if c in components]
    if not ordered:
        ordered = ["hourly"]
    q("UPDATE users SET salary_mode=? WHERE tg_id=?", (",".join(ordered), tg_id))
def get_point_value():
    """1 ball necha so'mligini qaytaradi (boshliq belgilaydi, masalan 1 ball = 1000 so'm)."""
    try: return float(get_setting("point_value_som","1000"))
    except: return 1000.0
def salary_mode_label(components):
    if isinstance(components, str):
        components = [c.strip() for c in components.split(",") if c.strip()]
    return " + ".join(SALARY_COMPONENT_LABEL.get(c, c) for c in components) or "⏰ Soatiga"

def calc_employee_total_pay(tg_id, work_minutes=0, sales_gross=0):
    """Xodimning ish haqi hisoblash komponentlariga qarab (soatiga/savdosiga/ballga —
    istalgan kombinatsiya) umumiy oylik daromadni hisoblaydi.
    Natija: dict(mode, hourly, sales_bonus, points, points_money, total)."""
    components = get_salary_mode(tg_id)
    hourly = salary_for_minutes(tg_id, work_minutes) if "hourly" in components else 0
    rate = get_bito_bonus_rate()
    sales_bonus = round((sales_gross or 0) * rate) if "sales" in components else 0
    pts = get_points(tg_id)
    points_money = round(pts * get_point_value()) if "points" in components else 0
    total = hourly + sales_bonus + points_money
    return {"mode": components, "hourly": hourly, "sales_bonus": sales_bonus,
            "points": pts, "points_money": points_money, "total": total}
def get_avg_rating(tg_id):
    r = qone("SELECT AVG(rating),COUNT(*) FROM reviews WHERE employee_tg_id=?", (tg_id,))
    return (round(float(r[0]),1), r[1]) if r and r[1] else (None,0)

# ===== HAFTALIK ISH JADVALI (kun bo'yicha kelish/ketish vaqti) =====
WEEKDAY_NAMES = ["Dushanba","Seshanba","Chorshanba","Payshanba","Juma","Shanba","Yakshanba"]

def get_weekly_schedule(tg_id, weekday):
    """weekday: 0=Dushanba ... 6=Yakshanba (Python datetime.weekday() bilan mos)."""
    return qone("SELECT checkin_time,checkout_time,is_off FROM weekly_schedule WHERE tg_id=? AND weekday=?", (tg_id, weekday))

def set_weekly_schedule(tg_id, weekday, checkin_time=None, checkout_time=None, is_off=0):
    r = qone("SELECT id FROM weekly_schedule WHERE tg_id=? AND weekday=?", (tg_id, weekday))
    if r:
        q("UPDATE weekly_schedule SET checkin_time=?,checkout_time=?,is_off=? WHERE id=?",
          (checkin_time, checkout_time, is_off, r[0]))
    else:
        q("INSERT INTO weekly_schedule (tg_id,weekday,checkin_time,checkout_time,is_off) VALUES (?,?,?,?,?)",
          (tg_id, weekday, checkin_time, checkout_time, is_off))

def get_attn_setting_int(key, default):
    try: return int(float(get_setting(key, str(default))))
    except: return int(default)

def apply_checkin_scoring(tg_id, name, actual_dt):
    """Belgilangan jadval bo'yicha kelish vaqtini tekshiradi va ball qo'shadi/ayiradi.
    Erta kelish (ish vaqtidan tashqarida ishlash) — kamida `overtime_tolerance_min`
    (standart 15 daqiqa) erta bo'lsa, bonus ball 2 BAROBAR beriladi.
    Kech kelish — `attendance_tolerance_min` (standart 5 daqiqa) dan oshsa, jarima qo'llaniladi.
    Qaytaradi: (status, pts, expected_str) yoki None (jadval belgilanmagan/dam olish kuni bo'lsa)."""
    sched = get_weekly_schedule(tg_id, actual_dt.weekday())
    if not sched or sched[2] == 1 or not sched[0]:
        return None
    try:
        exp_h, exp_m = map(int, sched[0].split(":"))
    except Exception:
        return None
    expected_dt = actual_dt.replace(hour=exp_h, minute=exp_m, second=0, microsecond=0)
    diff_min = (actual_dt - expected_dt).total_seconds() / 60
    gen_tol = get_attn_setting_int("attendance_tolerance_min", 5)
    ot_tol = get_attn_setting_int("overtime_tolerance_min", 15)
    if diff_min <= -ot_tol:
        # ✅ Ish vaqtidan tashqarida (15+ daqiqa erta) ishlagani uchun — bonus 2 barobar
        pts = get_attn_setting_int("pt_early_checkin", 1) * 2
        add_points(tg_id, name, pts)
        return ("early", pts, sched[0])
    elif diff_min >= gen_tol:
        pts = get_attn_setting_int("pt_late_checkin", -2)
        add_points(tg_id, name, pts)
        return ("late", pts, sched[0])
    else:
        return ("ontime", 0, sched[0])

def apply_checkout_scoring(tg_id, name, actual_dt, ci_dt=None):
    """Belgilangan jadval bo'yicha ketish vaqtini tekshiradi va ball qo'shadi/ayiradi.
    Kech ketish (ish vaqtidan tashqarida qo'shimcha ishlash) — kamida `overtime_tolerance_min`
    (standart 15 daqiqa) kech bo'lsa, bonus ball 2 BAROBAR beriladi.
    Erta ketish — `attendance_tolerance_min` (standart 5 daqiqa) dan oshsa, jarima qo'llaniladi.

    ISTISNO: agar KETISH VAQTINING O'ZI hali smena boshlanishidan oldingi
    ("ish vaqtidan tashqari") davrda bo'lsa — ya'ni xodim smena boshlanishidan
    oldin kelib, smena boshlanishidan oldin ham ketgan bo'lsa — bu butun sessiya
    ish vaqtidan tashqarida o'tgani uchun "erta ketish" jarimasi qo'llanilmaydi.
    Agar ketish vaqti smena boshlanishidan KEYIN bo'lsa (hatto tugashdan oldin
    bo'lsa ham) — bu oddiy ish vaqti hisoblanadi va jarima odatdagidek qo'llaniladi."""
    sched = get_weekly_schedule(tg_id, actual_dt.weekday())
    if not sched or sched[2] == 1 or not sched[1]:
        return None
    try:
        exp_h, exp_m = map(int, sched[1].split(":"))
    except Exception:
        return None
    expected_dt = actual_dt.replace(hour=exp_h, minute=exp_m, second=0, microsecond=0)
    diff_min = (actual_dt - expected_dt).total_seconds() / 60
    gen_tol = get_attn_setting_int("attendance_tolerance_min", 5)
    ot_tol = get_attn_setting_int("overtime_tolerance_min", 15)

    # Ketish vaqtining o'zi hali smena BOSHLANISHIDAN OLDINmi? (ya'ni butun sessiya
    # ish vaqtidan tashqarida o'tgan — smena hali boshlanmagan)
    still_before_shift_start = False
    if sched[0]:
        try:
            st_h, st_m = map(int, sched[0].split(":"))
            shift_start_dt = actual_dt.replace(hour=st_h, minute=st_m, second=0, microsecond=0)
            still_before_shift_start = actual_dt < shift_start_dt
        except Exception:
            pass

    if diff_min >= ot_tol:
        # ✅ Ish vaqtidan tashqarida (15+ daqiqa kech) qolib ishlagani uchun — bonus 2 barobar
        pts = get_attn_setting_int("pt_late_checkout", 1) * 2
        add_points(tg_id, name, pts)
        return ("late", pts, sched[1])
    elif diff_min <= -gen_tol:
        if still_before_shift_start:
            # ✅ Ketish vaqti hali smena boshlanishidan oldin — butun sessiya ish
            # vaqtidan tashqarida o'tgan, shuning uchun jarima YO'Q
            return ("early_ok", 0, sched[1])
        pts = get_attn_setting_int("pt_early_checkout", -2)
        add_points(tg_id, name, pts)
        return ("early", pts, sched[1])
    else:
        return ("ontime", 0, sched[1])
def get_month_plan():
    r = qone("SELECT plan_amount FROM sales_plan WHERE month=?", (now_dt().strftime("%Y-%m"),))
    return r[0] if r else None
def get_month_sales():
    # Har kunning OXIRGI kiritilgan savdo summasi yig'indisi (daily_sales dan)
    month = now_dt().strftime("%Y-%m")
    r = qone("""
        SELECT COALESCE(SUM(d.amount), 0) FROM (
            SELECT sale_date, MAX(rowid) as last_id FROM daily_sales
            WHERE strftime('%Y-%m', sale_date) = ?
            GROUP BY sale_date
        ) t JOIN daily_sales d ON d.rowid = t.last_id
    """, (month,))
    return float(r[0]) if r else 0

