W_RESET_CONFIRM = TDict()

W_APP_PASSWORD = TDict()

@bot.message_handler(commands=['parol'])
def set_app_password_cmd(message):
    """Mobil ilovaga kirish uchun login/parol o'rnatish."""
    tg_id = message.from_user.id
    u = get_user(tg_id)
    if not u or u[2] in ('pending', 'rejected'):
        bot.send_message(message.chat.id, "⛔ Avval ro'yxatdan o'tib, tasdiqlaning."); return
    row = qone("SELECT app_username FROM users WHERE tg_id=?", (tg_id,))
    cur_username = row[0] if row else None
    W_APP_PASSWORD[tg_id] = {"step": "username"}
    if cur_username:
        bot.send_message(message.chat.id,
            f"📱 Hozirgi login: `{cur_username}`\n\nYangi login kiriting (yoki bekor qilish uchun /menu):",
            parse_mode="Markdown")
    else:
        bot.send_message(message.chat.id,
            "📱 Mobil ilovaga kirish uchun LOGIN o'ylab toping (masalan ismingiz, faqat lotin harflari va raqamlar):")

@bot.message_handler(func=lambda m: m.from_user.id in W_APP_PASSWORD)
def set_app_password_flow(message):
    tg_id = message.from_user.id
    state = W_APP_PASSWORD.get(tg_id)
    if not state or message.text in MENU_TEXTS:
        W_APP_PASSWORD.pop(tg_id, None); return
    if state["step"] == "username":
        username = message.text.strip().lower().replace(" ", "_")
        if len(username) < 3:
            bot.send_message(tg_id, "❌ Login kamida 3 belgidan iborat bo'lsin."); return
        existing = qone("SELECT tg_id FROM users WHERE app_username=? AND tg_id!=?", (username, tg_id))
        if existing:
            bot.send_message(tg_id, "❌ Bu login band, boshqasini tanlang."); return
        state["username"] = username; state["step"] = "password"
        bot.send_message(tg_id, "🔒 Endi PAROL kiriting (kamida 4 belgi):")
    else:
        password = message.text.strip()
        if len(password) < 4:
            bot.send_message(tg_id, "❌ Parol kamida 4 belgidan iborat bo'lsin."); return
        username = state["username"]
        W_APP_PASSWORD.pop(tg_id, None)
        pw_hash = generate_password_hash(password)
        q("UPDATE users SET app_username=?, app_password_hash=? WHERE tg_id=?", (username, pw_hash, tg_id))
        try: bot.delete_message(message.chat.id, message.message_id)  # parolni chatdan tezroq o'chiramiz
        except Exception: pass
        bot.send_message(tg_id,
            f"✅ <b>Ilova uchun login/parol o'rnatildi!</b>\n\n👤 Login: <code>{h(username)}</code>\n"
            f"🔒 Parol: (yashiringan)\n\nEndi mobil ilovada shu login/parol bilan kirishingiz mumkin.",
            parse_mode="HTML")

