@bot.message_handler(commands=['set_license'])
def set_license_cmd(message):
    """FAQAT bot sotuvchisi (SAAS_OWNER_ID) uchun: mijozning litsenziyasini uzaytiradi.
    Foydalanish: /set_license 2026-08-15"""
    if not SAAS_OWNER_ID or message.from_user.id != SAAS_OWNER_ID:
        return  # do'kon egasi buni ko'rmasligi/ishlatolmasligi kerak
    parts = message.text.split(maxsplit=1)
    if len(parts) < 2:
        bot.send_message(message.chat.id,
            f"Foydalanish: `/set_license 2026-08-15`\n\nHozirgi: {license_status_text()}",
            parse_mode="Markdown")
        return
    try:
        new_date = datetime.strptime(parts[1].strip(), "%Y-%m-%d")
        set_setting("license_expires_at", new_date.strftime("%Y-%m-%d"))
        bot.send_message(message.chat.id, f"✅ Litsenziya {new_date.strftime('%Y-%m-%d')} gacha uzaytirildi.")
        for (bid,) in qall("SELECT tg_id FROM users WHERE role='boss'"):
            try:
                bot.send_message(bid, f"✅ <b>Obunangiz uzaytirildi!</b>\nAmal qilish muddati: {new_date.strftime('%Y-%m-%d')}", parse_mode="HTML")
            except Exception: pass
    except ValueError:
        bot.send_message(message.chat.id, "❌ Format: `YYYY-MM-DD` (masalan `2026-08-15`)", parse_mode="Markdown")

