# ===== AI MASLAHAT CHAT REJIMI =====
AI_CHAT_SESSIONS = TDict()  # tg_id -> [{"role": "user/model", "parts": [{"text": "..."}]}]
AI_CHAT_CONTEXT = TDict()   # tg_id -> bito_context string (cached)

def get_bito_context_for_ai():
    """Bito'dan joriy holat uchun qisqa kontekst oladi (AI uchun) — mahsulotlar + xodimlar."""
    try:
        headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
        import datetime as _dt
        today = now_dt()
        month_start = today.replace(day=1).strftime("%Y-%m-%d")
        week_start = (today - timedelta(days=6)).strftime("%Y-%m-%d")
        def to_utc(d): return _dt.datetime.strptime(d,"%Y-%m-%d").replace(tzinfo=UZT).astimezone(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")

        ctx = f"Do'kon: Bonnu Market | Sana: {today.strftime('%d.%m.%Y')}\n\n"

        # 1. Oylik top mahsulotlar
        try:
            r1 = requests.post(BITO_BASE_URL + "sales/by-item-pagin",
                json={"page":1,"limit":15,"from_date":to_utc(month_start),"organization_ids":[CFG.BITO_ORG_ID]},
                headers=headers, timeout=20)
            r1.raise_for_status()
            top_items = (r1.json().get("data",{}) or {}).get("data",[]) or []
            ctx += "TOP MAHSULOTLAR (bu oy):\n"
            for it in top_items[:10]:
                if not isinstance(it,dict): continue
                n = it.get("product_name","?")
                g = it.get("gross_sales",0) or 0
                p = it.get("profit",0) or 0
                s = it.get("items_sold",0) or 0
                m = round(p/g*100,1) if g>0 else 0
                ctx += f"- {n}: {fmt_money(g)}, {s:.0f} dona, {m}% marja, foyda={fmt_money(p)}\n"
        except: ctx += "Mahsulot ma'lumoti yuklanmadi\n"

        # 2. Xodimlar bo'yicha (haftalik)
        try:
            r2 = requests.post(BITO_BASE_URL + "reports/dashboard/top/responsible",
                json={"from_date":to_utc(week_start),"to_date":to_utc(today.strftime("%Y-%m-%d"))},
                headers=headers, timeout=15)
            r2.raise_for_status()
            d2 = r2.json().get("data",{})
            emps = d2.get("data",d2.get("list",[])) if isinstance(d2,dict) else d2
            ctx += "\nXODIMLAR BO'YICHA (so'nggi 7 kun):\n"
            for e in (emps or []):
                if not isinstance(e,dict): continue
                resp = e.get("responsible",{}) or {}
                name = resp.get("full_name","?")
                g = e.get("gross_sales",0) or 0
                rc = e.get("receipts",0) or 0
                pr = e.get("profit",0) or 0
                avg = round(g/rc) if rc>0 else 0
                m = round(pr/g*100,1) if g>0 else 0
                ctx += f"- {name}: savdo={fmt_money(g)}, {rc} chek, o'rtacha chek={fmt_money(avg)}, marja={m}%\n"
        except: ctx += "Xodim ma'lumoti yuklanmadi\n"

        # 3. Oylik reja
        plan = get_month_plan()
        if plan:
            ctx += f"\nOYLIK REJA: {fmt_money(int(float(plan)))}\n"

        return ctx
    except Exception as e:
        return f"Bito ma'lumotlari vaqtincha yuklanmadi ({str(e)[:50]})"

def ask_ai_chat(tg_id, user_message):
    """Claude API bilan chat — tarix saqlangan holda."""
    if tg_id not in AI_CHAT_SESSIONS:
        bito_ctx = get_bito_context_for_ai()
        system_msg = (f"Sen Bonnu Market do'konining AI marketing maslahatchisisn. "
                     f"Quyida HAQIQIY Bito savdo tizimidan olingan joriy ma'lumotlar bor — "
                     f"bu ma'lumotlar AYNAN HOZIR do'konning holati. "
                     f"Shu raqamlar asosida aniq, lo'nda va amaliy javob ber. "
                     f"'Bito'ga ulana olmayman' dema — ma'lumotlar allaqachon quyida. "
                     f"O'zbek tilida javob ber. Markdown formatlash ishlatma.\n\n{bito_ctx}")
        AI_CHAT_SESSIONS[tg_id] = {"system": system_msg, "messages": []}

    session = AI_CHAT_SESSIONS[tg_id]
    session["messages"].append({"role": "user", "content": user_message})

    # Oxirgi 20 xabar
    msgs = session["messages"][-20:]

    resp = requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={"x-api-key": ANTHROPIC_API_KEY,
                 "anthropic-version": "2023-06-01",
                 "content-type": "application/json"},
        json={"model": "claude-sonnet-4-6",
              "max_tokens": 800,
              "system": session["system"],
              "messages": msgs},
        timeout=30
    )
    resp.raise_for_status()
    answer = resp.json().get("content", [{}])[0].get("text", "Javob olinmadi.")
    session["messages"].append({"role": "assistant", "content": answer})
    return answer
    AI_CHAT_SESSIONS[tg_id].append({"role": "model", "parts": [{"text": answer}]})
    return answer

W_AI_CHAT = TSet()  # AI chat rejimida turgan foydalanuvchilar

def call_ai(messages_gemini, prompt_text):
    """Gemini'ga murojaat qiladi, muvaffaqiyatsiz bo'lsa Anthropic'ga o'tadi."""
    # Gemini urinishi
    if GEMINI_API_KEY:
        try:
            resp = requests.post(
                f"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={GEMINI_API_KEY}",
                headers={"content-type": "application/json"},
                json={"contents": messages_gemini,
                      "generationConfig": {"maxOutputTokens": 800, "temperature": 0.7}},
                timeout=30
            )
            if resp.status_code == 200:
                return resp.json().get("candidates",[{}])[0].get("content",{}).get("parts",[{}])[0].get("text","")
            print(f"GEMINI {resp.status_code}, Anthropic ga o'tildi", flush=True)
        except Exception as e:
            print(f"GEMINI ERR: {str(e)[:80]}, Anthropic ga o'tildi", flush=True)
    # Anthropic fallback
    if ANTHROPIC_API_KEY:
        resp = requests.post(
            "https://api.anthropic.com/v1/messages",
            headers={"x-api-key": ANTHROPIC_API_KEY,
                     "anthropic-version": "2023-06-01",
                     "content-type": "application/json"},
            json={"model": "claude-sonnet-4-6", "max_tokens": 800,
                  "messages": [{"role": "user", "content": prompt_text}]},
            timeout=30
        )
        resp.raise_for_status()
        return resp.json().get("content",[{}])[0].get("text","Javob olinmadi.")
    return "AI xizmati vaqtincha mavjud emas."

