        mk.add(types.InlineKeyboardButton(f"⏰ Ertalabki xabar: {tm}", callback_data="zlim_tm"))
        pen_on = get_setting("task_penalty_on", "1") == "1"
        pen_pts = get_setting("task_penalty_points", "3")
        pen_tm = get_setting("task_penalty_time", "09:00")
