def generate_personal_advice(emp_name, emp_data, all_context):
    """Bitta xodim uchun shaxsiy tavsiya generatsiya qiladi."""
    g = emp_data.get("gross_sales", 0) or 0
    rc = emp_data.get("receipts", 0) or 0
    pr = emp_data.get("profit", 0) or 0
    avg = round(g/rc) if rc > 0 else 0
    marja = round(pr/g*100, 1) if g > 0 else 0

    prompt = (f"Do'kon: Bonnu Market\n\n"
              f"Xodim: {emp_name}\n"
              f"So'nggi 7 kun:\n"
              f"- Savdo: {fmt_money(g)}\n"
              f"- Cheklar: {rc}\n"
              f"- O'rtacha chek: {fmt_money(avg)}\n"
              f"- Foyda: {fmt_money(pr)} ({marja}%)\n\n"
              f"Do'konning umumiy holati:\n{all_context}\n\n"
              f"Shu xodimga SHAXSAN yo'naltirilgan, iliqroq va motivatsion tavsiya yoz. "
              f"Uning kuchli va zaif tomonlarini aniq raqamlar bilan ayt. "
              f"Bugun u nimalarga e'tibor bersin. "
              f"O'zbek tilida, 100-150 so'z, do'stona ohangda. "
              f"Markdown ishlatma.")
    try:
        resp = requests.post(
            "https://api.anthropic.com/v1/messages",
            headers={"x-api-key": ANTHROPIC_API_KEY,
                     "anthropic-version": "2023-06-01",
                     "content-type": "application/json"},
            json={"model": "claude-sonnet-4-6", "max_tokens": 400,
                  "messages": [{"role": "user", "content": prompt}]},
            timeout=30
        )
        resp.raise_for_status()
        return resp.json().get("content", [{}])[0].get("text", "")
    except Exception as e:
        print("PERSONAL ADVICE ERR:", str(e)[:100], flush=True)
        return None

@bot.callback_query_handler(func=lambda c: c.data == "ai_send_to_emps")
def ai_send_to_employees(call):
    if not is_boss_or_mgr(call.from_user.id):
        _ack(call, "Ruxsat yo'q!"); return
    _ack(call)
    bot.send_message(call.message.chat.id,
        "⏳ Har bir xodim uchun shaxsiy tavsiya tayyorlanmoqda... (1-2 daqiqa)")

    def send_all():
        # Bito'dan xodimlar ma'lumotini olish
        try:
            headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
            import datetime as _dt
            week_start = (now_dt() - timedelta(days=6)).strftime("%Y-%m-%d")
            today_s = now_dt().strftime("%Y-%m-%d")
            def to_utc(d): return _dt.datetime.strptime(d,"%Y-%m-%d").replace(tzinfo=UZT).astimezone(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")
            r = requests.post(BITO_BASE_URL + "reports/dashboard/top/responsible",
                json={"from_date": to_utc(week_start), "to_date": to_utc(today_s)},
                headers=headers, timeout=15)
            r.raise_for_status()
            d = r.json().get("data", {})
            emps = d.get("data", d.get("list", [])) if isinstance(d, dict) else d
        except Exception as e:
            bot.send_message(call.message.chat.id, f"⚠️ Bito'dan xodim ma'lumoti olinmadi: {str(e)[:80]}")
            return

        # Bito nomi → telegram_id xaritasi
        bito_map = {row[1]: row[0] for row in qall("SELECT tg_id, bito_name FROM bito_employee_map")}
        all_ctx = get_bito_context_for_ai()

        sent = 0; failed = 0
        for emp in emps:
            if not isinstance(emp, dict): continue
            resp_obj = emp.get("responsible", {}) or {}
            bname = resp_obj.get("full_name", "?")
            tg_uid = bito_map.get(bname)
            if not tg_uid:
                continue

            advice = generate_personal_advice(bname, emp, all_ctx)
            if not advice:
                failed += 1; continue
            try:
                bot.send_message(tg_uid,
                    f"🤖 Sizga shaxsiy tavsiya\n\n{advice}")
                sent += 1
                time.sleep(1)  # Rate limit uchun
            except Exception as e:
                print(f"SEND TO EMP ERR {bname}:", str(e)[:80], flush=True)
                failed += 1

        result = f"✅ Yuborildi: {sent} ta xodim"
        if failed:
            result += f"\n⚠️ Yuborilmadi: {failed} ta (bog'lanmagan yoki xato)"
        if sent == 0:
            result += "\n\n💡 Eslatma: Xodimlarni Bito bilan bog'lash kerak (⚙️ Sozlamalar → 🔗 Bito xodim bog'lash)"
        bot.send_message(call.message.chat.id, result)

    import threading
    threading.Thread(target=send_all, daemon=True).start()
