ZAKAZ_PAGE_SIZE = 20

def get_supplier_markup(page=0, search=None):
    """Firmalar ro'yxatini inline keyboard sifatida qaytaradi."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    params = {"page": page + 1, "limit": ZAKAZ_PAGE_SIZE, "sort": "-last_sale_at"}
    if search:
        params["search"] = search
    try:
        r = requests.post(BITO_BASE_URL.replace("/integration/api/v2/", "/integration/api/v2/")
                          .rstrip("/") + "/../../../" + "supplier/get-paging",
                          json=params, headers=headers, timeout=15)
        # Try direct path
        base = "https://api.bito.uz/integration-api/integration/api/v2/"
        r = requests.post(base + "supplier/get-paging",
                         json=params, headers={"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"},
                         timeout=15)
        r.raise_for_status()
        j = r.json()
        d = j.get("data", j)
        items = d.get("data", []) if isinstance(d, dict) else d
        total = d.get("total", 0) if isinstance(d, dict) else 0
        return items, total
    except Exception as e:
        print("SUPPLIER ERR:", str(e)[:150], flush=True)
        return [], 0

def show_supplier_list(chat_id, page=0, search=None):
    items, total = get_supplier_markup(page, search)
    if not items:
        bot.send_message(chat_id, "⚠️ Firmalar topilmadi. Bito'da yetkazib beruvchilar mavjudligini tekshiring.")
        return
    total_pages = (total + ZAKAZ_PAGE_SIZE - 1) // ZAKAZ_PAGE_SIZE
    markup = types.InlineKeyboardMarkup(row_width=2)
    for sup in items:
        sid = sup.get("_id","")
        sname = sup.get("name","?")
        total_sale = sup.get("total_sale", 0)
        label = f"{sname} ({total_sale} xarid)" if total_sale else sname
        markup.add(types.InlineKeyboardButton(label, callback_data=f"zakaz_sup_{sid}"))

    # Sahifalar
    nav = []
    if page > 0:
        nav.append(types.InlineKeyboardButton("⬅️ Oldingi", callback_data=f"zakaz_page_{page-1}"))
    if page < total_pages - 1:
        nav.append(types.InlineKeyboardButton("➡️ Keyingi", callback_data=f"zakaz_page_{page+1}"))
    if nav:
        markup.row(*nav)
    markup.add(types.InlineKeyboardButton("🔍 Firma qidirish", callback_data="zakaz_search"))

    title = f"🛒 *Zakaz — Firmalar ro'yxati*"
    if search:
        title += f"\n🔍 Qidiruv: _{search}_"
    title += f"\n📄 Sahifa {page+1}/{max(total_pages,1)} ({total} ta firma)"
    bot.send_message(chat_id, title, parse_mode="Markdown", reply_markup=markup)

@bot.message_handler(func=lambda m: m.text == "🛒 Zakaz")
def zakaz_menu(message):
    if not is_boss_or_mgr(message.from_user.id): return
    show_supplier_list(message.chat.id, page=0)

W_ZAKAZ_SEARCH = TDict()

@bot.callback_query_handler(func=lambda c: c.data.startswith("zakaz_"))
def zakaz_cb(call):
    if not is_boss_or_mgr(call.from_user.id):
        _ack(call, "Ruxsat yo'q!"); return
    _ack(call)
    data = call.data

    if data.startswith("zakaz_page_"):
        page = int(data.replace("zakaz_page_", ""))
        try: bot.delete_message(call.message.chat.id, call.message.message_id)
        except: pass
        show_supplier_list(call.message.chat.id, page=page)

    elif data == "zakaz_search":
        W_ZAKAZ_SEARCH[call.from_user.id] = True
        bot.send_message(call.message.chat.id, "🔍 Firma nomini yozing (masalan: Coca, Lochira, Tuxum):")

    elif data.startswith("zakaz_sup_"):
        # 📅 Avval muddat so'raymiz (2026-08-08 so'rov): zakaz necha
        # haftaga yetishi kerak — tavsiya shunga qarab hisoblanadi
        sid = data.replace("zakaz_sup_", "")
        kb = types.InlineKeyboardMarkup(row_width=4)
        kb.add(*[types.InlineKeyboardButton(f"{w} hafta",
                 callback_data=f"zakaz_wk_{w}_{sid}") for w in (1, 2, 3, 4)])
        bot.send_message(call.message.chat.id,
                         "📅 Zakaz qancha muddatga yetadigan bo'lsin?",
                         reply_markup=kb)

    elif data.startswith("zakaz_wk_"):
        rest = data.replace("zakaz_wk_", "")
        weeks_s, _, sid = rest.partition("_")
        try:
            weeks = max(1, min(8, int(weeks_s)))
        except ValueError:
            weeks = 1
        bot.send_message(call.message.chat.id,
            f"⏳ Bito'dan ma'lumot olinmoqda va AI zakaz tavsiyasi "
            f"tayyorlanmoqda ({weeks} haftalik, 30-60 soniya)...")
        import threading
        threading.Thread(target=lambda: generate_zakaz_advice(
            call.message.chat.id, sid, weeks=weeks), daemon=True).start()

@bot.message_handler(func=lambda m: m.from_user.id in W_ZAKAZ_SEARCH)
def zakaz_search_handler(message):
    tg_id = message.from_user.id
    if message.text in MENU_TEXTS:
        W_ZAKAZ_SEARCH.pop(tg_id, None); return
    W_ZAKAZ_SEARCH.pop(tg_id, None)
    try: bot.delete_message(message.chat.id, message.message_id - 1)
    except: pass
    show_supplier_list(message.chat.id, page=0, search=message.text.strip())


def generate_zakaz_advice(chat_id, supplier_id, weeks=1):
    """✅ TO'G'RI: Firmadan harid qilingan mahsulotlar asosida zakaz.

    MUHIM: purchase/get-paging javobida mahsulotlar RO'YXATI yo'q —
    ular faqat purchase/get-by-id orqali ko'rinadi. Shuning uchun:
      1) avval qaysi filtr parametri (supliaer_id/supplier_id/supplier_ids)
         ishlashini aniqlaymiz (test_supplier_filter_variants),
      2) ishlaydigani bo'lsa o'sha bilan, bo'lmasa bruteforce bilan
         supplier'ning BARCHA xaridlarini topamiz,
      3) har bir xaridni get-by-id orqali ochib, ichidagi mahsulotlarni yig'amiz.
    """
    if is_license_locked():
        bot.send_message(chat_id, "🔒 Obuna muddati tugagan. To'lovni amalga oshirib, bot egasi bilan bog'laning.")
        return
    try:
        _t0 = time.time()  # ⏱ Umumiy vaqt hisoblagichi
        headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
        base = "https://api.bito.uz/integration-api/integration/api/v2/"

        # 1. Firma ma'lumoti
        r_sup = requests.get(base + f"supplier/get-by-id/{supplier_id}",
                            headers=headers, timeout=10)
        r_sup.raise_for_status()
        sup_data = r_sup.json().get("data", {})
        sup_name = sup_data.get("name", "?") if isinstance(sup_data, dict) else "?"
        print(f"[ZAKAZ] Firma: {sup_name}", flush=True)
        print(f"[VAQT] 1-bosqich (firma ma'lumoti): {time.time()-_t0:.1f}s", flush=True)
        _t1 = time.time()

        # 2. ✅ QAYSI FILTR PARAMETRI ISHLASHINI ANIQLAYMIZ
        variant_results = test_supplier_filter_variants(supplier_id)
        working_variant = next((v for v in variant_results if v.get("ok") and v.get("filter_works")), None)
        param_map = {
            "supliaer_id (string, docs.bito.uz'dagi xato yozilgan nom)": {"supliaer_id": supplier_id},
            "supplier_id (string, to'g'ri yozilgan)": {"supplier_id": supplier_id},
            "supplier_ids (array)": {"supplier_ids": [supplier_id]},
            "supliaer_ids (array, xato yozilgan)": {"supliaer_ids": [supplier_id]},
        }

        purchases_summary = []
        if working_variant:
            print(f"[ZAKAZ] Ishlaydigan filtr: {working_variant['label']}", flush=True)
            extra = param_map[working_variant["label"]]
            page = 1
            while True:
                body = {"page": page, "limit": 200}
                body.update(extra)
                r = requests.post(base + "purchase/get-paging", json=body, headers=headers, timeout=30)
                if r.status_code != 200: break
                j = r.json()
                d = j.get("data", j)
                items = d.get("data", []) if isinstance(d, dict) else (d or [])
                total = d.get("total", 0) if isinstance(d, dict) else 0
                if not items: break
                purchases_summary.extend(items)
                if page * 200 >= total: break
                page += 1
        else:
            print("[ZAKAZ] Hech qaysi filtr ishlamadi — bruteforce qidirilmoqda", flush=True)
            purchases_summary = find_purchases_by_supplier_bruteforce(supplier_id, max_pages=20, page_size=200)

        print(f"[ZAKAZ] Topilgan xaridlar soni: {len(purchases_summary)}", flush=True)
        print(f"[VAQT] 2-bosqich (xaridlar ro'yxati, Bito): {time.time()-_t1:.1f}s", flush=True)
        _t2 = time.time()

        # 3. ✅ HAR BIR XARIDNI OCHIB, MAHSULOTLARNI VA OXIRGI NARXNI YIG'AMIZ
        # ANIQLANDI (loglar orqali): full["orders"] -> har bir order["products"] -> mahsulotlar
        # ⚡ TEZLIK: har bir xaridni KETMA-KET emas, PARALLEL (bir vaqtda 8 tadan)
        # ochamiz — bu 3-bosqichni bir necha barobar tezlashtiradi.
        from concurrent.futures import ThreadPoolExecutor
        product_records = []  # [{pid, name, cost, date}]
        debug_printed = False

        valid_purchases = [p for p in purchases_summary if isinstance(p, dict) and p.get("_id")]
        with ThreadPoolExecutor(max_workers=8) as executor:
            fulls = list(executor.map(lambda p: (p, get_purchase_full_by_id(p["_id"])), valid_purchases))

        for pur, full in fulls:
            pur_date = full.get("date") or (pur.get("date") if isinstance(pur, dict) else "") or ""
            orders = full.get("orders") or []
            if not debug_printed:
                print(f"[ZAKAZ-DEBUG] orders soni = {len(orders)}", flush=True)
                if orders and isinstance(orders[0], dict):
                    prods = orders[0].get("products") or []
                    print(f"[ZAKAZ-DEBUG] birinchi order.products soni = {len(prods)}", flush=True)
                    if prods and isinstance(prods[0], dict):
                        print(f"[ZAKAZ-DEBUG] birinchi product.keys() = {list(prods[0].keys())}", flush=True)
                debug_printed = True
            for order in (orders or []):
                if not isinstance(order, dict):
                    continue
                products = order.get("products") or []
                for item in (products or []):
                    if isinstance(item, dict):
                        prod = item.get("product") or {}
                        real_pid = (prod.get("_id") if isinstance(prod, dict) else None) \
                                   or item.get("product_id") or item.get("productId")
                        pname = (prod.get("name") if isinstance(prod, dict) else None) \
                                or item.get("product_name") or item.get("productName") or item.get("name")
                        cost = item.get("cost") or 0
                        qty_bought = item.get("amount") or 0
                        if not cost:
                            amt = item.get("amount") or 0
                            tc = item.get("total_cost") or 0
                            if amt:
                                cost = tc / amt
                        if real_pid and pname:
                            product_records.append({
                                "pid": str(real_pid), "name": pname,
                                "cost": cost or 0, "date": pur_date,
                                "qty": qty_bought or 0
                            })

        # Har bir mahsulot uchun ENG OXIRGI (eng yangi sanali) narxni tanlaymiz
        purchased_product_ids = {}
        last_price_map = {}
        for rec in sorted(product_records, key=lambda r: r["date"], reverse=True):
            pid = rec["pid"]
            if pid not in purchased_product_ids:
                purchased_product_ids[pid] = rec["name"]
                print(f"[ZAKAZ] Mahsulot: {rec['name']} | oxirgi narx: {rec['cost']}", flush=True)
            if pid not in last_price_map:
                last_price_map[pid] = rec["cost"]

        # ✅ Har bir mahsulot uchun umumiy harid tarixi (jami dona, birinchi/oxirgi sana)
        purchase_history_agg = {}
        for rec in product_records:
            pid = rec["pid"]
            a = purchase_history_agg.setdefault(pid, {
                "total_qty": 0, "first_date": rec["date"], "last_date": rec["date"]
            })
            a["total_qty"] += (rec.get("qty") or 0)
            if rec["date"] and (not a["first_date"] or rec["date"] < a["first_date"]):
                a["first_date"] = rec["date"]
            if rec["date"] and (not a["last_date"] or rec["date"] > a["last_date"]):
                a["last_date"] = rec["date"]

        print(f"[ZAKAZ] Jami: {len(purchased_product_ids)}", flush=True)
        print(f"[VAQT] 3-bosqich (har bir xaridni ochish, Bito x{len(purchases_summary)} so'rov): {time.time()-_t2:.1f}s", flush=True)
        _t3 = time.time()
        
        if not purchased_product_ids:
            bot.send_message(chat_id, f"⚠️ {h(sup_name)} firmadan harid qilingan mahsulot topilmadi.")
            return

        # 3. ✅ O'SHA MAHSULOTLARNING HAFTALIK SAVDOSINI OLISH (BARCHA sahifalar bo'yicha)
        import datetime as _dt
        week_start = (now_dt() - timedelta(days=7)).strftime("%Y-%m-%d")
        to_utc = lambda d: _dt.datetime.strptime(d,"%Y-%m-%d").replace(tzinfo=UZT).astimezone(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")

        sales_dict = {}
        page = 1
        while page <= 10:  # xavfsizlik uchun max 10 sahifa (~2000 mahsulot)
            r_sales = requests.post(base + "sales/by-item-pagin",
                json={"page": page, "limit": 200, "from_date": to_utc(week_start),
                      "organization_ids": [CFG.BITO_ORG_ID]},
                headers=headers, timeout=30)
            if r_sales.status_code != 200:
                break
            sd = r_sales.json().get("data", {})
            sales_list = sd.get("data", []) if isinstance(sd, dict) else (sd or [])
            total_sales_items = sd.get("total", 0) if isinstance(sd, dict) else 0
            if not sales_list:
                break
            for item in sales_list:
                if isinstance(item, dict):
                    pid = str(item.get("product_id") or item.get("_id") or "")
                    pname = item.get("product_name", "?")
                    qty = item.get("items_sold", 0) or 0
                    if pid in purchased_product_ids and qty > 0:
                        sales_dict[pid] = {
                            "name": pname or purchased_product_ids[pid],
                            "qty_week": qty
                        }
            if page * 200 >= total_sales_items:
                break
            page += 1

        print(f"[ZAKAZ] Haftalik: {len(sales_dict)}", flush=True)
        print(f"[VAQT] 4-bosqich (haftalik savdo, Bito): {time.time()-_t3:.1f}s", flush=True)
        _t4 = time.time()

        # 4. ✅ OMBOR QOLDIG'INI TEKSHIRISH (product/get-paging + search, ISHLAYDIGAN usul)
        debug_keys_printed = False
        debug_wh_printed = False

        def _lookup_stock(pid, pname_for_search):
            nonlocal debug_keys_printed, debug_wh_printed
            stock = 0
            try:
                rp = requests.post(base + "product/get-paging",
                    json={"limit": 5, "page": 1, "search": pname_for_search},
                    headers=headers, timeout=15)
                if rp.status_code == 200:
                    pdata = rp.json().get("data", {})
                    plist = pdata.get("data", []) if isinstance(pdata, dict) else (pdata or [])
                    for p in plist:
                        if not isinstance(p, dict):
                            continue
                        if not debug_keys_printed:
                            print(f"[ZAKAZ-DEBUG] product.keys() = {list(p.keys())}", flush=True)
                            debug_keys_printed = True
                        if str(p.get("_id")) == str(pid):
                            whs = (p.get("_warehouses") or p.get("warehouses")
                                   or p.get("product_warehouses") or [])
                            if not debug_wh_printed:
                                print(f"[ZAKAZ-DEBUG] _warehouses = {whs}", flush=True)
                                debug_wh_printed = True
                            if isinstance(whs, dict):
                                stock = sum((v.get("amount", 0) or 0) for v in whs.values() if isinstance(v, dict))
                            elif isinstance(whs, list):
                                stock = sum((w.get("amount", 0) or 0) for w in whs if isinstance(w, dict))
                            break
            except Exception as e:
                print("STOCK ERR:", str(e)[:120], flush=True)
            return stock

        product_details = []
        for pid in list(purchased_product_ids.keys()):
            if pid not in sales_dict:
                continue
            stock = _lookup_stock(pid, purchased_product_ids.get(pid, ""))
            si = sales_dict[pid]
            product_details.append({
                "name": si["name"],
                "qty_week": si["qty_week"],
                "stock": int(stock),
                "last_price": last_price_map.get(pid, 0)
            })

        # ✅ SOTILMAYOTGAN (STALE) MAHSULOTLARNI ANIQLASH
        # — haridlar orasida bor, lekin so'nggi hafta ichida SOTILMAGAN mahsulotlar
        stale_products = []
        for pid, pname in purchased_product_ids.items():
            if pid in sales_dict:
                continue  # bu hafta sotilgan — stale emas
            hist = purchase_history_agg.get(pid, {})
            stock = _lookup_stock(pid, pname)
            stale_products.append({
                "name": pname,
                "total_qty": hist.get("total_qty", 0),
                "first_date": (hist.get("first_date") or "")[:10],
                "last_date": (hist.get("last_date") or "")[:10],
                "stock": stock
            })
        stale_products.sort(key=lambda x: -x["total_qty"])
        print(f"[VAQT] 5-bosqich (ombor qoldig'i + stale tekshiruvi, Bito): {time.time()-_t4:.1f}s", flush=True)
        _t5 = time.time()

        if not product_details and not stale_products:
            bot.send_message(chat_id, f"⚠️ {h(sup_name)} bo'yicha ma'lumot topilmadi.")
            return

        # 5. ✅ TAVSIYA ETILGAN MIQDOR VA SUMMANI DASTURIY HISOBLASH
        def _zqty(x):
            """Miqdorni halol ko'rsatish (2026-08-08 xatosidan):
            kasrli (kg/litr) miqdor :,.0f bilan 0.496→«0» bo'lib chiqardi,
            summa esa kasr bilan hisoblanib jadval mos kelmasdi. Butun
            bo'lsa butun, kasr bo'lsa 2 xonagacha (2.512→«2.51»)."""
            x = float(x or 0)
            if abs(x - round(x)) < 0.005:
                return f"{int(round(x)):,}"
            return f"{x:,.2f}".rstrip("0").rstrip(".")

        def calc_recommended_qty(qty_week, stock):
            """weeks haftalik ehtiyoj MINUS ombordagi qoldiq.
            Eski usul (qoldiqqa qarab % pasaytirish) o'rniga to'g'ridan:
            kerak = haftalik_savdo × hafta − qoldiq; 0 dan past emas."""
            need = qty_week * weeks - max(stock, 0)
            return max(need, 0)

        for p in product_details:
            p["recommended_qty"] = calc_recommended_qty(p["qty_week"], p["stock"])
            p["estimated_cost"] = p["recommended_qty"] * p["last_price"]

        sorted_products = sorted(product_details, key=lambda x: x['qty_week'], reverse=True)
        total_estimated = sum(p["estimated_cost"] for p in sorted_products)

        # 🪓 AJRATISH (2026-08-08): 0 li qatorlar jadvalni to'ldirib
        # «nega 0?» degan savol tug'dirardi. Jadvalda faqat zakaz KERAK
        # bo'lganlar; qoldiq yetarli bo'lganlar alohida ro'yxatda —
        # qoldiq va ehtiyoj yonma-yon, sababi ko'rinib turadi.
        need_products = [p for p in sorted_products if p["recommended_qty"] > 0.004]
        enough_products = [p for p in sorted_products if p["recommended_qty"] <= 0.004]

        # 📊 JADVAL (monospace, Telegram <pre> ichida chiroyli ko'rinadi)
        def _fit(s, n):
            s = str(s)
            return s[:n] if len(s) <= n else s[:n-1] + "…"

        table_text = ""
        if need_products:
            header = f"{'Mahsulot':<22}{'Zakaz':>7}{'Narx':>11}{'Summa':>13}"
            sep = "-" * len(header)
            table_rows = [header, sep]
            for p in need_products:
                table_rows.append(
                    f"{_fit(p['name'],22):<22}{_zqty(p['recommended_qty']):>7}"
                    f"{p['last_price']:>11,.0f}{p['estimated_cost']:>13,.0f}"
                )
            table_rows.append(sep)
            table_rows.append(f"{'JAMI':<22}{'':>7}{'':>11}{total_estimated:>13,.0f}")
            table_text = "\n".join(table_rows)

        enough_text = ""
        if enough_products:
            enough_text = "\n".join(
                f"• {p['name']}: omborda {_zqty(p['stock'])} bor, "
                f"{weeks} haftalik ehtiyoj ~{_zqty(p['qty_week'] * weeks)} — yetarli"
                for p in enough_products)

        def _unit_sfx(x):
            # kasrli miqdorga «dona/ta» yozmaymiz — bu kg/litr mahsulot
            return " dona" if abs(float(x or 0) - round(float(x or 0))) < 0.005 else ""

        detail_text = "\n".join([
            f"• {p['name']}: haftasiga {_zqty(p['qty_week'])}{_unit_sfx(p['qty_week'])} "
            f"| omborida {_zqty(p['stock'])}{_unit_sfx(p['stock'])} "
            f"| TAVSIYA: {_zqty(p['recommended_qty'])}{_unit_sfx(p['recommended_qty'])} "
            f"(narxi {p['last_price']:,.0f} so'm) "
            f"= {p['estimated_cost']:,.0f} so'm"
            for p in sorted_products
        ]) if sorted_products else "(faol sotilayotgan mahsulot topilmadi)"

        # ⚠️ STALE MAHSULOTLAR MATNI
        stale_text = ""
        if stale_products:
            stale_lines = []
            for sp in stale_products:
                date_range = f"{sp['first_date']} dan {sp['last_date']} gacha" if sp['first_date'] else "noma'lum sanada"
                stale_lines.append(
                    f"• {sp['name']}: {date_range} jami {_zqty(sp['total_qty'])} "
                    f"marta/dona harid qilingan, lekin so'nggi hafta ichida "
                    f"SOTILMAGAN (omborda hozir {_zqty(sp['stock'])}"
                    f"{_unit_sfx(sp['stock'])} qoldi). "
                    f"Qayta sotishni sinab ko'rmaysizmi?"
                )
            stale_text = "\n".join(stale_lines)

        # 6. ✅ AI'DAN QISQA IZOH (raqamlar allaqachon hisoblangan, AI faqat sharh beradi)
        advice = ""
        if sorted_products:
            prompt = f"""VAZIFA: {sup_name} firmasidan zakaz bo'yicha QISQA amaliy sharh yoz (3-5 gap).
Raqamlar ALLAQACHON hisoblangan, sen ularni QAYTA HISOBLAMA — faqat muhim narsalarga
(masalan qaysi mahsulot eng ustuvor, qaysi biri kutilishi mumkin) e'tibor qarat.

MAHSULOTLAR VA TAVSIYA ETILGAN ZAKAZ:
{detail_text}

JAMI TAXMINIY ZAKAZ SUMMASI: {total_estimated:,.0f} so'm

Javobni oddiy, qisqa va amaliy tilda yoz. Raqamlarni takrorlama, faqat izoh ber."""

            resp = requests.post(
                "https://api.anthropic.com/v1/messages",
                headers={"x-api-key": ANTHROPIC_API_KEY,
                         "anthropic-version": "2023-06-01",
                         "content-type": "application/json"},
                json={"model": "claude-sonnet-4-6", "max_tokens": 512,
                      "messages": [{"role": "user", "content": prompt}]},
                timeout=60
            )
            resp.raise_for_status()
            advice = resp.json().get("content",[{}])[0].get("text","Tavsiya olinmadi.")
            print(f"[VAQT] 6-bosqich (Claude AI tavsiyasi): {time.time()-_t5:.1f}s", flush=True)

        parts = [f"🛒 <b>Zakaz tavsiyasi — {h(sup_name)}</b> ({weeks} haftalik)"]
        if not need_products and sorted_products:
            parts.append("✅ <b>Zakaz shart emas</b> — ombordagi qoldiq "
                         f"{weeks} haftalik ehtiyojni to'liq qoplaydi.")
        if table_text:
            parts.append(f"📊 <b>JADVAL:</b>\n<pre>{h(table_text)}</pre>")
            parts.append(f"💰 <b>Jami taxminiy zakaz summasi: {total_estimated:,.0f} so'm</b>")
        if enough_text:
            parts.append(f"✅ <b>Zakaz kerak emas (ombor yetarli):</b>\n{enough_text}")
        if advice:
            parts.append(f"🤖 <b>IZOH:</b>\n{h(advice)}")
        if stale_text:
            parts.append(f"⏳ <b>SOTILMAYOTGAN MAHSULOTLAR:</b>\n{h(stale_text)}")

        text = "\n\n".join(parts)
        send_long_message(chat_id, text, parse_mode="HTML")
        print(f"[VAQT] ⏱ JAMI: {time.time()-_t0:.1f}s", flush=True)
        print(f"[ZAKAZ] ✅ {len(product_details)} faol, {len(stale_products)} stale, jami summa: {total_estimated:,.0f}", flush=True)
    except Exception as e:
        print("ZAKAZ ERR:", str(e)[:200], flush=True)
        bot.send_message(chat_id, f"⚠️ Xatolik: {str(e)[:100]}")

