# ===== SUPPLIER FILTER TEST VA ROBUST QIDIRUV =====
def _bito_headers():
    return {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}

def _bito_base():
    return "https://api.bito.uz/integration-api/integration/api/v2/"

def test_supplier_filter_variants(supplier_id):
    """
    /purchase/get-paging endpointi qaysi parametr nomi bilan
    supplier bo'yicha TO'G'RI filtrlashini aniqlaydi.
    Natija: har bir variant uchun (label, ok, jami, qaytgan, mos_kelgan, supplierlar_ro'yxati)
    """
    base = _bito_base()
    headers = _bito_headers()
    variants = [
        ("supliaer_id (string, docs.bito.uz'dagi xato yozilgan nom)", {"supliaer_id": supplier_id}),
        ("supplier_id (string, to'g'ri yozilgan)", {"supplier_id": supplier_id}),
        ("supplier_ids (array)", {"supplier_ids": [supplier_id]}),
        ("supliaer_ids (array, xato yozilgan)", {"supliaer_ids": [supplier_id]}),
    ]
    results = []
    for label, extra in variants:
        try:
            body = {"page": 1, "limit": 10}
            body.update(extra)
            r = requests.post(base + "purchase/get-paging", json=body, headers=headers, timeout=20)
            if r.status_code != 200:
                results.append({"label": label, "ok": False, "error": f"HTTP {r.status_code}"})
                continue
            j = r.json()
            d = j.get("data", j)
            items = d.get("data", []) if isinstance(d, dict) else (d or [])
            total = d.get("total", 0) if isinstance(d, dict) else 0
            matched = sum(1 for it in items if isinstance(it, dict) and str(it.get("supplier_id", "")) == str(supplier_id))
            supplier_names = sorted(set(
                ((it.get("supplier") or {}).get("name", "?")) for it in items if isinstance(it, dict)
            ))
            filter_works = bool(items) and matched == len(items)
            results.append({
                "label": label, "ok": True, "total": total,
                "returned": len(items), "matched": matched,
                "suppliers_seen": supplier_names, "filter_works": filter_works
            })
        except Exception as e:
            results.append({"label": label, "ok": False, "error": str(e)[:150]})
    return results

def find_purchases_by_supplier_bruteforce(supplier_id, max_pages=20, page_size=200):
    """
    Agar hech qanday filtr parametri ishlamasa, BARCHA xaridlarni sahifalab
    o'qib, supplier_id bo'yicha o'zimiz filtrlaymiz. Railway serverida
    ishlaydi (cheklanmagan internet), shuning uchun 3000+ yozuvni ham
    bemalol qayta ishlay oladi.
    Natija: mos kelgan xaridlar ro'yxati (raw dict'lar).
    """
    base = _bito_base()
    headers = _bito_headers()
    matches = []
    page = 1
    while page <= max_pages:
        try:
            r = requests.post(base + "purchase/get-paging",
                               json={"page": page, "limit": page_size, "sort": "-date"},
                               headers=headers, timeout=30)
            if r.status_code != 200:
                break
            j = r.json()
            d = j.get("data", j)
            items = d.get("data", []) if isinstance(d, dict) else (d or [])
            total = d.get("total", 0) if isinstance(d, dict) else 0
            if not items:
                break
            for it in items:
                if isinstance(it, dict) and str(it.get("supplier_id", "")) == str(supplier_id):
                    matches.append(it)
            # Agar shu supplier ilk marta paydo bo'lgan sanadan oldinroq
            # sahifalarga yetgan bo'lsak va hali hech narsa topmasak,
            # baribir oxirigacha davom etamiz (max_pages bilan cheklangan holda).
            if (page * page_size) >= total:
                break
            page += 1
        except Exception as e:
            print("BRUTEFORCE ERR:", str(e)[:150], flush=True)
            break
    return matches

def get_purchase_full_by_id(purchase_id):
    """Bitta xaridning to'liq tafsilotini (mahsulotlar bilan) oladi."""
    base = _bito_base()
    headers = _bito_headers()
    try:
        r = requests.get(base + f"purchase/get-by-id/{purchase_id}", headers=headers, timeout=15)
        if r.status_code == 200:
            return r.json().get("data", {})
    except Exception as e:
        print("PURCHASE BY ID ERR:", str(e)[:150], flush=True)
    return {}

@bot.message_handler(commands=['test_supplier'])
def test_supplier_cmd(message):
    """Foydalanish: /test_supplier <supplier_id>"""
    if not is_boss_or_mgr(message.from_user.id): return
    parts = message.text.split(maxsplit=1)
    if len(parts) < 2:
        bot.send_message(message.chat.id, "Foydalanish:\n`/test_supplier 698d8529e41634f093cfd096`", parse_mode="Markdown")
        return
    supplier_id = parts[1].strip()
    bot.send_message(message.chat.id, f"🔬 `{supplier_id}` uchun 4 xil parametr nomi sinalmoqda...", parse_mode="Markdown")
    import threading
    def run():
        results = test_supplier_filter_variants(supplier_id)
        lines = [f"🔬 *Supplier filter test natijasi*\nID: `{supplier_id}`\n"]
        any_works = False
        for res in results:
            if not res.get("ok"):
                lines.append(f"❌ {res['label']}\n   Xato: {res.get('error')}")
                continue
            mark = "✅ ISHLAYDI" if res["filter_works"] else "⚠️ e'tiborga olinmadi"
            if res["filter_works"]:
                any_works = True
            lines.append(
                f"{mark} — {res['label']}\n"
                f"   jami(filtrsiz)={res['total']}, qaytgan={res['returned']}, mos_kelgan={res['matched']}\n"
                f"   ko'ringan supplierlar: {', '.join(res['suppliers_seen']) or '-'}"
            )
        if any_works:
            lines.append("\n🎉 Kamida bitta parametr nomi ISHLAYAPTI — shuni ishlatamiz!")
        else:
            lines.append("\n⚠️ Hech biri ishlamadi. Endi /firma_xaridlari orqali "
                          "sahifama-sahifa qidirib topamiz (biroz sekinroq, lekin 100% aniq).")
        bot.send_message(message.chat.id, "\n\n".join(lines), parse_mode="Markdown")
    threading.Thread(target=run, daemon=True).start()

@bot.message_handler(commands=['firma_xaridlari'])
def firma_xaridlari_cmd(message):
    """
    Foydalanish: /firma_xaridlari <supplier_id>
    Avval tezkor filtrni sinaydi, ishlamasa BARCHA xaridlarni
    sahifalab o'zi filtrlaydi va har bir xariddagi mahsulotlarni yig'ib,
    yakuniy ro'yxatni yuboradi.
    """
    if not is_boss_or_mgr(message.from_user.id): return
    parts = message.text.split(maxsplit=1)
    if len(parts) < 2:
        bot.send_message(message.chat.id, "Foydalanish:\n`/firma_xaridlari 698d8529e41634f093cfd096`", parse_mode="Markdown")
        return
    supplier_id = parts[1].strip()
    bot.send_message(message.chat.id, "⏳ Qidirilmoqda, bu 1-2 daqiqa vaqt olishi mumkin...")
    import threading
    def run():
        base = _bito_base()
        headers = _bito_headers()

        # Firma nomini olish
        sup_name = supplier_id
        try:
            r_sup = requests.get(base + f"supplier/get-by-id/{supplier_id}", headers=headers, timeout=10)
            if r_sup.status_code == 200:
                sup_name = r_sup.json().get("data", {}).get("name", supplier_id)
        except Exception:
            pass

        # 1) Avval tez filtrni sinaymiz
        variant_results = test_supplier_filter_variants(supplier_id)
        working_variant = next((v for v in variant_results if v.get("ok") and v.get("filter_works")), None)

        purchases = []
        if working_variant:
            # Ishlaydigan parametr bilan to'liq ro'yxatni olamiz
            param_map = {
                "supliaer_id (string, docs.bito.uz'dagi xato yozilgan nom)": {"supliaer_id": supplier_id},
                "supplier_id (string, to'g'ri yozilgan)": {"supplier_id": supplier_id},
                "supplier_ids (array)": {"supplier_ids": [supplier_id]},
                "supliaer_ids (array, xato yozilgan)": {"supliaer_ids": [supplier_id]},
            }
            extra = param_map[working_variant["label"]]
            page = 1
            while True:
                body = {"page": page, "limit": 200}
                body.update(extra)
                r = requests.post(base + "purchase/get-paging", json=body, headers=headers, timeout=30)
                if r.status_code != 200: break
                j = r.json()
                d = j.get("data", j)
                items = d.get("data", []) if isinstance(d, dict) else (d or [])
                total = d.get("total", 0) if isinstance(d, dict) else 0
                if not items: break
                purchases.extend(items)
                if page * 200 >= total: break
                page += 1
        else:
            # 2) Hech qaysi filtr ishlamasa — qo'lda (bruteforce) qidiramiz
            bot.send_message(message.chat.id, "⚠️ Tezkor filtr ishlamadi, barcha xaridlarni tekshiryapman (sekinroq)...")
            purchases = find_purchases_by_supplier_bruteforce(supplier_id, max_pages=20, page_size=200)

        if not purchases:
            bot.send_message(message.chat.id, f"⚠️ {h(sup_name)} firmasidan hech qanday xarid topilmadi.")
            return

        # Har bir xariddagi mahsulotlarni yig'amiz (orders[].products[] tuzilmasi)
        product_totals = {}  # nomi -> jami dona
        for pur in purchases:
            pid = pur.get("_id")
            if not pid:
                continue
            full = get_purchase_full_by_id(pid)
            orders = full.get("orders") or []
            for order in orders:
                if not isinstance(order, dict):
                    continue
                products = order.get("products") or []
                for it in (products or []):
                    if not isinstance(it, dict):
                        continue
                    prod = it.get("product") or {}
                    pname = (prod.get("name") if isinstance(prod, dict) else None) \
                            or it.get("product_name") or it.get("name") or "?"
                    qty = it.get("amount") or it.get("quantity") or it.get("income_amount") or 0
                    product_totals[pname] = product_totals.get(pname, 0) + (qty or 0)

        if not product_totals:
            bot.send_message(message.chat.id, f"⚠️ {h(sup_name)}: {len(purchases)} ta xarid topildi, lekin mahsulot tafsiloti o'qilmadi.")
            return

        sorted_products = sorted(product_totals.items(), key=lambda x: -x[1])
        lines = [f"📦 <b>{h(sup_name)} firmasidan harid qilingan mahsulotlar</b>",
                 f"Jami xaridlar soni: {len(purchases)}\n"]
        for name, qty in sorted_products:
            lines.append(f"• {h(str(name))}: {qty:g} dona")
        send_long_message(message.chat.id, "\n".join(lines), parse_mode="HTML")

    threading.Thread(target=run, daemon=True).start()
