# ══════════════════════════════════════════════════════════════════
# 🎤 OVOZLI BOSHQARUV
# Gemini — ovozni matnga aylantiradi (STT), Claude — ma'nosini tushunib,
# kerakli funksiyani chaqiradi yoki erkin javob beradi.
# ══════════════════════════════════════════════════════════════════
GROQ_API_KEY = os.getenv("GROQ_API_KEY", "")

def groq_transcribe(audio_bytes, filename="voice.ogg"):
    """Groq Whisper orqali ovozni matnga aylantiradi (bepul, tez, o'zbek tilini biladi)."""
    if not GROQ_API_KEY:
        return None, "GROQ_API_KEY o'rnatilmagan"
    try:
        r = requests.post(
            "https://api.groq.com/openai/v1/audio/transcriptions",
            headers={"Authorization": f"Bearer {GROQ_API_KEY}"},
            files={"file": (filename, audio_bytes)},
            data={"model": "whisper-large-v3", "response_format": "json", "language": "uz",
                  "prompt": "Bugungi savdo qanday, kechagi savdo, zakaz tavsiyasi, ombor, "
                             "mahsulot, xodimlarga vazifa, hisobot, ball, maosh, turib qolgan mahsulotlar"},
            timeout=60)
        r.raise_for_status()
        text = (r.json().get("text") or "").strip()
        if text:
            return text, None
        return None, "Groq: bo'sh transkripsiya"
    except Exception as e:
        print("GROQ STT ERR:", str(e)[:200], flush=True)
        return None, f"Groq xatosi: {str(e)[:100]}"

def transcribe_audio(audio_bytes, mime_type="audio/ogg", filename="voice.ogg"):
    """Asosiy STT: avval Groq (bepul va ishonchli), bo'lmasa Gemini."""
    if GROQ_API_KEY:
        text, err = groq_transcribe(audio_bytes, filename)
        if text:
            return text, None
        print(f"STT: Groq ishlamadi ({err}), Gemini sinaladi...", flush=True)
    return gemini_transcribe(audio_bytes, mime_type)

def gemini_transcribe(audio_bytes, mime_type="audio/ogg"):
    """Gemini API orqali ovozni matnga aylantiradi. (None, xato) yoki (matn, None).
    429 (kvota tugadi) bo'lsa — boshqa modellar bilan qayta urinadi."""
    if not GEMINI_API_KEY:
        return None, "GEMINI_API_KEY o'rnatilmagan (Railway Variables'da bor bo'lishi kerak)."
    import base64
    payload = {
        "contents": [{"parts": [
            {"inline_data": {"mime_type": mime_type,
                              "data": base64.b64encode(audio_bytes).decode()}},
            {"text": "Bu audioni aynan aytilganidek matnga o'gir. Til o'zbek, rus yoki "
                      "qoraqalpoq bo'lishi mumkin. FAQAT transkripsiya matnini qaytar, "
                      "boshqa hech narsa yozma."}
        ]}]
    }
    # Har xil modellarning alohida kvotalari bor — birida tugasa, boshqasini sinaymiz
    models = ["gemini-2.5-flash", "gemini-2.0-flash", "gemini-2.5-flash-lite", "gemini-2.0-flash-lite"]
    last_err = ""
    for model in models:
        for attempt in range(2):
            try:
                r = requests.post(
                    f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent?key={GEMINI_API_KEY}",
                    json=payload, timeout=60)
                if r.status_code == 429:
                    last_err = f"{model}: kvota tugadi (429)"
                    print(f"GEMINI STT 429: {model}, urinish {attempt+1}", flush=True)
                    time.sleep(3)
                    continue
                r.raise_for_status()
                cands = r.json().get("candidates", [])
                if cands:
                    parts = cands[0].get("content", {}).get("parts", [])
                    text = " ".join(p.get("text", "") for p in parts).strip()
                    if text:
                        return text, None
                last_err = f"{model}: bo'sh javob"
                break
            except Exception as e:
                last_err = f"{model}: {str(e)[:80]}"
                print("GEMINI STT ERR:", last_err, flush=True)
                break
    return None, (f"Gemini kvotasi tugagan ko'rinadi. Yangi kalit oling: aistudio.google.com "
                   f"(oxirgi xato: {last_err})")

def route_voice_intent(tg_id, transcript):
    """Claude orqali aytilgan gapning MAQSADINI aniqlaydi.
    Natija: dict(intent, param, reply, normalized)."""
    role = get_role(tg_id)
    role_desc = "boshliq/menejer" if role in ("boss", "manager") else "xodim"
    prompt = f"""Sen supermarket Telegram botining ovozli buyruq tahlilchisisan.
Foydalanuvchi ({role_desc}) ovozli xabarda shunday dedi (transkripsiya qozoqcha/ruscha
yozuvda bo'lishi mumkin, aslida o'zbek yoki qoraqalpoq tilida gapirgan): "{transcript}"

FAQAT quyidagi JSON formatida javob ber (boshqa hech narsa yozma, markdown ham yo'q):
{{"intent": "<intent>", "param": "<param yoki bo'sh>", "normalized": "<aytilgan gapning o'zbek lotin yozuvidagi ko'rinishi>", "reply": "<faqat chat intentida javob matni>"}}

intent variantlari:
- "sales" — savdo hisobotini so'rasa (faqat boshliq uchun). param = davr: "today" (bugun), "yesterday" (kecha), "week" (hafta), "month" (oy). Aniq aytilmasa "today".
- "zakaz" — biror firma/yetkazib beruvchi uchun zakaz tavsiyasi so'rasa. param = firma nomi
- "stale" — turib qolgan/sotilmayotgan mahsulotlar tahlilini so'rasa
- "stock" — omborda qancha/qanday mahsulot borligi, ombor qoldig'i haqida so'rasa
- "my_report" — o'zining savdosi, ballari yoki maoshi haqida so'rasa
- "chat" — yuqoridagilarga mos kelmaydigan istalgan savol/gap. reply maydonida qisqa (2-4 gap), foydali javob yoz (o'zbek tilida). Agar so'ralgan narsa botning imkoniyatlaridan tashqarida bo'lsa, bot NIMALARNI qila olishini ayt: savdo hisoboti (bugun/kecha/hafta/oy), zakaz tavsiyasi, turib qolgan mahsulotlar, ombor holati, shaxsiy hisobot."""
    raw = _call_claude(prompt, max_tokens=500)
    try:
        import json as _json
        clean = raw.strip()
        if clean.startswith("```"):
            clean = clean.strip("`").replace("json", "", 1).strip()
        data = _json.loads(clean)
        return {"intent": data.get("intent", "chat"),
                "param": (data.get("param") or "").strip(),
                "normalized": (data.get("normalized") or "").strip(),
                "reply": data.get("reply", "")}
    except Exception:
        return {"intent": "chat", "param": "", "normalized": "",
                "reply": raw[:800] if raw else "Tushunmadim, qayta ayting."}

def execute_voice_intent(tg_id, chat_id, intent_data, transcript):
    intent = intent_data["intent"]
    param = intent_data["param"]
    role = get_role(tg_id)

    if intent in ("sales", "sales_today"):
        if role not in ("boss", "manager"):
            bot.send_message(chat_id, "⛔ Savdo hisoboti faqat boshliq uchun."); return
        period = (param or "today").lower()
        today = now_dt()
        if period == "yesterday":
            d = (today - timedelta(days=1)).strftime("%Y-%m-%d")
            df, dt_ = bito_period_utc(d)
            label = f"Savdo hisoboti — {d} (kecha)"
        elif period == "week":
            d7 = (today - timedelta(days=6)).strftime("%Y-%m-%d")
            df, dt_ = bito_range_utc(d7, today_str())
            label = "Savdo hisoboti — so'nggi 7 kun"
        elif period == "month":
            m_start = today.replace(day=1).strftime("%Y-%m-%d")
            df, dt_ = bito_range_utc(m_start, today_str())
            label = f"Savdo hisoboti — {today.strftime('%B %Y')}"
        else:
            df, dt_ = bito_period_utc(today_str())
            label = f"Savdo hisoboti — {today_str()}"
        summary = bito_get_sales_summary(df, dt_)
        employees = bito_get_sales_by_employee(df, dt_)
        text = fmt_savdo_report(summary, employees, label)
        bot.send_message(chat_id, text, parse_mode="Markdown")

    elif intent == "zakaz":
        if role not in ("boss", "manager"):
            bot.send_message(chat_id, "⛔ Zakaz tavsiyasi faqat boshliq uchun."); return
        if not param:
            bot.send_message(chat_id, "🎤 Qaysi firma uchun zakaz kerakligini ayting (masalan: \"Hydrolife uchun zakaz\")."); return
        try:
            headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
            r = requests.post(BITO_BASE_URL + "supplier/get-paging",
                              json={"page": 1, "limit": 5, "search": param},
                              headers=headers, timeout=15)
            items = (r.json().get("data", {}) or {}).get("data", []) if r.status_code == 200 else []
            if not items:
                bot.send_message(chat_id, f"⚠️ \"{h(param)}\" nomli firma topilmadi.", parse_mode="HTML"); return
            sup = items[0]
            bot.send_message(chat_id, f"🛒 <b>{h(sup.get('name','?'))}</b> uchun zakaz tavsiyasi tayyorlanmoqda (30-60 soniya)...", parse_mode="HTML")
            threading.Thread(target=generate_zakaz_advice, args=(chat_id, sup.get("_id")), daemon=True).start()
        except Exception as e:
            bot.send_message(chat_id, f"⚠️ Xatolik: {str(e)[:100]}")

    elif intent == "stale":
        if role not in ("boss", "manager"):
            bot.send_message(chat_id, "⛔ Bu hisobot faqat boshliq uchun."); return
        bot.send_message(chat_id, "⏳ Turib qolgan mahsulotlar tahlili boshlandi (1-2 daqiqa)...")
        threading.Thread(target=run_daily_ai_advice, daemon=True).start()

    elif intent == "stock":
        try:
            headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
            r = requests.post(BITO_BASE_URL + "product/get-paging",
                              json={"page": 1, "limit": 1}, headers=headers, timeout=15)
            total = 0
            if r.status_code == 200:
                d = r.json().get("data", {})
                total = d.get("total", 0) if isinstance(d, dict) else 0
            bot.send_message(chat_id,
                f"📦 <b>Ombor holati</b>\n\n"
                f"Ro'yxatda jami <b>{total}</b> xil mahsulot bor.\n\n"
                f"Batafsil (qoldiq miqdorlari, kam qolganlar) uchun: "
                f"📦 <b>Ombor hisoboti</b> bo'limidan foydalaning, yoki "
                f"\"turib qolgan mahsulotlar\" deb so'rang.", parse_mode="HTML")
        except Exception as e:
            bot.send_message(chat_id, f"⚠️ Ombor ma'lumotini olishda xatolik: {str(e)[:80]}")

    elif intent == "my_report":
        pts = get_points(tg_id)
        pv = get_point_value()
        bmap = get_bito_map()
        bname = bmap.get(tg_id)
        gross = 0
        if bname:
            df, dt_ = bito_period_utc(today_str())
            sd = get_bito_sales_dict(df, dt_)
            item = sd.get(bname) if sd else None
            gross = (item.get("gross_sales", 0) if item else 0) or 0
        rate = get_bito_bonus_rate()
        text = (f"📊 <b>Sizning bugungi holatlaringiz</b>\n\n"
                f"💰 Savdo: {h(fmt_money(int(gross)))}\n"
                f"🎁 Bonus ({rate*100:.2f}%): {h(fmt_money(round(gross*rate)))}\n"
                f"🏆 Ballar (bu oy): {pts} = {h(fmt_money(round(pts*pv)))}")
        bot.send_message(chat_id, text, parse_mode="HTML")

    else:  # chat — erkin javob
        reply = intent_data.get("reply") or "Tushunarli."
        bot.send_message(chat_id, f"🤖 {reply}")

