AGENT_TOOLS = [
    {"name": "savdo_hisoboti",
     "description": "Savdo hisobotini oladi: jami savdo, foyda, cheklar soni va xodimlar kesimida savdo.",
     "input_schema": {"type": "object", "properties": {
         "davr": {"type": "string", "enum": ["today", "yesterday", "week", "month"],
                   "description": "Qaysi davr uchun"}}, "required": ["davr"]}},
    {"name": "xodimlar_royxati",
     "description": "Barcha xodimlar ro'yxati: ism, rol, lavozim, bu oygi ballari, mijoz bahosi, bugun ishga kelgan-kelmagani va bugungi savdosi. Xodimlarga vazifa taqsimlash, baholash kabi savollarda ishlatiladi.",
     "input_schema": {"type": "object", "properties": {}}},
    {"name": "mahsulot_qidirish",
     "description": "Mahsulotni nomi bo'yicha Bito'dan qidiradi va ombordagi qoldig'ini qaytaradi.",
     "input_schema": {"type": "object", "properties": {
         "nom": {"type": "string", "description": "Mahsulot nomi yoki qismi"}}, "required": ["nom"]}},
    {"name": "eng_kop_sotilganlar",
     "description": "Oxirgi 30 kunda eng ko'p sotilgan mahsulotlar ro'yxati (talab yuqori mahsulotlar).",
     "input_schema": {"type": "object", "properties": {}}},
    {"name": "songgi_vazifalar",
     "description": "Xodimlarga so'nggi berilgan vazifalar va ularning holati (bajarildi/jarayonda).",
     "input_schema": {"type": "object", "properties": {}}},
    {"name": "zakaz_tavsiyasi",
     "description": "Berilgan firma (yetkazib beruvchi) uchun to'liq zakaz tavsiyasini tayyorlab, Telegram'ga alohida xabar qilib yuboradi (1-2 daqiqa davom etadi).",
     "input_schema": {"type": "object", "properties": {
         "firma": {"type": "string", "description": "Firma nomi"}}, "required": ["firma"]}},
]

def _agent_tool_run(tg_id, chat_id, name, inp):
    """Agent asbobini bajarib, natijani matn sifatida qaytaradi."""
    try:
        if name == "savdo_hisoboti":
            period = (inp.get("davr") or "today").lower()
            today = now_dt()
            if period == "yesterday":
                d = (today - timedelta(days=1)).strftime("%Y-%m-%d")
                df, dt_ = bito_period_utc(d); label = f"{d} (kecha)"
            elif period == "week":
                d7 = (today - timedelta(days=6)).strftime("%Y-%m-%d")
                df, dt_ = bito_range_utc(d7, today_str()); label = "so'nggi 7 kun"
            elif period == "month":
                m_start = today.replace(day=1).strftime("%Y-%m-%d")
                df, dt_ = bito_range_utc(m_start, today_str()); label = today.strftime("%B %Y")
            else:
                df, dt_ = bito_period_utc(today_str()); label = f"{today_str()} (bugun)"
            summary = bito_get_sales_summary(df, dt_) or {}
            employees = bito_get_sales_by_employee(df, dt_) or []
            emp_lines = []
            for e in employees:
                resp = e.get("responsible", {}) or {}
                nm = resp.get("full_name") or e.get("employee_name", "?")
                emp_lines.append(f"{nm}: {e.get('gross_sales',0):,.0f} so'm ({e.get('receipts',0)} chek)")
            return (f"Davr: {label}\nJami savdo: {summary.get('gross_sales',0):,.0f} so'm\n"
                    f"Foyda: {summary.get('profit',0):,.0f} so'm\nCheklar: {summary.get('receipts',0)}\n"
                    f"Xodimlar: " + ("; ".join(emp_lines) if emp_lines else "ma'lumot yo'q"))

        elif name == "xodimlar_royxati":
            rows = qall("SELECT tg_id, full_name, role, position FROM users WHERE role IN ('boss','manager','employee')")
            bmap = get_bito_map()
            df, dt_ = bito_period_utc(today_str())
            sd = get_bito_sales_dict(df, dt_) or {}
            lines = []
            for (uid, nm, rl, pos) in rows:
                pts = get_points(uid)
                avg_r, r_cnt = get_avg_rating(uid)
                at_work = qone("SELECT 1 FROM attendance WHERE tg_id=? AND work_date=? AND checkout_time IS NULL", (uid, today_str()))
                bname = bmap.get(uid)
                gross = 0
                if bname:
                    it = sd.get(bname)
                    gross = (it.get("gross_sales", 0) if it else 0) or 0
                lines.append(f"{nm} | rol: {rl} | lavozim: {pos or '-'} | ball: {pts}"
                             f" | baho: {avg_r or '-'} ({r_cnt}) | bugun ishda: {'ha' if at_work else 'yoq'}"
                             f" | bugungi savdo: {gross:,.0f}")
            return "\n".join(lines) if lines else "Xodimlar topilmadi."

        elif name == "mahsulot_qidirish":
            nom = (inp.get("nom") or "").strip()
            headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
            r = requests.post(BITO_BASE_URL + "product/get-paging",
                              json={"page": 1, "limit": 6, "search": nom}, headers=headers, timeout=20)
            d = r.json().get("data", {}) if r.status_code == 200 else {}
            items = d.get("data", []) if isinstance(d, dict) else []
            total = d.get("total", 0) if isinstance(d, dict) else 0
            out = [f"Topildi: {total} ta (birinchi {len(items)} tasi):"]
            for p in items:
                whs = p.get("_warehouses") or {}
                if isinstance(whs, dict):
                    stock = sum((v.get("amount", 0) or 0) for v in whs.values() if isinstance(v, dict))
                elif isinstance(whs, list):
                    stock = sum((w.get("amount", 0) or 0) for w in whs if isinstance(w, dict))
                else:
                    stock = 0
                out.append(f"- {p.get('name','?')}: omborda {stock:g} ta")
            return "\n".join(out)

        elif name == "eng_kop_sotilganlar":
            today = now_dt()
            p30 = (today - timedelta(days=30)).strftime("%Y-%m-%d")
            df, dt_ = bito_range_utc(p30, today_str())
            items = bito_get_items_sorted(df, dt_, limit=15, ascending=False)
            lines = [f"- {it.get('product_name','?')}: {it.get('items_sold',0):.0f} dona"
                     for it in items if isinstance(it, dict)]
            return "Oxirgi 30 kunda eng ko'p sotilganlar:\n" + "\n".join(lines)

        elif name == "songgi_vazifalar":
            rows = qall("SELECT employee_name, task, status, created_at FROM tasks ORDER BY id DESC LIMIT 15")
            if not rows: return "Hali vazifalar berilmagan."
            return "\n".join(f"- [{r[3][:10]}] {r[0]}: {r[1][:60]} — {r[2]}" for r in rows)

        elif name == "zakaz_tavsiyasi":
            firma = (inp.get("firma") or "").strip()
            headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
            r = requests.post(BITO_BASE_URL + "supplier/get-paging",
                              json={"page": 1, "limit": 3, "search": firma}, headers=headers, timeout=15)
            items = (r.json().get("data", {}) or {}).get("data", []) if r.status_code == 200 else []
            if not items:
                return f"'{firma}' nomli firma topilmadi."
            sup = items[0]
            threading.Thread(target=generate_zakaz_advice, args=(chat_id, sup.get("_id")), daemon=True).start()
            return (f"'{sup.get('name')}' uchun zakaz tavsiyasi tayyorlanmoqda — 1-2 daqiqada "
                    f"alohida xabar sifatida yuboriladi. Foydalanuvchiga shuni ayt.")
        return f"Noma'lum asbob: {name}"
    except Exception as e:
        print(f"AGENT TOOL ERR ({name}):", str(e)[:150], flush=True)
        return f"Xatolik: {str(e)[:100]}"

def _clean_agent_text(text):
    """AI javobidan xom Markdown belgilarini tozalaydi (Telegram'da xunuk ko'rinmasligi uchun)."""
    import re as _re
    out_lines = []
    for line in text.split("\n"):
        s = line
        s = _re.sub(r'^#{1,6}\s*', '', s)          # ## sarlavhalar
        s = s.replace("**", "").replace("__", "")    # qalin belgilar
        if _re.match(r'^\s*[-—_]{3,}\s*$', s):       # --- ajratkich chiziqlar
            continue
        if _re.match(r'^\s*\|[\s\-:|]+\|\s*$', s):   # jadval |---|---| qatorlari
            continue
        if s.strip().startswith("|") and s.strip().endswith("|"):
            # jadval qatorini oddiy matnga aylantiramiz
            cells = [c.strip() for c in s.strip().strip("|").split("|") if c.strip()]
            s = "• " + " — ".join(cells)
        out_lines.append(s)
    return "\n".join(out_lines).strip()

def ai_agent_answer(tg_id, chat_id, question, max_iters=5):
    """Claude'ga savol + asboblar beriladi; u kerak bo'lsa ma'lumot olib, yakuniy javob yozadi."""
    role = get_role(tg_id)
    role_desc = "boshliq/menejer" if role in ("boss", "manager") else "oddiy xodim"
    system = (f"Sen O'zbekistondagi supermarket ({get_setting('shop_name', CFG.SHOP_NAME)}) "
              f"boshqaruv botining aqlli yordamchisisan. Foydalanuvchi — {role_desc}. "
              f"Bugungi sana: {today_str()}. Savolga javob berishdan oldin kerakli asboblardan "
              f"foydalanib REAL ma'lumotlarni ol — taxmin qilma. Javobni o'zbek tilida, qisqa, "
              f"aniq va amaliy yoz. Xodimlarga vazifa taqsimlash so'ralsa — avval xodimlar "
              f"ro'yxatini olib, har biriga roli/holatiga mos ANIQ vazifa taklif qil. "
              f"Agar foydalanuvchi oddiy xodim bo'lsa, moliyaviy/maxfiy ma'lumotlarni berma. "
              f"MUHIM: Javobda Markdown ishlatma — ## sarlavha, ** qalin, | jadval, --- chiziq "
              f"MUTLAQO YO'Q. Oddiy matn, emoji va \"•\" belgili ro'yxatlar bilan chiroyli yoz.")
    messages = [{"role": "user", "content": question}]
    headers = {"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01",
               "content-type": "application/json"}
    for _ in range(max_iters):
        resp = requests.post("https://api.anthropic.com/v1/messages", headers=headers,
                             json={"model": "claude-sonnet-4-6", "max_tokens": 1200,
                                   "system": system, "tools": AGENT_TOOLS,
                                   "messages": messages}, timeout=90)
        resp.raise_for_status()
        data = resp.json()
        content = data.get("content", [])
        if data.get("stop_reason") == "tool_use":
            messages.append({"role": "assistant", "content": content})
            results = []
            for block in content:
                if block.get("type") == "tool_use":
                    out = _agent_tool_run(tg_id, chat_id, block.get("name"), block.get("input") or {})
                    print(f"[AGENT] tool={block.get('name')} -> {out[:80]}", flush=True)
                    results.append({"type": "tool_result", "tool_use_id": block.get("id"),
                                     "content": out})
            messages.append({"role": "user", "content": results})
            continue
        texts = [b.get("text", "") for b in content if b.get("type") == "text"]
        final = "\n".join(t for t in texts if t).strip() or "Javob topilmadi."
        return _clean_agent_text(final)
    return "Savol juda murakkab bo'ldi — iltimos, soddaroq qilib qayta so'rang."
