def plu_review_load(uid):
    e = PLU_REVIEW.get(uid)
    if e:
        return e
    raw = get_setting(f"plu_review_{uid}", "")
    if raw:
        try:
            import json as _j
            e = _j.loads(raw)
            PLU_REVIEW[uid] = e
            return e
        except Exception:
            pass
    return None


@bot.message_handler(commands=['plu_test'])
def plu_test_cmd(message):
    """🧪 BITTA mahsulotga PLU yozib sinaydi — ommaviy yozishdan oldin.
    Foydalanish: /plu_test <mahsulot nomi>
    Raqam avtomatik tanlanadi (eng kattadan keyingi bo'sh)."""
    if message.from_user.id != CFG.SUPER_ADMIN_ID:
        return
    chat_id = message.chat.id
    name = message.text.replace("/plu_test", "", 1).strip()
    if not name:
        bot.send_message(chat_id, "Foydalanish: <code>/plu_test Kartoshka qora</code>",
                         parse_mode="HTML"); return

    def run():
        refresh_nak_catalog(force=True)
        key = _translit_and_norm(name)
        hits = [p for p in NAK_CATALOG_CACHE["products"] if key and key in p["key"]]
        if not hits:
            bot.send_message(chat_id, f"'{name}' topilmadi."); return
        kg = [p for p in hits if p.get("is_kg")]
        if not kg:
            bot.send_message(chat_id, f"'{hits[0]['name']}' kg mahsulot emas — PLU kerak emas."); return
        # ⚠️ Mos kelganlar orasidan PLU'si YO'Q birini tanlaymiz. Aks holda
        # birinchi topilgan mahsulotda PLU bo'lsa, sinov o'tkazilmay qolardi.
        free = [p for p in kg if p.get("plu") is None]
        if not free:
            lines = [f"'{name}' bo'yicha topilgan kg mahsulotlarning hammasida PLU bor:", ""]
            for p in kg[:8]:
                lines.append(f"• {p['name']} → <b>{p['plu']}</b>")
            lines.append("")
            lines.append("PLU'siz mahsulotlar ro'yxatini <code>/plu</code> beradi.")
            bot.send_message(chat_id, "\n".join(lines), parse_mode="HTML"); return
        p = free[0]
        used = set(NAK_PLU_STATS.get("used") or set())
        n = plu_next_free(used, NAK_PLU_STATS.get("max", 0) + 1)
        bot.send_message(chat_id, f"🧪 '{p['name']}' → PLU <b>{n}</b> yozilmoqda...",
                         parse_mode="HTML")
        ok, err = bito_set_plu(p["id"], n)
        NAK_CATALOG_CACHE["ts"] = 0
        if ok:
            bot.send_message(chat_id,
                f"✅ Yozildi va qayta o'qib tasdiqlandi: <b>{p['name']} → {n}</b>\n\n"
                f"Bito'da ochib, mahsulotning boshqa maydonlari (narx, shtrix-kod, "
                f"kategoriya, qoldiq) joyidaligini tekshiring.", parse_mode="HTML")
        else:
            bot.send_message(chat_id, f"❌ Yozilmadi: {err}")
    threading.Thread(target=run, daemon=True).start()


@bot.message_handler(commands=['plu'])
def plu_report_cmd(message):
    """⚖️ Tarozi PLU kodlari bo'yicha hisobot.

    Ma'lumot katalog skanidan olinadi (refresh_nak_catalog) — qo'shimcha so'rov
    yubormaydi. Hech qanday narsa YOZILMAYDI, faqat o'qiydi."""
    if message.from_user.id != CFG.SUPER_ADMIN_ID:
        return
    chat_id = message.chat.id
    bot.send_message(chat_id, "⏳ Katalog o'qilmoqda (10 000+ mahsulot)...")

    def run():
        try:
            refresh_nak_catalog(force=True)
            s = NAK_PLU_STATS
            if not s.get("ts"):
                bot.send_message(chat_id, "⚠️ Katalogni o'qib bo'lmadi. Railway loglarini tekshiring.")
                return
            used = s["used"]
            mx = s["max"]
            # Keyingi bo'sh raqam: eng kattadan keyingisi
            nxt = mx + 1
            # 1..mx oralig'idagi bo'sh raqamlar (eskilarini qayta ishlatish uchun)
            gaps = [n for n in range(1, mx + 1) if n not in used]
            txt = ["⚖️ <b>PLU hisoboti</b>", ""]
            txt.append(f"🔢 Eng katta PLU: <b>{mx}</b>")
            txt.append(f"➡️ Keyingi bo'sh raqam: <b>{nxt}</b>")
            txt.append(f"📌 Band raqamlar: {len(used)} ta")
            txt.append(f"🕳 1–{mx} orasida bo'sh: {len(gaps)} ta")
            if gaps:
                txt.append("   " + ", ".join(str(g) for g in gaps[:20])
                           + (" ..." if len(gaps) > 20 else ""))
            txt.append("")
            txt.append(f"⚖️ Kg mahsulotlar: {s['kg_total']} ta")
            txt.append(f"❌ Shulardan PLU yo'q: <b>{len(s['kg_without'])}</b> ta")
            if s["duplicates"]:
                txt.append("")
                txt.append(f"⚠️ <b>Takrorlangan PLU: {len(s['duplicates'])} ta</b>")
                for n, names in list(s["duplicates"].items())[:5]:
                    txt.append(f"   {n} → {', '.join(str(x) for x in names[:3])}")
            if s["text_typed"]:
                txt.append("")
                txt.append(f"ℹ️ {s['text_typed']} ta PLU matn turida saqlangan "
                           f"(masalan \"304\"), son emas — solishtirishda hisobga olindi.")
            bot.send_message(chat_id, "\n".join(txt), parse_mode="HTML")

            # PLU'siz kg mahsulotlar ro'yxati — alohida xabar(lar)da
            missing = s["kg_without"]
            if missing:
                chunk, buf = [], "⚖️ <b>PLU berilmagan kg mahsulotlar:</b>\n"
                for i, m in enumerate(missing, 1):
                    line = f"{i}. {m['name']}\n"
                    if len(buf) + len(line) > 3500:
                        chunk.append(buf); buf = ""
                    buf += line
                chunk.append(buf)
                for c in chunk[:6]:
                    bot.send_message(chat_id, c, parse_mode="HTML")
                if len(chunk) > 6:
                    bot.send_message(chat_id, f"... va yana {len(chunk)-6} sahifa.")
        except Exception as e:
            bot.send_message(chat_id, f"⚠️ Xatolik: {str(e)[:200]}")
            print("PLU REPORT ERR:", str(e)[:200], flush=True)

    threading.Thread(target=run, daemon=True).start()


@bot.message_handler(commands=['test_purchase'])
def test_purchase_cmd(message):
    """Bito purchase/create sxemasini SINOV uchun: bitta mahsulot, kichik miqdor.
    Foydalanish: /test_purchase <mahsulot nomi> [soni] [narxi]
    Masalan: /test_purchase Coca-Cola 1 1000"""
    if message.from_user.id != CFG.SUPER_ADMIN_ID:
        return
    parts = message.text.split()
    if len(parts) < 2:
        bot.send_message(message.chat.id,
            "Foydalanish: `/test_purchase MahsulotNomi [soni] [narxi]`\n"
            "Masalan: `/test_purchase Tarvuz 1 1000`", parse_mode="Markdown")
        return
    # oxirgi 2 ta element raqam bo'lsa — soni va narxi
    qty, price = 1.0, 1000.0
    name_parts = parts[1:]
    try:
        if len(name_parts) >= 3 and name_parts[-1].replace(".", "").isdigit() and name_parts[-2].replace(".", "").isdigit():
            price = float(name_parts[-1]); qty = float(name_parts[-2])
            name_parts = name_parts[:-2]
    except Exception:
        pass
    pname = " ".join(name_parts)
    chat_id = message.chat.id
    bot.send_message(chat_id, f"🧪 Sinov: '{pname}' × {qty:g} dona, {price:,.0f} so'mdan. Qidirilmoqda...")

    def run():
        headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
        try:
            r = requests.post(BITO_BASE_URL + "product/get-paging",
                              json={"page": 1, "limit": 3, "search": pname},
                              headers=headers, timeout=15)
            plist = (r.json().get("data", {}) or {}).get("data", []) if r.status_code == 200 else []
            if not plist:
                bot.send_message(chat_id, f"⚠️ '{pname}' katalogda topilmadi."); return
            prod = plist[0]
            pid = prod.get("_id")
            bot.send_message(chat_id, f"✅ Topildi: {prod.get('name')}\n🚀 Yuklash sinovi boshlandi...")

            wh_id = tenant_setting("bito_warehouse_id", "69424f36a3a3cc43da908320")
            products = [{"product_id": pid, "amount": qty, "cost": price}]
            body = {
                "organization_id": CFG.BITO_ORG_ID,
                "state": "new",
                "date": today_str(),
                "income_date": today_str(),
                "responsible_id": tenant_setting("bito_responsible_id", "693fe9caff2118868c9554b1"),
                "warehouse_id": wh_id,
                "currency_id": tenant_setting("bito_currency_id", "69424f34f461a9f6fd61972d"),
                "note": "Telegram bot SINOV xaridi (test_purchase)",
                "is_auto_income": True,
                "additional_costs": [],
                "orders": [{"products": products}],
            }
            # Sinov uchun firma: "Mango Optom" (mavjudligini bilamiz)
            try:
                rs = requests.post(BITO_BASE_URL + "supplier/get-paging",
                                   json={"page": 1, "limit": 1, "search": "Mango"},
                                   headers=headers, timeout=15)
                sl = (rs.json().get("data", {}) or {}).get("data", []) if rs.status_code == 200 else []
                if sl:
                    body["supplier_id"] = sl[0].get("_id")
                    bot.send_message(chat_id, f"🏢 Sinov firmasi: {sl[0].get('name')}")
            except Exception:
                pass

            report = []
            try:
                r2 = requests.post(BITO_BASE_URL + "purchase/create", json=body,
                                   headers=headers, timeout=30)
                print(f"TEST PURCHASE: HTTP {r2.status_code} | {r2.text[:600]}", flush=True)
                report.append(f"{'✅' if r2.status_code == 200 else '❌'} HTTP {r2.status_code}\n<code>{h(r2.text[:350])}</code>")
            except Exception as e:
                report.append(f"❌ {h(str(e)[:150])}")
            send_long_message(chat_id, "🧪 <b>Sinov natijasi:</b>\n\n" + "\n\n".join(report), parse_mode="HTML")
            bot.send_message(chat_id,
                "ℹ️ Agar ✅ chiqqan bo'lsa — Bito'da 'Xaridlar' bo'limini ochib, yangi sinov xarid "
                "paydo bo'lganini tekshiring (keyin uni o'chirib tashlashingiz mumkin). "
                "Xato bo'lsa — shu xabar screenshotini tashlang.", parse_mode="HTML")
        except Exception as e:
            bot.send_message(chat_id, f"⚠️ Xatolik: {str(e)[:120]}")
    threading.Thread(target=run, daemon=True).start()

@bot.message_handler(commands=['nak_xotira'])
def nak_xotira_cmd(message):
    """Nakladnoy xotirasini ko'rish/tozalash. Foydalanish: /nak_xotira [qidiruv so'zi]"""
    if not is_boss_or_mgr(message.from_user.id): return
    parts = message.text.split(maxsplit=1)
    search = parts[1].strip() if len(parts) > 1 else ""
    if search:
        rows = qall("SELECT id, alias_name, product_name, hit_count FROM nak_aliases "
                    "WHERE alias_name LIKE ? ORDER BY hit_count DESC LIMIT 20",
                    (f"%{_nak_norm(search)}%",))
    else:
        rows = qall("SELECT id, alias_name, product_name, hit_count FROM nak_aliases "
                    "ORDER BY updated_at DESC LIMIT 20")
    if not rows:
        bot.send_message(message.chat.id, "📭 Xotirada hech narsa yo'q."); return
    mk = types.InlineKeyboardMarkup()
    lines = [f"🧠 <b>Nakladnoy xotirasi</b> ({len(rows)} ta ko'rsatilmoqda):\n"]
    for rid, alias, pname, hits in rows:
        lines.append(f"• \"{h(alias)}\" → {h(pname)} ({hits}x)")
        mk.add(types.InlineKeyboardButton(f"🗑 \"{alias[:30]}\"ni o'chirish", callback_data=f"nakdel_{rid}"))
    send_long_message(message.chat.id, "\n".join(lines), parse_mode="HTML")
    bot.send_message(message.chat.id, "Xato moslikni o'chirish uchun tugmani bosing:", reply_markup=mk)

