@bot.callback_query_handler(func=lambda c: c.data.startswith("posdb:"))
def posdb_cb(call):
    if not _promo_allowed(call.from_user.id):
        return
    _ack(call)
    uid, chat_id = call.from_user.id, call.message.chat.id
    st = W_POSDB.get(uid)
    if not st:
        bot.send_message(chat_id, "Muddat o'tgan — bazani qayta tashlang.")
        return
    action = call.data.replace("posdb:", "")
    deficit = st["deficit"]
    if action == "nak":
        items = [{"name": d["name"], "qty": d["qty"], "price": d["price"]}
                 for d in deficit]
        W_NAK[uid] = {"step": "confirm_supplier",
                      "supplier": "Sinxron tuzatish",
                      "date": now_dt().strftime("%d/%m/%Y"),
                      "items": items}
        bot.send_message(chat_id, "Kirim firmasini tanlang:")
        _nak_prompt_supplier(chat_id, uid)
        return
    # 📦 Inventarizatsiya ro'yxati: Bito'ga kiritiladigan MAQSAD miqdorlar
    def fq(x):
        return (f"{int(round(x))}" if abs(x - round(x)) < 0.005
                else f"{x:.2f}")
    lines = ["📦 INVENTARIZATSIYA — Bito'da kiritiladigan miqdorlar",
             "(«Bo'lishi kerak» ustuniga shu sonni yozing; sinxrondan "
             "keyin qoldiq 0 ga tushadi, so'ng haqiqiy sanoq qilinadi)",
             "",
             f"{'#':>3}  {'Mahsulot':<44} {'Hozir':>8} {'YOZILSIN':>9}",
             "-" * 70]
    for i, d in enumerate(deficit, 1):
        lines.append(f"{i:>3}  {(d['name'] or '?')[:44]:<44} "
                     f"{fq(d['stock']):>8} {fq(d['target']):>9}")
    txt = "\n".join(lines)
    import io as _io
    bio = _io.BytesIO(txt.encode("utf-8"))
    bio.name = f"inventarizatsiya_{now_dt().strftime('%d-%m')}.txt"
    bot.send_document(chat_id, bio,
                      caption=f"📦 {len(deficit)} ta mahsulot.\n"
                              f"Bito → Inventarizatsiya → shu sonlarni "
                              f"kiriting → tasdiqlang → kassada Sync.\n"
                              f"Sinxrondan keyin haqiqiy sanoq qilib, "
                              f"qoldiqni joyiga qo'ying.")
    W_POSDB.pop(uid, None)


def _pos_db_deficit(path):
    """Kassa (Bito desktop) bazasidan: sinxronlanmagan cheklar ehtiyoji −
    lokal ombor ko'zgusi = kirim qilinishi kerak ro'yxati.
    Qaytaradi: (chek_soni, jami_summa, deficit_items, ok_soni)."""
    import sqlite3 as _sq
    from collections import defaultdict as _dd
    c = _sq.connect(path)
    need = _dd(lambda: {"qty": 0.0, "cheks": set(), "name": "", "cost": 0.0})
    for pid, name, amt, uuid, cost in c.execute(
            "SELECT ri.productId, ri.name, ri.amount, r.uuid, ri.cost "
            "FROM receipt r JOIN receipt_item ri ON ri.receiptId=r.uuid "
            "WHERE r.synced=0"):
        n = need[pid]
        n["qty"] += float(amt or 0)
        n["cheks"].add(uuid)
        n["name"] = name
        try:
            cv = float(cost or 0)
            if cv > 0:
                n["cost"] = cv
        except Exception:
            pass
    stock = {}
    for pid, amt in c.execute(
            "SELECT productId, amount FROM product_warehouse "
            "WHERE warehouseId='69424f36a3a3cc43da908320' "
            "AND organizationId='693fea06ff2118868c955b6c'"):
        stock[pid] = float(amt or 0)
    # Tannarx: chekda bo'lmasa mahsulot kartasidagi lastCost/averageCost
    costs = {}
    try:
        for pid, lc, ac in c.execute(
                "SELECT productId, lastCost, averageCost FROM "
                "product_organization WHERE "
                "organizationId='693fea06ff2118868c955b6c'"):
            try:
                v = float(lc or 0) or float(ac or 0)
            except Exception:
                v = 0
            if v > 0:
                costs[pid] = v
    except Exception:
        pass
    total = sum(float(x or 0) for (x,) in c.execute(
        "SELECT totalToPay FROM receipt WHERE synced=0"))
    cheks = {u for n in need.values() for u in n["cheks"]}
    deficit, ok = [], 0
    for pid, n in need.items():
        s = stock.get(pid)
        d = n["qty"] - (s or 0)
        if s is None or d > 0.004:
            price = n["cost"] or costs.get(pid, 0)
            cur = s or 0
            deficit.append({"name": n["name"],
                            "qty": round(d if s is not None else n["qty"], 2),
                            "stock": round(cur, 2),
                            "target": round(cur + (d if s is not None
                                                   else n["qty"]), 2),
                            "price": round(price, 2),
                            "cheks": len(n["cheks"])})
        else:
            ok += 1
    deficit.sort(key=lambda x: -x["qty"])
    c.close()
    return len(cheks), total, deficit, ok


@bot.message_handler(content_types=['document'],
                     func=lambda m: _promo_allowed(m.from_user.id)
                     and (m.document.file_name or "").lower().endswith(
                         (".sqlite", ".db", ".zip")))
def pos_db_handler(message):
    """🔄 Kassa bazasi (main_db.sqlite yoki ZIP) tashlansa — sinxronlanmagan
    cheklar tahlili va KIRIM tayyorlash (2026-08-10 so'rov). Natija
    nakladnoy oqimiga ulanadi: firma tanlash → chiroyli tahrirlash
    (nomlar+soni+narx) → tasdiq → Bito'ga kirim."""
    uid, chat_id = message.from_user.id, message.chat.id
    fname = message.document.file_name or "db"
    if (message.document.file_size or 0) > 19_500_000:
        bot.send_message(chat_id,
                         "⚠️ Fayl 20 MB dan katta — Telegram botga bermaydi. "
                         "Faylni ZIP qilib yuboring (o'ng tugma → Сжатая "
                         "ZIP-папка), ZIP odatda sig'adi.")
        return
    bot.send_message(chat_id, "🔄 Kassa bazasi o'qilmoqda...")

    def run():
        try:
            f = bot.get_file(message.document.file_id)
            raw = requests.get(
                f"https://api.telegram.org/file/bot{TOKEN}/{f.file_path}",
                timeout=120).content
            import tempfile, zipfile, io as _io, os as __os
            tmpdir = tempfile.mkdtemp()
            path = __os.path.join(tmpdir, "pos.sqlite")
            if fname.lower().endswith(".zip"):
                with zipfile.ZipFile(_io.BytesIO(raw)) as z:
                    inner = next((n for n in z.namelist()
                                  if n.lower().endswith((".sqlite", ".db"))),
                                 None)
                    if not inner:
                        bot.send_message(chat_id, "ZIP ichida .sqlite fayl "
                                                  "topilmadi.")
                        return
                    with open(path, "wb") as out:
                        out.write(z.read(inner))
            else:
                with open(path, "wb") as out:
                    out.write(raw)
            cheks, total, deficit, ok = _pos_db_deficit(path)
            if not deficit:
                bot.send_message(chat_id,
                                 f"✅ {cheks} ta sinxronlanmagan chek bor, "
                                 f"lekin hamma mahsulotga ombor yetarli — "
                                 f"kirim shart emas. Kassada Sync bosing.")
                return
            W_POSDB[uid] = {"deficit": deficit, "cheks": cheks,
                            "total": total, "ok": ok}
            kb = types.InlineKeyboardMarkup(row_width=1)
            kb.add(types.InlineKeyboardButton(
                       "📦 Inventarizatsiya ro'yxati (tavsiya)",
                       callback_data="posdb:inv"),
                   types.InlineKeyboardButton(
                       "📥 Kirim (nakladnoy) qilib yozish",
                       callback_data="posdb:nak"))
            bot.send_message(chat_id,
                             f"📊 <b>{cheks} ta sinxronlanmagan chek</b> · "
                             f"{fmt_money(int(total))} so'm\n"
                             f"Yetishmayotgan: <b>{len(deficit)} ta</b> "
                             f"mahsulot (ombori yetarli: {ok} ta).\n\n"
                             f"<b>Qaysi usulda tuzatamiz?</b>\n"
                             f"📦 <b>Inventarizatsiya</b> — ombordagi sonni "
                             f"BELGILAYDI (to'g'ri yo'l: pul harakati "
                             f"yaratmaydi, ta'minotchiga qarz yozilmaydi).\n"
                             f"📥 <b>Kirim</b> — ombordagi ustiga QO'SHADI, "
                             f"lekin bo'lmagan xarid sifatida yoziladi "
                             f"(tannarx va qarz buziladi).",
                             parse_mode="HTML", reply_markup=kb)
        except Exception as e:
            import traceback
            print("POS DB ERR:", traceback.format_exc()[:400], flush=True)
            bot.send_message(chat_id, f"⚠️ Baza o'qishda xato: {str(e)[:120]}")

    threading.Thread(target=run, daemon=True).start()


@bot.message_handler(content_types=['photo', 'document'],
                     func=lambda m: W_NAK.get(m.from_user.id, {}).get("step") == "await_file")
def nak_file_handler(message):
    uid = message.from_user.id
    chat_id = message.chat.id
    # 🛡 Holat xabari yuborilmasa ham (Telegram timeout) ISH DAVOM ETADI —
    # avval aynan shu qatordagi ReadTimeout butun ishlovchini yiqitib,
    # bot "qotib qolgan"dek ko'ringan edi.
    try:
        status = bot.send_message(chat_id, "🔍 Nakladnoy o'qilmoqda (30-60 soniya)...")
    except Exception as e:
        print("NAK STATUS SEND ERR (davom etamiz):", str(e)[:120], flush=True)
        status = None

    def _status_edit(text):
        """Holat xabarini yangilaydi; yuborilmagan bo'lsa yangi xabar sifatida yuboradi.
        Hech qachon exception tashlamaydi — asosiy ish to'xtamasligi kerak."""
        nonlocal status
        try:
            if status is not None:
                bot.edit_message_text(text, chat_id, status.message_id)
            else:
                status = bot.send_message(chat_id, text)
        except Exception as e2:
            print("NAK STATUS EDIT ERR:", str(e2)[:120], flush=True)

    def run():
        try:
            import base64
            # ⚡ TEZLASHTIRISH: katalogni AI o'qiyotgan PAYTDA parallel isitamiz.
            # Ilgari foydalanuvchi firma tanlagach moslashtirish bosqichida
            # katalog sovuq bo'lsa yana 30-50 soniya kutardi — endi bu kutish
            # AI o'qishi ichida "yashirinadi". TTL yangi bo'lsa hech narsa
            # qilmaydi (refresh_nak_catalog o'zi tekshiradi).
            threading.Thread(target=refresh_nak_catalog, daemon=True).start()
            _t0 = time.time()
            if message.content_type == 'photo':
                f = bot.get_file(message.photo[-1].file_id)
                raw = requests.get(f"https://api.telegram.org/file/bot{TOKEN}/{f.file_path}", timeout=60).content
                blocks = [{"type": "image", "source": {"type": "base64", "media_type": "image/jpeg",
                                                        "data": base64.b64encode(raw).decode()}}]
                data, err = nak_extract(blocks)
            else:
                doc = message.document
                fname = (doc.file_name or "").lower()
                f = bot.get_file(doc.file_id)
                raw = requests.get(f"https://api.telegram.org/file/bot{TOKEN}/{f.file_path}", timeout=60).content
                if fname.endswith((".xlsx", ".xls")):
                    text = nak_excel_to_text(raw)
                    data, err = nak_extract(text, is_text=True)
                elif fname.endswith(".pdf"):
                    blocks = [{"type": "document", "source": {"type": "base64",
                               "media_type": "application/pdf",
                               "data": base64.b64encode(raw).decode()}}]
                    data, err = nak_extract(blocks)
                elif fname.endswith((".jpg", ".jpeg", ".png")):
                    mt = "image/png" if fname.endswith(".png") else "image/jpeg"
                    blocks = [{"type": "image", "source": {"type": "base64", "media_type": mt,
                                                            "data": base64.b64encode(raw).decode()}}]
                    data, err = nak_extract(blocks)
                else:
                    _status_edit("⚠️ Faqat rasm, PDF yoki Excel qabul qilinadi."); return
            if err or not data or not data["items"]:
                # API limiti/balans xatolarida "aniqroq rasm yuboring" deyish adashtiradi
                is_api_issue = err and ("💳" in err or "⏳" in err)
                hint = "" if is_api_issue else " Aniqroq rasm yuborib ko'ring."
                _status_edit(f"⚠️ O'qib bo'lmadi: {err or 'mahsulotlar topilmadi'}.{hint}")
                return
            print(f"NAK TIMING: extract={time.time()-_t0:.1f}s, "
                  f"items={len(data['items'])}", flush=True)
            W_NAK[uid] = {"step": "confirm_supplier", **data}
            try:
                if status is not None: bot.delete_message(chat_id, status.message_id)
            except Exception: pass
            _nak_prompt_supplier(chat_id, uid)
        except Exception as e:
            print("NAK FILE ERR:", str(e)[:200], flush=True)
            try: _status_edit(f"⚠️ Xatolik: {str(e)[:100]}")
            except Exception: pass
    threading.Thread(target=run, daemon=True).start()

def nak_ai_keywords(items):
    """Har bir nakladnoy mahsuloti uchun Bito katalogida topilishi ehtimoli yuqori
    bo'lgan 2-3 ta qidiruv varianti (lotin/kirill, brend so'zi) tuzadi."""
    names = [i["name"] for i in items]
    import json as _json
    prompt = ("Nakladnoydagi mahsulot nomlari (kirill/rus yozuvida bo'lishi mumkin) "
              "do'kon katalogida boshqacha (ko'pincha lotin-o'zbek yozuvida, boshqa tartibda) "
              "yozilgan bo'ladi. Har bir nom uchun katalogdan qidirish uchun 3 tagacha QISQA "
              "qidiruv varianti ber: 1) eng o'ziga xos so'z (brend) lotin yozuvida, "
              "2) o'sha so'z kirillda, 3) boshqa muhim so'z. O'lcham/soni (250gr, *24) kiritma.\n"
              f"NOMLAR: {_json.dumps(names, ensure_ascii=False)}\n"
              'FAQAT JSON qaytar: [["variant1","variant2"], ...] — har bir nom uchun bitta ichki ro\'yxat.')
    raw = _call_claude(prompt, max_tokens=800)
    try:
        clean = raw.strip()
        if clean.startswith("```"):
            clean = clean.strip("`").replace("json", "", 1).strip()
        arr = _json.loads(clean)
        if isinstance(arr, list) and len(arr) == len(items):
            return [[str(v) for v in (a or []) if str(v).strip()] for a in arr]
    except Exception as e:
        print("NAK KEYWORDS ERR:", str(e)[:120], flush=True)
    return [[] for _ in items]

def nak_ai_select(items, cands):
    """Har bir mahsulot uchun nomzodlar orasidan TO'G'RI mosini tanlaydi (yoki -1)."""
    import json as _json
    payload = []
    for i, it in enumerate(items):
        payload.append({"nakladnoy_nomi": it["name"],
                         "nomzodlar": [c["name"] for c in cands[i]]})
    prompt = ("Nakladnoy mahsulot nomini katalog nomzodlari bilan solishtir. Yozuv (kirill/lotin), "
              "so'z tartibi farq qilishi mumkin — MA'NOSI bir xil mahsulotni top. O'lcham/hajm "
              "(250gr, 1.5L, 24 dona) mos kelishiga E'TIBOR BER — o'lcham boshqa bo'lsa, bu boshqa mahsulot.\n"
              f"{_json.dumps(payload, ensure_ascii=False)}\n"
              'FAQAT JSON qaytar: har bir mahsulot uchun tanlangan nomzod INDEKSI (0 dan) yoki mos yo\'q bo\'lsa -1: [0, -1, 2, ...]')
    raw = _call_claude(prompt, max_tokens=400)
    try:
        clean = raw.strip()
        if clean.startswith("```"):
            clean = clean.strip("`").replace("json", "", 1).strip()
        arr = _json.loads(clean)
        if isinstance(arr, list) and len(arr) == len(items):
            return [int(x) if isinstance(x, (int, float)) else -1 for x in arr]
    except Exception as e:
        print("NAK SELECT ERR:", str(e)[:120], flush=True)
    return [-1] * len(items)

