# Katalog skanida yig'iladigan PLU statistikasi
NAK_PLU_STATS = {"ts": 0, "max": 0, "used": set(), "kg_total": 0,
                 "kg_without": [], "duplicates": {}, "text_typed": 0}


def _plu_value(product):
    """Mahsulotdan PLU raqamini oladi, yo'q bo'lsa None.

    ⚠️ Bito'da qiymat turi BIR XIL EMAS: ba'zi mahsulotlarda son (481),
    ba'zilarida matn ("304"). Shu sababli oddiy taqqoslash xato beradi —
    har doim songa keltiramiz. Bundan tashqari `custom_fields` butunlay
    bo'sh massiv bo'lishi yoki `value` null bo'lishi mumkin."""
    for cf in (product.get("custom_fields") or []):
        if cf.get("_id") != CFG.PLU_FIELD_ID:
            continue
        raw = cf.get("value")
        if raw is None or raw == "":
            return None
        try:
            n = int(float(str(raw).strip()))
        except (TypeError, ValueError):
            return None
        return (n, isinstance(raw, str))
    return None

NAK_CATALOG_TTL = 1800  # 30 daqiqa — katalog "tez-tez o'zgarmaydi" deb belgilangan
NAK_CATEGORY_CACHE = TDict(template={"ts": 0, "categories": []})  # [{"id":, "name":}, ...] — "Chiroyli tahrirlash"da
                                                    # yangi mahsulot uchun kategoriya tanlash ro'yxati

NAK_UOM_CACHE = TDict(template={"ts": 0, "uoms": []})  # [{"id":, "name":}, ...] — o'lchov birliklari

# 📏 Zaxira ro'yxat: Bito API'dan olib bo'lmasa ham, tanlagich BO'SH QOLMASLIGI kerak.
# Bu ID'lar aynan shu hisob uchun Bito'dan tekshirib olingan (faol, ombor turidagilar).
NAK_UOM_FALLBACK = [
    {"id": "693fea08ff2118868c955d27", "name": "Dona"},
    {"id": "69e4939fa112d570f3893b85", "name": "Blok"},
    {"id": "693fea08ff2118868c955d18", "name": "Kilogram"},
]

def refresh_nak_uoms(force=False):
    """Bito'dagi o'lchov birliklarini keshga yuklaydi.
    ⚠️ Bito'da mahsulot maydoni "measure_id" deb ataladi, shuning uchun REST resursi
    ham "measure" bo'lishi mumkin — bir nechta ehtimoliy manzil sinaladi va
    ishlagani sozlamalarda eslab qolinadi.
    Faol va omborga tegishli birliklar ustuvor (Bito ilovasida ham shular ko'rinadi:
    Dona, Blok, Kilogram); agar filtrdan hech narsa qolmasa, filtrsiz olinadi."""
    now_ts = time.time()
    if not force and NAK_UOM_CACHE["uoms"] and (now_ts - NAK_UOM_CACHE["ts"]) < NAK_CATALOG_TTL:
        return
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    # ⚠️ 2026-07-26: measure/get-all, uom/get-all, measure/get-paging, uom/get-paging —
    # to'rttasi ham HTTP 404 qaytardi (integration-api'da bu resurs ochilmagan).
    # Bito'dan jonli tekshirildi: faol inventar birliklari AYNAN Kilogram, Dona, Blok
    # (Metr va Litr — inactive). Ya'ni quyidagi zaxira ro'yxat to'liq va to'g'ri.
    # Shuning uchun keraksiz 4 ta so'rov qilinmaydi; agar kelajakda ishlaydigan
    # manzil topilib sozlamalarga yozilsa, faqat o'sha sinaladi.
    known = get_setting("bito_uom_endpoint", "")
    candidates = [known] if known else []

    raw = []
    used = None
    for path in candidates:
        try:
            body = {"page": 1, "limit": 100} if "paging" in path else {}
            r = requests.post(BITO_BASE_URL + path, json=body, headers=headers, timeout=15)
            if r.status_code != 200:
                r = requests.get(BITO_BASE_URL + path, headers=headers, timeout=15)
            if r.status_code != 200:
                print(f"NAK UOMS: {path} → HTTP {r.status_code}", flush=True)
                continue
            d = r.json().get("data", [])
            items = d if isinstance(d, list) else (d.get("data") or [])
            items = [u for u in items if isinstance(u, dict) and (u.get("_id") or u.get("id")) and u.get("name")]
            if items:
                raw, used = items, path
                break
        except Exception as e:
            print(f"NAK UOM ERR ({path}):", str(e)[:120], flush=True)
            continue

    if not raw:
        # API'dan olinmadi — zaxira ro'yxatni ishlatamiz, tanlagich baribir ishlasin
        if not NAK_UOM_CACHE["uoms"]:
            NAK_UOM_CACHE["uoms"] = list(NAK_UOM_FALLBACK)
            NAK_UOM_CACHE["ts"] = now_ts
            print("NAK UOMS: API'dan olinmadi — zaxira ro'yxat ishlatildi "
                  "(Dona, Blok, Kilogram)", flush=True)
        return

    def _pick(u):
        return {"id": u.get("_id") or u.get("id"), "name": u.get("name")}

    # Avval faqat faol + ombor turidagilarni olamiz (Bito ilovasidagi kabi)
    strict = [_pick(u) for u in raw
              if not u.get("is_deleted")
              and str(u.get("status", "active")).lower() != "inactive"
              and str(u.get("type", "inventory")).lower() != "service"]
    uoms = strict or [_pick(u) for u in raw if not u.get("is_deleted")]
    if uoms:
        NAK_UOM_CACHE["uoms"] = uoms
        NAK_UOM_CACHE["ts"] = now_ts
        if used and used != known:
            set_setting("bito_uom_endpoint", used)
        print(f"NAK UOMS: {len(uoms)} ta birlik ({used}) keshga yuklandi: "
              f"{', '.join(u['name'] for u in uoms)}", flush=True)

def refresh_nak_categories(force=False):
    """Bito'dagi barcha kategoriyalarni (odatda o'nlab-yuzlab — kam) lokal keshga yuklaydi."""
    now_ts = time.time()
    if not force and NAK_CATEGORY_CACHE["categories"] and (now_ts - NAK_CATEGORY_CACHE["ts"]) < NAK_CATALOG_TTL:
        return
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    cats = []
    try:
        for page in range(1, 6):  # ~1000 kategoriyagacha yetarli
            r = requests.post(BITO_BASE_URL + "category/get-paging",
                             json={"page": page, "limit": 200}, headers=headers, timeout=15)
            if r.status_code != 200:
                break
            d = (r.json().get("data", {}) or {})
            items = d.get("data", []) if isinstance(d, dict) else []
            if not items:
                break
            for c in items:
                cid, cname = c.get("_id"), c.get("name")
                if cid and cname:
                    cats.append({"id": cid, "name": cname})
            if len(items) < 200:
                break
        if cats:
            NAK_CATEGORY_CACHE["categories"] = cats
            NAK_CATEGORY_CACHE["ts"] = now_ts
            print(f"NAK CATEGORIES: {len(cats)} ta kategoriya keshga yuklandi", flush=True)
    except Exception as e:
        print("NAK CATEGORY REFRESH ERR:", str(e)[:120], flush=True)

_CYR2LAT = {
    "а":"a","б":"b","в":"v","г":"g","д":"d","е":"e","ё":"yo","ж":"j","з":"z","и":"i",
    "й":"y","к":"k","л":"l","м":"m","н":"n","о":"o","п":"p","р":"r","с":"s","т":"t",
    "у":"u","ф":"f","х":"x","ц":"ts","ч":"ch","ш":"sh","щ":"sh","ъ":"","ы":"i","ь":"",
    "э":"e","ю":"yu","я":"ya","ў":"o'","қ":"q","ғ":"g'","ҳ":"h",
}

def _translit_and_norm(name):
    """Kirillni lotinga o'giradi, kichik harfga o'tkazadi, faqat harf/raqam qoldiradi —
    shunday qilib 'Коктейль Мохито' va 'Moxito' solishtiriladigan shaklga keladi."""
    import re as _re
    s = (name or "").lower()
    s = "".join(_CYR2LAT.get(ch, ch) for ch in s)
    s = _re.sub(r"[^a-z0-9 ]", " ", s)
    return " ".join(s.split())

def refresh_nak_catalog(force=False):
    """Bito'dagi BARCHA mahsulot nomlarini (id + nom) lokal keshga yuklaydi.
    30 daqiqada bir marta (yoki force=True bo'lsa darhol) yangilanadi.
    🔢 Shu bilan birga ENG KATTA `sku` raqamini ham yig'ib boradi — yangi mahsulot
    yaratishda Bito `sku` maydonini majburiy talab qiladi va u ketma-ket raqam
    bo'lishi kerak. Katalog qanday bo'lsa ham to'liq o'qilayotgani uchun bu
    QO'SHIMCHA SO'ROVSIZ amalga oshadi."""
    now_ts = time.time()
    if not force and NAK_CATALOG_CACHE["products"] and (now_ts - NAK_CATALOG_CACHE["ts"]) < NAK_CATALOG_TTL:
        return
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    products = []
    max_sku = 0
    plu_max, plu_used, plu_dups = 0, {}, {}
    plu_kg_total, plu_kg_without, plu_text_typed = 0, [], 0
    try:
        # ⚡ TEZLASHTIRISH (2026-08-01): sahifalar 4 talab PARALLEL tortiladi.
        # Ilgari 52 sahifa ketma-ket ~40-50 soniya olardi; endi ~12 soniya.
        # Semantika saqlangan: sahifa tartibida ishlanadi, birinchi
        # xato/qisqa sahifada to'xtaydi (ketma-ket variant qanday bo'lsa).
        from concurrent.futures import ThreadPoolExecutor

        def _nak_cat_page(page):
            try:
                r = requests.post(BITO_BASE_URL + "product/get-paging",
                                  json={"page": page, "limit": 200},
                                  headers=headers, timeout=20)
                if r.status_code != 200:
                    return page, None          # xato — shu yerda to'xtaymiz
                d = (r.json().get("data", {}) or {})
                return page, (d.get("data", []) if isinstance(d, dict) else [])
            except Exception as e:
                print(f"NAK CAT PAGE {page} ERR:", str(e)[:120], flush=True)
                return page, None

        all_pages, stop = {}, False
        with ThreadPoolExecutor(max_workers=4) as ex:
            for wave_start in range(1, 80, 4):
                wave = list(range(wave_start, min(wave_start + 4, 80)))
                for page, items in ex.map(_nak_cat_page, wave):
                    all_pages[page] = items
                # To'lqin ichida tartib bilan tekshiramiz
                for page in wave:
                    items = all_pages.get(page)
                    if items is None or not items or len(items) < 200:
                        stop = True
                if stop:
                    break

        for page in sorted(all_pages):
            items = all_pages[page]
            if items is None:
                break                          # xato sahifa — undan keyingisini olmaymiz
            if not items:
                break
            for p in items:
                pid, pname = p.get("_id"), p.get("name")
                is_kg = ((p.get("measure") or {}).get("_id") == CFG.KG_MEASURE_ID)
                got = _plu_value(p)
                if pid and pname:
                    products.append({"id": pid, "name": pname, "key": _translit_and_norm(pname),
                                     # 📏 O'lchov birligi — Bito'dagi joriy qiymat.
                                     # "Chiroyli tahrirlash"da ko'rsatish uchun qo'shimcha
                                     # so'rovsiz shu yerdan olinadi.
                                     "measure_id": (p.get("measure") or {}).get("_id"),
                                     "measure_name": (p.get("measure") or {}).get("name"),
                                     # ⚖️ PLU ham shu yerda saqlanadi — yuklashdan keyin
                                     # "kimda PLU yo'q" tekshiruvi so'rovsiz bajarilsin
                                     "is_kg": is_kg,
                                     "plu": (got[0] if got else None),
                                     # 🏢 Qaysi firmadan olinishi — zakaz tavsiyasi
                                     # shu bo'yicha guruhlaydi. Qo'shimcha so'rovsiz.
                                     "supplier_ids": [x for x in (p.get("supplier_ids") or [])
                                                      if isinstance(x, str)]})
                # sku matn ko'rinishida keladi ("28046"), faqat butun sonlarni hisobga olamiz
                sk = str(p.get("sku") or "").strip()
                if sk.isdigit():
                    v = int(sk)
                    if v > max_sku:
                        max_sku = v
                # ⚖️ PLU statistikasi — katalog ALLAQACHON to'liq o'qilyapti,
                # shuning uchun qo'shimcha so'rov ketmaydi.
                if is_kg:
                    plu_kg_total += 1
                if got is None:
                    if is_kg and pid and pname:
                        plu_kg_without.append({"id": pid, "name": pname})
                else:
                    n, was_text = got
                    if was_text:
                        plu_text_typed += 1
                    if n > plu_max:
                        plu_max = n
                    if n in plu_used:
                        plu_dups.setdefault(n, [plu_used[n]]).append(pname)
                    else:
                        plu_used[n] = pname
            if len(items) < 200:
                break
        if products:
            NAK_CATALOG_CACHE["products"] = products
            NAK_CATALOG_CACHE["ts"] = now_ts
            if max_sku:
                NAK_CATALOG_CACHE["max_sku"] = max_sku
                # Keyingi beriladigan raqamni ham shu yerda tiklaymiz
                # ⚠️ NAK_SKU_STATE["next"] boshlanishida None bo'ladi — kalit MAVJUD
                # bo'lgani uchun .get("next", 0) nolni emas, None'ni qaytaradi va
                # max(None, int) TypeError beradi. Shuning uchun `or 0`.
                NAK_SKU_STATE["next"] = max(NAK_SKU_STATE.get("next") or 0, max_sku + 1)
            print(f"NAK CATALOG: {len(products)} ta mahsulot keshga yuklandi, eng katta sku={max_sku}", flush=True)
            # ⚖️ PLU statistikasi — faqat skan TO'LIQ o'tgan bo'lsa yozamiz
            NAK_PLU_STATS.update({
                "ts": now_ts, "max": plu_max, "used": set(plu_used.keys()),
                "kg_total": plu_kg_total, "kg_without": plu_kg_without,
                "duplicates": plu_dups, "text_typed": plu_text_typed,
            })
            print(f"PLU: eng katta={plu_max}, band={len(plu_used)} ta, "
                  f"kg mahsulot={plu_kg_total} (PLU yo'q: {len(plu_kg_without)}), "
                  f"takror={len(plu_dups)}, matn turida={plu_text_typed}", flush=True)
    except Exception as e:
        print("NAK CATALOG REFRESH ERR:", str(e)[:150], flush=True)

def _extract_numbers(name):
    """Nomdagi barcha raqamlarni ajratib oladi (250, 1.5, 0.5 kabi) — hajm/og'irlik/foiz."""
    import re as _re
    return set(_re.findall(r"\d+(?:[.,]\d+)?", name or ""))

def _numbers_conflict(a, b):
    """Ikkala nomda ham raqam bor-u, lekin umuman mos kelmasa — bu odatda BOSHQA
    hajm/og'irlik/foiz degani (masalan 'Lays 70gr' va 'Lays 150gr' — boshqa mahsulot!).
    AI promptida ham aynan shu qoida bor: "o'lcham boshqa bo'lsa, bu boshqa mahsulot"."""
    na, nb = _extract_numbers(a), _extract_numbers(b)
    return bool(na) and bool(nb) and not (na & nb)

def _local_fuzzy_match(name, min_ratio=0.80, min_gap=0.06):
    """Lokal katalogdan (Claude ishlatmasdan!) eng mos nomzodni topadi.
    Faqat YUQORI ISHONCHLI holatda natija qaytaradi — aks holda None
    (bu holda AI'ga murojaat qilinadi, xato moslikni Bito'ga yuklamaslik uchun).
    ⚠️ Raqam (hajm/og'irlik) ziddiyati bo'lsa — matn o'xshash bo'lsa ham RAD ETILADI,
    chunki bu ko'pincha "Lays 70gr" vs "Lays 150gr" kabi BOSHQA mahsulot degani."""
    catalog = NAK_CATALOG_CACHE["products"]
    if not catalog:
        return None
    import difflib
    key = _translit_and_norm(name)
    if not key:
        return None
    best, best_score, second_score = None, 0.0, 0.0
    for p in catalog:
        score = difflib.SequenceMatcher(None, key, p["key"]).ratio()
        if score > best_score:
            second_score = best_score
            best, best_score = p, score
        elif score > second_score:
            second_score = score
    if not best or best_score < min_ratio or (best_score - second_score) < min_gap:
        return None
    if _numbers_conflict(name, best["name"]):
        return None
    return best, best_score

def nak_catalog_warmer_thread():
    """Katalogni fonda muntazam yangilab turadi — birinchi moslashtirish so'rovi
    ham lokal keshdan foydalana olishi uchun darhol boshlab yuboradi."""
    time.sleep(15)
    while True:
        try:
            refresh_nak_catalog()
        except Exception as e:
            print("NAK CATALOG WARMER ERR:", str(e)[:120], flush=True)
        try:
            refresh_nak_categories()
        except Exception as e:
            print("NAK CATEGORY WARMER ERR:", str(e)[:120], flush=True)
        try:
            refresh_nak_uoms()
        except Exception as e:
            print("NAK UOM WARMER ERR:", str(e)[:120], flush=True)
        time.sleep(NAK_CATALOG_TTL)

