def _nak_norm(name):
    """Solishtirish uchun nomni soddalashtiradi (katta-kichik harf, ortiqcha bo'shliq)."""
    return " ".join((name or "").strip().lower().split())

def nak_get_alias(name):
    """Avval bog'langan bo'lsa, saqlangan moslikni qaytaradi:
    dict(product_id, product_name, last_price, block_size, measure_id) yoki None.
    block_size — 1 blok/quti/karobkada nechta dona borligi (standart: 1).
    measure_id — o'lchov birligi (Dona/Blok/Kilogram), bir marta kiritilsa eslab qolinadi."""
    row = qone("SELECT product_id, product_name, last_price, block_size, measure_id, sale_price "
               "FROM nak_aliases WHERE alias_name=?", (_nak_norm(name),))
    if not row: return None
    return {"product_id": row[0], "product_name": row[1], "last_price": row[2],
            "block_size": row[3] if row[3] else 1, "measure_id": row[4],
            "sale_price": row[5]}

def nak_forget_alias(name):
    """Eskirgan moslikni xotiradan o'chiradi (Bito'da mahsulot o'chirilgan bo'lsa).
    Shundan keyin bu nom qaytadan moslashtiriladi."""
    q("DELETE FROM nak_aliases WHERE alias_name=?", (_nak_norm(name),))

def nak_save_alias(name, product_id, product_name, price=None, block_size=None, measure_id=None, sale_price=None):
    """Nakladnoy nomi ↔ Bito mahsuloti mosligini (narx, blok o'lchami va o'lchov birligi bilan)
    xotiraga saqlaydi.
    block_size / measure_id = None bo'lsa — oldin saqlangan qiymat SAQLANIB QOLADI
    (qayta yozib yuborilmaydi), faqat aniq berilganda yangilanadi."""
    key = _nak_norm(name)
    if not key or not product_id:
        return
    row = qone("SELECT id, hit_count, block_size, measure_id, sale_price FROM nak_aliases WHERE alias_name=?", (key,))
    if row:
        # Berilmagan qiymatlar ESKISICHA qoladi (tasodifan o'chib ketmasin)
        final_block_size = block_size if block_size is not None else (row[2] if row[2] else 1)
        final_measure = measure_id if measure_id else row[3]
        final_sale = sale_price if sale_price is not None else row[4]
        q("UPDATE nak_aliases SET product_id=?, product_name=?, hit_count=?, last_price=?, "
          "block_size=?, measure_id=?, sale_price=?, updated_at=? WHERE id=?",
          (product_id, product_name, row[1] + 1, price, final_block_size, final_measure,
           final_sale, now_str(), row[0]))
    else:
        q("INSERT INTO nak_aliases (alias_name, product_id, product_name, last_price, block_size, "
          "measure_id, sale_price, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?)",
          (key, product_id, product_name, price, block_size if block_size is not None else 1,
           measure_id, sale_price, now_str(), now_str()))

def _nak_supplier_search(query):
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.post(BITO_BASE_URL + "supplier/get-paging",
                          json={"page": 1, "limit": 6, "search": query or ""},
                          headers=headers, timeout=15)
        items = (r.json().get("data", {}) or {}).get("data", []) if r.status_code == 200 else []
        return [{"id": s.get("_id"), "name": s.get("name", "?")} for s in items if s.get("_id")]
    except Exception as e:
        print("NAK SUPPLIER SEARCH ERR:", str(e)[:100], flush=True)
        return []

def _nak_supplier_markup(cands):
    mk = types.InlineKeyboardMarkup()
    for i, s in enumerate(cands):
        mk.add(types.InlineKeyboardButton(f"✅ {s['name']}", callback_data=f"naksup_{i}"))
    mk.add(types.InlineKeyboardButton("🔍 Boshqa nom bilan qidirish", callback_data="naksup_search"))
    mk.add(types.InlineKeyboardButton("❌ Bekor qilish", callback_data="nak_cancel"))
    return mk

q("""CREATE TABLE IF NOT EXISTS nak_supplier_aliases (
    alias_name TEXT PRIMARY KEY,
    supplier_id TEXT, supplier_name TEXT, updated_at TEXT)""")


def nak_get_supplier_alias(name):
    """🏢 Nakladnoyda o'qilgan firma nomi ilgari bog'langan bo'lsa — moslikni
    qaytaradi. Masalan «Khorezm Pulsar Savdo» → Bito'dagi «Coca Cola».
    Mahsulot aliaslari (nak_aliases) bilan bir xil naqsh."""
    row = qone("SELECT supplier_id, supplier_name FROM nak_supplier_aliases "
               "WHERE alias_name=?", (_nak_norm(name),))
    return {"id": row[0], "name": row[1]} if row else None


def nak_save_supplier_alias(extracted_name, supplier_id, supplier_name):
    key = _nak_norm(extracted_name)
    if not key or not supplier_id:
        return
    q("INSERT INTO nak_supplier_aliases (alias_name, supplier_id, supplier_name, updated_at) "
      "VALUES (?,?,?,?) ON CONFLICT(alias_name) DO UPDATE SET "
      "supplier_id=excluded.supplier_id, supplier_name=excluded.supplier_name, "
      "updated_at=excluded.updated_at",
      (key, supplier_id, supplier_name, now_str()))


def _nak_prompt_supplier(chat_id, uid):
    st = W_NAK[uid]
    st["step"] = "confirm_supplier"
    guess = st.get("supplier") or ""
    # 🧠 XOTIRA: bu firma nomi ilgari bog'langan bo'lsa — SAVOL BERILMAYDI
    # (foydalanuvchi so'rovi: har safar yozib yurish shart bo'lmasin)
    saved = nak_get_supplier_alias(guess)
    if saved:
        st["supplier_id"] = saved["id"]
        st["supplier_confirmed_name"] = saved["name"]
        st["step"] = "review"
        bot.send_message(chat_id,
                         f"🏢 Firma (xotiradan): <b>{h(saved['name'])}</b>\n"
                         f"<i>«{h(guess)}» avval shu firmaga bog'langan. "
                         f"O'zgartirish: /firma_unut</i>", parse_mode="HTML")
        send_long_message(chat_id, _nak_review_text(st), parse_mode="HTML")
        _nak_start_match(uid, chat_id, st)
        return
    cands = _nak_supplier_search(guess)
    st["supplier_cands"] = cands
    if cands:
        text = f"🏢 Nakladnoyda o'qilgan firma: <b>\"{h(guess) or 'aniqlanmadi'}\"</b>\n\nBito ro'yxatidan TASDIQLANG:"
    else:
        text = f"🏢 \"{h(guess) or 'aniqlanmadi'}\" bo'yicha Bito'da hech narsa topilmadi.\nBoshqa nom bilan qidiring:"
    bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=_nak_supplier_markup(cands))

