def _get_bito_sale_prices(product_ids, max_pages=65):
    """Berilgan product_id'lar uchun Bito'dagi JORIY SOTUV NARXINI ("Sotuv Narx" ro'yxatidan)
    qaytaradi: {product_id: {"amount": narx, "entry_id": narx_yozuvining_ozi_id}}.
    "entry_id" keyinchalik narxni YANGILASH uchun kerak bo'ladi.
    ⚠️ max_pages endi BUTUN katalogni (11000+ yozuv, 200/sahifa ≈ 56 sahifa) qamrab olish
    uchun yetarlicha katta — "sotuv narxi hammasida bo'lishi shart" talabiga javob beradi.
    "Chiroyli tahrirlash"da zakup narxi bilan solishtirish uchun ishlatiladi. Katta katalogni
    (10000+ mahsulot) to'liq sahifalab o'qish og'ir bo'lgani uchun, kerakli product_id'larning
    hammasi topilgach ERTA to'xtaydi.
    ⚠️ Bito'da bu endpointning aniq REST manzili hujjatlashtirilmagan — bir nechta ehtimoliy
    manzil sinaladi, ishlagani sozlamalarda eslab qolinadi (supplier_id muammosidagi kabi usul)."""
    if not product_ids:
        return {}
    price_id = tenant_setting("bito_sale_price_id", "694250a9c9b42022084696f6")  # "Sotuv Narx"
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    target = set(product_ids)
    found = {}
    candidates = [
        "price-items/get-paging",
        "price/items/get-paging",
        "price-item/get-paging",
        "prices/items/get-paging",
    ]
    known = get_setting("bito_price_items_endpoint", "")
    if known:
        candidates = [known] + [c for c in candidates if c != known]
    working_path = None
    for path in candidates:
        try:
            r = requests.post(BITO_BASE_URL + path,
                             json={"price_id": price_id, "page": 1, "limit": 200},
                             headers=headers, timeout=15)
            if r.status_code != 200:
                print(f"NAK SALE PRICE: endpoint sinaldi, ishlamadi ({path}): HTTP {r.status_code}", flush=True)
                continue
            j = r.json()
            d = j.get("data", j)
            items = d.get("data", []) if isinstance(d, dict) else (d if isinstance(d, list) else [])
            if not isinstance(items, list):
                continue
            working_path = path
            if path != known:
                set_setting("bito_price_items_endpoint", path)
                print(f"NAK SALE PRICE: ishlaydigan endpoint topildi: {path}", flush=True)
            for it in items:
                if not isinstance(it, dict): continue
                pid = (it.get("product") or {}).get("_id") or it.get("product_id")
                if pid in target and pid not in found:
                    found[pid] = {"amount": it.get("amount", 0) or 0, "entry_id": it.get("_id")}
            break
        except Exception as e:
            print(f"NAK SALE PRICE ERR ({path}):", str(e)[:120], flush=True)
            continue
    if not working_path:
        print("NAK SALE PRICE: hech qaysi endpoint ishlamadi — sotuv narxi ko'rsatilmaydi", flush=True)
        return {}
    # 1-sahifada topilmagan qolganlarini davom ettirib qidiramiz
    for page in range(2, max_pages + 1):
        if len(found) >= len(target):
            break
        try:
            r = requests.post(BITO_BASE_URL + working_path,
                             json={"price_id": price_id, "page": page, "limit": 200},
                             headers=headers, timeout=20)
            if r.status_code != 200:
                break
            j = r.json()
            d = j.get("data", j)
            items = d.get("data", []) if isinstance(d, dict) else (d if isinstance(d, list) else [])
            if not items:
                break
            for it in items:
                if not isinstance(it, dict): continue
                pid = (it.get("product") or {}).get("_id") or it.get("product_id")
                if pid in target and pid not in found:
                    found[pid] = {"amount": it.get("amount", 0) or 0, "entry_id": it.get("_id")}
            if len(items) < 200:
                break
        except Exception as e:
            print(f"NAK SALE PRICE ERR page {page}:", str(e)[:100], flush=True)
            break
    print(f"NAK SALE PRICE: {len(found)}/{len(target)} ta mahsulot uchun sotuv narxi topildi", flush=True)
    return found

def update_bito_sale_price(entry_id, product_id, new_amount, diag=None):
    """Sotuv narxini Bito'ga YOZADI — yangi usul: PUT /product/update.
    🆕 Yangi Swagger'da (api.systematicdev.uz Dev) product sxemasiga
    organizations[].prices[] qo'shilgan: {price_id, amount, uom_prices}.
    Tartib:
      1) Mahsulotni TO'LIQ o'qiymiz (GET product/get-by-id/{id})
      2) Mavjud maydonlarni SAQLAGAN holda update body quramiz — PUT to'liq
         almashtirish bo'lgani uchun kamaytirib yuborsak, ma'lumot o'chishi mumkin
      3) organizations[].prices = [{price_id: "Sotuv Narx", amount: yangi narx}]
      4) PUT product/update
      5) Narxni QAYTA O'QIB tekshiramiz — Bito 200 qaytarib ham narxni
         o'zgartirmasligi mumkin (production'da prices hali yoqilmagan bo'lsa)."""
    if not product_id:
        return False, "Mahsulot Bito'da topilmagan — avval mahsulotni yaratish kerak"
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    price_id = tenant_setting("bito_sale_price_id", "694250a9c9b42022084696f6")
    amt = float(new_amount)

    # 1) Mahsulotni to'liq o'qiymiz
    try:
        r = requests.get(BITO_BASE_URL + f"product/get-by-id/{product_id}",
                         headers=headers, timeout=20)
        if r.status_code != 200:
            return False, f"mahsulotni o'qib bo'lmadi: HTTP {r.status_code}: {(r.text or '')[:120]}"
        p = (r.json() or {}).get("data") or {}
    except Exception as e:
        return False, f"mahsulotni o'qishda xatolik: {str(e)[:120]}"
    if not p.get("_id"):
        return False, "mahsulot ma'lumoti bo'sh qaytdi"

    # 2-3) Mavjud qiymatlarni saqlab, narxni qo'shamiz
    orgs = []
    for o in (p.get("organizations") or [{"organization_id": CFG.BITO_ORG_ID}]):
        orgs.append({
            "organization_id": o.get("organization_id") or CFG.BITO_ORG_ID,
            "is_available": bool(o.get("is_available", True)),
            "max_stock": o.get("max_stock") or 0,
            "yellow_line": o.get("yellow_line") or 0,
            "red_line": o.get("red_line") or 0,
            "standard": o.get("standard") or 0,
            "is_available_for_sale": bool(o.get("is_available_for_sale", True)),
            "prices": [{"price_id": price_id, "amount": amt, "uom_prices": []}],
        })
    body = {
        "_id": p["_id"],
        "name": p.get("name") or "",
        "measure_id": (p.get("measure") or {}).get("_id"),
        "box_item": p.get("box_item") or 0,
        "box_item_barcode": p.get("box_item_barcode") or "",
        "sku": p.get("sku") or "",
        "barcode": p.get("barcode") or "",
        "supplier_ids": p.get("supplier_ids") or [],
        "image": p.get("image") or "",
        "materials": p.get("materials") or [],
        "barcodes": [b for b in (p.get("barcodes") or []) if isinstance(b, dict)],
        "is_semi_product": bool(p.get("is_semi_product")),
        "is_product": bool(p.get("is_product", True)),
        "is_material": bool(p.get("is_material")),
        "is_compound": bool(p.get("is_compound")),
        "is_marked": bool(p.get("is_marked")),
        "tax_ids": p.get("tax_ids") or [],
        "discount_ids": p.get("discount_ids") or [],
        "attributes": p.get("attributes") or [],
        "dimension": p.get("dimension") or {"shape": "other", "netto_weight": 0,
            "gross_weight": 0, "height": 0, "volume": 0, "diameter": 0,
            "width": 0, "length": 0},
        # ⚠️ MUHIM: PUT to'liq ALMASHTIRISH qiladi. Agar custom_fields yuborilmasa,
        # mahsulotning PLU (tarozi kodi) qiymati O'CHIB KETISHI mumkin. Shuning
        # uchun o'qilgan qiymatni o'zgartirmasdan qaytarib yuboramiz.
        "custom_fields": p.get("custom_fields") or [],
        "organizations": orgs,
    }
    cat_id = (p.get("category") or {}).get("_id")
    if cat_id:
        body["category_id"] = cat_id
    if p.get("box_type_id"):
        body["box_type_id"] = p["box_type_id"]

    # 4) PUT product/update
    try:
        r2 = requests.put(BITO_BASE_URL + "product/update", json=body, headers=headers, timeout=25)
    except Exception as e:
        return False, f"PUT product/update xatolik: {str(e)[:120]}"
    if r2.status_code not in (200, 201):
        if diag is not None:
            diag["attempts"] = [("PUT product/update", r2.status_code, (r2.text or "")[:300])]
        fld = _bito_error_field(r2.text or "")
        if fld:
            return False, f"PUT product/update → {r2.status_code}: Bito «{fld}» maydonini talab qilyapti"
        return False, f"PUT product/update → HTTP {r2.status_code}: {(r2.text or '')[:150]}"

    # 5) Haqiqatan yozildimi — qayta o'qib tekshiramiz
    try:
        check = _get_bito_sale_prices([product_id])
        got = (check.get(product_id) or {}).get("amount")
        if got is not None and abs(float(got) - amt) < 0.01:
            print(f"NAK PRICE SET: {product_id} → {amt:,.0f} so'm (tekshirildi ✓)", flush=True)
            return True, ""
        return False, ("Bito 200 qaytardi, lekin narx o'zgarmadi "
                        f"(hozirgi qiymat: {got}). Ehtimol 'prices' maydoni production "
                        "serverda hali yoqilmagan — Bito'da qo'lda kiriting.")
    except Exception:
        # Tekshirib bo'lmadi — 200 javobga ishonamiz
        return True, ""

def _nak_search_products(query, limit=6):
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.post(BITO_BASE_URL + "product/get-paging",
                          json={"page": 1, "limit": limit, "search": query},
                          headers=headers, timeout=15)
        if r.status_code != 200:
            print(f"NAK SEARCH: HTTP {r.status_code}", flush=True)
            return []
        # ⚠️ Bito javobi ikki qavatli ham, bir qavatli ham bo'lishi mumkin —
        # _bito_rows ikkalasini ham to'g'ri ochadi.
        plist = _bito_rows(r.json() or {})
        out = []
        for p in plist:
            if not p.get("_id"):
                continue
            amt = None
            try:
                for o in (p.get("organizations") or []):
                    if o.get("organization_id") == CFG.BITO_ORG_ID:
                        amt = o.get("amount")
                        break
            except Exception:
                amt = None
            meas = p.get("measure") or {}
            out.append({"id": p.get("_id"), "name": p.get("name", "?"),
                        "sku": str(p.get("sku") or ""), "amount": amt,
                        # 📏 O'lchov birligi — qatorni bog'laganda darhol to'ldiriladi
                        "measure_id": (meas.get("_id") or ""),
                        "measure_name": (meas.get("name") or "")})
        return out
    except Exception as e:
        print("NAK SEARCH ERR:", str(e)[:100], flush=True)
        return []

def _nak_match_summary(st, uid=None):
    # 💾 Har ko'rsatishda sessiyani bazaga ham saqlaymiz (deploy'dan omon qolsin)
    if uid is not None:
        try:
            nak_session_save(uid)
        except Exception:
            pass
    lines = ["🔗 <b>Moslashtirish natijasi:</b>\n"]
    mk = types.InlineKeyboardMarkup()

    # ✅ Web app tugmasi — ma'lumot SERVERDA saqlanadi (URL'da emas), shuning uchun
    # WebView keshlash muammosi umuman bo'lmaydi va URL uzunlik chegarasi ham yo'q bo'ladi.
    base = _public_base_url()
    if base and uid:
        matches_with_item = [m for m in st.get("matches", []) if m.get("item")]
        # 🏷️ Bito'dagi JORIY SOTUV NARXINI ham olib, "Chiroyli tahrirlash"da zakup
        # narxi bilan yonma-yon ko'rsatamiz (foydalanuvchi so'ragan qo'shimcha ma'lumot).
        pids_needing_price = [m["product_id"] for m in matches_with_item if m.get("product_id")]
        sale_prices = _get_bito_sale_prices(pids_needing_price) if pids_needing_price else {}
        items_for_web = []
        for m in matches_with_item:
            it = dict(m["item"])  # nusxa olamiz — asl item o'zgarib qolmasin
            if m.get("product_id"):
                # ✅ Bito mahsulot ID'sini HAR DOIM biriktiramiz — narx ro'yxatida bu
                # mahsulot uchun yozuv bo'lmasa ham, foydalanuvchi narx kiritsa uni
                # YANGI yozuv sifatida yaratish uchun kerak bo'ladi.
                it["bito_product_id"] = m["product_id"]
                # 🔗 Bog'langan Bito mahsulotining nomi — web-app'da ko'rsatiladi va
                # foydalanuvchi uni o'sha yerdan boshqasiga almashtira oladi.
                it["bito_product_name"] = m.get("found_name") or ""
                sp = sale_prices.get(m["product_id"])
                if sp:
                    it["price_entry_id"] = sp.get("entry_id")
            # 📈 Kelish narxi oldingi nakladnoyga nisbatan o'zgargan bo'lsa —
            # webapp'da ham ko'rsatish uchun eski narx va foizni uzatamiz
            if m.get("price_changed") and m.get("old_price"):
                it["prev_price"] = m["old_price"]
            # 🏷 Narxni ko'rsatish tartibi:
            #    1) foydalanuvchi kiritgan narx (item ichida saqlangan) — ENG USTUVOR,
            #       shunda sahifa qayta ochilganda kiritilgan qiymat yo'qolmaydi;
            #    2) aks holda Bito'dagi joriy narx.
            own = it.get("sale_price")
            if own is None and it.get("remembered_sale_price"):
                # Bito'da narx yo'q, lekin bot xotirasida bor — ko'rsatamiz
                it["sale_price"] = it["remembered_sale_price"]
                it["sale_price_saved"] = None   # Bito'da tasdiqlanmagan
                own = it["sale_price"]
            if own is None:
                sp = sale_prices.get(m.get("product_id")) if m.get("product_id") else None
                if sp:
                    it["sale_price"] = sp["amount"]
                    it["sale_price_saved"] = sp["amount"]  # Bito'da tasdiqlangan qiymat
                else:
                    it.pop("sale_price", None)
                    it["sale_price_saved"] = None
            # 📏 O'lchov birligi: item'da bo'lmasa (foydalanuvchi hali tanlamagan bo'lsa),
            # Bito'dagi mahsulotning joriy birligini lokal katalogdan olib qo'yamiz.
            if not it.get("measure_id") and m.get("product_id"):
                cat_p = next((p for p in (NAK_CATALOG_CACHE.get("products") or [])
                              if p.get("id") == m["product_id"]), None)
                if cat_p and cat_p.get("measure_id"):
                    it["measure_id"] = cat_p["measure_id"]
                    it["measure_name"] = cat_p.get("measure_name")
            items_for_web.append(it)
        if items_for_web:
            import time as _time, secrets as _secrets
            token = _secrets.token_urlsafe(16)
            nak_webapp_store(uid, items_for_web, token)
            webapp_url = f"{base}/webapp/nakladnoy?uid={uid}&t={token}&v={int(_time.time()*1000)}"
            mk.add(types.InlineKeyboardButton("📱 Chiroyli tahrirlash", web_app=types.WebAppInfo(url=webapp_url)))

    ok_count = 0
    mem_count = 0
    price_alerts = 0
    # ⚠️ Bir xil Bito mahsulotiga bir nechta TURLI nakladnoy nomi bog'langan bo'lsa —
    # bu ko'pincha noto'g'ri moslik belgisi (masalan har xil ta'mlar bitta mahsulotga tushib qolgan)
    pid_counts = {}
    for m in st["matches"]:
        if m.get("product_id"):
            pid_counts[m["product_id"]] = pid_counts.get(m["product_id"], 0) + 1

    # 🔘 MUHIM: Telegram bitta xabarga ~100 tadan ortiq inline tugma sig'dirmaydi.
    # Katta nakladnoylarda (100+ qator) HAR BIR qatorga tugma qo'yilsa, oxirgi
    # "Tayyorlarini yuklash"/"Bekor" tugmalari umuman chiqmay qoladi. Shuning uchun
    # endi tugma FAQAT muammoli (topilmagan / shubhali / narxi o'zgargan) qatorlarga
    # qo'yiladi — toza moslashgan qatorlar matnda ko'rinadi, lekin tugma olmaydi.
    flagged = []  # (priority, i, m, suspicious)
    local_count = 0
    for i, m in enumerate(st["matches"]):
        if m.get("product_id"):
            ok_count += 1
            if m.get("from_memory"):
                icon = "🧠"; mem_count += 1
            elif m.get("from_local"):
                icon = "📚"; local_count += 1
            else:
                icon = "✅"
            suspicious = pid_counts.get(m["product_id"], 0) > 1
            warn_icon = " ⚠️" if suspicious else ""
            lines.append(f"{icon} {h(m['item']['name'])}{warn_icon}\n   → {h(m['found_name'])}")
            if suspicious:
                lines.append(f"   ⚠️ <i>Boshqa {pid_counts[m['product_id']]-1} ta qator ham shu mahsulotga bog'landi — tekshiring!</i>")
            if m.get("price_changed"):
                price_alerts += 1
                old_p, new_p = m["old_price"], m["new_price"]
                arrow = "📈" if new_p > old_p else "📉"
                diff_pct = (new_p - old_p) / old_p * 100 if old_p else 0
                lines.append(f"   {arrow} <b>KELISH NARXI O'ZGARDI:</b> {old_p:,.0f} → {new_p:,.0f} so'm ({diff_pct:+.1f}%)")
            if suspicious:
                flagged.append((0, i, suspicious))  # eng muhimi — bir xil mahsulotga bog'lanish xatosi
            elif m.get("price_changed"):
                flagged.append((1, i, suspicious))
            else:
                # 🔄 TOZA qatorlar ham (2026-08-02): ilgari tugma faqat muammoli
                # qatorlarga berilardi — toza moslashgan (masalan KIWI 2л) qatorni
                # O'ZGARTIRIB BO'LMASDI. Toza moslashuv ham xato bo'lishi mumkin,
                # shuning uchun hammasi tugma oladi; muammolilar ro'yxat boshida.
                flagged.append((2, i, False))
        else:
            lines.append(f"❓ {h(m['item']['name'])} — mos topilmadi")
            flagged.append((-1, i, False))  # eng muhimi — topilmagan

    ai_count = ok_count - mem_count - local_count
    lines.append(f"\n{ok_count} ta tayyor (🧠 {mem_count} xotiradan, 📚 {local_count} lokal katalogdan, "
                  f"🤖 {ai_count} AI orqali), {len(st['matches'])-ok_count} ta topilmadi.")
    if mem_count + local_count:
        lines.append(f"💡 {mem_count + local_count} ta qator uchun Claude ishlatilmadi — token tejaldi.")
    if price_alerts:
        lines.append(f"⚠️ {price_alerts} ta mahsulotning KELISH NARXI oldingi safardan farq qiladi (yuqorida ko'rsatildi).")
    if any(pid_counts.get(m.get("product_id"), 0) > 1 for m in st["matches"] if m.get("product_id")):
        lines.append("⚠️ Diqqat: bir nechta turli mahsulot bitta Bito mahsulotiga bog'langan — bu xato bo'lishi mumkin, pastdagi \"🔄 boshqasini tanlash\" orqali tekshiring.")

    # Eng muhim (topilmagan → shubhali → narx o'zgargan) tartibda, xavfsiz chegaragacha tugma qo'shamiz.
    # Chegara: 100 (Telegram limiti) minus web-app/yuklash/bekor/tahrirlash uchun ~4 joy = 90.
    MAX_ITEM_BUTTONS = 90
    flagged.sort(key=lambda x: x[0])
    shown = flagged[:MAX_ITEM_BUTTONS]
    hidden_count = len(flagged) - len(shown)
    for _, i, suspicious in shown:
        m = st["matches"][i]
        if m.get("product_id"):
            btn_label = f"🔄 {i+1}-qator: boshqasini tanlash" + (" ⚠️" if suspicious else "")
        else:
            btn_label = f"🔍 {i+1}-qatorni qo'lda qidirish"
        mk.add(types.InlineKeyboardButton(btn_label, callback_data=f"nakfix_{i}"))
    if hidden_count > 0:
        lines.append(f"\nℹ️ Yana {hidden_count} ta qator uchun tugma sig'madi (Telegram cheklovi) — "
                      f"ularni o'zgartirish uchun \"✏️ Tahrirlash\" yoki \"📱 Chiroyli tahrirlash\"dan foydalaning.")

    # 🆕 Topilmaganlar bo'lsa — ularni Bito'da BIR TUGMA bilan yaratish imkoni.
    # (Aks holda har birini alohida shtrix-kod bilan kiritish kerak bo'lardi.)
    n_missing = len([m for m in st["matches"] if not m.get("product_id")])
    if n_missing:
        mk.add(types.InlineKeyboardButton(f"🆕 {n_missing} ta topilmaganini Bito'da yaratish",
                                          callback_data="nak_create_missing"))
    if ok_count:
        mk.add(types.InlineKeyboardButton("🚀 Tayyorlarini yuklash", callback_data="nak_do"))
    mk.add(types.InlineKeyboardButton("✏️ Tahrirlash", callback_data="nak_edit"),
           types.InlineKeyboardButton("❌ Bekor", callback_data="nak_cancel"))
    return "\n".join(lines), mk

def _nak_apply_webapp_items(uid, raw_items, silent_summary=False):
    """Web App'dan kelgan itemlarni holatga qo'llaydi va foydalanuvchiga natijani yuboradi.
    Ham eski web_app_data yo'lidan, ham yangi HTTP POST yo'lidan chaqiriladi.
    Qaytaradi: (ok: bool, xabar: str)"""
    st = nak_session_restore(uid)
    if not st:
        return False, "Sessiya tugagan — /nakladnoy bilan qayta boshlang."
    new_items = []
    price_updates = []  # (index, nom, entry_id, product_id, yangi_narx) — Bito'ga DARHOL yuboriladi
    for idx, it in enumerate(raw_items):
        nsp = it.get("new_sale_price")
        has_pid = bool(str(it.get("bito_product_id") or "").strip())
        # 🏷 Foydalanuvchi kiritgan/ko'rgan narxni HAR DOIM item ichida saqlaymiz — aks holda
        # sahifa qayta ochilganda kiritilgan narx yo'qolib, katak yana bo'sh chiqadi.
        try:
            shown_price = float(nsp) if nsp is not None else None
        except Exception:
            shown_price = None
        # Bito'da mahsulotning O'ZI hali yo'q bo'lsa, narxni hozir o'rnatib bo'lmaydi —
        # uni saqlab qo'yamiz va "Bitoga yuklash"da, mahsulot yaratilgandan KEYIN qo'llaymiz.
        pending_price = shown_price if (shown_price is not None and not has_pid) else None
        new_items.append({"_link_pid": str(it.get("bito_product_id","") or "").strip(),
                          "_link_name": str(it.get("bito_product_name","") or "").strip(),
                          "_link_new": bool(it.get("auto_create", False)),
                          "name": str(it.get("name","")).strip(),
                          "qty": float(it.get("qty",0) or 0),
                          "price": float(it.get("price",0) or 0),
                          "barcode": str(it.get("barcode","") or "").strip(),
                          "category_id": str(it.get("category_id","") or "").strip(),
                          "category_name": str(it.get("category_name","") or "").strip(),
                          "block_size": float(it.get("block_size", 1) or 1),
                          # ✅ Faqat foydalanuvchi HAQIQATAN o'zgartirgan bo'lsa True — shu
                          # bilan xotiraga yozishda ESKI/KESHLANGAN qiymat qayta yozib
                          # yubormaydi (masalan sahifa eski holatda ochilib qolgan bo'lsa).
                          "block_size_edited": bool(it.get("block_size_edited", False)),
                          # 📏 O'lchov birligi (Dona/Blok/Kilogram)
                          "measure_id": str(it.get("measure_id","") or "").strip(),
                          "measure_name": str(it.get("measure_name","") or "").strip(),
                          # 👇 ko'rsatiladigan narx; "saqlangan" holati pastda aniqlanadi
                          "sale_price": shown_price,
                          "sale_price_saved": None,
                          "pending_sale_price": pending_price})
        if nsp is not None and has_pid:
            price_updates.append((idx, str(it.get("name","")).strip(), it.get("price_entry_id"),
                                  it.get("bito_product_id"), float(nsp)))
    new_items = [i for i in new_items if i["name"] and i["qty"] > 0]
    _link_backup = [{"pid": i.get("_link_pid", ""), "name": i.get("_link_name", ""),
                     "new": i.get("_link_new", False)} for i in new_items]
    if not new_items:
        bot.send_message(uid, "⚠️ Ro'yxat bo'sh — hech narsa saqlanmadi.")
        return False, "Ro'yxat bo'sh"

    # 🏷️ Bito'da MAVJUD mahsulotlarning narxi kiritilgan/o'zgartirilgan bo'lsa — darhol yuboramiz
    if price_updates:
        ok_names, fail_names = [], []
        pdiag = {}
        for idx, name, entry_id, product_id, new_price in price_updates:
            ok, err = update_bito_sale_price(entry_id, product_id, new_price, diag=pdiag)
            if ok:
                ok_names.append(f"{name} → {new_price:,.0f} so'm")
                # ✅ Bito qabul qildi — endi bu "saqlangan" qiymat hisoblanadi
                if idx < len(new_items):
                    new_items[idx]["sale_price_saved"] = new_price
            else:
                fail_names.append(f"{name} → {new_price:,.0f} so'm — {err[:120]}")
        if ok_names:
            bot.send_message(uid, "🏷 Sotuv narxi o'rnatildi:\n" + "\n".join(f"• {h(n)}" for n in ok_names), parse_mode="HTML")
        if fail_names:
            msg = ("⚠️ <b>Sotuv narxini Bito'ga yozib bo'lmadi</b> — narx bot xotirasida "
                   "saqlandi (keyingi tasdiqlashda avtomatik qayta uriniladi):\n")
            for n in fail_names[:15]:
                msg += f"• {h(n)}\n"
            if len(fail_names) > 15:
                msg += f"...va yana {len(fail_names)-15} ta\n"
            msg += "\n💡 Zarur bo'lsa Bito → Mahsulot → Narxlar → «Narx qo'shing» orqali qo'lda kiriting."
            send_long_message(uid, msg, parse_mode="HTML")

    # 🆕 Yangi mahsulotlarning narxi keyinga qoldirilgani haqida xabar beramiz
    pending = [i for i in new_items if i.get("pending_sale_price")]
    if pending:
        bot.send_message(uid, "🆕 Bu mahsulotlar Bito'da hali yo'q — narxi <b>yuklash paytida</b> "
                               "mahsulot yaratilgandan keyin o'rnatiladi:\n" +
                               "\n".join(f"• {h(i['name'])} → {i['pending_sale_price']:,.0f} so'm" for i in pending),
                          parse_mode="HTML")

    old_matches = st.get("matches") or []
    # 🆕 "Yangi mahsulot qilib kiritish" bayrog'i web-app javobida qaytmaydi —
    # uni ESKI itemlardan ko'chirib olamiz, aks holda qator yana "topilmagan"
    # holatiga tushib, Bito'da yaratilmay qolardi.
    old_items = st.get("items") or []
    if len(old_items) == len(new_items):
        for i, oi in enumerate(old_items):
            if isinstance(oi, dict) and oi.get("auto_create"):
                new_items[i]["auto_create"] = True
    st["items"] = new_items

    # 🔄 MUHIM: matches ichidagi "item" havolalari eski dictlarga ishora qiladi.
    # Ularni yangi itemlar bilan almashtiramiz, aks holda qayta kirilganda ESKI
    # soni/narx ko'rinadi va Bito'ga ham eski qiymat yuklanadi.
    if old_matches and len(old_matches) == len(new_items):
        for i, m in enumerate(old_matches):
            if m:
                m["item"] = new_items[i]
                # 🔗 "Chiroyli tahrirlash"da bog'lanish o'zgartirilgan bo'lsa — qo'llaymiz.
                # Endi nakladnoy bo'yicha MOSLASHTIRISH ham shu sahifada bajariladi.
                lp = new_items[i].pop("_link_pid", "")
                ln = new_items[i].pop("_link_name", "")
                lnew = new_items[i].pop("_link_new", False)
                if lnew and not lp:
                    m["product_id"] = None
                    m["found_name"] = ""
                    new_items[i]["auto_create"] = True
                elif lp and lp != m.get("product_id"):
                    m["product_id"] = lp
                    m["found_name"] = ln or new_items[i]["name"]
                    m["from_memory"] = False
                    new_items[i].pop("auto_create", None)
                    nak_save_alias(new_items[i]["name"], lp, m["found_name"])
                # narx o'zgargan bo'lsa, ogohlantirishni qayta hisoblash
                if m.get("old_price"):
                    np = new_items[i].get("price") or 0
                    op = m["old_price"]
                    if op and np and abs(op - np) > 0.01:
                        m["price_changed"] = True; m["new_price"] = np
                    else:
                        m.pop("price_changed", None)
                # 🧊 "1 blokda nechta dona" — FAQAT foydalanuvchi shu yerda ONGLI ravishda
                # tuzatgan bo'lsagina xotiraga qaytarib saqlaymiz (block_size_edited=True).
                # ⚠️ Agar bu tekshiruv bo'lmasa, eski/keshlangan veb-sahifa ochilib qolib,
                # hech narsa o'zgartirilmasdan "Tasdiqlash" bosilganda ham, sahifadagi
                # (mumkin eski/xato) qiymat qayta bazaga yozilib, to'g'ri xotirani buzib
                # qo'yishi mumkin edi — aynan shu sabab avvalgi safar xato takrorlangan edi.
                if m.get("product_id"):
                    bs_to_save = new_items[i].get("block_size") if new_items[i].get("block_size_edited") else None
                    nak_save_alias(new_items[i]["name"], m["product_id"], m.get("found_name", ""),
                                   new_items[i].get("price"), block_size=bs_to_save,
                                   measure_id=new_items[i].get("measure_id") or None,
                                   sale_price=new_items[i].get("sale_price"))
        st["matches"] = old_matches
        st["step"] = "matched"
        if silent_summary:
            # Darhol yuklash bosilgan — uzun ro'yxat kerak emas, yuklash xabari keladi
            bot.send_message(uid, "✅ Tahrir saqlandi.")
        else:
            bot.send_message(uid, "✅ Tahrir saqlandi. To'g'rilangan nakladnoy:")
            send_long_message(uid, _nak_review_text(st), parse_mode="HTML")
            text, mk = _nak_match_summary(st, uid)
            send_long_message(uid, text, parse_mode="HTML")
            bot.send_message(uid, "Davom etamizmi?", reply_markup=mk)
    else:
        # Qator soni o'zgargan — eski moslashtirish endi to'g'ri kelmaydi
        for _it in new_items:
            _it.pop("_link_pid", None); _it.pop("_link_name", None); _it.pop("_link_new", None)
        st.pop("matches", None); st.pop("cands", None)
        st["step"] = "review"
        if old_matches:
            bot.send_message(uid, "✅ Tahrir saqlandi. Qatorlar soni o'zgargani uchun "
                                  "moslashtirishni qayta bajarish kerak.")
        else:
            bot.send_message(uid, "✅ Tahrir saqlandi. To'g'rilangan nakladnoy:")
        send_long_message(uid, _nak_review_text(st), parse_mode="HTML")
        # ⚡ Avto-davom: tahrir saqlangach yuklash o'zi boshlanadi
        _nak_start_match(uid, uid, st)
    return True, "OK"

@bot.message_handler(content_types=['web_app_data'])
def nak_webapp_data(message):
    """Eski yo'l: faqat KeyboardButton orqali ochilgan Web App'lardan keladi.
    Inline tugmalar uchun /webapp/nakladnoy/save POST endpointi ishlatiladi."""
    uid = message.from_user.id
    if nak_session_restore(uid) is None:
        return
    try:
        import json as _json
        data = _json.loads(message.web_app_data.data)
        _nak_apply_webapp_items(uid, data.get("items", []))
    except Exception as e:
        print("NAK WEBAPP DATA ERR:", str(e)[:150], flush=True)
        bot.send_message(uid, f"⚠️ Ma'lumotni qayta ishlashda xatolik: {str(e)[:100]}")

def _nak_start_create_missing(uid, chat_id, st):
    """Topilmagan mahsulotlarni Bito'da fonda yaratadi va ro'yxatni yangilaydi.
    Ikki joydan chaqiriladi: tugma bosilganda, va kategoriya endigina tanlanganda."""
    missing = [m for m in st.get("matches", []) if not m.get("product_id")]
    if not missing:
        bot.send_message(chat_id, "✅ Topilmagan mahsulot qolmadi.")
        return
    status = bot.send_message(chat_id, f"🆕 Bito'da {len(missing)} ta mahsulot yaratilmoqda...")

    def run_create():
        ok_n, fail = 0, []
        diag = {}
        try:
            for k, m in enumerate(missing, 1):
                item = m.get("item", {}) or {}
                name = (item.get("name") or "").strip()
                if not name:
                    continue
                cat = (item.get("category_id") or "").strip() or None
                ok, res = create_bito_product(name, (item.get("barcode") or "").strip() or None,
                                              category_id=cat, diag=diag,
                                              measure_id=(item.get("measure_id") or "").strip() or None)
                if ok:
                    m["product_id"] = res
                    m["found_name"] = name
                    m["from_created"] = True
                    nak_save_alias(name, res, name)
                    ok_n += 1
                    pending = item.get("pending_sale_price")
                    if pending:
                        p_ok, _ = update_bito_sale_price(None, res, float(pending))
                        if p_ok:
                            item["sale_price_saved"] = float(pending)
                            item["pending_sale_price"] = None
                else:
                    fail.append(f"{name}: {str(res)[:90]}")
                    # ⚠️ BIRINCHISI yiqilsa — bu mahsulotga xos emas, balki manzil/so'rov
                    # muammosi. 42 marta bir xil xatoni takrorlamasdan DARHOL to'xtaymiz
                    # va nimalar sinalgani haqida to'liq hisobot beramiz.
                    if k == 1:
                        break
                if k % 10 == 0:
                    try:
                        bot.edit_message_text(f"🆕 Bito'da mahsulot yaratilmoqda... {k}/{len(missing)}",
                                              chat_id, status.message_id)
                    except Exception:
                        pass
        except Exception as e:
            print("NAK CREATE RUN ERR:", str(e)[:200], flush=True)
            fail.append(f"kutilmagan xatolik: {str(e)[:120]}")
        try: bot.delete_message(chat_id, status.message_id)
        except Exception: pass

        if ok_n == 0 and fail:
            # Hech biri yaratilmadi — sabab bitta va umumiy. Aniq tashxis beramiz.
            msg = ("❌ <b>Mahsulot yaratib bo'lmadi.</b>\n\n"
                   f"Sinab ko'rilgan manzillar (Bito javobi bilan):\n")
            for pth, code, txt in (diag.get("attempts") or []):
                msg += f"• <code>{h(pth)}</code> → {h(str(code))}\n"
            codes = {a[1] for a in (diag.get("attempts") or [])}
            if codes and codes <= {404}:
                msg += ("\n📌 Hammasi <b>404</b> — ya'ni Bito'da mahsulot yaratish uchun "
                        "boshqa manzil ishlatiladi.\n\n"
                        "<b>Nima qilish kerak:</b> Bito Swagger'ni (docs.bito.uz) oching, "
                        "mahsulot yaratish (product create) bo'limini toping va o'sha "
                        "manzilni menga yuboring — kodga qo'shib qo'yaman.\n\n"
                        "Hozircha mahsulotlarni Bito ilovasida qo'lda yaratib, "
                        "keyin nakladnoyni qayta yuklashingiz mumkin.")
            else:
                msg += ("\n📌 404 bo'lmagan javob bor — manzil <b>topilgan</b>, lekin so'rov "
                        "tarkibi Bito talabiga mos emas.")
                # Bito qaysi maydonni talab qilayotganini alohida, ko'zga tashlanadigan qilib
                for pth, code, txt in (diag.get("attempts") or []):
                    if code in (404, "EXC"):
                        continue
                    fld = _bito_error_field(txt)
                    if fld:
                        msg += f"\n\n🎯 Bito aynan shu maydondan shikoyat qilyapti: <b>{h(fld)}</b>"
                    msg += f"\n\n<code>{h(txt[:350])}</code>"
                    break
                msg += "\n\nShu xabarni menga yuboring — so'rovni to'g'rilab beraman."
            first = fail[0] if fail else ""
            if first:
                msg += f"\n\n<i>Batafsil: {h(first[:200])}</i>"
            send_long_message(chat_id, msg, parse_mode="HTML")
            return

        msg = f"✅ Bito'da <b>{ok_n} ta</b> yangi mahsulot yaratildi."
        if fail:
            msg += (f"\n\n⚠️ {len(fail)} tasi yaratilmadi:\n" +
                    "\n".join(f"• {h(x)}" for x in fail[:8]) +
                    (f"\n...va yana {len(fail)-8} ta" if len(fail) > 8 else ""))
        send_long_message(chat_id, msg, parse_mode="HTML")
        text, mk2 = _nak_match_summary(st, uid)
        send_long_message(chat_id, text, parse_mode="HTML")
        bot.send_message(chat_id, "Davom etamizmi?", reply_markup=mk2)
    threading.Thread(target=run_create, daemon=True).start()

def _nak_start_match(uid, chat_id, st):
    """🔗 Moslashtirish + Bito'ga yuklash zanjiri.

    Alohida funksiya (2026-08-02): ilgari faqat «Bitoga yuklash» tugmasi
    ostida edi. Endi firma tasdiqlangan zahoti AVTOMATIK chaqiriladi —
    foydalanuvchi so'rovi bo'yicha oraliq menyu olib tashlandi.
    """
    bot.send_message(chat_id, "🔗 Avval xotiradan, keyin lokal katalogdan, so'ng kerak bo'lsagina AI orqali moslashtirilmoqda...")
    def run_match():
        try:
            items = st["items"]
            matches = [None] * len(items)
            unknown_idx = []

            # 🛡 Katalogni OLDIN yuklaymiz — xotiradagi mahsulot ID'lari hali ham
            # Bito'da mavjudligini tekshirish uchun. Bito'da mahsulot o'chirilgan
            # bo'lsa, eski ID bilan yuklash butun partiyani yiqitadi
            # ({"code":26000,"message":"Ushbu tafsilotlarga ega mahsulot topilmadi"}).
            refresh_nak_catalog()
            catalog_ids = {p.get("id") for p in (NAK_CATALOG_CACHE.get("products") or [])}
            # Katalog haqiqatan yuklangan bo'lsagina tekshiramiz (aks holda
            # tarmoq nosozligida butun xotirani o'chirib yuborish xavfi bor)
            can_validate = len(catalog_ids) > 100
            stale_names = []

            # 1) Avval XOTIRADAN tekshiramiz — bir marta to'g'rilangan nomlar darhol topiladi
            #    Shu bilan birga OLDINGI NARX bilan solishtirib, o'zgargan bo'lsa ogohlantiramiz.
            #    🧊 Eslab qolingan "1 blokda nechta dona" ham shu yerda qo'llaniladi — bu
            #    hujjatdagi AI aniqlashidan KO'RA ISHONCHLIROQ (chunki inson tasdiqlagan).
            for i, it in enumerate(items):
                alias = nak_get_alias(it["name"])
                # 🛡 Eskirgan xotira: Bito'da bunday mahsulot endi yo'q → tozalaymiz
                if alias and can_validate and alias.get("product_id") not in catalog_ids:
                    nak_forget_alias(it["name"])
                    stale_names.append(it["name"])
                    alias = None
                if alias:
                    # 📏 Eslab qolingan o'lchov birligi (Dona/Blok/Kilogram)
                    if alias.get("measure_id"):
                        it["measure_id"] = alias["measure_id"]
                    # 🏷 Eslab qolingan sotuv narxi — Bito'da bo'lmasa ham
                    # foyda foizini ko'rsatish uchun tiklaymiz
                    if alias.get("sale_price"):
                        it["remembered_sale_price"] = alias["sale_price"]
                    remembered_bs = alias.get("block_size", 1) or 1
                    # 🛡 Hujjat jamisi bilan TASDIQLANGAN blok bo'lsa (nak_extract
                    # ratio topgan) — narx allaqachon DONA narxi ekani isbotlangan,
                    # xotiradagi block_size bilan QAYTA bo'lish MUMKIN EMAS
                    # (4 500 → 750 bo'lib ketardi). Xotira yo'li faqat hujjatda
                    # jami ustuni bo'lmagan/tasdiqlanmagan qatorlar uchun.
                    doc_bs = float(it.get("block_size", 1) or 1)
                    if remembered_bs > 1 and doc_bs <= 1:
                        it["block_size"] = remembered_bs                            # 💡 MUHIM: AI hujjatdan narxni SO'ZMA-SO'Z oladi, va blokli
                        # mahsulotlarda hujjatning narx ustuni ("ЦЕНА ЗА УП.") — BLOK
                        # narxi bo'ladi (masalan 24 donalik blok = 71,999.2). Foydalanuvchi
                        # "1 blokda 24 dona" deb bir marta o'rgatgan bo'lsa, demak bu
                        # mahsulot narxi blok narxi — uni DONA narxiga bo'lib qo'yamiz:
                        # 71,999.2 ÷ 24 = 3,000 so'm/dona. Shunda "Chiroyli tahrirlash"da
                        # dona narxi to'g'ri chiqadi, blok narxi (3,000×24=71,999.2) va
                        # jami ham hujjat bilan AYNAN mos bo'ladi.
                        if it.get("price"):
                            it["price"] = it["price"] / remembered_bs
                    m = {"item": it, "product_id": alias["product_id"],
                         "found_name": alias["product_name"], "from_memory": True}
                    old_price = alias.get("last_price")
                    new_price = it.get("price") or 0
                    if old_price and new_price and abs(old_price - new_price) > 0.01:
                        m["price_changed"] = True
                        m["old_price"] = old_price
                        m["new_price"] = new_price
                    matches[i] = m
                else:
                    unknown_idx.append(i)

            # 1.2) 🏷 SHTRIX-KOD BO'YICHA — eng ishonchli yo'l. Ba'zi nakladnoylarda
            #      "Штрих код" ustuni bo'ladi; u qatorni Bito mahsuloti bilan ANIQ
            #      bog'laydi (nom bo'yicha taxmin qilish shart emas). Shuning uchun
            #      lokal fuzzy va AI'dan ham OLDIN tekshiriladi.
            bc_unknown = []
            bc_count = 0
            for i in unknown_idx:
                bc = str(items[i].get("barcode") or "").strip()
                if not bc:
                    bc_unknown.append(i)
                    continue
                hit = None
                try:
                    hit = find_bito_product_by_barcode(bc)
                except Exception as e:
                    print("NAK MATCH BARCODE ERR:", str(e)[:120], flush=True)
                if hit:
                    pid, pname = hit
                    matches[i] = {"item": items[i], "product_id": pid,
                                  "found_name": pname or items[i]["name"],
                                  "from_memory": False, "from_barcode": True}
                    bc_count += 1
                else:
                    bc_unknown.append(i)
            unknown_idx = bc_unknown
            if bc_count:
                print(f"NAK MATCH: {bc_count} ta qator SHTRIX-KOD bo'yicha topildi", flush=True)

            # 1.5) 🧠 TOKEN TEJASH: xotirada yo'qlar uchun — Claude'ga murojaat qilishdan OLDIN
            #      lokal katalog (kirill/lotin transliteratsiya bilan) orqali qidiramiz.
            #      Faqat YUQORI ISHONCHLI moslik topilsa ishlatamiz — aks holda AI'ga qoldiramiz.
            still_unknown = []
            local_count = 0
            for i in unknown_idx:
                result = _local_fuzzy_match(items[i]["name"])
                if result:
                    p, score = result
                    matches[i] = {"item": items[i], "product_id": p["id"],
                                  "found_name": p["name"], "from_memory": False,
                                  "from_local": True}
                    local_count += 1
                else:
                    still_unknown.append(i)
            unknown_idx = still_unknown
            if local_count:
                print(f"NAK MATCH: {local_count} ta qator lokal katalogdan topildi (AI ishlatilmadi)", flush=True)

            # 2) Faqat XOTIRADA VA LOKAL KATALOGDA yo'qlar uchun AI + qidiruv ishlatamiz
            cands = [[] for _ in items]
            if unknown_idx:
                sub_items = [items[i] for i in unknown_idx]
                variants = nak_ai_keywords(sub_items)
                sub_cands = []
                for k, it in enumerate(sub_items):
                    queries = [it["name"]] + variants[k]
                    found = []
                    seen_ids = set()
                    for qv in queries:
                        for c in _nak_search_products(qv, limit=5):
                            if c["id"] not in seen_ids:
                                seen_ids.add(c["id"]); found.append(c)
                        if len(found) >= 5:
                            break
                    sub_cands.append(found[:8])
                sel = nak_ai_select(sub_items, sub_cands)
                for k, i in enumerate(unknown_idx):
                    cands[i] = sub_cands[k]
                    idx = sel[k]
                    if 0 <= idx < len(sub_cands[k]):
                        matches[i] = {"item": items[i], "product_id": sub_cands[k][idx]["id"],
                                      "found_name": sub_cands[k][idx]["name"], "from_memory": False}
                    else:
                        matches[i] = {"item": items[i], "product_id": None, "found_name": None, "from_memory": False}

            # 3) Barcha topilgan mosliklarni (yangi narx bilan) XOTIRAGA yozamiz
            #    (lokal katalogdan topilganlar ham — keyingi safar ENDI eng tez, exact-match yo'li orqali topiladi)
            for m in matches:
                if m and m.get("product_id"):
                    nak_save_alias(m["item"]["name"], m["product_id"], m["found_name"],
                                   m["item"].get("price"), block_size=m["item"].get("block_size"),
                                   measure_id=m["item"].get("measure_id"))

            if stale_names:
                preview = "; ".join(stale_names[:8])
                more = f" va yana {len(stale_names)-8} ta" if len(stale_names) > 8 else ""
                bot.send_message(chat_id,
                    f"🧹 <b>{len(stale_names)} ta eskirgan xotira tozalandi</b> — bu mahsulotlar "
                    f"Bito'da o'chirilgan edi, shuning uchun ular qaytadan moslashtirildi:\n{h(preview)}{more}",
                    parse_mode="HTML")
            st["matches"] = matches
            st["cands"] = cands
            st["local_match_count"] = local_count
            text, mk = _nak_match_summary(st, uid)
            send_long_message(chat_id, text, parse_mode="HTML")
            print(f"NAK_MATCH: send_message bilan reply_markup yuborilmoqda...", flush=True)
            bot.send_message(chat_id, "Davom etamizmi?", reply_markup=mk)
            print(f"NAK_MATCH: send_message muvaffaqiyatli ✅", flush=True)
        except Exception as e:
            print(f"NAK_MATCH ERROR: {str(e)[:200]}", flush=True)
            bot.send_message(chat_id, f"⚠️ Moslashtirish xatosi: {str(e)[:80]}")
    threading.Thread(target=run_match, daemon=True).start()
    


@bot.callback_query_handler(func=lambda c: c.data in ("nak_edit", "nak_add", "nak_cancel", "nak_match", "nak_do", "nak_create_missing"))
def nak_callbacks(call):
    uid = call.from_user.id
    chat_id = call.message.chat.id
    st = nak_session_restore(uid)
    _ack(call)
    if not st:
        bot.send_message(chat_id, "Sessiya tugagan — /nakladnoy bilan qayta boshlang."); return
    if call.data == "nak_cancel":
        nak_session_clear(uid)
        bot.send_message(chat_id, "❌ Bekor qilindi."); return
    if call.data == "nak_edit":
        st["step"] = "edit"
        bot.send_message(chat_id, "✏️ Tahrirlash — shunday yozing:\n<code>qator | nom | soni | narx</code>\n"
                                   "Masalan: <code>3 | Coca-Cola 1.5L | 24 | 12000</code>\n"
                                   "Qatorni O'CHIRISH uchun: <code>3 | ochir</code>", parse_mode="HTML")
        return
    if call.data == "nak_add":
        st["step"] = "add"
        bot.send_message(chat_id, "➕ Yangi qator — shunday yozing:\n<code>nom | soni | narx</code>", parse_mode="HTML")
        return
    if call.data == "nak_match":
        _nak_start_match(uid, chat_id, st)
        return
    if call.data == "nak_create_missing":
        # ⚠️ Har qanday xatolik JIM qolmasin — foydalanuvchi sababini ko'rsin
        try:
            missing = [m for m in st.get("matches", []) if not m.get("product_id")]
            if not missing:
                bot.send_message(chat_id, "✅ Topilmagan mahsulot qolmadi.")
                return
            default_cat = get_setting("bito_new_product_category_id", "")
            if not default_cat:
                # Kategoriya hali tanlanmagan — shu yerning o'zida tanlatamiz
                # (⚙️ Sozlamalarga yuborib, foydalanuvchini boshi berk ko'chaga
                # qo'ymaslik uchun)
                try:
                    refresh_nak_categories()
                except Exception:
                    pass
                cats = (NAK_CATEGORY_CACHE.get("categories") or [])[:25]
                if not cats:
                    bot.send_message(chat_id, "⚠️ Bito kategoriyalari yuklanmadi. "
                                               "⚙️ Sozlamalar → 🆕 Yangi mahsulot kategoriyasi orqali qo'lda tanlang.")
                    return
                W_NAK_CAT[uid] = {"step": "pick", "cands": cats, "after": "create_missing"}
                mkc = types.InlineKeyboardMarkup()
                for ci, c in enumerate(cats):
                    mkc.add(types.InlineKeyboardButton(c["name"], callback_data=f"natcatpick_{ci}"))
                bot.send_message(chat_id,
                    f"🆕 <b>{len(missing)} ta yangi mahsulot</b> qaysi kategoriyada yaratilsin?\n"
                    f"Tanlang (keyinchalik ⚙️ Sozlamalardan o'zgartirsa bo'ladi):",
                    parse_mode="HTML", reply_markup=mkc)
                return
            _nak_start_create_missing(uid, chat_id, st)
        except Exception as e:
            print("NAK CREATE MISSING ERR:", str(e)[:200], flush=True)
            bot.send_message(chat_id, f"⚠️ Xatolik: {str(e)[:200]}")
        return

    if call.data == "nak_do":
        nak_start_upload(uid, chat_id, st)

def nak_start_upload(uid, chat_id, st):
    """Nakladnoyni Bito'ga yuklashni boshlaydi (fonda).
    Ikki joydan chaqiriladi: Telegram tugmasi va "Chiroyli tahrirlash" sahifasidagi
    "🚀 Bito'ga yuklash" tugmasi — mantiq bitta joyda turishi uchun."""
    all_m = st.get("matches", [])
    n_items = len([m for m in all_m if m.get("product_id")])
    n_skip = len([m for m in all_m if not m.get("product_id")
                  and not (m.get("item", {}) or {}).get("barcode", "").strip()
                  and not (m.get("item", {}) or {}).get("auto_create")])
    warn = (f"\n⚠️ {n_skip} ta mahsulot Bito'da topilmagani uchun BU YUKLASHGA KIRMAYDI."
            if n_skip else "")
    n_batches = max(1, (n_items + NAK_BATCH_SIZE - 1) // NAK_BATCH_SIZE)
    batch_info = (f"\n📦 {n_batches} ta partiyaga bo'lib yuboriladi "
                  f"(har birida {NAK_BATCH_SIZE} tagacha mahsulot)." if n_batches > 1 else "")
    status = bot.send_message(chat_id, f"⏳ Bito'ga yuklanmoqda ({n_items} ta mahsulot)...{warn}{batch_info}")

    def show_progress(bi, total_b):
        if total_b <= 1:
            return
        try:
            bot.edit_message_text(f"⏳ Bito'ga yuklanmoqda ({n_items} ta mahsulot)...{warn}\n"
                                   f"📦 Partiya {bi}/{total_b} yuborilmoqda...",
                                  chat_id, status.message_id)
        except Exception:
            pass

    def run_upload():
        try:
            uploaded_ids = [m["product_id"] for m in (st.get("matches") or [])
                            if isinstance(m, dict) and m.get("product_id")]
            ok, msg = create_bito_purchase(st, progress_cb=show_progress)
            try: bot.delete_message(chat_id, status.message_id)
            except Exception: pass
            if ok:
                nak_session_clear(uid)
                send_long_message(chat_id, f"✅ <b>Nakladnoy Bito'ga yuklandi!</b>\n{msg}", parse_mode="HTML")
                _offer_plu_assignment(chat_id, uid, uploaded_ids)
            else:
                send_long_message(chat_id, f"⚠️ Yuklashda xatolik: {msg}", parse_mode="HTML")
        except Exception as e:
            print("NAK UPLOAD THREAD ERR:", str(e)[:200], flush=True)
            try:
                bot.send_message(chat_id, f"⚠️ Yuklashda kutilmagan xato: {str(e)[:200]}")
            except Exception:
                pass
    threading.Thread(target=run_upload, daemon=True).start()


def _nak_next_unmatched(st, after=-1):
    """`after` dan KEYINGI hali mos topilmagan qator indeksini qaytaradi (yo'q bo'lsa None).
    Qo'lda qidirish zanjiri shu orqali o'zi-o'zidan davom etadi — foydalanuvchi har safar
    ro'yxatga qaytib, tugma bosib o'tirmaydi."""
    for i, m in enumerate(st.get("matches", [])):
        if i > after and not m.get("product_id"):
            return i
    return None


def _nak_query_fits(query, item_name):
    """Oldingi qidiruv so'zi shu qatorga ham TO'G'RI kelishini tekshiradi.
    Masalan "Alper jid" so'rovi "Жидкое мыло для рук Alper Алоэ 500 мл" qatoriga mos
    (ichida "alper" bor), lekin "Губки Extra Grande" qatoriga mos emas — u yerda
    avtomatik taklif ko'rsatilmaydi, aks holda noto'g'ri mahsulot tanlanib ketishi mumkin."""
    nm = (item_name or "").lower()
    hit = any(len(w) >= 3 and w in nm for w in (query or "").lower().split())
    if not hit:
        return False
    # 🚫 HAJM MOS KELMASA — meros qilinmaydi. "Pepsi 2l" so'rovi "PEPSI-1,0л" qatoriga
    # brend bo'yicha mos tushadi, lekin bu BOSHQA mahsulot. Shu tekshiruvsiz bot
    # 5-qatorni (Pepsi 1l) 4-qatorning javobi (Pepsi 2l) bilan belgilab yuborgan edi.
    qs = _nak_norm_size(_nak_size_token(query))
    ns = _nak_norm_size(_nak_size_token(item_name))
    if qs and qs != ns:
        return False
    return True


def _nak_size_token(name):
    """Nomdan HAJM/ o'lchov bo'lagini ajratadi: "... PET butilka 1,5 l." → "1,5 l".
    Bito nomlari uzun va bir xil boshlanadi (Lipton, alkogolsiz gazlanmagan sovuq ...),
    farq esa OXIRIDA turadi — tugmada u kesilib qolardi va tanlash imkonsiz edi."""
    import re as _re
    pat = _re.compile(r"(\d+[.,]?\d*)\s*(ml\b|мл\b|kg\b|кг\b|gr\b|гр\b|sht\b|шт\b|dona\b|l\b|л\b|g\b|г\b)", _re.I)
    hits = pat.findall(name or "")
    if not hits:
        return ""
    # ⚠️ HAJM/OG'IRLIK sanoq birligidan USTUN. "PEPSI-2,0л PET FS 6шт" da oxirgi
    # moslik "6шт" (blokdagi dona soni) — u mahsulotni ajratmaydi, kerakli belgi "2,0л".
    volume = [hp for hp in hits if hp[1].lower() in ("ml", "мл", "kg", "кг", "gr", "гр", "l", "л", "g", "г")]
    num, unit = (volume[-1] if volume else hits[-1])
    return f"{num} {unit.lower()}"


def _nak_norm_size(tok):
    """Hajm belgisini taqqoslanadigan ko'rinishga keltiradi: "2,0 л" va "2 l" → "2:l"."""
    if not tok:
        return ""
    try:
        num, unit = tok.split(" ", 1)
    except ValueError:
        return ""
    unit = unit.strip().lower()
    unit = {"л": "l", "мл": "ml", "кг": "kg", "гр": "g", "г": "g", "gr": "g",
            "шт": "sht", "dona": "sht"}.get(unit, unit)
    try:
        val = float(num.replace(",", "."))
    except Exception:
        return ""
    if unit == "ml":
        val, unit = val / 1000.0, "l"
    elif unit == "g":
        val, unit = val / 1000.0, "kg"
    return f"{val:g}:{unit}"


def _nak_shorten(text, limit=60):
    """Uzun yorliqni O'RTASIDAN qisqartiradi — oxiri (odatda hajm/ta'm kabi FARQLI
    qism) ko'rinib turadi. Oddiy kesish oxirini yo'qotib, tugmalarni bir xil qilardi."""
    t = (text or "").strip()
    if len(t) <= limit:
        return t
    head = (limit - 1) * 2 // 3
    tail = limit - 1 - head
    return t[:head] + "…" + t[-tail:]


def _nak_common_prefix(names):
    """Nomzodlarning umumiy boshlanishini topadi (so'z chegarasigacha).
    Shu qism tugmadan olib tashlanadi — ekranda faqat FARQ ko'rinadi."""
    if len(names) < 2:
        return ""
    p = names[0]
    for n in names[1:]:
        i = 0
        while i < min(len(p), len(n)) and p[i].lower() == n[i].lower():
            i += 1
        p = p[:i]
        if not p:
            return ""
    cut = max(p.rfind(" "), p.rfind(","))
    p = p[:cut] if cut > 0 else p
    return p if len(p) >= 12 else ""


def _nak_send_candidates(chat_id, st, idx, cands, header):
    """Nomzodlarni yuboradi. Tugmada faqat FARQLI qism + hajm + qoldiq ko'rsatiladi,
    to'liq nomlar esa xabar matnida raqamlangan holda turadi — Telegram tugmasi
    ~60 belgidan keyin kesilib ketadi, uzun bir xil nomlarni ajratib bo'lmasdi."""
    st["fixcands"] = cands
    names = [c.get("name", "?") for c in cands]
    pref = _nak_common_prefix(names)
    lines = [header, ""]
    mk = types.InlineKeyboardMarkup()
    for j, c in enumerate(cands):
        nm = c.get("name", "?")
        size = _nak_size_token(nm)
        tail = nm[len(pref):].strip(" ,.-·") if pref and nm.lower().startswith(pref.lower()) else nm
        parts = [f"{j+1})"]
        if size:
            parts.append(size)
        parts.append(tail)
        label = " · ".join(parts[:1]) + " " + " · ".join(parts[1:])
        amt = c.get("amount")
        if amt not in (None, ""):
            try:
                label += f"  [{float(amt):g}]"
            except Exception:
                pass
        mk.add(types.InlineKeyboardButton(_nak_shorten(label, 60), callback_data=f"nakpick_{idx}_{j}"))
        extra = []
        if c.get("sku"):
            extra.append(f"SKU {c['sku']}")
        if amt not in (None, ""):
            extra.append(f"qoldiq {amt}")
        lines.append(f"<b>{j+1})</b> {h(nm)}" + (f"\n     <i>{' · '.join(extra)}</i>" if extra else ""))
    mk.add(types.InlineKeyboardButton("✏️ Boshqa so'z bilan qidirish", callback_data=f"nakask_{idx}"))
    mk.add(types.InlineKeyboardButton("🆕 Yangi mahsulot qilib kiritish", callback_data=f"naknew_{idx}"))
    mk.add(types.InlineKeyboardButton("⏭ Bu qatorni tashlab ketish", callback_data=f"nakskip_{idx}"))
    bot.send_message(chat_id, "\n".join(lines), reply_markup=mk, parse_mode="HTML")


def _nak_apply_pick(chat_id, st, i, cand):
    """Tanlangan mahsulotni qatorga bog'laydi va xotiraga yozadi.
    ⚠️ Telegram bir update'ni qayta yuborishi mumkin (bot sekin javob qaytarsa) —
    shuning uchun allaqachon bog'langan qator IKKINCHI marta o'zgartirilmaydi."""
    if st["matches"][i].get("product_id"):
        return
    st["matches"][i]["product_id"] = cand["id"]
    st["matches"][i]["found_name"] = cand["name"]
    st["matches"][i]["from_memory"] = False
    nak_save_alias(st["matches"][i]["item"]["name"], cand["id"], cand["name"])
    bot.send_message(chat_id, f"✅ {i+1}-qator: {h(cand['name'])}", parse_mode="HTML")


def _nak_ask_fix(chat_id, st, idx, force_ask=False):
    """Qator uchun qidiruvni boshlaydi.
    ⚡️ Tezlik uchun uchta yo'l:
      1) oldingi qidiruv so'zi shu qatorga ham mos bo'lsa — AVTOMATIK qidiradi va
         nomzodlarni darrov ko'rsatadi (foydalanuvchi qayta yozmaydi);
      2) natija BITTA bo'lsa — hech nima so'ramay o'zi tanlaydi;
      3) aks holda — odatdagidek so'z so'raladi."""
    if st["matches"][idx].get("product_id"):
        # Bu qator allaqachon hal bo'lgan (takroriy update) — keyingisiga o'tamiz
        _nak_advance_fix(chat_id, st, idx)
        return
    st["step"] = "fixsearch"
    st["fix_idx"] = idx
    it = st["items"][idx]
    name = it.get("name", "?")
    q = None if force_ask else (st.get("last_fix_query") or "").strip()
    if q and _nak_query_fits(q, name):
        try:
            found = _nak_search_products(q, limit=6)
        except Exception as e:
            print("NAK FIX AUTO SEARCH ERR:", str(e)[:150], flush=True)
            found = []
        # ⚠️ Meros qilingan so'rovda BITTA natija chiqsa ham AVTOMATIK tanlanmaydi —
        # so'rovni foydalanuvchi BOSHQA qator uchun yozgan, tasdiq shart.
        if found:
            _nak_send_candidates(chat_id, st, idx, found,
                                 f"🔍 <b>{h(name)}</b>\n«{h(q)}» bo'yicha topildi — qaysi biri?")
            return
    mk = types.InlineKeyboardMarkup()
    mk.add(types.InlineKeyboardButton("🆕 Yangi mahsulot qilib kiritish", callback_data=f"naknew_{idx}"))
    mk.add(types.InlineKeyboardButton("⏭ Bu qatorni tashlab ketish", callback_data=f"nakskip_{idx}"))
    bot.send_message(chat_id,
        f"🔍 <b>{h(name)}</b> uchun Bito'dagi nomini yozing (qisqa, masalan brend so'zi):",
        parse_mode="HTML", reply_markup=mk)


def _nak_advance_fix(chat_id, st, done_idx):
    """Qator hal bo'lgach — KEYINGI topilmagan qatorga o'zi o'tadi.
    Hammasi tugasa, umumiy ro'yxatni bir marta ko'rsatadi (avval har qatordan keyin
    uzun ro'yxat qayta-qayta chiqib, ish sekinlashardi)."""
    nxt = _nak_next_unmatched(st, after=done_idx)
    if nxt is not None:
        _nak_ask_fix(chat_id, st, nxt)
        return
    st["step"] = "matched"
    text, mk = _nak_match_summary(st, st.get("uid"))
    send_long_message(chat_id, text, parse_mode="HTML")
    bot.send_message(chat_id, "Davom etamizmi?", reply_markup=mk)


@bot.callback_query_handler(func=lambda c: c.data.startswith("nakfix_") or c.data.startswith("nakpick_")
                            or c.data.startswith("nakask_") or c.data.startswith("nakskip_")
                            or c.data.startswith("naknew_"))
def nak_fix_callbacks(call):
    uid = call.from_user.id
    chat_id = call.message.chat.id
    st = nak_session_restore(uid)
    _ack(call)
    if not st or "matches" not in st:
        bot.send_message(chat_id, "Sessiya tugagan — /nakladnoy bilan qayta boshlang."); return
    st["uid"] = uid
    if call.data.startswith("nakfix_"):
        _nak_ask_fix(chat_id, st, int(call.data.replace("nakfix_", "")))
        return
    if call.data.startswith("nakask_"):
        # "✏️ Boshqa so'z bilan qidirish" — avtomatik taklifni chetlab o'tamiz
        _nak_ask_fix(chat_id, st, int(call.data.replace("nakask_", "")), force_ask=True)
        return
    if call.data.startswith("naknew_"):
        # 🆕 Shu qatorni Bito'da YANGI mahsulot qilib kiritish — "Chiroyli tahrirlash"
        # sahifasi aynan shu qatorga ochiladi (kategoriya / shtrix-kod / narx u yerda
        # kiritiladi), yuklash paytida esa mahsulot Bito'da yaratiladi.
        idx = int(call.data.replace("naknew_", ""))
        try:
            it = st["items"][idx]
            it["auto_create"] = True
            st["matches"][idx]["product_id"] = None
            import time as _time, secrets as _secrets
            token = _secrets.token_urlsafe(16)
            nak_webapp_store(uid, st["items"], token)
            url = (f"{_public_base_url()}/webapp/nakladnoy?uid={uid}&t={token}"
                   f"&v={int(_time.time()*1000)}&focus={idx}")
            mkw = types.InlineKeyboardMarkup()
            mkw.add(types.InlineKeyboardButton("📱 Chiroyli tahrirlash", web_app=types.WebAppInfo(url=url)))
            bot.send_message(chat_id,
                f"🆕 <b>{h(it.get('name','?'))}</b> yangi mahsulot sifatida belgilandi.\n"
                f"Sahifa shu qatorga ochiladi — <b>kategoriya</b>, kerak bo'lsa shtrix-kod va "
                f"sotuv narxini kiriting va saqlang. Mahsulot Bito'ga yuklash paytida yaratiladi.",
                parse_mode="HTML", reply_markup=mkw)
        except Exception as e:
            print("NAK NEW ROW ERR:", str(e)[:200], flush=True)
            bot.send_message(chat_id, f"⚠️ Ochib bo'lmadi: {str(e)[:150]}")
        return
    if call.data.startswith("nakskip_"):
        idx = int(call.data.replace("nakskip_", ""))
        bot.send_message(chat_id, f"⏭ {idx+1}-qator tashlab ketildi.")
        _nak_advance_fix(chat_id, st, idx)
        return
    # nakpick_<idx>_<candIdx>
    _, rest = call.data.split("nakpick_")
    i_s, j_s = rest.rsplit("_", 1)
    i, j = int(i_s), int(j_s)
    fixcands = st.get("fixcands", [])
    if j < len(fixcands):
        _nak_apply_pick(chat_id, st, i, fixcands[j])
    _nak_advance_fix(chat_id, st, i)

@bot.message_handler(func=lambda m: W_NAK.get(m.from_user.id, {}).get("step") == "fixsearch")
def nak_fixsearch_text(message):
    uid = message.from_user.id
    st = nak_session_restore(uid)
    if not st or message.text in MENU_TEXTS:
        return
    idx = st.get("fix_idx", 0)
    st["uid"] = uid
    q = (message.text or "").strip()
    found = _nak_search_products(q, limit=6)
    if not found:
        bot.send_message(message.chat.id, "📭 Hech narsa topilmadi — boshqa so'z bilan urinib ko'ring.")
        return
    # 🧠 So'nggi qidiruv so'zini eslab qolamiz — keyingi O'XSHASH qator uchun avtomatik
    # ishlatiladi (bir xil brendning bir nechta qatorini qayta-qayta yozmaslik uchun).
    st["last_fix_query"] = q
    if len(found) == 1:
        # ⚡️ Bitta natija — so'ramaymiz, o'zi tanlanadi.
        # Ammo hujjatdagi hajm topilgan mahsulot hajmiga MOS kelmasa — tasdiq so'raymiz.
        it_name = (st["items"][idx] or {}).get("name", "")
        s_doc = _nak_norm_size(_nak_size_token(it_name))
        s_found = _nak_norm_size(_nak_size_token(found[0].get("name", "")))
        if not (s_doc and s_found and s_doc != s_found):
            _nak_apply_pick(message.chat.id, st, idx, found[0])
            _nak_advance_fix(message.chat.id, st, idx)
            return
        _nak_send_candidates(message.chat.id, st, idx, found,
                             f"⚠️ Hajmi mos kelmayapti (hujjatda <b>{h(_nak_size_token(it_name))}</b>) — tasdiqlang:")
        return
    _nak_send_candidates(message.chat.id, st, idx, found, "Qaysi biri to'g'ri?")

@bot.message_handler(func=lambda m: W_NAK.get(m.from_user.id, {}).get("step") in ("edit", "add"))
def nak_text_edit(message):
    uid = message.from_user.id
    st = nak_session_restore(uid)
    if not st or message.text in MENU_TEXTS:
        nak_session_clear(uid); return
    parts = [p.strip() for p in message.text.split("|")]
    try:
        if st["step"] == "edit":
            idx = int(parts[0]) - 1
            if idx < 0 or idx >= len(st["items"]):
                bot.send_message(uid, "❌ Bunday qator yo'q."); return
            if len(parts) >= 2 and parts[1].lower() in ("ochir", "o'chir", "delete"):
                st["items"].pop(idx)
            else:
                st["items"][idx] = {"name": parts[1], "qty": float(parts[2].replace(",", ".")),
                                     "price": float(parts[3].replace(",", ".").replace(" ", ""))}
        else:  # add
            st["items"].append({"name": parts[0], "qty": float(parts[1].replace(",", ".")),
                                 "price": float(parts[2].replace(",", ".").replace(" ", ""))})
        st["step"] = "review"
        send_long_message(message.chat.id, _nak_review_text(st), parse_mode="HTML")
        _nak_start_match(uid, message.chat.id, st)
    except Exception:
        bot.send_message(uid, "❌ Format xato. Namuna: <code>3 | Nom | 24 | 12000</code>", parse_mode="HTML")

# ══════════════════════════════════════════════════════════════════
# 🆕 BITO'DA YANGI MAHSULOT YARATISH — nakladnoyda bor, lekin Bito katalogida
# hali yo'q mahsulotlar uchun (shtrix-kod bilan). Bito'da bu endpointning aniq
# manzili hujjatlashtirilmagan — bir nechta ehtimoliy manzil sinaladi.
# ══════════════════════════════════════════════════════════════════
# [tenant] CFG.NAK_DEFAULT_UOM_ID = "693fea08ff2118868c955d27"  # "Dona" — standart o'lchov birligi
# [tenant] CFG.NAK_DEFAULT_BOX_TYPE_ID = "69427e1ff461a9f6fd765b30"  # "Blok" — Bito'da tasdiqlangan (bito_box_type_get_all)

# 🔢 SKU (mahsulot raqami) — Bito'da ketma-ket boradi va BO'SH BO'LISHI MUMKIN EMAS
# (aks holda: {"code":10001,"data":"sku"}). Bito o'z ilovasida uni avtomatik beradi,
# lekin API orqali yaratganda biz o'zimiz hisoblab yuborishimiz kerak.
NAK_SKU_STATE = TDict(template={"next": None})

def _fetch_max_bito_sku():
    """Bito'dagi eng katta raqamli SKU'ni qaytaradi (topilmasa None).
    `sort=-sku` bilan yuqoridagi bir nechtasini olib, ular orasidan eng kattasini
    tanlaymiz — SKU matn sifatida saqlangani uchun saralash ba'zan harf tartibida
    bo'lishi mumkin, shuning uchun bittasiga emas, bir nechtasiga qaraymiz."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    best = 0
    try:
        r = requests.post(BITO_BASE_URL + "product/get-paging",
                         json={"page": 1, "limit": 30, "sort": "-sku"},
                         headers=headers, timeout=20)
        if r.status_code == 200:
            d = (r.json().get("data") or {})
            items = d.get("data") if isinstance(d, dict) else d
            for p in (items or []):
                s = str((p or {}).get("sku") or "").strip()
                if s.isdigit():
                    best = max(best, int(s))
    except Exception as e:
        print("NAK SKU FETCH ERR:", str(e)[:150], flush=True)
    return best or None

def _next_bito_sku(force_refresh=False):
    """Keyingi bo'sh SKU raqamini qaytaradi (matn ko'rinishida).
    Ketma-ket yaratishda har chaqiruvda bittaga oshib boradi, shuning uchun
    42 ta mahsulot yaratilganda 28047, 28048, 28049 ... bo'lib ketadi."""
    if force_refresh or NAK_SKU_STATE["next"] is None:
        mx = _fetch_max_bito_sku()
        if not mx:
            return None
        NAK_SKU_STATE["next"] = mx + 1
        print(f"NAK SKU: Bito'dagi eng katta SKU {mx}, keyingisi {mx+1} dan boshlanadi", flush=True)
    v = NAK_SKU_STATE["next"]
    NAK_SKU_STATE["next"] = v + 1
    return str(v)

def _bito_error_field(resp_text):
    """Bito xatosidan AYBDOR MAYDON nomini ajratib oladi.
    Bito 10001 ("Iltimos, to'ldirilgan ma'lumotlarga e'tibor bering") xatosida
    qaysi maydon muammoli ekanini "data" maydonida qaytaradi. Masalan:
      {"code":10001,"message":"...","data":"page"}  → "page"
    Javob ba'zan {"status":400,"upstream":{...}} ichida bo'ladi — ikkalasini ham qaraymiz."""
    import json as _json
    try:
        j = _json.loads(resp_text)
    except Exception:
        return None
    for node in (j, (j or {}).get("upstream") or {}):
        if isinstance(node, dict):
            d = node.get("data")
            if isinstance(d, str) and d:
                return d
            if isinstance(d, list) and d and isinstance(d[0], str):
                return ", ".join(d[:5])
    return None

def _bito_error_code(resp_text):
    """Bito javobidan xato KODINI ajratib oladi (int), topilmasa None.
    Muhim kodlar: 10001 — maydon yetishmayapti, 26018 — shtrix kod boshqa
    mahsulotda band. Javob ba'zan {"status":400,"upstream":{...}} ichida
    keladi, shuning uchun ikkala qavatga ham qaraymiz."""
    import json as _json
    try:
        j = _json.loads(resp_text)
    except Exception:
        return None
    for node in (j, (j or {}).get("upstream") or {}):
        if isinstance(node, dict):
            c = node.get("code")
            if isinstance(c, int):
                return c
    return None


def _bito_barcode_owner(resp_text):
    """26018 xatosidan shtrix-kodni EGALLAB turgan mahsulot nomini oladi.
    Bito xabari: "<NOM> mahsulotda <SHTRIX> shtrix kod allaqachon mavjud".
    Qaytaradi (nom, shtrix) yoki None."""
    import json as _json
    import re as _re
    try:
        j = _json.loads(resp_text)
    except Exception:
        return None
    msg = ""
    for node in (j, (j or {}).get("upstream") or {}):
        if isinstance(node, dict):
            m = ((node.get("messages") or {}).get("uz") if isinstance(node.get("messages"), dict) else "") \
                or node.get("message") or ""
            if m:
                msg = str(m)
                break
    mm = _re.search(r"^(.*?)\s+mahsulotda\s+(\S+)\s+shtrix", msg)
    if mm:
        return mm.group(1).strip(), mm.group(2).strip()
    return None


def find_bito_product_by_barcode(barcode):
    """Shtrix-kod bo'yicha Bito'dagi MAVJUD mahsulotni qidiradi.
    Topilsa (product_id, nom), aks holda None.

    ⚠️ Jonli tekshirilgan cheklovlar (docs.bito.uz + MCP):
      • `product/get-by-barcode` uchta joyga qaraydi — asosiy `barcode`,
        `barcodes[]` va `measure_ratios[]` — LEKIN ustiga
        `organizations.is_available = true` sharti qo'yiladi, ya'ni
        tashkilotda o'chirib qo'yilgan mahsulot TOPILMAYDI.
      • `product/get-paging?search=` esa faqat nom + sku + asosiy shtrix-kodni
        qidiradi, `barcodes[]` va `measure_ratios[]` ni ko'rmaydi.
      • Blok shtrix-kodi (`box_item_barcode`) HECH QAYSI qidiruvga tushmaydi,
        lekin mahsulot yaratishda BAND hisoblanadi.
    Shu sababli bu funksiya "topilmadi" desa ham, Bito 26018 ("shtrix kod
    allaqachon mavjud") qaytarishi mumkin — o'sha holat alohida ishlanadi."""
    bc = (barcode or "").strip()
    if not bc:
        return None
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.post(BITO_BASE_URL + "product/get-by-barcode",
                          json={"barcode": bc, "organization_id": CFG.BITO_ORG_ID},
                          headers=headers, timeout=20)
        if r.status_code == 200:
            d = (r.json() or {}).get("data") or {}
            if isinstance(d, list):
                d = d[0] if d else {}
            pid = d.get("_id") or d.get("id")
            if pid:
                return pid, (d.get("name") or "")
    except Exception as e:
        print("NAK BARCODE LOOKUP ERR:", str(e)[:150], flush=True)
    try:
        r = requests.post(BITO_BASE_URL + "product/get-paging",
                          json={"page": 1, "limit": 5, "search": bc},
                          headers=headers, timeout=20)
        if r.status_code == 200:
            d = (r.json() or {}).get("data") or {}
            items = d.get("data") if isinstance(d, dict) else d
            for p in (items or []):
                if not isinstance(p, dict):
                    continue
                cand = [str(p.get("barcode") or "")]
                cand += [str((b or {}).get("barcode") or "") for b in (p.get("barcodes") or [])]
                cand += [str((b or {}).get("barcode") or "") for b in (p.get("measure_ratios") or [])]
                cand.append(str(p.get("box_item_barcode") or ""))
                if bc in cand:
                    pid = p.get("_id") or p.get("id")
                    if pid:
                        return pid, (p.get("name") or "")
    except Exception as e:
        print("NAK BARCODE SEARCH ERR:", str(e)[:150], flush=True)
    return None


def create_bito_product(name, barcode=None, category_id=None, diag=None, measure_id=None):
    """Bito'da yangi mahsulot yaratadi (shtrix-kod bilan, agar berilgan bo'lsa).
    category_id berilmasa — sozlamalardagi standart kategoriya ishlatiladi.
    diag — dict berilsa, sinab ko'rilgan HAR BIR manzil va uning javobi shunga yoziladi
    (404 = manzil yo'q; 400/422 = manzil BOR, lekin so'rov tarkibi noto'g'ri — bu juda
    muhim farq, chunki avval oxirgi xato boshqalarini yashirib qo'yardi).
    Muvaffaqiyatli bo'lsa (True, product_id), aks holda (False, xato_matni)."""
    if not category_id:
        category_id = get_setting("bito_new_product_category_id", "")
    if not category_id:
        return False, ("Kategoriya tanlanmagan. \"Chiroyli tahrirlash\"da kategoriya kiriting, "
                        "yoki ⚙️ Sozlamalar → 🆕 Yangi mahsulot kategoriyasi orqali standartini belgilang.")
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    # 🔎 AVVAL QIDIRAMIZ, keyin yaratamiz. Shtrix-kod allaqachon Bito'dagi biror
    # mahsulotga tegishli bo'lsa — dublikat yaratish o'rniga O'SHANI ishlatamiz
    # (aks holda Bito 26018 bilan rad etadi va qator xaridga umuman kirmaydi).
    if (barcode or "").strip():
        found = find_bito_product_by_barcode(barcode)
        if found:
            pid, fname = found
            print(f"NAK PRODUCT: '{name}' uchun shtrix {barcode} → mavjud mahsulot '{fname}' ({pid}) ishlatildi", flush=True)
            if diag is not None:
                diag["reused"] = fname or name
            return True, pid
    # 🔢 SKU bo'sh bo'lsa Bito rad etadi ({"code":10001,"data":"sku"}) — Bito'dagi
    # eng katta SKU'ni topib, ketma-ket keyingi raqamni beramiz.
    sku = _next_bito_sku()
    if not sku:
        return False, ("SKU raqamini aniqlab bo'lmadi (Bito'dan mahsulotlar ro'yxati "
                        "olinmadi). Biroz kutib qayta urinib ko'ring.")
    body = {
        "name": name,
        "category_id": category_id,
        # 📏 Foydalanuvchi "Chiroyli tahrirlash"da tanlagan o'lchov birligi;
        # tanlanmagan bo'lsa — standart "Dona"
        "measure_id": measure_id or CFG.NAK_DEFAULT_UOM_ID,
        "note": "",
        "box_item": 0,
        "sku": sku,
        "barcode": barcode or "",
        "supplier_ids": [],
        "is_compound": False,
        "materials": [],
        "barcodes": [{"is_active": True, "barcode": barcode}] if barcode else [],
        # 👇 Bito'dagi MAVJUD mahsulot tuzilishidan olingan maydonlar (bito_product_get_paging
        # orqali tekshirilgan). Mahsulot turi va qaysi tashkilotga tegishliligi
        # ko'rsatilmasa, Bito "to'ldirilgan ma'lumotlarga e'tibor bering" deb rad etadi.
        # ⚠️ "box_type_id" ataylab YUBORILMAYDI — haqiqiy mahsulotlarda u null.
        "is_product": True,
        "is_material": False,
        "is_semi_product": False,
        # ⚠️ "organizations" ichidagi maydonlar ham TO'LIQ bo'lishi kerak — Bito faqat
        # "organization_id" yuborilsa, "is_available" yo'qligidan shikoyat qiladi.
        # Quyidagi tuzilma Bito'dagi MAVJUD mahsulotdan (bito_product_get_paging) olingan.
        "organizations": [{
            "organization_id": CFG.BITO_ORG_ID,
            "is_available": True,            # omborda hisobga olinsinmi
            "is_available_for_sale": True,   # sotuvga chiqsinmi
            "amount": 0,                     # boshlang'ich qoldiq (xarid keyin qo'shadi)
            "in_transit": 0,
            "trash": 0,
            "booked": 0,
            "yellow_line": 0,                # ogohlantirish chegarasi
            "red_line": 0,                   # kritik chegara
            "max_stock": 0,
            "standard": 0,                   # standart zaxira
        }],
        # 👇 Bito bir vaqtning o'zida BITTA yetishmayotgan maydon haqida shikoyat qiladi
        # (avval "sku", keyin "is_available"). Har safar deploy qilib sinamaslik uchun,
        # haqiqiy mahsulotda mavjud bo'lgan qolgan maydonlarni ham xavfsiz bo'sh
        # qiymatlar bilan oldindan yuboramiz.
        "is_marked": False,
        "tax_ids": [],
        "discount_ids": [],
        "attributes": [],
        "images": [],
        "custom_fields": [],
        "measure_ratios": [],
        "dimension": {
            "shape": "other", "netto_weight": 0, "gross_weight": 0,
            "height": 0, "volume": 0, "diameter": 0, "width": 0, "length": 0,
        },
    }
    # 📍 Bito'ning YAGONA to'g'ri manzili — "product/create" (docs.bito.uz Swagger'da
    # tasdiqlangan). Ilgari 5 ta zaxira nom ham sinalardi; ular doim 404 qaytarib,
    # foydalanuvchiga "hammasi 404" degan chalg'ituvchi ro'yxat ko'rsatar va HAQIQIY
    # sababni (masalan "shtrix kod band") ko'zdan yashirar edi.
    path = "product/create"

    def _try_create(b):
        return requests.post(BITO_BASE_URL + path, json=b, headers=headers, timeout=20)

    def _pid_of(resp):
        try:
            jj = resp.json()
        except Exception:
            return None
        dd = jj.get("data", jj) if isinstance(jj, dict) else {}
        if not isinstance(dd, dict):
            return None
        return dd.get("_id") or dd.get("id")

    try:
        r = _try_create(body)

        # 🔁 SKU band/noto'g'ri bo'lsa (masalan boshqa xodim ayni paytda mahsulot
        # yaratgan bo'lsa) — BIR marta qayta uramiz. Yangi raqam har doim
        # muvaffaqiyatsiz bo'lganidan KATTA bo'lishi kafolatlanadi, aks holda
        # server o'sha raqamni qaytarib, bir joyda aylanib qolish mumkin edi.
        if r.status_code == 400 and _bito_error_field(r.text or "") == "sku":
            _next_bito_sku(force_refresh=True)  # server bilan sinxronlash
            try:
                failed_n = int(body.get("sku") or 0)
                if NAK_SKU_STATE["next"] is None or NAK_SKU_STATE["next"] <= failed_n:
                    NAK_SKU_STATE["next"] = failed_n + 1
            except Exception:
                pass
            new_sku = _next_bito_sku()
            if new_sku and new_sku != body.get("sku"):
                body["sku"] = new_sku
                print(f"NAK SKU: band ekan, {new_sku} bilan qayta urinilmoqda", flush=True)
                r = _try_create(body)

        # 🏷 26018 — shtrix kod BOSHQA mahsulotda band. Bu ko'pincha o'sha kodni
        # boshqa kartochkaning BLOK shtrix-kodi (`box_item_barcode`) sifatida
        # kiritib qo'yilganidan kelib chiqadi — u holda kodni hech qaysi qidiruv
        # endpointi topa olmaydi, shuning uchun oldindan tekshirish yetarli emas.
        # Nakladnoy to'xtab qolmasligi uchun mahsulotni SHTRIX-KODSIZ yaratamiz va
        # egasining nomini foydalanuvchiga aniq aytamiz.
        if r.status_code not in (200, 201) and _bito_error_code(r.text or "") == 26018:
            owner = _bito_barcode_owner(r.text or "")
            owner_name = owner[0] if owner else ""
            body2 = dict(body)
            body2["barcode"] = ""
            body2["barcodes"] = []
            r2 = _try_create(body2)
            pid2 = _pid_of(r2) if r2.status_code in (200, 201) else None
            if pid2:
                warn = (f"shtrix kod {barcode} «{owner_name or 'boshqa mahsulot'}» kartochkasida band "
                        f"(ehtimol blok shtrix-kodi sifatida) — mahsulot SHTRIX-KODSIZ yaratildi, "
                        f"Bito'da tekshirib qo'ying")
                print(f"NAK PRODUCT CREATE: '{name}' — {warn}", flush=True)
                if diag is not None:
                    diag["warning"] = warn
                return True, pid2
            return False, (f"shtrix kod {barcode} «{owner_name or 'boshqa mahsulot'}» da band; "
                           f"shtrix-kodsiz yaratishga urinish ham bo'lmadi: "
                           f"HTTP {r2.status_code} {(r2.text or '')[:150]}")

        if r.status_code not in (200, 201):
            txt = (r.text or "")[:400]
            print(f"NAK PRODUCT CREATE: HTTP {r.status_code} {txt[:150]}", flush=True)
            if diag is not None:
                diag["attempts"] = [(path, r.status_code, txt)]
            field = _bito_error_field(txt)
            if field:
                return False, f"HTTP {r.status_code}: Bito «{field}» maydonini talab qilyapti. {txt[:200]}"
            return False, f"HTTP {r.status_code}: {txt[:250]}"

        pid = _pid_of(r)
        if not pid:
            return False, f"Bito javobida ID yo'q: {(r.text or '')[:200]}"
        print(f"NAK PRODUCT CREATE: '{name}' yaratildi, id={pid}", flush=True)
        return True, pid
    except Exception as e:
        print(f"NAK PRODUCT CREATE EXC: {str(e)[:200]}", flush=True)
        if diag is not None:
            diag["attempts"] = [(path, "EXC", str(e)[:200])]
        return False, f"so'rov yuborilmadi: {str(e)[:200]}"

def _find_recent_bito_purchase(supplier_id, expected_total, upload_tag=None, max_age_sec=1200):
    """504 / timeout dan keyin xarid Bito'da HAQIQATAN yaratilganini tekshiradi.
    Bito javob bermay qolsa ham, xaridni serverda yaratib ulgurgan bo'lishi mumkin —
    shunday holatda foydalanuvchi qayta yuklab, DUBLIKAT yaratib qo'ymasligi uchun
    so'nggi xaridlar ro'yxatidan mos keladiganini qidiramiz.

    ⚠️ Ikkita muhim ehtiyot chorasi (amalda sinovdan chiqqan):
      1) BEKOR QILINGAN (state=canceled) va o'chirilgan xaridlar HISOBGA OLINMAYDI —
         ular ro'yxatda qolaveradi va summasi bir xil bo'lgani uchun eski, bekor
         qilingan xaridni "yaratildi" deb ko'rsatib yuborishi mumkin edi.
      2) Har bir yuklashga BETAKROR belgi (upload_tag) beriladi va u xarid izohiga
         yoziladi — shunda AYNAN SHU yuklash aniqlanadi, avval yuklanib bekor
         qilingan bir xil nakladnoy bilan chalkashmaydi.
    Topilsa dict(number, total_cost), aks holda None."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        r = requests.post(BITO_BASE_URL + "purchase/get-paging",
                         json={"page": 1, "limit": 20, "sort": "-created_at"},
                         headers=headers, timeout=25)
        if r.status_code != 200:
            return None
        d = (r.json().get("data", {}) or {})
        items = d.get("data", []) if isinstance(d, dict) else (d if isinstance(d, list) else [])
        now_utc = datetime.now(timezone.utc)
        for p in items:
            if not isinstance(p, dict):
                continue
            # 1) bekor qilingan / o'chirilganlarni butunlay chetlab o'tamiz
            if str(p.get("state", "")).lower() in ("canceled", "cancelled", "deleted", "rejected"):
                continue
            if p.get("is_deleted"):
                continue
            # 2) betakror belgi bo'lsa — AYNAN shu bo'yicha aniqlaymiz
            if upload_tag:
                if upload_tag in str(p.get("note") or ""):
                    return {"number": p.get("number") or "?", "total_cost": p.get("total_cost") or 0}
                continue  # belgi bor-u mos kelmadi → bu boshqa xarid
            # 3) belgi yo'q (eski yuklash) — firma + summa + vaqt bo'yicha taxminiy moslik
            if supplier_id and p.get("supplier_id") != supplier_id:
                continue
            tc = p.get("total_cost") or 0
            if expected_total and abs(tc - expected_total) > max(2.0, expected_total * 0.002):
                continue
            ca = p.get("created_at") or ""
            try:
                created = datetime.fromisoformat(ca.replace("Z", "+00:00"))
                if (now_utc - created).total_seconds() > max_age_sec:
                    continue
            except Exception:
                pass
            return {"number": p.get("number") or "?", "total_cost": tc}
        return None
    except Exception as e:
        print("NAK VERIFY ERR:", str(e)[:150], flush=True)
        return None

# 📦 Bitta so'rovda nechta mahsulot yuborilsin. Bito'ning nginx'i katta so'rovni
# ~60 soniyada uzib yuboradi (504), shuning uchun katta nakladnoy partiyalarga bo'linadi.
NAK_BATCH_SIZE = 50

def create_bito_purchase(st, progress_cb=None):
    """Bito'ga xarid (purchase) yaratadi — docs.bito.uz'dagi RASMIY sxema bo'yicha:
    organization_id, state, date, income_date, supplier_id, responsible_id,
    warehouse_id, currency_id, is_auto_income, orders[].products[].
    ⚠️ Shtrix-kod bilan belgilangan, lekin Bito'da mos topilmagan qatorlar uchun
    AVVAL yangi mahsulot yaratiladi, so'ng xaridga qo'shiladi."""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    matches = [m for m in st.get("matches", []) if m.get("product_id")]

    # 🆕 Shtrix-kodi kiritilgan, lekin hali Bito'da topilmagan qatorlar — avval yaratamiz
    new_product_results = []  # (nom, ok, natija_yoki_xato)
    new_price_results = []    # (nom, ok, xato) — yangi mahsulotga narx o'rnatish natijasi
    new_product_notes = []    # 🔗 qayta ishlatilgan / ⚠️ shtrix-kodsiz yaratilgan qatorlar
    for m in st.get("matches", []):
        if m.get("product_id"):
            continue
        item = m.get("item", {}) or {}
        barcode = item.get("barcode", "").strip()
        name = item.get("name", "").strip()
        item_category_id = item.get("category_id", "").strip()
        # 🆕 Yaratish sharti: nom bo'lsa VA (shtrix-kod kiritilgan BO'LSA yoki
        # foydalanuvchi "topilmaganlarni yaratish" tugmasi orqali ruxsat bergan bo'lsa).
        # Shtrix-kod majburiy emas — Bito'da usiz ham mahsulot yaratsa bo'ladi.
        if name and (barcode or item.get("auto_create")):
            _diag = {}
            ok, result = create_bito_product(name, barcode, category_id=item_category_id or None,
                                             diag=_diag,
                                             measure_id=(item.get("measure_id") or "").strip() or None)
            if ok and _diag.get("reused"):
                # Yangi yaratilmadi — shtrix-kod bo'yicha MAVJUD kartochka topildi
                new_product_notes.append(f"🔗 {name} → mavjud «{_diag['reused']}» ishlatildi")
            elif ok and _diag.get("warning"):
                new_product_notes.append(f"⚠️ {name}: {_diag['warning']}")
            if ok:
                m["product_id"] = result
                m["found_name"] = name
                matches.append(m)
                nak_save_alias(name, result, name)
                new_product_results.append((name, True, result))
                # 🏷 Foydalanuvchi tahrirlashda sotuv narxini kiritgan bo'lsa — mahsulot
                # endigina yaratilgani uchun narxni AYNAN SHU YERDA o'rnatamiz.
                pending = item.get("pending_sale_price")
                if pending:
                    p_ok, p_err = update_bito_sale_price(None, result, float(pending))
                    if p_ok:
                        # Endi Bito'da tasdiqlangan — qayta yuborilmasin
                        item["sale_price_saved"] = float(pending)
                        item["pending_sale_price"] = None
                    new_price_results.append((name, p_ok, p_err if not p_ok else f"{float(pending):,.0f}"))
            else:
                new_product_results.append((name, False, result))

    if not matches:
        return False, "Yuklanadigan mahsulot yo'q (hech biri katalogda topilmadi va shtrix-kod ham kiritilmagan)."
    supplier_id = st.get("supplier_id")
    if not supplier_id:
        return False, "Firma tasdiqlanmagan. /nakladnoy bilan qayta boshlang."

    # ⚠️ Bito'da mos topilmagan (va shtrix-kod ham kiritilmagan) qatorlar xaridga
    # KIRMAYDI. Foydalanuvchi "nega hammasi yuklanmadi?" deb hayron qolmasligi uchun
    # ularning sonini va nomlarini aniq ko'rsatamiz.
    skipped = [(m.get("item", {}) or {}).get("name", "?")
               for m in st.get("matches", []) if not m.get("product_id")]
    skipped_note = ""
    if skipped:
        preview = "; ".join(skipped[:12])
        more = f" va yana {len(skipped)-12} ta" if len(skipped) > 12 else ""
        skipped_note = (f"\n\n⚠️ <b>{len(skipped)} ta mahsulot yuklanmadi</b> — ular Bito katalogida "
                        f"topilmadi va shtrix-kod ham kiritilmagan:\n{preview}{more}."
                        f"\n💡 Ularni yuklash uchun: nakladnoyni qayta yuboring va "
                        f"\"🔍 qo'lda qidirish\" orqali moslang, yoki \"📱 Chiroyli tahrirlash\"da "
                        f"shtrix-kod + kategoriya kiriting — shunda Bito'da yangi mahsulot yaratiladi.")

    # 🧊 "qty" — blok soni, "price" — 1 DONANING narxi (hujjatda shunday yozilgan).
    # Bito'ga YAKUNIY DONA SONI (amount) va DONA narxi (cost) kerak:
    #   amount = qty × block_size (necha dona)
    #   cost   = price (o'zgarishsiz — bu allaqachon 1 donaning narxi)
    products = [{"product_id": m["product_id"],
                 "amount": m["item"]["qty"] * (m["item"].get("block_size", 1) or 1),
                 "cost": m["item"]["price"]} for m in matches]
    total = sum(p["amount"] * p["cost"] for p in products)

    # Yangi mahsulot / narx natijalari haqidagi izoh (barcha partiyalar uchun umumiy)
    note = ""
    if new_product_results:
        ok_new = [n for n, ok, _ in new_product_results if ok]
        fail_new = [(n, e) for n, ok, e in new_product_results if not ok]
        if ok_new:
            note += f"\n🆕 Bito'da yangi yaratildi: {', '.join(ok_new)}."
        if fail_new:
            note += "\n⚠️ Yaratib bo'lmadi (xaridga kiritilmadi): " + "; ".join(f"{n} ({e[:60]})" for n, e in fail_new)
    if new_product_notes:
        note += "\n" + "\n".join(new_product_notes)
    if new_price_results:
        ok_p = [f"{n} → {info} so'm" for n, ok, info in new_price_results if ok]
        fail_p = [(n, info) for n, ok, info in new_price_results if not ok]
        if ok_p:
            note += "\n🏷 Yangi mahsulotlarga sotuv narxi o'rnatildi: " + "; ".join(ok_p) + "."
        if fail_p:
            note += "\n⚠️ Sotuv narxini o'rnatib bo'lmadi: " + "; ".join(f"{n} ({e[:60]})" for n, e in fail_p)

    # 📦 PARTIYALAB YUBORISH: Bito'ning nginx'i katta so'rovni ~60 soniyada uzib yuboradi
    # (504 Gateway Time-out). Shuning uchun mahsulotlarni NAK_BATCH_SIZE tadan bo'lib,
    # har birini alohida xarid qilib yuboramiz — har bir so'rov tez tugaydi, 504 chiqmaydi.
    # ⚠️ Natijada Bito'da bitta emas, bir nechta xarid hujjati paydo bo'ladi.
    # Bito xatosidagi mahsulot ID'sini NOMGA aylantirish uchun lug'at
    id2name = {m["product_id"]: (m.get("found_name") or (m.get("item") or {}).get("name") or "?")
               for m in matches}
    batches = [products[i:i + NAK_BATCH_SIZE] for i in range(0, len(products), NAK_BATCH_SIZE)]
    n_batches = len(batches)
    results = []  # (partiya raqami, ok, xarid_raqami_yoki_xato, mahsulot soni, summa)
    for bi, chunk in enumerate(batches, 1):
        if progress_cb:
            try: progress_cb(bi, n_batches)
            except Exception: pass
        chunk_total = sum(pr["amount"] * pr["cost"] for pr in chunk)
        ok, info = _send_one_purchase(headers, supplier_id, chunk, chunk_total, bi, n_batches,
                                       id2name=id2name)
        results.append((bi, ok, info, len(chunk), chunk_total))
        if bi < n_batches:
            time.sleep(1)  # Bito'ni bo'g'ib qo'ymaslik uchun kichik tanaffus

    ok_rows   = [r for r in results if r[1]]
    fail_rows = [r for r in results if not r[1]]
    ok_total  = sum(r[4] for r in ok_rows)
    ok_count  = sum(r[3] for r in ok_rows)

    if n_batches == 1:
        head = (f"Xarid raqami: {ok_rows[0][2]}. Jami: {total:,.0f} so'm, {len(products)} ta mahsulot."
                if ok_rows else "")
    else:
        nums = ", ".join(str(r[2]) for r in ok_rows)
        head = (f"{n_batches} ta partiyaga bo'lib yuborildi.\n"
                f"✅ Yaratilgan xaridlar: {nums}\n"
                f"Jami: {ok_total:,.0f} so'm, {ok_count} ta mahsulot.")
    if fail_rows:
        det = "\n".join(f"• {r[0]}-partiya ({r[3]} ta mahsulot): {str(r[2])[:120]}" for r in fail_rows)
        fail_note = (f"\n\n⚠️ <b>{len(fail_rows)} ta partiya yuklanmadi</b> "
                     f"({sum(r[3] for r in fail_rows)} ta mahsulot):\n{det}"
                     f"\n💡 Faqat shu partiyalarni qayta yuklash uchun nakladnoyni qayta yuboring.")
    else:
        fail_note = ""

    if not ok_rows:
        return False, f"Hech bir partiya yuklanmadi.{fail_note}{note}"
    return True, f"{head}{fail_note}{skipped_note}{note}"

def _send_one_purchase(headers, supplier_id, products, total, batch_no=1, n_batches=1, id2name=None):
    """Bitta xarid (yoki bitta partiya) yaratadi. Qaytaradi: (ok, xarid_raqami | xato_matni).
    504/timeout bo'lsa — betakror belgi orqali HAQIQATAN yaratilganini tekshiradi."""
    import secrets as _secrets
    upload_tag = "bot-" + _secrets.token_hex(4)
    suffix = f" ({batch_no}/{n_batches})" if n_batches > 1 else ""
    body = {
        "organization_id": CFG.BITO_ORG_ID,
        "state": "new",
        "date": today_str(),
        "income_date": today_str(),
        "supplier_id": supplier_id,
        "responsible_id": tenant_setting("bito_responsible_id", "693fe9caff2118868c9554b1"),
        "warehouse_id": tenant_setting("bito_warehouse_id", "69424f36a3a3cc43da908320"),
        "currency_id": tenant_setting("bito_currency_id", "69424f34f461a9f6fd61972d"),
        # 🔖 Betakror belgi: 504 dan keyin AYNAN shu yuklashni aniqlash uchun
        # (bir xil nakladnoy avval yuklanib bekor qilingan bo'lsa ham chalkashmaydi)
        "note": f"Telegram bot orqali nakladnoydan yuklandi{suffix} [{upload_tag}]",
        "is_auto_income": True,
        "additional_costs": [],
        "orders": [{"products": products}],
    }
    try:
        dynamic_timeout = max(60, 30 + (len(products) // 50) * 30)
        r = requests.post(BITO_BASE_URL + "purchase/create", json=body, headers=headers, timeout=dynamic_timeout)
        print(f"NAK UPLOAD [{batch_no}/{n_batches}]: HTTP {r.status_code} | {r.text[:300]}", flush=True)
        if r.status_code == 200:
            j = r.json()
            d = j.get("data", {}) if isinstance(j.get("data"), dict) else {}
            return True, (d.get("number") or d.get("code") or "?")
        # ⚠️ 502/504 — Bito'ning nginx'i javobni kutmay uzdi. Bu so'rov YETMAGANini
        # bildirmaydi: xarid serverda YARATILGAN bo'lishi mumkin. Avtomatik qayta
        # yubormaymiz, balki HAQIQATAN yaratilganini tekshiramiz.
        if r.status_code in (502, 503, 504):
            return _verify_after_timeout(supplier_id, total, upload_tag)
        # 🧹 26000 = "Ushbu tafsilotlarga ega mahsulot topilmadi" — ya'ni yuborilgan
        # product_id Bito'da yo'q (mahsulot o'chirilgan). Qaysi mahsulot ekanini aytamiz.
        bad_id = _bito_error_field(r.text or "")
        if bad_id and id2name and bad_id in id2name:
            return False, (f"«{id2name[bad_id]}» mahsuloti Bito'da topilmadi (o'chirilgan bo'lishi "
                            f"mumkin). Nakladnoyni qayta yuboring — bot uni avtomatik qaytadan "
                            f"moslashtiradi.")
        return False, f"HTTP {r.status_code}: {r.text[:150]}"
    except requests.exceptions.Timeout:
        print(f"NAK UPLOAD TIMEOUT [{batch_no}/{n_batches}]", flush=True)
        return _verify_after_timeout(supplier_id, total, upload_tag)
    except Exception as e:
        print("NAK UPLOAD ERR:", str(e)[:200], flush=True)
        return False, str(e)[:150]

def _verify_after_timeout(supplier_id, total, upload_tag):
    """Bito javob bermay qolganda — xarid baribir yaratilganmi, tekshiramiz."""
    time.sleep(8)  # Bito yozib tugatishiga ulgursin
    found = _find_recent_bito_purchase(supplier_id, total, upload_tag=upload_tag)
    if found:
        return True, found["number"]
    return False, ("504 Gateway Time-out — tekshirdim, xarid yaratilmagan")


@bot.message_handler(commands=['ai'])
def ai_text_cmd(message):
    """Yozma savol: /ai <savol> — xuddi ovozli agent kabi ishlaydi."""
    tg_id = message.from_user.id
    u = get_user(tg_id)
    if not u or u[2] in ('pending', 'rejected'): return
    parts = message.text.split(maxsplit=1)
    if len(parts) < 2:
        bot.send_message(message.chat.id, "Foydalanish: `/ai savolingiz`\nMasalan: `/ai xodimlarga bugun qanday vazifa beray?`", parse_mode="Markdown")
        return
    question = parts[1].strip()
    status = bot.send_message(message.chat.id, "🧠 O'ylanmoqda...")
    def run():
        try:
            answer = ai_agent_answer(tg_id, message.chat.id, question)
            try: bot.delete_message(message.chat.id, status.message_id)
            except Exception: pass
            send_long_message(message.chat.id, f"🤖 {answer}")
        except Exception as e:
            print("AI CMD ERR:", str(e)[:150], flush=True)
            bot.send_message(message.chat.id, f"⚠️ Xatolik: {str(e)[:80]}")
    threading.Thread(target=run, daemon=True).start()

@bot.message_handler(content_types=['voice'])
def voice_message_handler(message):
    tg_id = message.from_user.id
    u = get_user(tg_id)
    if not u or u[2] in ('pending', 'rejected'):
        return
    chat_id = message.chat.id
    status_msg = bot.send_message(chat_id, "🎧 Ovoz tinglanmoqda...")
    def run():
        try:
            f = bot.get_file(message.voice.file_id)
            audio = requests.get(
                f"https://api.telegram.org/file/bot{TOKEN}/{f.file_path}", timeout=30).content
            transcript, err = transcribe_audio(audio, "audio/ogg", "voice.ogg")
            if err:
                bot.edit_message_text(f"⚠️ {err}", chat_id, status_msg.message_id); return
            try:
                bot.edit_message_text(f"🎤 <i>\"{h(transcript)}\"</i>\n🧠 O'ylanmoqda...", chat_id, status_msg.message_id, parse_mode="HTML")
            except Exception:
                pass
            print(f"[VOICE] {tg_id}: '{transcript[:60]}' -> agent", flush=True)
            answer = ai_agent_answer(tg_id, chat_id, transcript)
            try:
                bot.edit_message_text(f"🎤 <i>\"{h(transcript)}\"</i>", chat_id, status_msg.message_id, parse_mode="HTML")
            except Exception:
                pass
            send_long_message(chat_id, f"🤖 {answer}")
        except Exception as e:
            print("VOICE ERR:", str(e)[:200], flush=True)
            try: bot.edit_message_text(f"⚠️ Ovozni qayta ishlashda xatolik: {str(e)[:80]}", chat_id, status_msg.message_id)
            except Exception: pass
    threading.Thread(target=run, daemon=True).start()
