@bot.message_handler(commands=['bitotest'])
def bitotest_cmd(message):
    if not is_boss_or_mgr(message.from_user.id):
        bot.send_message(message.chat.id, "⛔ Faqat boshliq/menejer uchun."); return
    parts = message.text.split()
    try:
        if len(parts) >= 3:
            d1 = datetime.strptime(parts[1], "%d.%m.%Y").strftime("%Y-%m-%d")
            d2 = datetime.strptime(parts[2], "%d.%m.%Y").strftime("%Y-%m-%d")
        else:
            d2 = today_str()
            d1 = (now_dt() - timedelta(days=2)).strftime("%Y-%m-%d")
    except Exception:
        bot.send_message(message.chat.id, "❌ Format: /bitotest 24.06.2026 26.06.2026"); return
    df, dt_ = bito_range_utc(d1, d2)
    bot.send_message(message.chat.id, f"⏳ Sinov: {d1} → {d2}\nUTC: {df} → {dt_}\nNatija Railway logida `BITO DEBUG:` qatorida ham chiqadi.")
    items = bito_sales_by_employee(df, dt_)
    if items is None:
        bot.send_message(message.chat.id, "⚠️ So'rovda xato (loglarga qarang).")
    elif not items:
        bot.send_message(message.chat.id, "📭 Bo'sh javob qaytdi (0 ta yozuv).")
    else:
        total = sum((it.get("gross_sales", 0) or 0) for it in items)
        names = ", ".join(_bito_emp_name(it) for it in items[:10])
        bot.send_message(message.chat.id, f"✅ {len(items)} ta yozuv qaytdi.\nJami gross_sales: {fmt_money(total)}\nIsmlar: {names}")

