@bot.message_handler(commands=['start'])
def start(message):
    tg_id = message.from_user.id
    W_REGISTER.pop(tg_id, None)
    W_ONBOARD.pop(tg_id, None)
    txt = message.text or ""
    _parts = txt.split(maxsplit=1)
    _payload = _parts[1].strip() if len(_parts) > 1 else ""

    # 🏢 Havola bilan kelgan bo'lsa — ko'p-ijarachi ro'yxatdan o'tish
    if _payload and onboarding_start(message, _payload):
        return
    # 🔒 Havolasiz va hech qaysi biznesga bog'lanmagan — kirish YOPIQ.
    # Bizneslar soni ahamiyatsiz. Ilgari bitta biznes bo'lganda begona odam
    # avtomatik "employee" qilib bog'lanardi va boshliqqa tasdiqlash so'rovi
    # ketardi — bu teshik edi: botni nomi bilan topgan HAR KIM so'rov
    # yubora olardi. Endi faqat taklif havolasi orqali kiriladi.
    if not _payload and CENTRAL.tenant_of_user(tg_id) is None:
        bot.send_message(tg_id,
                         "🔒 <b>Bu bot yopiq.</b>\n\n"
                         "Kirish faqat taklif havolasi orqali:\n\n"
                         "• <b>Xodim</b> bo'lsangiz — boshlig'ingizdan taklif "
                         "havolasini so'rang.\n"
                         "• <b>Biznes egasi</b> bo'lmoqchi bo'lsangiz — "
                         f"@{CENTRAL.ADMIN_BOT_USERNAME} ga murojaat qiling.",
                         parse_mode="HTML")
        return
    # /start har qanday yarim qolgan jarayonni to'xtatadi (ariza to'ldirish ham).
    # Aks holda /start ariza javobi sifatida saqlanib qolardi.
    if not txt.split(maxsplit=1)[1:] or not txt.split(maxsplit=1)[1].strip().startswith("job_"):
        W_APPLY.pop(tg_id, None)
    if CFG.REVIEW_SECRET in txt:
        _start_review(message); return
    # 🧑‍💼 Vakansiyaga ariza: /start job_<id>
    parts = txt.split(maxsplit=1)
    if len(parts) > 1 and parts[1].strip().startswith("job_"):
        try:
            job_id = int(parts[1].strip().replace("job_", ""))
            start_job_application(message, job_id)
            return
        except ValueError:
            pass
    u = get_user(tg_id)
    if u:
        role = u[2]
        if tg_id == CFG.SUPER_ADMIN_ID and role != 'boss':
            q("UPDATE users SET role='boss' WHERE tg_id=?", (tg_id,))
            bot.send_message(tg_id, f"👑 Xush kelibsiz, *{u[1]}*!\nSiz *Boshliq* sifatida tasdiqlandi.", parse_mode="Markdown", reply_markup=boss_kb()); return
        if role == 'pending':
            bot.send_message(tg_id, "⏳ So'rovingiz hali tasdiqlanmagan. Boshliq tasdiqlashini kuting."); return
        if role == 'rejected':
            bot.send_message(tg_id, "❌ Kirishingiz rad etildi."); return
        pos = f" | {u[3]}" if u[3] else ""
        bot.send_message(tg_id, f"👋 Xush kelibsiz, *{u[1]}*{pos}!", parse_mode="Markdown", reply_markup=get_kb(tg_id)); return
    if tg_id == CFG.SUPER_ADMIN_ID:
        W_REGISTER[tg_id] = 'boss'
        bot.send_message(tg_id, "👑 *Siz bosh admin!*\n\nIsm va familiyangizni yozing:", parse_mode="Markdown"); return
    W_REGISTER[tg_id] = 'user'
    bot.send_message(tg_id, "👋 Xush kelibsiz!\n\nIsm va familiyangizni yozing:")

@bot.message_handler(func=lambda m: m.from_user.id in W_REGISTER)
def handle_register(message):
    tg_id = message.from_user.id
    mode = W_REGISTER.get(tg_id)
    if not mode: return
    if message.text and message.text in MENU_TEXTS:
        W_REGISTER.pop(tg_id, None); return
    name = message.text.strip() if message.text else ""
    if len(name) < 2:
        bot.send_message(tg_id, "⚠️ Ism juda qisqa."); return
    W_REGISTER.pop(tg_id)
    if mode == 'boss':
        q("INSERT OR REPLACE INTO users (tg_id,full_name,role,approved_by,created_at) VALUES (?,?,'boss',?,?)", (tg_id,name,tg_id,now_str()))
        bot.send_message(tg_id, f"✅ Xush kelibsiz, *{name}*!\n👑 *Boshliq* sifatida kiritildingiz.", parse_mode="Markdown", reply_markup=boss_kb())
    else:
        q("INSERT OR IGNORE INTO users (tg_id,full_name,role,created_at) VALUES (?,?,'pending',?)", (tg_id,name,now_str()))
        bot.send_message(tg_id, f"✅ So'rovingiz yuborildi!\n👤 *{name}*\n\nBoshliq tasdiqlashini kuting.", parse_mode="Markdown")
        for (aid,) in qall("SELECT tg_id FROM users WHERE role IN ('boss','manager')"):
            markup = types.InlineKeyboardMarkup()
            markup.add(types.InlineKeyboardButton("✅ Hodim", callback_data=f"approve_employee_{tg_id}"),
                       types.InlineKeyboardButton("👔 Menejer", callback_data=f"approve_manager_{tg_id}"))
            markup.add(types.InlineKeyboardButton("👑 Boshliq", callback_data=f"approve_boss_{tg_id}"),
                       types.InlineKeyboardButton("❌ Rad", callback_data=f"approve_reject_{tg_id}"))
            try: bot.send_message(aid, f"🆕 *Yangi foydalanuvchi*\n\n👤 *{name}*\n🆔 `{tg_id}`\n\nRolni tanlang:", parse_mode="Markdown", reply_markup=markup)
            except: pass

@bot.callback_query_handler(func=lambda c: c.data.startswith("approve_"))
def approve_cb(call):
    if not is_boss_or_mgr(call.from_user.id): return
    parts = call.data.split("_"); action = parts[1]; target_id = int(parts[2])
    role_map = {"employee":"employee","manager":"manager","boss":"boss","reject":"rejected"}
    name_map = {"employee":"Hodim","manager":"Menejer","boss":"Boshliq","rejected":"Rad etildi"}
    new_role = role_map.get(action)
    if not new_role: return
    q("UPDATE users SET role=?,approved_by=? WHERE tg_id=?", (new_role,call.from_user.id,target_id))
    _ack(call, name_map[new_role]+" qilindi.")
    u = get_user(target_id)
    uname = u[1] if u else str(target_id)
    try:
        bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
        bot.edit_message_text(f"👤 *{uname}*\n\n✅ {name_map[new_role]} tasdiqlandi.", call.message.chat.id, call.message.message_id, parse_mode="Markdown")
    except: pass
    if new_role != 'rejected':
        try: bot.send_message(target_id, f"✅ *Kirishingiz tasdiqlandi!*\nRolingiz: *{name_map[new_role]}*", parse_mode="Markdown", reply_markup=get_kb(target_id))
        except: pass
    else:
        try: bot.send_message(target_id, "❌ Kirishingiz rad etildi.")
        except: pass

