def _save_rv2(uid, comment):
    s = W_REVIEW_V2.pop(uid, {}); emp_id=s.get('emp_id'); emp_name=s.get('emp_name','')
    svc=s.get('service',0); spd=s.get('speed',0); avg=round((svc+spd)/2,1)
    detail = f"Muomala:{svc}|Tezlik:{spd}" + (f"|Izoh:{comment}" if comment else "")
    q("INSERT INTO reviews (employee_tg_id,employee_name,rating,comment,created_at) VALUES (?,?,?,?,?)", (emp_id,emp_name,avg,detail,now_str()))
    pts = {5:3,4:2,3:1}.get(int(round(avg)),0)
    if pts: add_points(emp_id, emp_name, pts)
    r_avg, cnt = get_avg_rating(emp_id)
    for (aid,) in qall("SELECT tg_id FROM users WHERE role IN ('boss','manager')"):
        try:
            bot.send_message(aid, f"⭐ *Yangi baho — {emp_name}*\n\n😊 Muomala: {stars(svc)} ({svc}/5)\n🚀 Tezlik: {stars(spd)} ({spd}/5)\n📊 O'rtacha: *{avg}/5*" + (f"\n💬 {comment}" if comment else "") + f"\n\n📈 Umumiy: {r_avg}/5 ({cnt} ta)", parse_mode="Markdown")
        except: pass

