@bot.message_handler(content_types=['location'])
def handle_location(message):
    tg_id = message.from_user.id
    u = get_user(tg_id)
    if not u or u[2] != 'employee': return
    name = u[1]
    action = W_LOCATION.pop(tg_id, None)
    radius = int(get_setting("gps_radius","200"))
    dist = calc_dist(message.location.latitude, message.location.longitude, CFG.SHOP_LAT, CFG.SHOP_LON)
    if dist > radius:
        bot.send_message(tg_id, f"❌ *Do'kondan uzoqdasiz!*\n📍 {int(dist)} metr\n✅ Ruxsat: {radius} metr", parse_mode="Markdown", reply_markup=emp_kb())
        for (aid,) in qall("SELECT tg_id FROM users WHERE role IN ('boss','manager')"):
            try: bot.send_message(aid, f"⚠️ *{name}* {int(dist)}m uzoqda — rad etildi.", parse_mode="Markdown")
            except: pass
        return
    if action == 'checkin':
        sess = qone("SELECT id,checkin_time FROM attendance WHERE tg_id=? AND work_date=? AND checkout_time IS NULL", (tg_id,today_str()))
        if sess:
            bot.send_message(tg_id, f"ℹ️ Siz bugun *{display_time(sess[1])}* da kelgansiz.", parse_mode="Markdown", reply_markup=emp_kb()); return
        q("INSERT INTO attendance (tg_id,employee_name,checkin_time,work_date) VALUES (?,?,?,?)", (tg_id,name,now_str(),today_str()))
        score = apply_checkin_scoring(tg_id, name, now_dt())
        score_txt = ""
        if score is None:
            add_points(tg_id, name, 1)  # jadval belgilanmagan — standart +1
        else:
            status, pts, expected = score
            if status == "early":
                score_txt = f"\n🟢 Belgilangan vaqtdan ({expected}) erta keldingiz: *+{pts} ball*"
            elif status == "late":
                score_txt = f"\n🔴 Belgilangan vaqtdan ({expected}) kech qoldingiz: *{pts} ball*"
            else:
                score_txt = f"\n✅ Vaqtida keldingiz ({expected})"
        t = now_dt().strftime("%H:%M")
        bot.send_message(tg_id, f"✅ *Kelish qayd etildi!*\n👤 {name}\n🕐 *{t}*{score_txt}", parse_mode="Markdown", reply_markup=emp_kb())
        # ⏳ Xodim ishga keldi — uni kutib turgan vazifalarni endi yetkazamiz
        try:
            _deliver_pending_tasks(tg_id, name)
        except Exception as e:
            print("PENDING TASKS ERR:", str(e)[:150], flush=True)
        for (aid,) in qall("SELECT tg_id FROM users WHERE role IN ('boss','manager')"):
            try: bot.send_message(aid, f"🟢 *{name}* keldi — {t}", parse_mode="Markdown")
            except: pass
    elif action == 'checkout':
        # Oxirgi ochiq sessiyani topamiz (work_date tekshirmasdan - tun yarim o'tishi uchun)
        sess = qone("SELECT id,checkin_time FROM attendance WHERE tg_id=? AND checkout_time IS NULL ORDER BY id DESC LIMIT 1", (tg_id,))
        if not sess:
            bot.send_message(tg_id, "⚠️ Avval *🟢 Kelish* tugmasini bosing!", parse_mode="Markdown", reply_markup=emp_kb()); return
        ci_str = str(sess[1])
        ci_dt = datetime.strptime(ci_str, "%Y-%m-%d %H:%M:%S").replace(tzinfo=UZT)
        diff = (now_dt()-ci_dt).total_seconds()
        if diff < 0: diff += 86400
        mins = max(0, int(diff/60))
        salary = salary_for_minutes(tg_id, mins)
        q("UPDATE attendance SET checkout_time=?,work_minutes=? WHERE id=?", (now_str(),mins,sess[0]))
        score = apply_checkout_scoring(tg_id, name, now_dt(), ci_dt=ci_dt)
        score_txt = ""
        if score is not None:
            status, pts, expected = score
            if status == "early":
                score_txt = f"\n🔴 Belgilangan vaqtdan ({expected}) erta ketdingiz: *{pts} ball*"
            elif status == "early_ok":
                score_txt = f"\n✅ Smena boshlanishidan oldin (ish vaqtidan tashqarida) ketganingiz uchun ball ayirilmadi"
            elif status == "late":
                score_txt = f"\n🟢 Belgilangan vaqtdan ({expected}) kech qoldingiz (qo'shimcha ishladingiz): *+{pts} ball*"
            else:
                score_txt = f"\n✅ Vaqtida ketdingiz ({expected})"
        t = now_dt().strftime("%H:%M")
        sal_txt = f"\n💰 *{fmt_money(salary)}*" if salary > 0 else ""
        bot.send_message(tg_id, f"🏁 *Ketish qayd etildi!*\n👤 {name}\n🕐 Kelish: *{display_time(ci_str)}*\n🕔 Ketish: *{t}*\n⏱ *{minutes_to_str(mins)}*{sal_txt}{score_txt}", parse_mode="Markdown", reply_markup=emp_kb())
        for (aid,) in qall("SELECT tg_id FROM users WHERE role IN ('boss','manager')"):
            try: bot.send_message(aid, f"🔴 *{name}* ketdi — {t}\n⏱ *{minutes_to_str(mins)}*", parse_mode="Markdown")
            except: pass

# Hodim menyulari
@bot.message_handler(func=lambda m: m.text == "🕐 Holat (bugun)")
def emp_today(message):
    if get_role(message.from_user.id) != 'employee': return
    tg_id = message.from_user.id
    rows = qall("SELECT checkin_time,checkout_time,work_minutes,note FROM attendance WHERE tg_id=? AND work_date=? ORDER BY id", (tg_id,today_str()))
    if not rows: bot.send_message(tg_id, "📭 Bugun davomat ma'lumoti yo'q."); return
    text = f"📅 *Bugun — {now_dt().strftime('%d.%m.%Y')}*\n\n"; total = 0
    for i,(ci,co,mins,note) in enumerate(rows,1):
        if not co:
            try:
                ci_dt = datetime.strptime(str(ci), "%Y-%m-%d %H:%M:%S").replace(tzinfo=UZT)
                elapsed = max(0, int((now_dt()-ci_dt).total_seconds()/60))
            except: elapsed = 0
            m_str = f"{minutes_to_str(elapsed)} (davom etmoqda)"
        else:
            m_str = minutes_to_str(mins or 0); total += (mins or 0)
        text += f"{i}. {display_time(str(ci))} → {display_time(str(co) if co else None)} | {m_str}\n"
    salary = salary_for_minutes(tg_id, total)
    text += f"\n⏱ *Jami: {minutes_to_str(total)}*"
    if salary: text += f"\n💰 *{fmt_money(salary)}*"
    bot.send_message(tg_id, text, parse_mode="Markdown")

@bot.message_handler(func=lambda m: m.text == "📊 Mening hisobotim")
def emp_stat(message):
    if get_role(message.from_user.id) != 'employee': return
    tg_id = message.from_user.id; u = get_user(tg_id); name = u[1]
    t_rows = qall("SELECT status FROM tasks WHERE employee_tg_id=?", (tg_id,))
    total = len(t_rows)
    month = now_dt().strftime("%Y-%m")
    sr = qone("SELECT COALESCE(SUM(amount),0),COALESCE(SUM(customer_count),0),COALESCE(AVG(avg_check),0),COUNT(*) FROM sales WHERE tg_id=? AND strftime('%Y-%m',sale_date)=?", (tg_id,month))
    s_amt = float(sr[0]) if sr else 0; s_cust = int(sr[1]) if sr else 0
    s_avg = float(sr[2]) if sr else 0; s_cnt = int(sr[3]) if sr else 0
    pts = get_points(tg_id); avg_r, r_cnt = get_avg_rating(tg_id)
    text = f"📊 *{name} — Hisobot*\n\n"
    if s_amt: text += f"💵 *Oylik savdo:* {fmt_money(int(s_amt))} | 👥 {s_cust} mijoz\n📊 O'rtacha chek: {fmt_money(int(s_avg))}\n"
    if total:
        done = sum(1 for r in t_rows if r[0] in ["✅ To'liq bajarildi","🟡 Chala bajarildi"])
        text += f"📋 *Vazifalar:* {total} ta | 🎯 *{round(done/total*100)}%*\n"
    text += f"🏆 *Ball: {pts}*"
    if avg_r: text += f"\n⭐ *Mijoz bahosi: {avg_r}/5* ({r_cnt} ta)"

    # 💰 TO'LIQ ISH HAQI XULOSASI (hisoblash turiga qarab: soatiga/savdosiga/ikkalasi + ball puli)
    mr = qone("SELECT COALESCE(SUM(work_minutes),0) FROM attendance WHERE tg_id=? AND strftime('%Y-%m',work_date)=?", (tg_id, month))
    month_mins = int(mr[0]) if mr and mr[0] else 0
    bito_gross_month = 0
    bmap = get_bito_map()
    bname = bmap.get(tg_id)
    if bname:
        try:
            m_start = now_dt().replace(day=1).strftime("%Y-%m-%d")
            df_m, dt_m = bito_range_utc(m_start, today_str())
            sd = get_bito_sales_dict(df_m, dt_m)
            item = sd.get(bname) if sd is not None else None
            bito_gross_month = (item.get("gross_sales", 0) if item else 0) or 0
        except Exception:
            pass
    pay = calc_employee_total_pay(tg_id, work_minutes=month_mins, sales_gross=bito_gross_month)
    pay_lines = [f"\n\n💰 *Ish haqi xulosasi ({salary_mode_label(pay['mode'])}):*"]
    if "hourly" in pay["mode"]:
        pay_lines.append(f"⏰ Soatiga: {fmt_money(pay['hourly'])} ({month_mins//60} soat {month_mins%60} daq)")
    if "sales" in pay["mode"]:
        pay_lines.append(f"💵 Savdodan: {fmt_money(pay['sales_bonus'])} (savdo: {fmt_money(int(bito_gross_month))})")
    if "points" in pay["mode"]:
        pay_lines.append(f"🎯 Ballardan: {fmt_money(pay['points_money'])} ({pay['points']} ball)")
    pay_lines.append(f"💰 *JAMI: {fmt_money(pay['total'])}*")
    text += "\n".join(pay_lines)
    bot.send_message(tg_id, text, parse_mode="Markdown")

@bot.message_handler(func=lambda m: m.text == "🏆 Mening ballarim")
def my_pts(message):
    if get_role(message.from_user.id) != 'employee': return
    tg_id = message.from_user.id; u = get_user(tg_id); name = u[1]
    pts = get_points(tg_id); month = now_dt().strftime("%Y-%m")
    all_pts = qall("SELECT tg_id,points FROM points WHERE month=? ORDER BY points DESC", (month,))
    rank = next((i+1 for i,r in enumerate(all_pts) if r[0]==tg_id), len(all_pts)+1)
    medals = {1:"🥇",2:"🥈",3:"🥉"}
    medal = medals.get(rank, f"{rank}-o'rin")
    pv = get_point_value(); pts_money = round(pts * pv)
    bot.send_message(tg_id, f"🏆 *{name} — Ballar*\n\n🎯 Bu oy: *{pts} ball*\n💰 Pul ko'rinishida: *{fmt_money(pts_money)}* (1 ball = {fmt_money(int(pv))})\n📊 Reyting: *{medal}*\n\n📌 *Ball tizimi:*\n✅ Vazifa to'liq: +5\n🟡 Vazifa chala: +2\n💵 Har 100k so'm: +1\n⭐5: +3 | ⭐4: +2 | ⭐3: +1\n📅 Vaqtida kelish: +1", parse_mode="Markdown")

@bot.message_handler(func=lambda m: m.text == "⭐ Mening baholarim")
def my_reviews(message):
    if get_role(message.from_user.id) != 'employee': return
    tg_id = message.from_user.id
    avg, cnt = get_avg_rating(tg_id)
    rows = qall("SELECT rating,comment,created_at FROM reviews WHERE employee_tg_id=? ORDER BY id DESC LIMIT 10", (tg_id,))
    text = "⭐ *Mening baholarim*\n\n"
    if not rows: text += "📭 Hali baholar yo'q."
    else:
        text += f"📊 O'rtacha: *{avg}/5* ({cnt} ta)\n\n"
        for rating,comment,created_at in rows:
            d = str(created_at)[:10]; c_str = str(comment) if comment else ""
            if "Muomala:" in c_str:
                try:
                    parts = c_str.split("|")
                    svc = parts[0].replace("Muomala:","").strip()
                    spd = parts[1].replace("Tezlik:","").strip()
                    svc_str = f"😊{svc} 🚀{spd}"
                    c_str = parts[2].replace("Izoh:","").strip() if len(parts)>2 else ""
                except: svc_str = stars(rating)
            else: svc_str = stars(rating)
            text += f"📅 {d} | {svc_str}"
            if c_str: text += f"\n   💬 {c_str}"
            text += "\n"
    bot.send_message(tg_id, text, parse_mode="Markdown")

@bot.message_handler(func=lambda m: m.text == "📆 Haftalik")
def emp_weekly(message):
    if get_role(message.from_user.id) != 'employee': return
    tg_id = message.from_user.id; u = get_user(tg_id); name = u[1]
    cutoff = (now_dt()-timedelta(days=7)).strftime("%Y-%m-%d")
    rows = qall("SELECT work_date,checkin_time,checkout_time,work_minutes FROM attendance WHERE tg_id=? AND work_date>=? ORDER BY work_date,id", (tg_id,cutoff))
    text = f"📆 *Haftalik — {name}*\n\n"
    if not rows: text += "📭 Ma'lumot yo'q."
    else:
        total = 0; by_day = {}
        for date,ci,co,mins in rows: by_day.setdefault(date,[]).append((ci,co,mins or 0))
        for date, sessions in sorted(by_day.items()):
            day_mins = sum(s[2] for s in sessions if s[1]); total += day_mins
            d = datetime.strptime(date,"%Y-%m-%d").strftime("%d.%m")
            text += f"📅 *{d}*: {minutes_to_str(day_mins)}\n"
        salary = salary_for_minutes(tg_id, total)
        text += f"\n⏱ *Jami: {minutes_to_str(total)}*"
        if salary: text += f"\n💰 *{fmt_money(salary)}*"
    bot.send_message(tg_id, text, parse_mode="Markdown")

@bot.message_handler(func=lambda m: m.text == "🗓 Muddatli hisobot")
def emp_custom(message):
    if get_role(message.from_user.id) != 'employee': return
    W_CUSTOM_DATE[message.from_user.id] = {'step':'from'}
