@bot.message_handler(func=lambda m: m.from_user.id in W_CUSTOM_DATE)
def handle_custom_date(message):
    tg_id = message.from_user.id; state = W_CUSTOM_DATE[tg_id]
    if message.text in MENU_TEXTS: W_CUSTOM_DATE.pop(tg_id,None); return
    try: dt = datetime.strptime(message.text.strip(), "%d.%m.%Y")
    except: bot.send_message(tg_id, "❌ Format: `DD.MM.YYYY`", parse_mode="Markdown"); return
    if state['step'] == 'from':
        W_CUSTOM_DATE[tg_id] = {'step':'to','from':dt.strftime("%Y-%m-%d"),'is_admin':state.get('is_admin')}
        bot.send_message(tg_id, "📅 Tugash sanasi (`DD.MM.YYYY`):", parse_mode="Markdown")
    else:
        from_date = state['from']; to_date = dt.strftime("%Y-%m-%d"); W_CUSTOM_DATE.pop(tg_id)
        if BITO_BONUS_ENABLED:
            bdf, bdt = bito_range_utc(from_date, to_date)
            bito_sales = get_bito_sales_dict(bdf, bdt)  # None = xato, {} = bo'sh, dict = ma'lumot
        else:
            bito_sales = None
        rate = get_bito_bonus_rate()
        if state.get('is_admin'):
            rows = qall("SELECT u.tg_id,u.full_name,SUM(a.work_minutes),COUNT(DISTINCT a.work_date) FROM attendance a JOIN users u ON a.tg_id=u.tg_id WHERE a.checkout_time IS NOT NULL AND a.work_date BETWEEN ? AND ? GROUP BY u.tg_id", (from_date,to_date))
            fd = datetime.strptime(from_date,"%Y-%m-%d").strftime("%d.%m.%Y"); td = datetime.strptime(to_date,"%Y-%m-%d").strftime("%d.%m.%Y")
            text = f"📊 *{fd} → {td}*\n\n"
            if not rows: text += "📭 Ma'lumot yo'q."
            else:
                for emp_id,name,total_mins,days in rows:
                    salary = salary_for_minutes(emp_id, total_mins or 0)
                    text += f"👤 *{name}*\n   📅 {days} kun | ⏱ {minutes_to_str(total_mins or 0)}"
                    if salary: text += f" | 💰 {fmt_money(salary)}"
                    bmap_row = qone("SELECT bito_name FROM bito_employee_map WHERE tg_id=?", (emp_id,))
                    bonus = 0
                    if bmap_row and bito_sales is not None:
                        item = bito_sales.get(bmap_row[0])
                        gross = (item.get("gross_sales",0) if item else 0) or 0
                        bonus = round(gross*rate)
                        text += f" | 🎁 {fmt_money(bonus)}"
                    total_pay = (salary or 0) + bonus
                    if total_pay:
                        text += f"\n   💵 *Jami ish haqi: {fmt_money(total_pay)}*"
                    text += "\n"
        else:
            u = get_user(tg_id); name = u[1]
            rows = qall("SELECT work_date,checkin_time,checkout_time,work_minutes FROM attendance WHERE tg_id=? AND work_date BETWEEN ? AND ? ORDER BY work_date,id", (tg_id,from_date,to_date))
            fd = datetime.strptime(from_date,"%Y-%m-%d").strftime("%d.%m.%Y"); td = datetime.strptime(to_date,"%Y-%m-%d").strftime("%d.%m.%Y")
            text = f"📊 *{name}* — {fd} → {td}\n\n"
            total = 0
            if not rows: text += "📭 Davomat ma'lumoti yo'q.\n"
            else:
                by_day = {}
                for date,ci,co,mins in rows: by_day.setdefault(date,[]).append((ci,co,mins or 0))
                for date,sessions in sorted(by_day.items()):
                    day_mins = sum(s[2] for s in sessions if s[1]); total += day_mins
                    d = datetime.strptime(date,"%Y-%m-%d").strftime("%d.%m")
                    text += f"📅 *{d}*: {minutes_to_str(day_mins)}\n"
            salary = salary_for_minutes(tg_id, total)
            text += f"\n⏱ *Jami ishlagan vaqt: {minutes_to_str(total)}*"
            if salary: text += f"\n💰 *Ish haqi (soat bo'yicha): {fmt_money(salary)}*"
            bonus = 0
            bmap_row = qone("SELECT bito_name FROM bito_employee_map WHERE tg_id=?", (tg_id,))
            if bmap_row:
                if bito_sales is None:
                    text += "\n⚠️ Bito integratsiyasi vaqtincha o'chirilgan (savdo/bonus hisoblanmadi)."
                else:
                    item = bito_sales.get(bmap_row[0])
                    gross = (item.get("gross_sales",0) if item else 0) or 0
                    bonus = round(gross*rate)
                    text += f"\n💵 *Savdo qilingan:* {fmt_money(gross)}\n🎁 *Bonus ({rate*100:.2f}%):* {fmt_money(bonus)}"
            total_pay = (salary or 0) + bonus
            if total_pay:
                text += f"\n\n🟰 *Umumiy ish haqing: {fmt_money(total_pay)}*"
        bot.send_message(tg_id, text, parse_mode="Markdown")

