# Jadval (hodim)
@bot.message_handler(func=lambda m: m.text == "📅 Jadval")
def jadval(message):
    tg_id = message.from_user.id; role = get_role(tg_id)
    if role == 'employee':
        today = now_dt(); monday = today - timedelta(days=today.weekday())
        day_names = ["Du","Se","Cho","Pa","Ju","Sha","Ya"]
        text = "📅 *Mening haftalik jadvalim*\n\n"
        for i in range(7):
            day = monday + timedelta(days=i); ds = day.strftime("%Y-%m-%d")
            row = qone("SELECT shift,is_off FROM schedules WHERE tg_id=? AND work_date=?", (tg_id,ds))
            icon = "🔴" if (row and row[1]) else ("🟢" if row else "⬜")
            shift = row[0] if row else "belgilanmagan"
            prefix = "👉 " if ds == today_str() else ""
            text += f"{prefix}{icon} *{day_names[i]} {day.strftime('%d.%m')}* — {shift}\n"
        bot.send_message(tg_id, text, parse_mode="Markdown")
    elif is_boss_or_mgr(tg_id):
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("📅 Bu hafta", callback_data="sch_week"))
        markup.add(types.InlineKeyboardButton("➕ Jadval qo'shish", callback_data="sch_add"))
        bot.send_message(message.chat.id, "📅 *Ish jadvali:*", parse_mode="Markdown", reply_markup=markup)

@bot.callback_query_handler(func=lambda c: c.data == "sch_week")
def sch_week(call):
    _ack(call)
    today = now_dt(); monday = today - timedelta(days=today.weekday())
    day_names = ["Dushanba","Seshanba","Chorshanba","Payshanba","Juma","Shanba","Yakshanba"]
    text = "📅 *Haftalik ish jadvali*\n\n"
    for i in range(7):
        day = monday + timedelta(days=i); ds = day.strftime("%Y-%m-%d")
        prefix = "👉 " if ds == today_str() else ""
        rows = qall("SELECT employee_name,shift,is_off FROM schedules WHERE work_date=?", (ds,))
        text += f"{prefix}*{day_names[i]} {day.strftime('%d.%m')}:*\n"
