@bot.callback_query_handler(func=lambda c: c.data.startswith("sch_s_"))
def sch_shift(call):
    mgr_id = call.from_user.id
    if mgr_id not in W_SCHEDULE: return
    state = W_SCHEDULE.pop(mgr_id)
    shifts = {"full":("To'liq kun (09:00-18:00)",0),"morning":("Ertalab (08:00-14:00)",0),"evening":("Kechqurun (14:00-20:00)",0),"off":("Dam olish",1)}
    key = call.data.replace("sch_s_",""); shift, is_off = shifts[key]
    emp_key = state['emp_key']; work_date = state['date']
    d_label = datetime.strptime(work_date,"%Y-%m-%d").strftime("%d.%m.%Y")
    if emp_key == "all":
        employees = qall("SELECT tg_id,full_name FROM users WHERE role='employee'")
    else:
        emp = get_user(int(emp_key))
        employees = [(int(emp_key),emp[1])] if emp else []
    for eid, ename in employees:
        q("INSERT OR REPLACE INTO schedules (tg_id,employee_name,work_date,shift,is_off) VALUES (?,?,?,?,?)", (eid,ename,work_date,shift,is_off))
        try:
            icon = "🔴" if is_off else "🟢"
            bot.send_message(eid, f"📅 *Jadvalingiz yangilandi*\n\n{icon} {d_label}: {shift}", parse_mode="Markdown")
        except: pass
    _ack(call)
    names = ", ".join(e[1] for e in employees)
    bot.send_message(call.message.chat.id, f"✅ Jadval saqlandi!\n👤 {names}\n📅 {d_label}: {shift}", parse_mode="Markdown")

# Guruh chat
@bot.message_handler(func=lambda m: m.text == "💬 Guruh chat")
def group_chat(message):
    tg_id = message.from_user.id; role = get_role(tg_id)
    if role not in ('employee','manager','boss'): return
    if get_setting("chat_enabled","1") != "1":
        bot.send_message(message.chat.id, "💬 Chat hozircha o'chirilgan."); return
    rows = qall("SELECT from_name,message,sent_at FROM group_messages ORDER BY id DESC LIMIT 10")
    text = "💬 *Jamoa chati — Oxirgi xabarlar:*\n\n"
    if rows:
        for name, msg, sent in reversed(rows):
            t = str(sent)[11:16] if sent else ""
            text += f"👤 *{name}* [{t}]:\n{msg}\n\n"
    else: text += "_Hali xabarlar yo'q_\n\n"
    text += "📝 Xabaringizni yozing:"
    W_GROUP_MSG[tg_id] = True
    markup = types.ReplyKeyboardMarkup(resize_keyboard=True, row_width=1)
    markup.add(types.KeyboardButton("🚪 Chatdan chiqish"))
    bot.send_message(message.chat.id, text, parse_mode="Markdown", reply_markup=markup)

@bot.message_handler(func=lambda m: W_GROUP_MSG.get(m.from_user.id) and m.text not in ("🔙 Orqaga","🚪 Chatdan chiqish","❌ Bekor qilish"))
def group_chat_send(message):
    tg_id = message.from_user.id; u = get_user(tg_id); name = u[1] if u else "Noma'lum"
    q("INSERT INTO group_messages (from_tg_id,from_name,message,sent_at) VALUES (?,?,?,?)", (tg_id,name,message.text,now_str()))
    t = now_dt().strftime("%H:%M"); broadcast = f"💬 *{name}* [{t}]:\n{message.text}"
    for (rid,) in qall("SELECT tg_id FROM users WHERE role IN ('employee','manager','boss') AND tg_id!=?", (tg_id,)):
        try: bot.send_message(rid, broadcast, parse_mode="Markdown")
        except: pass
    markup = types.ReplyKeyboardMarkup(resize_keyboard=True)
    markup.add(types.KeyboardButton("🚪 Chatdan chiqish"))
    bot.send_message(tg_id, "✅ Yuborildi!", reply_markup=markup)

# Admin menyulari
@bot.message_handler(func=lambda m: m.text == "👥 Xodimlar")
def staff_list(message):
    if not is_boss_or_mgr(message.from_user.id): return
    rows = qall("SELECT tg_id,full_name,role,position,hourly_rate FROM users WHERE role IN ('employee','manager','boss') ORDER BY role,full_name")
    if not rows: bot.send_message(message.chat.id, "📭 Hali xodimlar yo'q."); return
    role_icon = {'boss':'👑','manager':'👔','employee':'👤'}
    markup = types.InlineKeyboardMarkup(); text = "👥 *Xodimlar:*\n\n"
    for tg_id, name, role, pos, rate in rows:
        pos_str = f" | {pos}" if pos else ""; rate_str = f" | {fmt_money(int(rate))}/soat" if rate else ""
        avg, cnt = get_avg_rating(tg_id); star_str = f" ⭐{avg}" if cnt > 0 else ""
        text += f"{role_icon.get(role,'👤')} *{name}*{pos_str}{rate_str}{star_str}\n"
        if role == 'employee':
            markup.add(types.InlineKeyboardButton(f"✏️ {name}", callback_data=f"edit_emp_{tg_id}"))
    bot.send_message(message.chat.id, text, parse_mode="Markdown", reply_markup=markup)

