@bot.callback_query_handler(func=lambda c: c.data.startswith("fire_") and not c.data.startswith("fireok_"))
def fire_emp_ask(call):
    """🚫 Ishdan bo'shatish — TASDIQLASH bosqichi.

    MUHIM: hech qanday jadval o'chirilmaydi. Faqat users.role='fired'
    bo'ladi (soft-delete): xodim botga kira olmaydi, ro'yxatlarda
    ko'rinmaydi, lekin davomat/oylik/savdo/baho TARIXI to'liq qoladi —
    ular alohida jadvallarda (attendance, sales, reviews, tasks) va
    tg_id+ism bo'yicha saqlangan, eski hisobotlarda ko'rinaveradi."""
    if call.from_user.id != CFG.SUPER_ADMIN_ID and get_role(call.from_user.id) != 'boss':
        _ack(call, "Faqat rahbar bo'shata oladi")
        return
    _ack(call)
    tg_id = int(call.data.replace("fire_", ""))
    u = get_user(tg_id)
    if not u:
        return
    kb = types.InlineKeyboardMarkup()
    kb.add(types.InlineKeyboardButton("✅ Ha, bo'shatilsin",
                                      callback_data=f"fireok_{tg_id}"))
    bot.send_message(call.message.chat.id,
                     f"🚫 <b>{h(u[1])}</b> ishdan bo'shatilsinmi?\n\n"
                     f"• Botga kira olmaydi, ro'yxatlardan chiqadi\n"
                     f"• Davomat, oylik, savdo, baho TARIXI to'liq saqlanadi\n"
                     f"• Kerak bo'lsa keyin qayta tiklash mumkin (/boshatilganlar)",
                     parse_mode="HTML", reply_markup=kb)


