W_MODE_TOGGLE = TDict()  # boss_tg_id -> {"target_id": int, "selected": set(...)}

def _mode_toggle_markup(selected):
    markup = types.InlineKeyboardMarkup()
    for comp in SALARY_COMPONENTS:
        mark = "✅" if comp in selected else "⬜"
        markup.add(types.InlineKeyboardButton(
            f"{mark} {SALARY_COMPONENT_LABEL[comp]}", callback_data=f"modetoggle_{comp}"))
    markup.add(types.InlineKeyboardButton("💾 Saqlash", callback_data="modetoggle_save"))
    return markup

@bot.callback_query_handler(func=lambda c: c.data.startswith("setmode_"))
def setmode_start(call):
    if not is_boss_or_mgr(call.from_user.id): return
    target_id = int(call.data.replace("setmode_",""))
    _ack(call)
    current = set(get_salary_mode(target_id))
    W_MODE_TOGGLE[call.from_user.id] = {"target_id": target_id, "selected": current}
    u = get_user(target_id)
    bot.send_message(call.message.chat.id,
        f"🧮 *{u[1]}* uchun ish haqi hisoblash turi\n\n"
        f"Kerakli komponentlarni belgilang (bir nechtasini tanlash mumkin), so'ng *Saqlash*ni bosing:",
        parse_mode="Markdown", reply_markup=_mode_toggle_markup(current))

@bot.callback_query_handler(func=lambda c: c.data.startswith("modetoggle_"))
def setmode_toggle(call):
    if not is_boss_or_mgr(call.from_user.id): return
    state = W_MODE_TOGGLE.get(call.from_user.id)
    if not state:
        _ack(call, "Sessiya tugagan, qaytadan boshlang."); return
    action = call.data.replace("modetoggle_", "")
    if action == "save":
        target_id = state["target_id"]; selected = state["selected"]
        set_salary_mode(target_id, selected)
        W_MODE_TOGGLE.pop(call.from_user.id, None)
        _ack(call, "Saqlandi!")
        u = get_user(target_id)
        label = salary_mode_label(get_salary_mode(target_id))
        bot.send_message(call.message.chat.id, f"✅ *{u[1]}* uchun ish haqi turi: *{label}*", parse_mode="Markdown")
        try:
            bot.send_message(target_id, f"🧮 Ish haqingiz hisoblash turi o'zgartirildi: *{label}*", parse_mode="Markdown")
        except: pass
        return
    # komponentni yoqish/o'chirish
    if action in state["selected"]:
        state["selected"].discard(action)
    else:
        state["selected"].add(action)
    _ack(call)
    try:
        bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id,
                                       reply_markup=_mode_toggle_markup(state["selected"]))
    except Exception:
        pass

@bot.callback_query_handler(func=lambda c: c.data.startswith("setweek_"))
def setweek_start(call):
    if not is_boss_or_mgr(call.from_user.id): return
    target_id = int(call.data.replace("setweek_",""))
    _ack(call)
    _show_week_menu(call.message.chat.id, target_id)

def _week_day_label(tg_id, wd):
    sched = get_weekly_schedule(tg_id, wd)
    if not sched or (not sched[0] and not sched[1] and not sched[2]):
        return f"{WEEKDAY_NAMES[wd]}: belgilanmagan"
    if sched[2] == 1:
        return f"{WEEKDAY_NAMES[wd]}: 🚫 Dam olish"
    ci = sched[0] or "?"; co = sched[1] or "?"
    return f"{WEEKDAY_NAMES[wd]}: {ci}—{co}"

def _show_week_menu(chat_id, target_id):
    u = get_user(target_id)
    markup = types.InlineKeyboardMarkup()
    for wd in range(7):
        markup.add(types.InlineKeyboardButton(_week_day_label(target_id, wd), callback_data=f"weekday_{target_id}_{wd}"))
    bot.send_message(chat_id, f"📅 *{u[1]}* — hafta jadvali\n\nKunni tanlang:", parse_mode="Markdown", reply_markup=markup)

