W_WEEK_TIME = TDict()  # boss_tg_id -> {"emp_id":.., "weekday":.., "step":"checkin"/"checkout", "checkin":..}

@bot.callback_query_handler(func=lambda c: c.data.startswith("weeksettime_"))
def weekday_settime_start(call):
    if not is_boss_or_mgr(call.from_user.id): return
    _, rest = call.data.split("weeksettime_")
    target_id_s, wd_s = rest.rsplit("_", 1)
    target_id = int(target_id_s); wd = int(wd_s)
    _ack(call)
    W_WEEK_TIME[call.from_user.id] = {"emp_id": target_id, "weekday": wd, "step": "checkin"}
    bot.send_message(call.message.chat.id,
        f"🕐 *{WEEKDAY_NAMES[wd]}* uchun kelish vaqti (`HH:MM`, masalan `09:00`):", parse_mode="Markdown")

@bot.message_handler(func=lambda m: m.from_user.id in W_WEEK_TIME)
def weekday_settime_value(message):
    mgr_id = message.from_user.id; state = W_WEEK_TIME.get(mgr_id)
    if not state or message.text in MENU_TEXTS: W_WEEK_TIME.pop(mgr_id, None); return
    try: datetime.strptime(message.text.strip(), "%H:%M")
    except:
        bot.send_message(mgr_id, "❌ Format: `HH:MM` (masalan `09:00`)", parse_mode="Markdown"); return
    if state["step"] == "checkin":
        state["checkin"] = message.text.strip(); state["step"] = "checkout"
        bot.send_message(mgr_id, f"🕔 *{WEEKDAY_NAMES[state['weekday']]}* uchun ketish vaqti (`HH:MM`, masalan `18:00`):", parse_mode="Markdown")
    else:
        checkout = message.text.strip()
        target_id = state["emp_id"]; wd = state["weekday"]; checkin = state["checkin"]
        W_WEEK_TIME.pop(mgr_id, None)
        set_weekly_schedule(target_id, wd, checkin_time=checkin, checkout_time=checkout, is_off=0)
        u = get_user(target_id)
        bot.send_message(mgr_id, f"✅ *{u[1]}* — *{WEEKDAY_NAMES[wd]}*: *{checkin}—{checkout}* saqlandi.", parse_mode="Markdown")
        try:
            bot.send_message(target_id, f"📅 Sizning *{WEEKDAY_NAMES[wd]}* kunidagi jadvalingiz: *{checkin}—{checkout}*", parse_mode="Markdown")
        except: pass

