@bot.message_handler(content_types=['photo'], func=lambda m: m.from_user.id in W_TASK and W_TASK[m.from_user.id].get('step')=='photo')
def task_photo(message): _send_task(message.from_user.id, message.photo[-1].file_id)

def _emp_at_work(tg_id):
    """Xodim AYNI PAYTDA ishdami?

    ⚠️ Avvalgi versiya `WHERE checkout_time IS NULL` bilan qidirardi — bu XATO edi:
    xodim bir kun «Ketdim» bosishni unutgan bo'lsa, o'sha eski yozuv abadiy
    «ishda» deb ko'rsatardi. Endi FAQAT oxirgi yozuv olinadi va u BUGUNGI
    bo'lishi hamda ketish qayd etilmagan bo'lishi shart."""
    row = qone("SELECT work_date, checkout_time FROM attendance "
               "WHERE tg_id=? ORDER BY id DESC LIMIT 1", (tg_id,))
    if not row:
        return False
    work_date, checkout = row[0], row[1]
    return (checkout is None or checkout == "") and str(work_date) == today_str()


def _deliver_pending_tasks(tg_id, name=""):
    """Xodim ishga kelganda — kutib turgan vazifalarni yetkazadi.
    `checkin` handleridan chaqiriladi. Bir nechta vazifa kutayotgan bo'lsa hammasi boradi."""
    rows = qall("SELECT id,task,photo_file_id,attempt FROM tasks "
                "WHERE employee_tg_id=? AND pending_delivery=1 AND status='Jarayonda' "
                "AND (claimed_by IS NULL OR claimed_by=0 OR claimed_by=employee_tg_id) "
                "ORDER BY id", (tg_id,))
    sent = 0
    for tid, ttext, tphoto, attempt in rows:
        hdr = ("📋 <b>Yangi vazifa:</b>" if (attempt or 1) <= 1
               else f"🔄 <b>Vazifa qaytarildi ({attempt}-urinish):</b>")
        if _deliver_task(tid, tg_id, ttext, tphoto, header=hdr, force=True):
            q("UPDATE tasks SET pending_delivery=0, last_reminded=? WHERE id=?", (now_str(), tid))
            sent += 1
    if sent:
        try:
            bot.send_message(tg_id, f"📋 Sizni <b>{sent} ta vazifa</b> kutib turgan edi — yuqorida.",
                             parse_mode="HTML")
        except Exception:
            pass
    return sent


def _deliver_task(task_id, emp_id, task_text, photo_id, header="📋 <b>Yangi vazifa:</b>", force=False):
    """Vazifani xodimga yuboradi.

    ⏳ Xodim hozir ishda bo'lmasa (kelish qayd etilmagan) — vazifa YUBORILMAYDI,
    `pending_delivery=1` qilib qo'yiladi va u ishga kelganda avtomatik boradi.
    Shu bilan dam olishdagi yoki uydagi xodimga vazifa tushib, unutilib ketmaydi.
    `force=True` — tekshiruvsiz yuborish (kutib turganlarni yetkazishda)."""
    if not force and not _emp_at_work(emp_id):
        q("UPDATE tasks SET pending_delivery=1 WHERE id=?", (task_id,))
        return "pending"
    mk = types.InlineKeyboardMarkup()
    mk.add(types.InlineKeyboardButton("✅ Bajarildi", callback_data=f"done_task_{task_id}"))
    cap = f"{header}\n\n{h(task_text)}"
    try:
        if photo_id:
            bot.send_photo(emp_id, photo_id, caption=cap, parse_mode="HTML", reply_markup=mk)
        else:
            bot.send_message(emp_id, cap, parse_mode="HTML", reply_markup=mk)
        return True
    except Exception as e:
        print(f"TASK DELIVER ERR (emp={emp_id}):", str(e)[:120], flush=True)
        return False


def _send_task(mgr_id, photo_id):
    state = W_TASK.pop(mgr_id, None)
    if not state:
        return
    task_text = state.get('task_text', '')
    # Bir nechta xodim tanlangan bo'lishi mumkin; eski bitta tanlov ham qo'llab-quvvatlanadi
    emp_ids = list(state.get('sel') or ([state['emp_id']] if state.get('emp_id') else []))
    if not emp_ids:
        bot.send_message(mgr_id, "⚠️ Xodim tanlanmagan — qaytadan urinib ko'ring."); return

    # 🔗 Guruh identifikatori: bitta vazifaning barcha nusxalarini bog'laydi
    group_id = f"g{int(time.time()*1000)}_{mgr_id}"
    created, failed, pending = [], [], []
    for emp_id in emp_ids:
        emp = get_user(emp_id)
        emp_name = emp[1] if emp else "Noma'lum"
        cur = q("INSERT INTO tasks (given_by,employee_tg_id,employee_name,task,photo_file_id,"
                "status,reminder_interval,last_reminded,created_at,group_id,claimed_by,attempt,"
                "pending_delivery,due_date) "
                "VALUES (?,?,?,?,?,'Jarayonda',120,?,?,?,0,1,0,?)",
                (mgr_id, emp_id, emp_name, task_text, photo_id, now_str(), now_str(), group_id,
                 today_str()))
        tid = cur.lastrowid if cur else 0
        res = _deliver_task(tid, emp_id, task_text, photo_id)
        if res == "pending":
            created.append((tid, emp_name))
            pending.append(emp_name)
        elif res:
            created.append((tid, emp_name))
        else:
            failed.append(emp_name)

    if not created:
        bot.send_message(mgr_id, "⚠️ Hech kimga yetkazib bo'lmadi — xodimlar botni "
                                 "bloklagan yoki /start bosmagan bo'lishi mumkin."); return

    names = ", ".join(n for _, n in created)
    txt = f"✅ Vazifa <b>{h(names)}</b> ga yuborildi."
    if len(created) > 1:
        txt += "\n👥 Kim birinchi topshirsa, qolganlardan olib tashlanadi."
    if pending:
        txt += (f"\n⏳ <b>{h(', '.join(pending))}</b> hozir ishda emas — vazifa ular "
                f"ishga kelganda avtomatik yuboriladi.")
    if failed:
        txt += f"\n⚠️ Yetkazib bo'lmadi: {h(', '.join(failed))}"

    # Eslatma intervali butun GURUHga o'rnatiladi
    first_id = created[0][0]
    mk = types.InlineKeyboardMarkup()
    mk.add(types.InlineKeyboardButton("30 daq", callback_data=f"remind_{first_id}_30"),
           types.InlineKeyboardButton("1 soat", callback_data=f"remind_{first_id}_60"),
           types.InlineKeyboardButton("2 soat", callback_data=f"remind_{first_id}_120"),
           types.InlineKeyboardButton("Eslatmasiz", callback_data=f"remind_{first_id}_0"))
    bot.send_message(mgr_id, txt + "\n\n⏰ Eslatma intervali?", parse_mode="HTML", reply_markup=mk)

@bot.callback_query_handler(func=lambda c: c.data.startswith("remind_"))
def set_reminder(call):
    parts = call.data.split("_"); task_id = int(parts[1]); interval = int(parts[2])
    # Vazifa bir nechta xodimga berilgan bo'lsa — interval butun guruhga qo'llanadi
    gr = qone("SELECT group_id FROM tasks WHERE id=?", (task_id,))
    if gr and gr[0]:
        q("UPDATE tasks SET reminder_interval=? WHERE group_id=?", (interval, gr[0]))
    else:
        q("UPDATE tasks SET reminder_interval=? WHERE id=?", (interval, task_id))
    _ack(call, f"{interval} daqiqada bir" if interval else "Eslatmasiz")
    try: bot.edit_message_reply_markup(call.message.chat.id, call.message.message_id, reply_markup=None)
    except: pass

@bot.callback_query_handler(func=lambda c: c.data.startswith("done_task_"))
def done_task(call):
    task_id = int(call.data.replace("done_task_", ""))
    _ack(call)
    row = qone("SELECT status, group_id, claimed_by, employee_tg_id FROM tasks WHERE id=?", (task_id,))
    if not row:
        bot.send_message(call.message.chat.id, "⚠️ Bu vazifa topilmadi."); return
    status, gid, claimed, owner = row
    if owner != call.from_user.id:
        return
    # 👥 Guruhdagi vazifani boshqa xodim allaqachon topshirgan bo'lsa
    if claimed and claimed != call.from_user.id:
        who = get_user(claimed)
        bot.send_message(call.message.chat.id,
            f"ℹ️ Bu vazifani <b>{h(who[1] if who else 'boshqa xodim')}</b> allaqachon "
            f"topshirgan — sizdan olib tashlandi.", parse_mode="HTML")
        return
    if str(status).startswith("✅") or str(status).startswith("🟡"):
        bot.send_message(call.message.chat.id, "ℹ️ Bu vazifa allaqachon yakunlangan."); return
    W_PHOTO_TASK[call.from_user.id] = task_id
    bot.send_message(call.message.chat.id, "📷 Bajarilgan ishning rasmini yuboring:")

@bot.message_handler(content_types=['photo'], func=lambda m: m.from_user.id in W_PHOTO_TASK and m.from_user.id not in W_TASK)
def task_report(message):
    emp_id = message.from_user.id; task_id = W_PHOTO_TASK.pop(emp_id)
    photo_id = message.photo[-1].file_id
    task = qone("SELECT id,given_by,employee_tg_id,employee_name,task,group_id,claimed_by,attempt "
                "FROM tasks WHERE id=?", (task_id,))
    if not task: return
    emp = get_user(emp_id); name = emp[1] if emp else "Noma'lum"; mgr_id = task[1]
    gid, claimed, attempt = task[5], task[6], task[7] or 1

    # 🔒 Guruhni BAND qilamiz va qolgan xodimlardan vazifani olib tashlaymiz.
    # Shu qadam birinchi topshirganda bajariladi — boshqalar bir ishni takrorlamasin.
    freed = []
    if gid:
        if claimed and claimed != emp_id:
            who = get_user(claimed)
            bot.send_message(emp_id, f"ℹ️ Bu vazifani <b>{h(who[1] if who else 'boshqa xodim')}</b> "
                                     f"sizdan oldin topshirgan.", parse_mode="HTML")
            return
        q("UPDATE tasks SET claimed_by=? WHERE group_id=?", (emp_id, gid))
        freed = qall("SELECT id,employee_tg_id,employee_name FROM tasks "
                     "WHERE group_id=? AND employee_tg_id<>?", (gid, emp_id))
        for _tid, _eid, _ename in freed:
            q("UPDATE tasks SET status=? WHERE id=?", ("🔁 Boshqa xodim bajardi", _tid))
            try:
                bot.send_message(_eid, f"🔁 <b>Vazifa yopildi</b>\n\n📋 {h(task[4])}\n\n"
                                       f"Buni <b>{h(name)}</b> bajardi — sizdan olib tashlandi.",
                                 parse_mode="HTML")
            except Exception: pass
    q("UPDATE tasks SET status='⏳ Tekshiruvda' WHERE id=?", (task_id,))

    markup = types.InlineKeyboardMarkup()
    markup.add(types.InlineKeyboardButton("✅ To'liq (100%)", callback_data=f"verdict_full_{task_id}"))
    markup.add(types.InlineKeyboardButton("🟡 Chala (50%)", callback_data=f"verdict_partial_{task_id}"))
    markup.add(types.InlineKeyboardButton("🔄 Bajarilmadi — qaytarish", callback_data=f"verdict_redo_{task_id}"))
    markup.add(types.InlineKeyboardButton("❌ Bajarilmadi (0%) — yopish", callback_data=f"verdict_reject_{task_id}"))
    cap = f"📸 <b>Hisobot</b>\n\n👤 {h(name)}\n📋 {h(task[4])}"
    if attempt > 1:
        cap += f"\n🔄 {attempt}-urinish"
    if freed:
        cap += f"\n👥 {len(freed)} ta xodimdan olib tashlandi"
    sent = bot.send_photo(mgr_id, photo_id, caption=cap, parse_mode="HTML", reply_markup=markup)
    W_PENDING_REVIEW[sent.message_id] = {'task_id': task_id, 'emp_id': emp_id}
    bot.send_message(emp_id, "✅ Hisobotingiz yuborildi.")

@bot.callback_query_handler(func=lambda c: c.data.startswith("verdict_"))
def task_verdict(call):
    if not is_boss_or_mgr(call.from_user.id): return
    parts = call.data.split("_"); verdict = parts[1]; task_id = int(parts[2])
    info = W_PENDING_REVIEW.pop(call.message.message_id, {})
    row = qone("SELECT employee_tg_id,task,photo_file_id,attempt FROM tasks WHERE id=?", (task_id,))
    if not row:
        _ack(call, "Vazifa topilmadi"); return
    # emp_id ni bazadan olamiz — bot qayta ishga tushsa W_PENDING_REVIEW bo'shab qoladi
    emp_id = info.get('emp_id') or row[0]
    task_text, photo_id, attempt = row[1], row[2], (row[3] or 1)

    # 🔄 QAYTARISH — vazifa yopilmaydi, xodimga qayta boradi
    if verdict == "redo":
        q("UPDATE tasks SET status='Jarayonda', score=0, attempt=?, last_reminded=?, "
          "due_date=?, penalized_on=NULL WHERE id=?",
          (attempt + 1, now_str(), today_str(), task_id))
        try:
            bot.edit_message_caption(
                caption=(call.message.caption or "") + "\n\n🔄 <b>Qaytarildi</b> — qayta bajarish uchun yuborildi",
                chat_id=call.message.chat.id, message_id=call.message.message_id, parse_mode="HTML")
        except Exception: pass
        _ack(call, "Qaytarildi")
        ok = _deliver_task(task_id, emp_id, task_text, photo_id,
                           header=f"🔄 <b>Vazifa qaytarildi ({attempt + 1}-urinish)</b>\n"
                                  f"Bajarilmagan deb topildi — boshidan bajarishingiz kerak:")
        if ok == "pending":
            bot.send_message(call.from_user.id, "⏳ Xodim hozir ishda emas — vazifa u ishga "
                                                "kelganda avtomatik yuboriladi.")
        elif not ok:
            bot.send_message(call.from_user.id, "⚠️ Xodimga yetkazib bo'lmadi (botni bloklagan bo'lishi mumkin).")
        return

    status_map = {"full": "✅ To'liq bajarildi", "partial": "🟡 Chala bajarildi", "reject": "❌ Bajarilmadi"}
    score_map = {"full": 100, "partial": 50, "reject": 0}
    pts_map = {"full": 5, "partial": 2, "reject": 0}
    status = status_map[verdict]; score = score_map[verdict]; pts = pts_map[verdict]
    q("UPDATE tasks SET status=?,score=? WHERE id=?", (status, score, task_id))
    if emp_id and pts:
        emp = get_user(emp_id)
        if emp: add_points(emp_id, emp[1], pts)
    try:
        bot.edit_message_caption(caption=(call.message.caption or "") + f"\n\n{status} — <b>{score}%</b>",
            chat_id=call.message.chat.id, message_id=call.message.message_id, parse_mode="HTML")
    except Exception: pass
    _ack(call, status)
    if emp_id:
        try: bot.send_message(emp_id, f"📢 Vazifangiz: <b>{status}</b> — <b>{score}%</b>", parse_mode="HTML")
        except Exception: pass

