@bot.callback_query_handler(func=lambda c: c.data.startswith("tstat_"))
def tstat_show(call):
    _ack(call); target = call.data.replace("tstat_","")
    if target == "all": rows = qall("SELECT status,score FROM tasks"); title = "Barcha"
    else:
        tg_id = int(target); rows = qall("SELECT status,score FROM tasks WHERE employee_tg_id=?", (tg_id,))
        u = get_user(tg_id); title = u[1] if u else str(tg_id)
    total = len(rows); text = f"📊 *{title}*\n\n"
    if not total: text += "📭 Vazifalar yo'q."
    else:
        counts = {"✅ To'liq bajarildi":0,"🟡 Chala bajarildi":0,"❌ Bajarilmadi":0,"Jarayonda":0}
        for (s,sc) in rows: counts[s] = counts.get(s,0)+1
        text += f"Jami: *{total}* ta\n\n"
        for k, v in counts.items():
            pct = round(v/total*100); bar = "█"*(pct//10)+"░"*(10-pct//10)
            text += f"{k}: {v} ta — *{pct}%* {bar}\n"
        done = counts["✅ To'liq bajarildi"]+counts["🟡 Chala bajarildi"]
        text += f"\n🎯 *Samaradorlik: {round(done/total*100)}%*"
    bot.send_message(call.message.chat.id, text, parse_mode="Markdown")

