@bot.callback_query_handler(func=lambda c: c.data.startswith("att_"))
def att_detail(call):
    _ack(call); period = call.data.replace("att_","")
    if period == "custom":
        W_CUSTOM_DATE[call.from_user.id] = {'step':'from','is_admin':True}
        bot.send_message(call.message.chat.id, "📅 Boshlanish sanasi (`DD.MM.YYYY`):", parse_mode="Markdown"); return
    if period == "today":
        rows = qall("SELECT u.full_name,a.checkin_time,a.checkout_time,a.work_minutes FROM attendance a JOIN users u ON a.tg_id=u.tg_id WHERE a.work_date=? ORDER BY a.checkin_time", (today_str(),))
        text = f"🕐 *Bugun — {now_dt().strftime('%d.%m.%Y')}*\n\n"
        if not rows: text += "📭 Hech kim kelmagan."
        else:
            for name,ci,co,mins in rows:
                st = "🟢" if not co else "✅"
                text += f"{st} *{name}*: {display_time(str(ci))} → {display_time(str(co) if co else None)} | {minutes_to_str(mins or 0)}\n"
    else:
        if period == "week": cutoff=(now_dt()-timedelta(days=7)).strftime("%Y-%m-%d"); filt=f"AND a.work_date>='{cutoff}'"; title="Haftalik"
        else: month=now_dt().strftime("%Y-%m"); filt=f"AND strftime('%Y-%m',a.work_date)='{month}'"; title="Oylik"
        rows = qall(f"SELECT u.tg_id,u.full_name,SUM(a.work_minutes),COUNT(DISTINCT a.work_date) FROM attendance a JOIN users u ON a.tg_id=u.tg_id WHERE a.checkout_time IS NOT NULL {filt} GROUP BY u.tg_id")
        text = f"📊 *{title}*\n\n"
        if not rows: text += "📭 Ma'lumot yo'q."
        else:
            for tg_id,name,total_mins,days in rows:
                salary = salary_for_minutes(tg_id, total_mins or 0)
                text += f"👤 *{name}*\n   📅 {days} kun | ⏱ {minutes_to_str(total_mins or 0)}"
                if salary: text += f" | 💰 {fmt_money(salary)}"
                text += "\n"
    bot.send_message(call.message.chat.id, text, parse_mode="Markdown")

