@bot.message_handler(func=lambda m: m.from_user.id in W_SAVDO_DATE)
def bsales_custom_date(message):
    tg_id = message.from_user.id
    state = W_SAVDO_DATE.get(tg_id)
    if not state or message.text in MENU_TEXTS:
        W_SAVDO_DATE.pop(tg_id, None); return
    try: dt = datetime.strptime(message.text.strip(), "%d.%m.%Y")
    except:
        bot.send_message(tg_id, "❌ Format: `DD.MM.YYYY`", parse_mode="Markdown"); return
    if state["step"] == "from":
        W_SAVDO_DATE[tg_id] = {"step": "to", "from": dt.strftime("%Y-%m-%d")}
        bot.send_message(tg_id, "📅 Tugash sanasi (`DD.MM.YYYY`):", parse_mode="Markdown")
    else:
        from_date = state["from"]; to_date = dt.strftime("%Y-%m-%d")
        W_SAVDO_DATE.pop(tg_id)
        df, dt_ = bito_range_utc(from_date, to_date)
        fd = datetime.strptime(from_date, "%Y-%m-%d").strftime("%d.%m.%Y")
        td_str = datetime.strptime(to_date, "%Y-%m-%d").strftime("%d.%m.%Y")
        title = f"Savdo: {fd} — {td_str}"
        bot.send_message(tg_id, "⏳ Bito'dan ma'lumot olinmoqda...")
        summary = bito_get_sales_summary(df, dt_)
        employees = bito_get_sales_by_employee(df, dt_)
        text = fmt_savdo_report(summary, employees, title)
        bot.send_message(tg_id, text, parse_mode="Markdown")

