@bot.message_handler(func=lambda m: m.from_user.id in W_PLAN)
def set_plan_value(message):
    if message.text in MENU_TEXTS: W_PLAN.pop(message.from_user.id,None); return
    mgr_id = message.from_user.id; mode = W_PLAN.pop(mgr_id)
    try:
        plan = float(message.text.strip().replace(" ","").replace(",",""))
        if mode == 'daily':
            # Kunlik plan
            q("INSERT OR REPLACE INTO daily_plan (plan_amount,plan_date,created_by,created_at) VALUES (?,?,?,?)",
              (plan,today_str(),mgr_id,now_str()))
            bot.send_message(message.chat.id, f"✅ *Bugungi kunlik plan belgilandi:*\n💰 {fmt_money(int(plan))}", parse_mode="Markdown")
            # Barcha hodim va adminlarga xabar
            daily_sales = get_daily_sales_total()
            pct = round(daily_sales/plan*100) if plan > 0 else 0
            bar = "█"*min(pct//10,10)+"░"*max(10-pct//10,0)
            msg = (f"📋 *Bugungi savdo plani belgilandi!*\n"
                   f"💰 *{fmt_money(int(plan))}*\n\n"
                   f"Hozirgi savdo: {fmt_money(int(daily_sales))}\n"
                   f"Bajarildi: *{pct}%* {bar}\n\nHarakatchan bo'laylik! 💪")
            for (uid,) in qall("SELECT tg_id FROM users WHERE role IN ('employee','manager','boss')"):
                try: bot.send_message(uid, msg, parse_mode="Markdown")
                except: pass
        else:
            # Oylik plan
            month = now_dt().strftime("%Y-%m")
            q("INSERT OR REPLACE INTO sales_plan (month,plan_amount,created_by,created_at) VALUES (?,?,?,?)", (month,plan,mgr_id,now_str()))
            bot.send_message(message.chat.id, f"✅ *Oylik reja belgilandi:*\n💰 {fmt_money(int(plan))}\n\n⏳ Bito'dan joriy savdo olinmoqda...", parse_mode="Markdown")
            # Bito'dan joriy oyning haqiqiy savdosini olamiz
            try:
                m_start = now_dt().replace(day=1).strftime("%Y-%m-%d")
                df_m, dt_m = bito_range_utc(m_start, today_str())
                bito_summary = bito_get_sales_summary(df_m, dt_m)
                month_sales = float((bito_summary or {}).get("gross_sales", 0) or 0)
            except:
                month_sales = float(get_month_sales() or 0)
            pct = round(month_sales/plan*100) if plan > 0 else 0
            bar = "█"*min(pct//10,10)+"░"*max(10-pct//10,0)
            msg = (f"🎯 *Oylik savdo rejasi belgilandi!*\n"
                   f"💰 Reja: *{fmt_money(int(plan))}*\n\n"
                   f"📊 Hozirgi: *{fmt_money(int(month_sales))}* ({pct}%)\n{bar}\n\nHarakatchan bo'laylik! 💪")
            for (uid,) in qall("SELECT tg_id FROM users WHERE role IN ('employee','manager','boss')"):
                try: bot.send_message(uid, msg, parse_mode="Markdown")
                except: pass
    except: bot.send_message(message.chat.id, "❌ Noto'g'ri raqam.")

@bot.callback_query_handler(func=lambda c: c.data.startswith("sales_") and c.data != "sales_set_plan")
def sales_report(call):
    _ack(call); period = call.data.replace("sales_","")
    if period == "today": filt = f"WHERE sale_date='{today_str()}'"; title = "Bugungi savdo"
    elif period == "week": cutoff=(now_dt()-timedelta(days=7)).strftime("%Y-%m-%d"); filt=f"WHERE sale_date>='{cutoff}'"; title="Haftalik savdo"
    else:
        month=now_dt().strftime("%Y-%m"); title="Oylik savdo"
        # Har kunning oxirgi savdosi yig'indisi
        rows = qall("""
            SELECT 'Jami' as emp, SUM(d.amount) as total, COUNT(DISTINCT d.sale_date) as days, 0, COUNT(*)
            FROM (SELECT sale_date, MAX(rowid) as last_id FROM daily_sales
                  WHERE strftime('%Y-%m', sale_date) = ? GROUP BY sale_date) t
            JOIN daily_sales d ON d.rowid = t.last_id
        """, (month,))
        tot = qone("""
            SELECT SUM(d.amount), COUNT(DISTINCT d.sale_date) FROM (
                SELECT sale_date, MAX(rowid) as last_id FROM daily_sales
                WHERE strftime('%Y-%m', sale_date) = ? GROUP BY sale_date
            ) t JOIN daily_sales d ON d.rowid = t.last_id
        """, (month,))
        filt = f"WHERE strftime('%Y-%m',sale_date)='{month}'"
    total_amt = float(tot[0] or 0); total_cust = int(tot[1] or 0)
    total_avg = round(total_amt/total_cust) if total_cust else 0
    text = f"💵 *{title}*\n\n"
    if not rows or (rows and not rows[0][1]): text += "📭 Ma'lumot yo'q."
    else:
        total_amt = float(tot[0] or 0) if tot and tot[0] else 0
        if period == "month":
            # Oylik: har kunlik savdo yig'indisi
            text += f"📅 *Oylik jami ({int(tot[1] or 0)} kun):*\n💰 *{fmt_money(int(total_amt))}*"
            plan = get_month_plan()
            if plan and float(plan) > 0:
                pct = round(total_amt/float(plan)*100); bar = "█"*min(pct//10,10)+"░"*max(10-pct//10,0)
                text += f"\n\n🎯 *Oylik reja: {pct}%*\n{bar}\n{fmt_money(int(total_amt))} / {fmt_money(int(plan))}"
            # Oxirgi 7 kunlik ko'rinish
            week_rows = qall("""
                SELECT d.sale_date, d.amount, d.entered_name FROM (
                    SELECT sale_date, MAX(rowid) as last_id FROM daily_sales
                    WHERE strftime('%Y-%m', sale_date) = ?
                    GROUP BY sale_date ORDER BY sale_date DESC LIMIT 7
                ) t JOIN daily_sales d ON d.rowid = t.last_id ORDER BY d.sale_date DESC
            """, (now_dt().strftime("%Y-%m"),))
            if week_rows:
                text += "\n\n📅 *Oxirgi kunlar:*\n"
                for date, amt, ename in week_rows:
                    d = datetime.strptime(date,"%Y-%m-%d").strftime("%d.%m") if len(date)==10 else date[:10]
                    text += f"  {d}: {fmt_money(int(amt))}\n"
        else:
            medals = ["🥇","🥈","🥉"]
            for i,(name,amt,cust,avg_chk,cnt) in enumerate(rows):
                medal = medals[i] if i<3 else "  "
                text += f"{medal} *{name}*\n   💰 {fmt_money(int(amt))}\n\n"
            text += f"━━━━━━━━━━━━\n💰 *Jami: {fmt_money(int(total_amt))}*"
    bot.send_message(call.message.chat.id, text, parse_mode="Markdown")

# Kunlik savdo
DAILY_SALE_TIMES = [("09:00","Ertalab (09:00)"),("15:00","Tushdan keyin (15:00)"),("00:20","Kecha yakuniy (00:20)")]

@bot.message_handler(func=lambda m: m.text == "💵 Kunlik savdo")
def kunlik_savdo(message):
    if not is_boss_or_mgr(message.from_user.id): return
    text = f"💵 *Bugungi savdo kiritmalari — {today_str()}*\n\n"
    rows = qall("SELECT period,amount,entered_name FROM daily_sales WHERE sale_date=? ORDER BY period", (today_str(),))
    entered = {r[0]:r for r in rows}; last_amount = 0
    for pt, pn in DAILY_SALE_TIMES:
        if pt in entered:
            _, amt, ename = entered[pt]; last_amount = float(amt)
            text += f"✅ *{pn}*\n   💰 {fmt_money(int(amt))} | {ename}\n\n"
        else: text += f"⏳ *{pn}* — kiritilmagan\n\n"
    if rows: text += f"━━━━━━━━━━━━\n💰 *Bugungi yakuniy savdo: {fmt_money(int(last_amount))}*"
    markup = types.InlineKeyboardMarkup()
    for pt, pn in DAILY_SALE_TIMES:
        if pt not in entered:
            markup.add(types.InlineKeyboardButton(f"➕ {pn}", callback_data=f"dsale_{pt}"))
    if markup.keyboard: bot.send_message(message.chat.id, text, parse_mode="Markdown", reply_markup=markup)
    else: bot.send_message(message.chat.id, text, parse_mode="Markdown")
@bot.callback_query_handler(func=lambda c: c.data.startswith("dsale_"))
def dsale_start(call):
    if not is_boss_or_mgr(call.from_user.id): return
