@bot.callback_query_handler(func=lambda c: c.data.startswith("quiz_"))
def handle_quiz(call):
    parts = call.data.split("_"); quiz_id = int(parts[1]); answer = parts[2]; tg_id = call.from_user.id
    u = get_user(tg_id)
    if not u: return
    try: q("INSERT INTO quiz_answers (quiz_id,tg_id,employee_name,answer,is_correct,answered_at) VALUES (?,?,?,?,0,?)", (quiz_id,tg_id,u[1],answer,now_str()))
    except:
        _ack(call, "Siz allaqachon javob bergansiz!"); return
    qz = qone("SELECT question,option_a,option_b,option_c,option_d,correct FROM quizzes WHERE id=?", (quiz_id,))
    if not qz: return
    opts = {'a':qz[1],'b':qz[2],'c':qz[3],'d':qz[4]}
    is_correct = 1 if answer == qz[5] else 0
    q("UPDATE quiz_answers SET is_correct=? WHERE quiz_id=? AND tg_id=?", (is_correct,quiz_id,tg_id))
    if is_correct: add_points(tg_id, u[1], 2)
    chosen = opts.get(answer,'')
    result = "✅ *To'g'ri javob!* +2 ball 🏆" if is_correct else f"❌ *Noto'g'ri!*\n✅ To'g'ri: *{opts[qz[5]]}*"
    _ack(call)
    try:
        bot.edit_message_text(f"🧠 *Test*\n\n❓ {qz[0]}\n\nJavobingiz: *{chosen}*\n\n{result}", call.message.chat.id, call.message.message_id, parse_mode="Markdown")
    except: pass
    for (aid,) in qall("SELECT tg_id FROM users WHERE role IN ('boss','manager')"):
        icon = "✅" if is_correct else "❌"
        try: bot.send_message(aid, f"{icon} *{u[1]}* test javob berdi\n{str(qz[0])[:50]}...\nJavob: *{chosen}* — {'To\'g\'ri' if is_correct else 'Noto\'g\'ri'}", parse_mode="Markdown")
        except: pass

# Excel
@bot.message_handler(func=lambda m: m.text == "📥 Excel")
def excel_download(message):
    if not is_boss_or_mgr(message.from_user.id): return
    wb = Workbook()
    ws1 = wb.active; ws1.title = "Vazifalar"
    for col, h in enumerate(["Sana","Xodim","Vazifa","Holat","Ball"],1):
        c=ws1.cell(1,col,h); c.font=Font(bold=True,color="FFFFFF")
        c.fill=PatternFill("solid",fgColor="2E7D32"); c.alignment=Alignment(horizontal="center")
    for row in qall("SELECT created_at,employee_name,task,status,score FROM tasks ORDER BY id DESC"): ws1.append(list(row))
    ws2 = wb.create_sheet("Davomat")
    for col, h in enumerate(["Sana","Xodim","Kelish","Ketish","Ishlagan","Haq"],1):
        c=ws2.cell(1,col,h); c.font=Font(bold=True,color="FFFFFF")
        c.fill=PatternFill("solid",fgColor="1565C0"); c.alignment=Alignment(horizontal="center")
    for date,name,ci,co,mins,rate in qall("SELECT a.work_date,u.full_name,a.checkin_time,a.checkout_time,a.work_minutes,u.hourly_rate FROM attendance a JOIN users u ON a.tg_id=u.tg_id ORDER BY a.work_date DESC"):
        ws2.append([date,name,display_time(str(ci)),display_time(str(co) if co else None),minutes_to_str(mins or 0),round((rate or 0)*(mins or 0)/60)])
    ws3 = wb.create_sheet("Savdo")
    for col, h in enumerate(["Sana","Xodim","Jami","Mijozlar","O'rtacha chek"],1):
        c=ws3.cell(1,col,h); c.font=Font(bold=True,color="FFFFFF")
        c.fill=PatternFill("solid",fgColor="E65100"); c.alignment=Alignment(horizontal="center")
    for row in qall("SELECT sale_date,employee_name,amount,customer_count,avg_check FROM sales ORDER BY sale_date DESC"): ws3.append(list(row))
    ws4 = wb.create_sheet("Shikoyatlar")
    for col, h in enumerate(["Sana","Xodim","Shikoyat"],1):
        c=ws4.cell(1,col,h); c.font=Font(bold=True,color="FFFFFF")
        c.fill=PatternFill("solid",fgColor="B71C1C"); c.alignment=Alignment(horizontal="center")
    for row in qall("SELECT created_at,from_name,complaint FROM complaints ORDER BY id DESC"): ws4.append(list(row))
    for ws in [ws1,ws2,ws3,ws4]:
        for col in ws.columns:
            mx = max((len(str(c.value or "")) for c in col), default=10)
            ws.column_dimensions[col[0].column_letter].width = min(mx+4, 40)
    path = "/tmp/hisobot.xlsx" if os.path.exists("/tmp") else "hisobot.xlsx"
    wb.save(path)
    with open(path,"rb") as f:
        bot.send_document(message.chat.id, f, caption=f"📊 To'liq hisobot — {now_dt().strftime('%d.%m.%Y %H:%M')}")

# Sozlamalar
@bot.message_handler(func=lambda m: m.text == "⚙️ Sozlamalar")
def sozlamalar(message):
    if get_role(message.from_user.id) != 'boss': return
    _show_settings(message.chat.id)

def _settings_vals():
    """Sozlamalar qiymatlari — bo'lim ekranlari uchun bitta joydan."""
    v = {}
    # Yangi tenantda settings bo'sh — nomni markaziy bazadan olamiz
    # (CFG.SHOP_NAME = tenants.name). Boshliq 🏪 Do'kon nomi orqali
    # o'zgartirsa, settings dagi qiymat ustun turadi.
    v["sn"]=get_setting("shop_name", CFG.SHOP_NAME); v["ot"]=get_setting("shop_open_time","09:00")
    v["ct"]=get_setting("shop_close_time","21:00"); v["r"]=get_setting("gps_radius","200")
    v["tt"]=get_setting("tips_time","10:00"); v["lt"]=get_setting("late_check_time","10:30")
    v["qe"]=get_setting("quiz_enabled","1"); v["ce"]=get_setting("chat_enabled","1")
    v["br"]=get_bito_bonus_rate()
    v["sae"]=get_setting("stock_alert_enabled","1")
    v["stimes"]=get_setting("stock_alert_times","09:00")
    v["stop_n"]=get_setting("stock_top_count","30")
    v["sdays"]=get_setting("stock_days_threshold","1")
    sroles=get_setting("stock_alert_roles","boss,manager")
    v["sroles_str"]=sroles.replace("boss","Boshliq").replace("manager","Menejer")
    v["ert"]=get_setting("emp_report_time","18:00")
    v["pv"]=get_point_value()
    v["pec"]=get_attn_setting_int("pt_early_checkin",1); v["plc"]=get_attn_setting_int("pt_late_checkin",-2)
    v["peo"]=get_attn_setting_int("pt_early_checkout",-2); v["plo"]=get_attn_setting_int("pt_late_checkout",1)
    v["atol"]=get_attn_setting_int("attendance_tolerance_min",5)
    v["otol"]=get_attn_setting_int("overtime_tolerance_min",15)
    v["aat"]=get_setting("ai_advice_times","10:00,17:00")
    v["aae"]=get_setting("ai_advice_enabled","1")
    return v


def _show_settings(chat_id, edit_message_id=None):
    """⚙️ Sozlamalar — bo'limlarga ajratilgan bosh ekran (2026-08-09
    tartiblandi: 24 ta tugma yig'ilib 4 bo'limga bo'lindi)."""
    v = _settings_vals()
    onoff = lambda x: "✅" if x == "1" else "❌"
    text = ("⚙️ *Sozlamalar*\n\n"
            f"🏪 *{v['sn']}* · {v['ot']}—{v['ct']} · GPS {v['r']}m\n"
            f"🧠 Test {onoff(v['qe'])} · 💬 Chat {onoff(v['ce'])} · "
            f"🤖 AI tavsiya {onoff(v['aae'])} · 📦 Ombor {onoff(v['sae'])}\n\n"
            "Bo'limni tanlang:")
    markup = types.InlineKeyboardMarkup(row_width=1)
    markup.add(types.InlineKeyboardButton("🏪 Do'kon sozlamalari",
                                          callback_data="set_cat_shop"),
               types.InlineKeyboardButton("👥 Xodimlar va ballar",
                                          callback_data="set_cat_emp"),
               types.InlineKeyboardButton("🤖 AI va eslatmalar",
                                          callback_data="set_cat_ai"),
               types.InlineKeyboardButton("🎛 Interfeys va boshqa",
                                          callback_data="set_cat_other"))
    if edit_message_id:
        try:
            bot.edit_message_text(text, chat_id, edit_message_id,
                                  parse_mode="Markdown", reply_markup=markup)
            return
        except Exception:
            pass
    bot.send_message(chat_id, text, parse_mode="Markdown", reply_markup=markup)


