W_STOCK_SEARCH = TDict()  # tg_id -> "search" yoki ("min_qty", product_id, product_name)

def _show_stock_menu(chat_id):
    rows = qall("SELECT product_id, product_name, min_qty FROM stock_alerts ORDER BY product_name")
    sae = get_setting("stock_alert_enabled","1")
    sat = get_setting("stock_alert_time","09:00")
    sae_lbl = '✅ Yoqilgan' if sae=='1' else "❌ O'chirilgan"
    text = f'📦 <b>Ombor eslatmasi</b>\nVaqt: <b>{sat}</b> | Holat: {sae_lbl}\n\n'
    if rows:
        for pid, pname, min_qty in rows:
            text += f"• <b>{h(pname)}</b> — chegara: {min_qty:.0f} ta\n"
    else:
        text += "Hali hech qanday mahsulot qo'shilmagan.\n"
    markup = types.InlineKeyboardMarkup()
    markup.add(types.InlineKeyboardButton("➕ Mahsulot qo'shish", callback_data="stock_add"))
    if rows:
        markup.add(types.InlineKeyboardButton("🗑 Mahsulot o'chirish", callback_data="stock_remove_list"))
        markup.add(types.InlineKeyboardButton("📋 Hozir tekshirish", callback_data="stock_check_now"))
    markup.add(types.InlineKeyboardButton(
        "🔕 O'chirish" if sae=="1" else "🔔 Yoqish", callback_data="stock_toggle"))
    bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=markup)

@bot.callback_query_handler(func=lambda c: c.data.startswith("stock_"))
def stock_cb(call):
    if get_role(call.from_user.id) not in ('boss','manager'):
        _ack(call, "Ruxsat yo'q!"); return
    _ack(call)
    action = call.data
    if action == "stock_add":
        W_STOCK_SEARCH[call.from_user.id] = "search"
        bot.send_message(call.message.chat.id, "🔍 Mahsulot nomini yozing (masalan: Cola, Fanta):")
    elif action == "stock_remove_list":
        rows = qall("SELECT product_id, product_name FROM stock_alerts ORDER BY product_name")
        markup = types.InlineKeyboardMarkup()
        for pid, pname in rows:
            markup.add(types.InlineKeyboardButton(f"🗑 {pname}", callback_data=f"stock_del_{pid}"))
        bot.send_message(call.message.chat.id, "Qaysi mahsulotni o'chirish?", reply_markup=markup)
    elif action.startswith("stock_del_"):
        pid = action.replace("stock_del_","")
        row = qone("SELECT product_name FROM stock_alerts WHERE product_id=?", (pid,))
        q("DELETE FROM stock_alerts WHERE product_id=?", (pid,))
        pname = row[0] if row else pid
        bot.send_message(call.message.chat.id, f"✅ <b>{h(pname)}</b> kuzatuvdan olib tashlandi.", parse_mode="HTML")
    elif action == "stock_toggle":
        cur = get_setting("stock_alert_enabled","1")
        set_setting("stock_alert_enabled", "0" if cur=="1" else "1")
        _show_stock_menu(call.message.chat.id)
    elif action.startswith("stock_pick_"):
        # Admin mahsulot tanladi, endi minimal miqdorni so'raymiz
        parts = action.split("_", 3)  # stock_pick_<pid>_<pname>
        pid = parts[2]; pname = parts[3] if len(parts)>3 else "?"
        W_STOCK_SEARCH[call.from_user.id] = ("min_qty", pid, pname)
        bot.send_message(call.message.chat.id,
            f"📦 <b>{h(pname)}</b> uchun minimal qoldiq miqdorini yozing:\n"
            f"(masalan: 10 — 10 ta va undan kam qolganda eslatadi, 0 — faqat tugaganda)", parse_mode="HTML")
    elif action == "stock_check_now":
        bot.send_message(call.message.chat.id, "⏳ Bito'dan qoldiqlar tekshirilmoqda...")
        check_and_send_stock_alerts()
        bot.send_message(call.message.chat.id, "✅ Tekshirish yakunlandi. Agar kamaygan mahsulotlar bo'lsa, yuqorida xabar kelgan bo'ladi.")

@bot.message_handler(func=lambda m: m.from_user.id in W_STOCK_SEARCH and m.from_user.id not in W_SETTING)
def handle_stock_search(message):
    tg_id = message.from_user.id
    state = W_STOCK_SEARCH.get(tg_id)
    if not state or message.text in MENU_TEXTS:
        W_STOCK_SEARCH.pop(tg_id, None); return

    if state == "search":
        query = message.text.strip()
        bot.send_message(message.chat.id, f"⏳ Bito'dan qidirilmoqda: <b>{h(query)}</b>...", parse_mode="HTML")
        results = bito_search_products(query, limit=8)
        if not results:
            bot.send_message(message.chat.id, "❌ Hech narsa topilmadi. Boshqa nom bilan qidiring.")
            return
        markup = types.InlineKeyboardMarkup()
        for it in results:
            pid = it.get("_id","")
            pname = it.get("name","?")
            qty = it.get("amount", it.get("in_stock", 0)) or 0
            label = f"{pname} ({qty:.0f} ta)"
            # callback_data max 64 belgi — pname ni qisqartiramiz
            short_name = pname[:30] if len(pname) > 30 else pname
            markup.add(types.InlineKeyboardButton(label, callback_data=f"stock_pick_{pid}_{short_name}"))
        bot.send_message(message.chat.id, f"Topildi — qaysi mahsulotni qo'shamiz?",
                         reply_markup=markup)
        W_STOCK_SEARCH.pop(tg_id)

    elif isinstance(state, tuple) and state[0] == "min_qty":
        _, pid, pname = state
        try:
            min_qty = float(message.text.strip().replace(",","."))
        except:
            bot.send_message(message.chat.id, "❌ Faqat raqam kiriting (masalan: 10)"); return
        q("INSERT OR REPLACE INTO stock_alerts (product_id,product_name,min_qty,created_by,created_at) VALUES (?,?,?,?,?)",
          (pid, pname, min_qty, tg_id, now_str()))
        W_STOCK_SEARCH.pop(tg_id)
        bot.send_message(message.chat.id,
            f"✅ Qo'shildi!\n📦 <b>{h(pname)}</b>\n📊 Chegara: <b>{min_qty:.0f} ta</b>\n\n"
            f"Har kuni soat <b>{get_setting('stock_alert_time','09:00')}</b> da tekshiriladi.",
            parse_mode="HTML")
# ===== OMBOR ESLATMASI TUGADI =====

@bot.message_handler(func=lambda m: m.from_user.id in W_SETTING)
def handle_setting(message):
    if message.text in MENU_TEXTS: W_SETTING.pop(message.from_user.id,None); return
    mgr_id = message.from_user.id; key = W_SETTING.pop(mgr_id); value = message.text.strip()
    if "time" in key and key not in ("stock_alert_times", "emp_report_time", "ai_advice_times"):
        try: datetime.strptime(value, "%H:%M")
        except: bot.send_message(message.chat.id, "❌ Format: `HH:MM`", parse_mode="Markdown"); return
    if key == "gps_radius":
        try: int(value)
        except: bot.send_message(message.chat.id, "❌ Faqat raqam."); return
    if key == "bito_bonus_rate":
        try: float(value.replace(",", "."))
        except: bot.send_message(message.chat.id, "❌ Masalan: `0.005` (0.5% uchun)."); return
        value = value.replace(",", ".")
    if key == "stale_bonus_rate":
        try: float(value.replace(",", "."))
        except: bot.send_message(message.chat.id, "❌ Masalan: `0.02` (2% uchun)."); return
        value = value.replace(",", ".")
    if key == "stock_top_count":
        try:
            n = int(value)
            if not 10 <= n <= 200: raise ValueError
        except: bot.send_message(message.chat.id, "❌ 10 dan 200 gacha raqam kiriting."); return
    if key == "stock_days_threshold":
        try: float(value.replace(",","."))
        except: bot.send_message(message.chat.id, "❌ Raqam kiriting (masalan: 1 yoki 1.5)."); return
        value = value.replace(",",".")
    if key == "stock_alert_times":
        import re as _re
        times = [t.strip() for t in _re.split(r'[,\s]+', value.strip()) if t.strip()]
        for t in times:
            try: datetime.strptime(t, "%H:%M")
            except:
                bot.send_message(message.chat.id, f"❌ Noto'g'ri vaqt: `{t}`. Format: HH:MM (masalan: `07:00,22:00`)"); return
        value = ",".join(times)
    if key == "emp_report_time":
        import re as _re
        times = [t.strip() for t in _re.split(r'[,\s]+', value.strip()) if t.strip()]
        for t in times:
            try: datetime.strptime(t, "%H:%M")
            except:
                bot.send_message(message.chat.id, f"❌ Noto'g'ri vaqt: `{t}`. Format: HH:MM (masalan: `12:00,16:00,19:00`)"); return
        value = ",".join(times)
    if key == "ai_advice_times":
        import re as _re
        times = [t.strip() for t in _re.split(r'[,\s]+', value.strip()) if t.strip()]
        for t in times:
            try: datetime.strptime(t, "%H:%M")
            except:
                bot.send_message(message.chat.id, f"❌ Noto'g'ri vaqt: `{t}`. Format: HH:MM (masalan: `10:00,17:00`)"); return
        value = ",".join(times)
    if key == "point_value_som":
        try:
            pv = float(value.replace(" ","").replace(",","."))
            if pv < 0: raise ValueError
        except: bot.send_message(message.chat.id, "❌ Raqam kiriting (masalan: 1000)."); return
        value = str(pv)
    if key in ("pt_early_checkin","pt_late_checkin","pt_early_checkout","pt_late_checkout"):
        try: pt = int(float(value.replace(" ","").replace(",",".")))
        except: bot.send_message(message.chat.id, "❌ Butun son kiriting (manfiy bo'lishi ham mumkin, masalan: -2)."); return
        value = str(pt)
    if key == "attendance_tolerance_min":
        try:
            tol = int(float(value.replace(" ","").replace(",",".")))
            if tol < 0: raise ValueError
        except: bot.send_message(message.chat.id, "❌ Musbat butun son kiriting (masalan: 5)."); return
        value = str(tol)
    if key == "overtime_tolerance_min":
        try:
            tol2 = int(float(value.replace(" ","").replace(",",".")))
            if tol2 < 0: raise ValueError
        except: bot.send_message(message.chat.id, "❌ Musbat butun son kiriting (masalan: 15)."); return
        value = str(tol2)
    set_setting(key, value)
    bot.send_message(message.chat.id, f"✅ Yangilandi: *{value}*", parse_mode="Markdown")
    _show_settings(message.chat.id)

