@bot.message_handler(func=lambda m: m.text == "📋 Vazifa tarixi")
def task_history(message):
    tg_id = message.from_user.id; role = get_role(tg_id)
    if role not in ('boss','manager','employee'): return
    markup = types.InlineKeyboardMarkup()
    if role in ('boss','manager'):
        markup.add(types.InlineKeyboardButton("📊 Barcha vazifalar", callback_data="th_all"))
        for eid, ename in qall("SELECT tg_id,full_name FROM users WHERE role IN ('employee','manager') ORDER BY full_name"):
            markup.add(types.InlineKeyboardButton(ename, callback_data=f"th_{eid}"))
        bot.send_message(message.chat.id, "📋 Kim uchun vazifa tarixi?", reply_markup=markup)
    else:
        _show_task_history(message.chat.id, tg_id, tg_id)

def _show_task_history(chat_id, viewer_id, target_id):
    rows = qall("SELECT id,task,status,score,created_at,photo_file_id FROM tasks WHERE employee_tg_id=? ORDER BY id DESC LIMIT 20", (target_id,))
    u = get_user(target_id)
    title = u[1] if u else str(target_id)
    if not rows:
        bot.send_message(chat_id, f"📭 *{title}* uchun vazifalar yo'q."); return
    text = f"📋 *{title} — Vazifa tarixi*\n\n"
    markup = types.InlineKeyboardMarkup()
    for task_id, task_text, status, score, created_at, photo_id in rows:
        d = str(created_at)[:10]; short = task_text[:40]+"..." if len(task_text)>40 else task_text
        status_icon = {"✅ To'liq bajarildi":"✅","🟡 Chala bajarildi":"🟡","❌ Bajarilmadi":"❌","Jarayonda":"⏳"}.get(status,"⏳")
        text += f"{status_icon} *{short}*\n   📅 {d} | {status}\n"
        if photo_id:
            markup.add(types.InlineKeyboardButton(f"🖼 {short[:25]}", callback_data=f"th_photo_{task_id}"))
    bot.send_message(chat_id, text, parse_mode="Markdown", reply_markup=markup if markup.keyboard else None)

@bot.callback_query_handler(func=lambda c: c.data.startswith("th_"))
def task_history_cb(call):
    _ack(call)
    data = call.data.replace("th_","")
    if data == "all":
        rows = qall("SELECT id,employee_name,task,status,score,created_at FROM tasks ORDER BY id DESC LIMIT 30")
        text = "📋 *Barcha vazifalar:*\n\n"
        if not rows: text += "📭 Vazifalar yo'q."
        else:
            for task_id,emp_name,task_text,status,score,created_at in rows:
                d = str(created_at)[:10]; short = task_text[:35]+"..." if len(task_text)>35 else task_text
                icons = {"✅ To'liq bajarildi":"✅","🟡 Chala bajarildi":"🟡","❌ Bajarilmadi":"❌","Jarayonda":"⏳"}
                text += f"{icons.get(status,'⏳')} *{emp_name}*: {short}\n   📅 {d}\n"
        bot.send_message(call.message.chat.id, text, parse_mode="Markdown")
    elif data.startswith("photo_"):
        task_id = int(data.replace("photo_",""))
        task = qone("SELECT photo_file_id,task,status FROM tasks WHERE id=?", (task_id,))
        if task and task[0]:
            try: bot.send_photo(call.message.chat.id, task[0], caption=f"📋 {task[1]}\n\nHolat: {task[2]}")
            except: bot.send_message(call.message.chat.id, "⚠️ Rasmni yuklashda xato.")
    else:
        try:
            target_id = int(data)
            _show_task_history(call.message.chat.id, call.from_user.id, target_id)
        except: pass

