# ===== MARKETING TAHLIL (Claude AI) =====
def get_marketing_analysis():
    """✅ TUZATILGAN: Bito'dan ma'lumot olib, Claude AI orqali marketing tahlil qiladi."""
    try:
        if not CFG.BITO_ORG_ID:
            print("ERR: CFG.BITO_ORG_ID aniqlanmagan!", flush=True)
            return None
        
        headers_bito = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
        today = now_dt()
        month_start = today.replace(day=1).strftime("%Y-%m-%d")
        week_start = (today - timedelta(days=6)).strftime("%Y-%m-%d")
        import datetime as _dt
        def to_utc(d): return _dt.datetime.strptime(d,"%Y-%m-%d").replace(tzinfo=UZT).astimezone(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")

        # 1. Oylik top mahsulotlar
        r1 = requests.post(BITO_BASE_URL + "sales/by-item-pagin",
            json={"page":1,"limit":20,"from_date":to_utc(month_start),"organization_ids":[CFG.BITO_ORG_ID]},
            headers=headers_bito, timeout=60)
        r1.raise_for_status()
        j1 = r1.json()
        top_items = (j1.get("data",{}) or {}).get("data",[]) or []

        # 2. Xodimlar bo'yicha (haftalik)
        r2 = requests.post(BITO_BASE_URL + "reports/dashboard/top/responsible",
            json={"from_date":to_utc(week_start),"to_date":to_utc(today.strftime("%Y-%m-%d"))},
            headers=headers_bito, timeout=20)
        r2.raise_for_status()
        j2 = r2.json()
        d2 = j2.get("data",{})
        emps = d2.get("data",d2.get("list",[])) if isinstance(d2,dict) else d2

        # Ma'lumotlarni formatlash
        products_text = ""
        for it in top_items[:15]:
            if not isinstance(it,dict): continue
            name = it.get("product_name","?")
            gross = it.get("gross_sales",0) or 0
            cost = it.get("cost",0) or 0
            sold = it.get("items_sold",0) or 0
            profit = it.get("profit",0) or 0
            margin = round(profit/gross*100,1) if gross>0 else 0
            products_text += f"- {name}: savdo={fmt_money(gross)}, sotildi={sold:.0f}, marja={margin}%, foyda={fmt_money(profit)}\n"

        emps_text = ""
        for e in emps:
            if not isinstance(e,dict): continue
            resp = e.get("responsible",{}) or {}
            name = resp.get("full_name","?")
            g = e.get("gross_sales",0) or 0
            rc = e.get("receipts",0) or 0
            pr = e.get("profit",0) or 0
            avg = round(g/rc) if rc>0 else 0
            emps_text += f"- {name}: savdo={fmt_money(g)}, cheklar={rc}, o'rtacha chek={fmt_money(avg)}, foyda={fmt_money(pr)}\n"

        prompt = f"""Sen Bonnu Market do'konining marketing maslahatchiasisn. Quyidagi haqiqiy savdo ma'lumotlari asosida aniq, amaliy marketing tavsiyalar ber. Faqat raqamlarga asoslangan, lo'nda va amaliy bo'lsin.

Bugungi sana: {today.strftime('%d.%m.%Y')}

TOP 15 MAHSULOT (bu oy):
{products_text}

XODIMLAR (so'nggi 7 kun):
{emps_text}

Quyidagilarni tahlil qil va tavsiya ber (O'zbek tilida, qisqa va aniq):
1. Qaysi 2-3 mahsulotni ZUDLIK BILAN narxini o'zgartirish kerak va nima qilish kerak (zarar/past marja)
2. Qaysi mahsulotni stokini ko'paytirish kerak (ko'p sotilayotgan + yaxshi marja)
3. Xodimlar bo'yicha: kim yaxshi, kim yaxshilanishi kerak va qanday
4. Bugun amalga oshirish mumkin bo'lgan 1 ta aniq marketing tavsiya

Har bir tavsiyada aniq raqam bo'lsin. Maksimal 300 so'z."""

        # Gemini API ga yuborish
        api_key = GEMINI_API_KEY or ANTHROPIC_API_KEY
        if GEMINI_API_KEY:
            resp = requests.post(
                f"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={GEMINI_API_KEY}",
                headers={"content-type": "application/json"},
                json={"contents": [{"parts": [{"text": prompt}]}],
                      "generationConfig": {"maxOutputTokens": 1024, "temperature": 0.7}},
                timeout=60
            )
            resp.raise_for_status()
            result = resp.json()
            text = result.get("candidates", [{}])[0].get("content", {}).get("parts", [{}])[0].get("text", "Tahlil olinmadi.")
        else:
            resp = requests.post(
                "https://api.anthropic.com/v1/messages",
                headers={"x-api-key": ANTHROPIC_API_KEY,
                         "anthropic-version": "2023-06-01",
                         "content-type": "application/json"},
                json={"model": "claude-sonnet-4-6",
                      "max_tokens": 1024,
                      "messages": [{"role": "user", "content": prompt}]},
                timeout=60
            )
            resp.raise_for_status()
            result = resp.json()
            text = result.get("content", [{}])[0].get("text", "Tahlil olinmadi.")
        return f"🤖 *Marketing tahlil — {today.strftime('%d.%m.%Y')}*\n\n{text}"
    except Exception as e:
        print("MARKETING ERR:", str(e)[:200], flush=True)
        return None

def marketing_thread():
    """Har kuni belgilangan vaqtda marketing tahlil yuboradi."""
    SEND_TIME = "08:00"
    sent_today = set()
    last_date = today_str()
    while True:
        try:
            cur = today_str()
            if cur != last_date:
                sent_today = set()
                last_date = cur
            ct = now_dt().strftime("%H:%M")
            if ct == SEND_TIME and ct not in sent_today:
                sent_today.add(ct)
                text = get_marketing_analysis()
                if text:
                    for (uid,) in qall("SELECT tg_id FROM users WHERE role='boss'"):
                        try: bot.send_message(uid, text, parse_mode="Markdown")
                        except Exception as e: print("MKT SEND ERR:", str(e)[:100], flush=True)
        except Exception as e:
            print("MARKETING THREAD ERR:", str(e)[:150], flush=True)
        time.sleep(30)

_boot_thread(marketing_thread, module="marketing")

