# ══════════════════════════════════════════════════════════════════
# 📦 INVENTARIZATSIYA TAHLILI
#
# Bito'da inventarizatsiya (revision) YOZISH ishlamaydi — tekshirilgan:
# `revision/update` 200 qaytaradi, lekin mahsulot qo'shmaydi (12 xil
# variant sinaldi). Shuning uchun SANASH Bito ilovasida qoladi, bot esa
# TAHLIL beradi: qayerda pul qotgan, qaysi qoldiq soxta, nima sotilmayapti.
#
# ⚠️ BITO SARALASHI — endpointga qarab TURLICHA ishlaydi:
#   sales/by-item-pagin          → sort_by + sort_order   ✅ ishlaydi
#   .../product/chart-paging     → `sort` → 400 xato      ❌
#   product-warehouse/get-paging → `sort` qabul qiladi, lekin JIM
#                                   E'TIBORSIZ QOLDIRADI (jonli sinaldi)
# Shuning uchun qoldiq saralashi HAR DOIM kodda qilinadi.
#
# Javob ochish uchun mavjud _bito_rows() ishlatiladi (u total qaytarmaydi,
# shuning uchun sahifalash "to'liq bo'lmagan sahifa = oxiri" bo'yicha).
# ══════════════════════════════════════════════════════════════════

INV_FAKE_MIN, INV_FAKE_MAX = 1900.0, 2100.0   # qo'lda qo'yilgan soxta ~2000
INV_SUSPECT_LINE_VALUE = 200_000_000          # bitta qatorda 200 mln+
INV_SUSPECT_UNIT_COST = 1_000_000             # birlik tannarxi 1 mln+
INV_SUSPECT_BIG_QTY = 1000                    # 1000+ qoldiq
INV_PAGE_LIMIT = 200                          # Bito maksimumi
INV_MAX_PAGES = 60                            # 200×60 = 12 000 qator
INV_COVER_DAYS = 90                           # qoldiq shuncha kunga yetsa — ortiqcha

INV_CACHE = TDict(template={"stock": None, "sold": None, "sum": None, "ts": 0})


def inv_post(path, body, timeout=40):
    """Bito'ga POST. Xatoda None."""
    try:
        r = requests.post(BITO_BASE_URL + path, json=body,
                          headers={"api-key": CFG.BITO_API_KEY,
                                   "Content-Type": "application/json"},
                          timeout=timeout)
        r.raise_for_status()
        return r.json()
    except Exception as e:
        print(f"INV POST ERR [{path}]: {str(e)[:200]}", flush=True)
        return None


def inv_fetch_stock():
    """Butun ombor qoldig'i: [{id, name, amount, unit, cost, value}, ...]

    ⚠️ TUZATISH TARIXI (2026-08-01): dastlab bitta manzil qattiq yozilgan
    edi va "qoldiq olinmadi" xatosi chiqdi. Ildiz sabab: Bito manzillari
    izchil emas (`-pagin`/`-paging`), MCP'da ishlagan yo'l to'g'ridan-to'g'ri
    API'da ishlamasligi mumkin. Endi mavjud _bito_try_paths() ishlatiladi —
    bito_stock_and_cost() bilan BIR XIL kalit ("bito_stockcost_endpoint"),
    shuning uchun u topib saqlagan ishlaydigan manzildan darhol foydalanadi.

    Server saralashni qo'llab-quvvatlamagani uchun hamma sahifa tortiladi.
    """
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    cands = ["reports/dashboard/summary/product/chart-pagin",
             "reports/dashboard/summary/product/chart-paging",
             "reports/dashboard/summary/product/pagin",
             "reports/dashboard/summary/product/paging",
             "reports/pos/summary/product/chart-pagin",
             "reports/pos/summary/product/chart-paging"]
    out, page = [], 1
    while page <= INV_MAX_PAGES:
        j, _p = _bito_try_paths("bito_stockcost_endpoint", cands,
                                {"page": page, "limit": INV_PAGE_LIMIT,
                                 "organization_ids": [CFG.BITO_ORG_ID]},
                                headers, "INV STOCK")
        if j is None:
            break
        items = _bito_rows(j)
        if not items:
            break
        for it in items:
            if not isinstance(it, dict):
                continue
            measure = it.get("measure") or {}
            amount = float(it.get("in_stock") or it.get("amount") or 0)
            cost = float(it.get("cost") or 0)
            # total_cost ba'zi manzil variantlarida kelmasligi mumkin —
            # bo'lmasa o'zimiz hisoblaymiz
            value = float(it.get("total_cost") or 0) or (amount * cost)
            out.append({
                "id": it.get("_id"),
                "name": (it.get("name") or "?").strip(),
                "amount": amount,
                "unit": measure.get("short_name") or "?",
                "measure_id": measure.get("_id") or it.get("measure_id"),
                "cost": cost,
                "value": value,
            })
        if len(items) < INV_PAGE_LIMIT:   # to'liq bo'lmagan sahifa = oxiri
            break
        page += 1
        time.sleep(0.15)
    return out


def inv_fetch_sold(days=30):
    """N kunda sotilgan mahsulotlar: {product_id: miqdor}.

    DIQQAT: bu endpoint SOTILMAGANLARNI qaytarmaydi — ularni katalogdan
    ayirib topamiz.
    """
    period_start = (now_dt() - timedelta(days=days)).strftime("%Y-%m-%d")
    frm, to = bito_range_utc(period_start, today_str())
    sold, page = {}, 1
    while page <= INV_MAX_PAGES:
        j = inv_post("sales/by-item-pagin",
                     {"page": page, "limit": 300, "from_date": frm,
                      "to_date": to, "organization_ids": [CFG.BITO_ORG_ID]})
        if j is None:
            break
        items = _bito_rows(j)
        if not items:
            break
        for it in items:
            if isinstance(it, dict):
                pid = it.get("product_id") or it.get("_id")
                if pid:
                    sold[pid] = float(it.get("items_sold") or 0)
        if len(items) < 300:              # to'liq bo'lmagan sahifa = oxiri
            break
        page += 1
        time.sleep(0.15)
    return sold


def inv_find_fake(stock):
    """Soxta ~2000 qoldiqlar — minusga sotmaslik uchun qo'lda qo'yilgan."""
    return sorted([p for p in stock if INV_FAKE_MIN <= p["amount"] <= INV_FAKE_MAX],
                  key=lambda p: -p["value"])


def inv_find_dead(stock, sold, skip_ids=None):
    """Qotgan pul: qoldig'i bor, davr ichida umuman sotilmagan.

    Soxta qoldiqlar CHETLAB O'TILADI — ular real pul emas, fantom.
    Qo'shsak "omborda qotgan pul" summasi soxta ravishda shishadi.
    """
    skip = skip_ids or set()
    return sorted([p for p in stock
                   if p["amount"] > 0 and p["value"] > 0
                   and p["id"] not in skip and sold.get(p["id"], 0) == 0],
                  key=lambda p: -p["value"])


def inv_find_slow(stock, sold, days=30):
    """Sekin aylanadigan: sotilyapti, lekin qoldiq 90+ kunga yetadi."""
    out = []
    for p in stock:
        qty = sold.get(p["id"], 0)
        if p["amount"] <= 0 or qty <= 0:
            continue
        per_day = qty / float(days)
        cover = p["amount"] / per_day if per_day > 0 else 9999
        if cover >= INV_COVER_DAYS:
            out.append(dict(p, cover=int(cover), sold=qty))
    return sorted(out, key=lambda p: -p["value"])


def inv_find_suspect(stock):
    """Shubhali tannarx — ombor qiymatini shishirayotgan qatorlar.

    Misol: 13 999 dona × 125 000 = 1.7 mlrd — kiritishda xato bo'lgan.
    """
    hits = []
    for p in stock:
        why = []
        if p["value"] >= INV_SUSPECT_LINE_VALUE:
            why.append("qator qiymati juda katta")
        if p["cost"] >= INV_SUSPECT_UNIT_COST:
            why.append("birlik tannarxi yuqori")
        if p["amount"] >= INV_SUSPECT_BIG_QTY and p["cost"] >= 50_000:
            why.append("ko'p miqdor × qimmat tannarx")
        if why:
            hits.append(dict(p, why=", ".join(why)))
    return sorted(hits, key=lambda p: -p["value"])


def inv_summarize(stock, sold, days=30):
    positive = [p for p in stock if p["amount"] > 0]
    fake = inv_find_fake(stock)
    dead = inv_find_dead(stock, sold, skip_ids={p["id"] for p in fake})
    return {
        "days": days,
        "qoldiqli": len(positive),
        "minus": len([p for p in stock if p["amount"] < 0]),
        "soxta": fake,
        "qotgan_pul": dead,
        "sekin": inv_find_slow(stock, sold, days=days),
        "shubhali": inv_find_suspect(stock),
        "qotgan_summa": sum(p["value"] for p in dead),
        "soxta_summa": sum(p["value"] for p in fake),
    }


def inv_money(n):
    return f"{int(round(n)):,}".replace(",", " ")


def inv_line(i, p, extra=""):
    amt = f"{p['amount']:.3f}".rstrip("0").rstrip(".")
    return (f"{i}. {p['name'][:38]}\n   {amt} {p['unit']} × "
            f"{inv_money(p['cost'])} = <b>{inv_money(p['value'])}</b>{extra}")


def inv_render_summary(s):
    return "\n".join([
        "📦 <b>INVENTARIZATSIYA TAHLILI</b>",
        f"Davr: oxirgi {s['days']} kun\n",
        f"Qoldig'i bor: <b>{s['qoldiqli']}</b> ta",
        f"Minus qoldiq: {s['minus']} ta (hisobga olinmadi)\n",
        f"🧊 Qotgan pul: <b>{inv_money(s['qotgan_summa'])}</b> so'm "
        f"({len(s['qotgan_pul'])} ta)",
        f"🎭 Soxta qoldiq: {len(s['soxta'])} ta "
        f"(~{inv_money(s['soxta_summa'])} so'm)",
        f"🐌 Sekin aylanadigan: {len(s['sekin'])} ta",
        f"⚠️ Shubhali tannarx: {len(s['shubhali'])} ta",
        "\n✍️ Sanash: /sanash nomi · Hisobot: /sanash_hisobot",
        "<i>Yakuniy tuzatish Bito ilovasida kiritiladi.</i>",
    ])


INV_TITLES = {
    "qotgan_pul": ("🧊 QOTGAN PUL", "sotuvi yo'q, pul omborda turibdi"),
    "soxta": ("🎭 SOXTA QOLDIQLAR", "qo'lda qo'yilgan ~2000 lar"),
    "sekin": ("🐌 SEKIN AYLANADIGAN", "qoldiq 90+ kunga yetadi"),
    "shubhali": ("⚠️ SHUBHALI TANNARX", "tekshirish kerak"),
}


def inv_render_section(key, s, top=15):
    title, note = INV_TITLES.get(key, (key, ""))
    items = s.get(key, [])[:top]
    if not items:
        return f"<b>{title}</b>\n\nBu bo'limda hech narsa topilmadi. ✅"
    L = [f"<b>{title}</b>", f"<i>{note}</i>", ""]
    for i, p in enumerate(items, 1):
        extra = ""
        if key == "sekin":
            extra = f"\n   ↻ {p['cover']} kunga yetadi"
        elif key == "shubhali":
            extra = f"\n   ⚠️ {p['why']}"
        L.append(inv_line(i, p, extra))
    total = len(s.get(key, []))
    if total > top:
        L.append(f"\n<i>… yana {total - top} ta</i>")
    return "\n".join(L)


def inv_keyboard():
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(types.InlineKeyboardButton("🧊 Qotgan pul", callback_data="inv:qotgan_pul"),
           types.InlineKeyboardButton("🎭 Soxta qoldiq", callback_data="inv:soxta"))
    kb.add(types.InlineKeyboardButton("🐌 Sekin", callback_data="inv:sekin"),
           types.InlineKeyboardButton("⚠️ Shubhali", callback_data="inv:shubhali"))
    kb.add(types.InlineKeyboardButton("🔄 Yangilash", callback_data="inv:refresh"))
    return kb


def inv_run(chat_id):
    """Tahlilni fon rejimida bajaradi.

    Alohida funksiya, chunki uni HAM /inventar buyrug'i, HAM «Yangilash»
    tugmasi chaqiradi. Ilgari tugma inv_cmd(call.message) ni chaqirardi —
    lekin call.message.from_user BOT bo'ladi, foydalanuvchi emas, shuning
    uchun admin tekshiruvi uni jim to'xtatib qo'yardi.
    """
    bot.send_message(chat_id, "⏳ Ombor o'qilmoqda (5000+ qator, ~30 soniya)...")

    def run():
        try:
            stock = inv_fetch_stock()
            if not stock:
                bot.send_message(chat_id,
                                 "❌ Bito'dan qoldiq olinmadi.\n"
                                 "Railway loglarida «INV STOCK» qatorlarini "
                                 "ko'ring — qaysi manzil qanday xato "
                                 "qaytargani yozilgan.")
                return
            sold = inv_fetch_sold(30)
            s = inv_summarize(stock, sold, days=30)
            INV_CACHE.update(stock=stock, sold=sold, sum=s, ts=time.time())
            bot.send_message(chat_id, inv_render_summary(s),
                             parse_mode="HTML", reply_markup=inv_keyboard())
        except Exception as e:
            print("INV CMD ERR:", str(e)[:300], flush=True)
            bot.send_message(chat_id, f"❌ Xato: {str(e)[:200]}")

    threading.Thread(target=run, daemon=True).start()


@bot.message_handler(commands=['inventar'])
def inv_cmd(message):
    """📦 Inventarizatsiya tahlili. Faqat O'QIYDI — hech narsa yozmaydi."""
    if message.from_user.id != CFG.SUPER_ADMIN_ID:
        return
    inv_run(message.chat.id)


@bot.callback_query_handler(func=lambda c: c.data.startswith("inv:"))
def inv_cb(call):
    if call.from_user.id != CFG.SUPER_ADMIN_ID:
        return
    _ack(call)
    chat_id = call.message.chat.id
    key = call.data.split(":", 1)[1]

    if key in ("refresh", "run"):
        if key == "refresh":
            INV_CACHE.update(stock=None, sold=None, sum=None, ts=0)
        inv_run(chat_id)
        return
    if key == "report":
        # ⚠️ inv_count_report(call.message) chaqirib BO'LMAYDI:
        # call.message.from_user — BOT, admin tekshiruvi to'xtatadi
        # (o'sha tuzoq refresh tugmasida ham bo'lgan edi)
        _inv_send_count_report(chat_id)
        return
    if key == "promo":
        promo_cmd(_FakeMsg(call.from_user.id, chat_id))
        return
    if key == "clearask":
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("✅ Ha, tozalash",
                                          callback_data="inv:clearyes"))
        bot.send_message(chat_id, "Barcha sanash yozuvlari o'chirilsinmi?",
                         reply_markup=kb)
        return
    if key == "applyask":
        ok, txt = inv_apply_confirm_text()
        if not ok:
            bot.send_message(chat_id, txt)
            return
        kb = types.InlineKeyboardMarkup()
        kb.add(types.InlineKeyboardButton("✅ Ha, Bito'ga yozilsin",
                                          callback_data="inv:applyyes"))
        bot.send_message(chat_id, txt, parse_mode="HTML", reply_markup=kb)
        return
    if key == "applyyes":
        bot.send_message(chat_id, "📤 Bito'ga yozilmoqda...")
        def _apply():
            try:
                res = inv_apply_to_bito()
            except Exception as e:
                print("INV APPLY ERR:", repr(e)[:250], flush=True)
                res = f"❌ Xato: {str(e)[:200]}"
            send_long_message(chat_id, res)
        threading.Thread(target=_apply, daemon=True).start()
        return
    if key == "clearyes":
        n = qone("SELECT COUNT(*) FROM inv_counts")
        q("DELETE FROM inv_counts")
        bot.send_message(chat_id, f"🗑 {n[0] if n else 0} ta yozuv o'chirildi.")
        return

    s = INV_CACHE.get("sum")
    if not s:
        bot.send_message(chat_id, "Ma'lumot eskirgan. /inventar ni qayta yuboring.")
        return
    send_long_message(chat_id, inv_render_section(key, s), parse_mode="HTML")


@bot.message_handler(commands=['inv_qidir'])
def inv_search_cmd(message):
    """🔎 /inv_qidir <nom> — ombordan mahsulot qidirish."""
    if message.from_user.id != CFG.SUPER_ADMIN_ID:
        return
    q = (message.text or "").replace("/inv_qidir", "", 1).strip().lower()
    if not q:
        bot.send_message(message.chat.id, "Foydalanish: <code>/inv_qidir shokolad</code>",
                         parse_mode="HTML")
        return
    stock = INV_CACHE.get("stock")
    if not stock:
        bot.send_message(message.chat.id, "Avval /inventar ni yuboring.")
        return
    hits = sorted([p for p in stock if q in p["name"].lower()],
                  key=lambda p: -p["value"])[:20]
    if not hits:
        bot.send_message(message.chat.id, f"«{q}» bo'yicha topilmadi.")
        return
    L = [f"🔎 <b>«{q}»</b> — {len(hits)} ta\n"]
    for i, p in enumerate(hits, 1):
        L.append(inv_line(i, p))
    send_long_message(message.chat.id, "\n".join(L), parse_mode="HTML")


