W_INV_COUNT = TDict()   # {uid: {"cands": [...], "pick": {...}}}


@bot.message_handler(commands=['sanash'])
def inv_count_cmd(message):
    """✍️ /sanash <nom> — mahsulotni topib, sanalgan sonni yozish."""
    if message.from_user.id != CFG.SUPER_ADMIN_ID:
        return
    chat_id = message.chat.id
    query = (message.text or "").replace("/sanash", "", 1).strip().lower()
    if not query:
        bot.send_message(chat_id,
                         "Foydalanish: <code>/sanash shokolad</code>\n"
                         "Hisobot: /sanash_hisobot", parse_mode="HTML")
        return
    stock = INV_CACHE.get("stock")
    if not stock:
        bot.send_message(chat_id, "Avval /inventar ni yuboring — "
                                  "ombor keshi kerak.")
        return
    cands = sorted([p for p in stock if query in p["name"].lower()],
                   key=lambda p: -p["value"])[:6]
    if not cands:
        bot.send_message(chat_id, f"«{query}» topilmadi.")
        return
    W_INV_COUNT[message.from_user.id] = {"cands": cands}
    kb = types.InlineKeyboardMarkup(row_width=1)
    for i, p in enumerate(cands):
        amt = f"{p['amount']:.3f}".rstrip("0").rstrip(".")
        kb.add(types.InlineKeyboardButton(
            f"{p['name'][:40]} · {amt} {p['unit']}",
            callback_data=f"invc:{i}"))
    bot.send_message(chat_id, "Qaysi mahsulot?", reply_markup=kb)


