# ──────────────────────────────────────────────────────────────────
# 📤 BITO'GA TUZATISH YOZISH — sanash farqini hujjat sifatida yuborish
#
# Revision (inventarizatsiya) API'si YOZMAYDI (yakuniy isbotlangan).
# Lekin qoldiqni boshqa hujjatlar o'zgartiradi:
#   • KAMOMAD (farq < 0)  → chiqim (write-off, action=remove) —
#     do'konda har kuni ishlatiladi, hujjat tuzilishi jonli o'qildi
#   • ORTIQCHA (farq > 0) → kirim (purchase/create) —
#     nakladnoy moduli shu yo'l bilan yozadi, ISBOTLANGAN
#
# ⚠️ write-off/create endpointi hali jonli sinalmagan (konteynerdan
# api.bito.uz yopiq) — birinchi yuborish o'zi sinov: manzil variantlari
# _bito_try_paths bilan sinaladi, natija loglarda va javobda ko'rinadi.
# ──────────────────────────────────────────────────────────────────

# [tenant] CFG.INV_WO_REASON_ID = "695ff2a1a354cd778ad58183"   # "Ulugbek" (write_off turi, faol)


def inv_collect_diffs():
    """Sanashdan farqlarni yig'adi: (kamomad[], ortiqcha[], jami_summa).

    Farq sanash PAYTIDAGI Bito qoldig'iga nisbatan — sanashdan keyin
    savdo davom etgan bo'lsa ozgina siljish bo'lishi mumkin, shuning
    uchun sanagan zahoti yuborish tavsiya etiladi.
    """
    rows = qall("SELECT product_id, name, unit, expected, cost, counted "
                "FROM inv_counts")
    short, extra = [], []
    for pid, name, unit, exp, cost, cnt in rows:
        diff = (cnt or 0) - (exp or 0)
        if abs(diff) < 0.001:
            continue
        item = {"id": pid, "name": name, "unit": unit,
                "qty": abs(diff), "cost": cost or 0}
        (short if diff < 0 else extra).append(item)
    total = sum(i["qty"] * i["cost"] for i in short) + \
            sum(i["qty"] * i["cost"] for i in extra)
    return short, extra, total


def _inv_measure_id(pid):
    """Keshdan measure_id — chiqim hujjatiga kerak bo'lishi mumkin."""
    for p in (INV_CACHE.get("stock") or []):
        if p["id"] == pid:
            return p.get("measure_id")
    return None


def bito_inv_writeoff(items):
    """Kamomadni chiqim hujjati qilib yozadi. (ok, xabar).

    Tuzilish jonli o'qilgan №10063 hujjatdan olingan. Manzil noma'lum —
    variantlar sinaladi va ishlagani saqlanadi.
    """
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    products = []
    for i in items:
        row = {"product_id": i["id"], "amount": i["qty"]}
        mid = _inv_measure_id(i["id"])
        if mid:
            row["measure_id"] = mid
        products.append(row)
    body = {
        "organization_id": CFG.BITO_ORG_ID,
        "warehouse_id": tenant_setting("bito_warehouse_id",
                                       "69424f36a3a3cc43da908320"),
        "source_warehouse_id": tenant_setting("bito_warehouse_id",
                                              "69424f36a3a3cc43da908320"),
        "responsible_id": tenant_setting("bito_responsible_id",
                                         "693fe9caff2118868c9554b1"),
        "currency_id": tenant_setting("bito_currency_id",
                                      "69424f34f461a9f6fd61972d"),
        "action": "remove",
        "reason_id": CFG.INV_WO_REASON_ID,
        "state": "done",
        "write_date": datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S.000Z"),
        "note": "Inventarizatsiya kamomadi — bot orqali",
        "products": products,
    }
    cands = ["write-off/create", "writeoff/create", "write_off/create"]
    j, path = _bito_try_paths("bito_writeoff_endpoint", cands, body,
                              headers, "INV CHIQIM")
    if j is None:
        return False, ("Chiqim yozilmadi — hech qaysi manzil qabul qilmadi. "
                       "Railway loglarida «INV CHIQIM» qatorlarini ko'ring.")
    num = ""
    d = j.get("data") if isinstance(j, dict) else None
    if isinstance(d, dict):
        num = d.get("number") or d.get("_id") or ""
    return True, f"Chiqim yaratildi{' №' + str(num) if num else ''} ({path})"


def bito_inv_income(items):
    """Ortiqchani kirim (purchase) qilib yozadi. (ok, xabar).

    Yetkazib beruvchi: nomida «Inventar» bo'lgan firma qidiriladi —
    hisob aralashmasligi uchun. Topilmasa yozilmaydi va foydalanuvchiga
    Bito'da bir marta shunday firma ochish aytiladi (30 soniyalik ish).
    """
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    try:
        rs = requests.post(BITO_BASE_URL + "supplier/get-paging",
                           json={"page": 1, "limit": 3, "search": "Inventar"},
                           headers=headers, timeout=15)
        sl = _bito_rows(rs.json() or {}) if rs.status_code == 200 else []
    except Exception as e:
        print("INV KIRIM SUPPLIER ERR:", str(e)[:150], flush=True)
        sl = []
    if not sl:
        return False, ("Ortiqcha yozilmadi: Bito'da «Inventarizatsiya» nomli "
                       "firma yo'q. Bir marta ochib qo'ying "
                       "(Firmalar → yangi → nomi: Inventarizatsiya), "
                       "keyin qayta yuboring.")
    supplier_id = sl[0].get("_id")
    products = [{"product_id": i["id"], "amount": i["qty"], "cost": i["cost"]}
                for i in items]
    body = {
        "organization_id": CFG.BITO_ORG_ID,
        "state": "new",
        "date": today_str(),
        "income_date": today_str(),
        "supplier_id": supplier_id,
        "responsible_id": tenant_setting("bito_responsible_id",
                                         "693fe9caff2118868c9554b1"),
        "warehouse_id": tenant_setting("bito_warehouse_id",
                                       "69424f36a3a3cc43da908320"),
        "currency_id": tenant_setting("bito_currency_id",
                                      "69424f34f461a9f6fd61972d"),
        "note": "Inventarizatsiya ortiqchasi — bot orqali",
        "is_auto_income": True,
        "additional_costs": [],
        "orders": [{"products": products}],
    }
    try:
        r = requests.post(BITO_BASE_URL + "purchase/create", json=body,
                          headers=headers, timeout=90)
        print(f"INV KIRIM: HTTP {r.status_code} | {r.text[:250]}", flush=True)
        if r.status_code != 200:
            return False, f"Kirim xatosi: HTTP {r.status_code}"
        d = (r.json() or {}).get("data") or {}
        num = d.get("number") or d.get("_id") or ""
        return True, f"Kirim yaratildi{' №' + str(num) if num else ''}"
    except Exception as e:
        return False, f"Kirim xatosi: {str(e)[:150]}"


def inv_apply_to_bito():
    """Farqlarni Bito'ga yozadi. Natija matnini qaytaradi."""
    short, extra, total = inv_collect_diffs()
    if not short and not extra:
        return "Farq yo'q — hamma sanalgan son Bito bilan bir xil. ✅"
    out = []
    if short:
        ok, msg = bito_inv_writeoff(short)
        out.append(("✅ " if ok else "❌ ") + msg +
                   f" — {len(short)} ta mahsulot (kamomad)")
        if ok:
            for i in short:
                q("DELETE FROM inv_counts WHERE product_id=?", (i["id"],))
    if extra:
        ok, msg = bito_inv_income(extra)
        out.append(("✅ " if ok else "❌ ") + msg +
                   f" — {len(extra)} ta mahsulot (ortiqcha)")
        if ok:
            for i in extra:
                q("DELETE FROM inv_counts WHERE product_id=?", (i["id"],))
    left = qall("SELECT COUNT(*) FROM inv_counts")
    n_left = left[0][0] if left else 0
    out.append(f"\nYozilganlar ro'yxatdan o'chirildi. Qolgan: {n_left} ta "
               f"(farqsizlar yoki yozilmaganlar).")
    out.append("Tekshirish: Bito → Chiqimlar / Xaridlar bo'limi.")
    # Keshni eskirtiramiz — keyingi tahlil yangi qoldiqni ko'rsin
    INV_CACHE.update(ts=0)
    return "\n".join(out)


def inv_apply_confirm_text():
    """Tasdiqlash matni — nima yozilishini OLDINDAN ko'rsatadi."""
    short, extra, total = inv_collect_diffs()
    if not short and not extra:
        return None, "Farq yo'q — yozishga hojat yo'q. ✅"
    L = ["📤 <b>BITO'GA YOZILADI:</b>\n"]
    if short:
        s = sum(i["qty"] * i["cost"] for i in short)
        L.append(f"🔻 Chiqim (kamomad): {len(short)} ta, {inv_money(s)} so'm")
        for i in short[:8]:
            L.append(f"   • {i['name'][:36]} −{i['qty']:g} {i['unit']}")
        if len(short) > 8:
            L.append(f"   … yana {len(short) - 8} ta")
    if extra:
        s = sum(i["qty"] * i["cost"] for i in extra)
        L.append(f"🔺 Kirim (ortiqcha): {len(extra)} ta, {inv_money(s)} so'm")
        for i in extra[:8]:
            L.append(f"   • {i['name'][:36]} +{i['qty']:g} {i['unit']}")
        if len(extra) > 8:
            L.append(f"   … yana {len(extra) - 8} ta")
    L.append("\n⚠️ Bu Bito qoldig'ini HAQIQATAN o'zgartiradi.")
    return True, "\n".join(L)


