# ──────────────────────────────────────────────────────────────────
# 🔗 RASMDAN BOG'LASH (o'rgatish rejimi) — /bogla
#
# Foydalanuvchi taklifi (2026-08-02): nakladnoy KIRITMASDAN, bo'sh vaqtda
# rasm tashlab, undagi mahsulotlarni Bito mahsulotlariga bog'lab chiqish.
# Xarid YARATILMAYDI — faqat nak_aliases xotirasi to'ldiriladi. Keyin
# haqiqiy nakladnoylar shu xotira tufayli savolsiz avto-moslashadi.
# Mavjud qismlar ishlatiladi: nak_extract (AI o'qish), NAK_CATALOG_CACHE
# (lokal qidiruv), nak_save_alias / nak_get_alias (xotira).
# ──────────────────────────────────────────────────────────────────

W_BOGLA = TDict()   # uid -> {"names":[...], "idx":0, "cands":[...], "step":...}


def _bogla_cands(name, limit=6):
    """Lokal katalogdan nomzodlar: so'z mosligi soni bo'yicha saralangan."""
    key_words = [w for w in _translit_and_norm(name).split() if len(w) >= 3]
    if not key_words:
        return []
    scored = []
    for p in (NAK_CATALOG_CACHE.get("products") or []):
        score = sum(1 for w in key_words if w in p["key"])
        if score:
            scored.append((score, p))
    scored.sort(key=lambda x: -x[0])
    return [p for _, p in scored[:limit]]


def _bogla_markup(cands):
    kb = types.InlineKeyboardMarkup(row_width=1)
    for j, p in enumerate(cands):
        kb.add(types.InlineKeyboardButton(p["name"][:60], callback_data=f"bgl_{j}"))
    kb.add(types.InlineKeyboardButton("🔍 Boshqa nom bilan qidirish",
                                      callback_data="bgl_search"),
           types.InlineKeyboardButton("⏭ O'tkazib yuborish",
                                      callback_data="bgl_skip"))
    kb.add(types.InlineKeyboardButton("🛑 To'xtatish", callback_data="bgl_stop"))
    return kb


def _bogla_next(uid, chat_id):
    st = W_BOGLA.get(uid)
    if not st:
        return
    while st["idx"] < len(st["names"]):
        name = st["names"][st["idx"]]
        if nak_get_alias(name):
            st["idx"] += 1        # allaqachon bog'langan — o'tkazamiz
            continue
        cands = _bogla_cands(name)
        st["cands"] = cands
        st["step"] = "pick"
        done = st["idx"] + 1
        total = len(st["names"])
        txt = (f"🔗 <b>{h(name)}</b>  ({done}/{total})\n"
               f"Bito'dagi qaysi mahsulot?")
        if not cands:
            txt += "\n<i>Lokal katalogda o'xshashi topilmadi — qidiring.</i>"
        bot.send_message(chat_id, txt, parse_mode="HTML",
                         reply_markup=_bogla_markup(cands))
        return
    # Tugadi
    n = st.get("linked", 0)
    skipped = st.get("skipped", 0)
    W_BOGLA.pop(uid, None)
    bot.send_message(chat_id,
                     f"✅ Bog'lash tugadi: {n} ta bog'landi, "
                     f"{skipped} ta o'tkazildi.\n"
                     f"Endi bu mahsulotlar nakladnoylarda savolsiz avto-topiladi. "
                     f"Yana rasm yuborish: /bogla")


def _bogla_allowed(uid):
    """Admin har doim; xodim — tugma unga yashirilmagan bo'lsa.
    (Tugma yashirilganda hidden_menu_guard baribir to'sadi, bu esa
    /bogla BUYRUG'I orqali aylanib o'tishning oldini oladi.)"""
    if uid == CFG.SUPER_ADMIN_ID or get_role(uid) in ('boss', 'manager'):
        return True
    return (get_role(uid) == 'employee'
            and "🔗 Mahsulot bog'lash" not in get_hidden_menu("emp"))


@bot.message_handler(func=lambda m: m.text == "🔗 Mahsulot bog'lash")
def btn_bogla(message):
    if not _bogla_allowed(message.from_user.id):
        return
    bogla_cmd(message, _skip_check=True)


@bot.message_handler(commands=['bogla'])
def bogla_cmd(message, _skip_check=False):
    """🔗 Rasm ichidagi mahsulotlarni Bito'ga bog'lash (xarid yaratilmaydi)."""
    if not _skip_check and not _bogla_allowed(message.from_user.id):
        return
    W_BOGLA[message.from_user.id] = {"step": "await_photo", "names": [],
                                     "idx": 0, "linked": 0, "skipped": 0}
    bot.send_message(message.chat.id,
                     "🔗 <b>O'rgatish rejimi</b>\n\n"
                     "Nakladnoy/pretsent rasmini yuboring — undagi mahsulotlarni "
                     "Bito'ga bog'lab chiqamiz. Xarid YARATILMAYDI, faqat xotira "
                     "to'ladi: keyin haqiqiy nakladnoylar savolsiz o'tadi.\n"
                     "Bekor qilish: /bekor", parse_mode="HTML")


@bot.message_handler(content_types=['photo', 'document'],
                     func=lambda m: W_BOGLA.get(m.from_user.id, {}).get("step") == "await_photo")
def bogla_photo(message):
    uid = message.from_user.id
    chat_id = message.chat.id
    st = W_BOGLA.get(uid)
    if not st:
        return
    st["step"] = "reading"
    bot.send_message(chat_id, "🔍 Rasm o'qilmoqda (30-60 soniya)...")

    def run():
        try:
            import base64
            threading.Thread(target=refresh_nak_catalog, daemon=True).start()
            if message.content_type == 'photo':
                f = bot.get_file(message.photo[-1].file_id)
            else:
                f = bot.get_file(message.document.file_id)
            raw = requests.get(f"https://api.telegram.org/file/bot{TOKEN}/{f.file_path}",
                               timeout=60).content
            blocks = [{"type": "image",
                       "source": {"type": "base64", "media_type": "image/jpeg",
                                  "data": base64.b64encode(raw).decode()}}]
            data, err = nak_extract(blocks)
            if err or not data or not data["items"]:
                W_BOGLA.pop(uid, None)
                bot.send_message(chat_id, f"⚠️ O'qib bo'lmadi: {err or 'mahsulot topilmadi'}")
                return
            names = [i["name"] for i in data["items"] if i.get("name")]
            already = sum(1 for n in names if nak_get_alias(n))
            st["names"] = names
            refresh_nak_catalog()   # nomzodlar uchun katalog tayyor bo'lsin
            bot.send_message(chat_id,
                             f"📥 {len(names)} ta mahsulot o'qildi"
                             + (f", {already} tasi allaqachon bog'langan"
                                if already else "") + ". Boshladik:")
            _bogla_next(uid, chat_id)
        except Exception as e:
            print("BOGLA ERR:", str(e)[:200], flush=True)
            W_BOGLA.pop(uid, None)
            bot.send_message(chat_id, f"⚠️ Xatolik: {str(e)[:120]}")

    threading.Thread(target=run, daemon=True).start()


@bot.callback_query_handler(func=lambda c: c.data.startswith("bgl_"))
def bogla_cb(call):
    uid = call.from_user.id
    chat_id = call.message.chat.id
    _ack(call)
    st = W_BOGLA.get(uid)
    if not st or st.get("step") != "pick":
        return
    action = call.data.replace("bgl_", "")
    if action == "stop":
        n = st.get("linked", 0)
        W_BOGLA.pop(uid, None)
        bot.send_message(chat_id, f"🛑 To'xtatildi. {n} ta bog'lash saqlandi.")
        return
    if action == "skip":
        st["skipped"] = st.get("skipped", 0) + 1
        st["idx"] += 1
        _bogla_next(uid, chat_id)
        return
    if action == "search":
        st["step"] = "search_text"
        bot.send_message(chat_id, "🔍 Bito'dagi nomini yozing (qisqa, masalan brend so'zi):")
        return
    try:
        p = st["cands"][int(action)]
    except (ValueError, IndexError):
        return
    name = st["names"][st["idx"]]
    nak_save_alias(name, p["id"], p["name"])
    st["linked"] = st.get("linked", 0) + 1
    st["idx"] += 1
    bot.send_message(chat_id, f"🧠 <b>{h(name)}</b> → {h(p['name'])}",
                     parse_mode="HTML")
    _bogla_next(uid, chat_id)


@bot.message_handler(func=lambda m: W_BOGLA.get(m.from_user.id, {}).get("step") == "search_text"
                     and not (m.text or "").startswith("/"))
def bogla_search_text(message):
    uid = message.from_user.id
    st = W_BOGLA.get(uid)
    if not st:
        return
    query = (message.text or "").strip()
    key = _translit_and_norm(query)
    hits = [p for p in (NAK_CATALOG_CACHE.get("products") or [])
            if key and key in p["key"]][:6]
    if not hits:
        # so'z bo'laklari bilan yumshoqroq qidiruv
        hits = _bogla_cands(query)
    st["cands"] = hits
    st["step"] = "pick"
    if not hits:
        bot.send_message(message.chat.id, "Topilmadi — boshqa so'z bilan urinib ko'ring:")
        st["step"] = "search_text"
        return
    name = st["names"][st["idx"]]
    bot.send_message(message.chat.id, f"🔗 <b>{h(name)}</b> uchun topilganlar:",
                     parse_mode="HTML", reply_markup=_bogla_markup(hits))


