def _promo_ai_post(p, avoid_text=None, plain=False):
    """Claude'dan bitta mahsulot uchun sotuv posti oladi.

    `plain=True` — ODDIY post: chegirma yo'q, «aksiya/chegirma/arzonlashdi»
    kabi so'zlar ishlatilmaydi. Mahsulotning o'zi tanishtiriladi."""
    avoid = (f"\n\nOLDINGI VARIANT YOQMADI, BOSHQACHA yoz "
             f"(boshqa uslub/urg'u):\n{avoid_text[:400]}" if avoid_text else "")
    amt = f"{p['amount']:g} {p.get('unit') or 'dona'}"
    if plain:
        prompt = (
            "Sen «Bonnu Market» supermarketi uchun Telegram/Instagram "
            "posti yozasan. O'zbek tilida, qisqa (60-90 so'z), jonli, "
            "2-4 ta emoji bilan. Maqsad: mahsulotni tanishtirish va "
            "sotuvni oshirish.\n\n"
            f"MAHSULOT: {p['name']}\n\n"
            "QOIDALAR:\n"
            "1. Bu ODDIY post — chegirma YO'Q. «aksiya», «chegirma», "
            "«arzonlashdi», «tushdi» kabi so'zlarni ISHLATMA.\n"
            "2. Narx o'rniga ANIQ {NARX} joy tutuvchisini yoz.\n"
            "3. Mahsulotning foydasi/ta'mi/qulayligi haqida halol yoz, "
            "yolg'on va'da bermа.\n"
            "4. Oxirida «Bonnu Market» bo'lsin. Shahar/manzil YOZMA.\n"
            "5. FAQAT post matnini qaytar — izohsiz, sarlavhasiz." + avoid)
    else:
        prompt = (
            "Sen «Bonnu Market» supermarketi uchun Telegram/Instagram "
            "sotuv posti yozasan. O'zbek tilida, qisqa (60-90 so'z), jonli, "
            "2-4 ta emoji bilan. Maqsad: omborda turib qolgan tovarni tezroq sotish.\n\n"
            f"MAHSULOT: {p['name']}\n"
            f"OMBORDA: {amt}\n\n"
            "QOIDALAR:\n"
            "1. Narx o'rniga ANIQ {NARX} joy tutuvchisini yoz — egasi o'zi qo'yadi.\n"
            "2. Yolg'on va'da yozma (sifat/foyda haqida umumiy, halol gaplar).\n"
            "3. Oxirida do'kon nomi va «zaxira cheklangan» turtkisi bo'lsin.\n"
            "   Shahar/manzil YOZMA — faqat «Bonnu Market».\n"
            "4. FAQAT post matnini qaytar — izohsiz, sarlavhasiz." + avoid)
    headers = {"x-api-key": ANTHROPIC_API_KEY,
               "anthropic-version": "2023-06-01",
               "content-type": "application/json"}
    r = requests.post("https://api.anthropic.com/v1/messages", headers=headers,
                      json={"model": "claude-sonnet-4-6", "max_tokens": 600,
                            "messages": [{"role": "user", "content": prompt}]},
                      timeout=60)
    r.raise_for_status()
    content = r.json().get("content", [])
    return "".join(b.get("text", "") for b in content
                   if b.get("type") == "text").strip()


def _promo_allowed(uid):
    """Post oqimi kimga ochiq: super-admin, boshliq, menejer
    (2026-08-08: ertalabki xabar menejerga ham boradi)."""
    return uid == CFG.SUPER_ADMIN_ID or is_boss_or_mgr(uid)


_INV_WARMING = TDict(template={"on": False})


def _promo_cost_price(product_id):
    """Kelish narxi (tannarx) — inventar keshidagi cost maydonidan.
    Kesh bo'sh bo'lsa (bot endi qayta ishga tushgan) fonda isitiladi —
    keyingi mahsulotda chiqadi."""
    stock = INV_CACHE.get("stock") or []
    for p in stock:
        if p.get("id") == product_id and p.get("cost"):
            return float(p["cost"])
    # 2026-08-09: keshga tayanish deploy'lar orasida «aniqlanmadi»
    # berardi — endi TO'G'RIDAN bitta so'rov (o'sha cost hisobot
    # endpointi, nom bilan qidirib _id moslash). Kesh faqat tezlik uchun.
    try:
        pname = None
        rown = qone("SELECT name FROM promo_posts WHERE product_id=? "
                    "ORDER BY id DESC LIMIT 1", (product_id,))
        if rown:
            pname = rown[0]
        if pname:
            headers = {"api-key": CFG.BITO_API_KEY,
                       "Content-Type": "application/json"}
            cands = ["reports/dashboard/summary/product/chart-pagin",
                     "reports/dashboard/summary/product/chart-paging",
                     "reports/dashboard/summary/product/pagin",
                     "reports/dashboard/summary/product/paging"]
            j, _p = _bito_try_paths("bito_stockcost_endpoint", cands,
                                    {"page": 1, "limit": 20,
                                     "search": pname[:60],
                                     "organization_ids": [CFG.BITO_ORG_ID]},
                                    headers, "PROMO COST")
            for it in (_bito_rows(j) if j else []):
                if isinstance(it, dict) and it.get("_id") == product_id                         and it.get("cost"):
                    return float(it["cost"])
    except Exception as e:
        print("PROMO COST ERR:", str(e)[:100], flush=True)
    if not stock and not _INV_WARMING["on"]:
        _INV_WARMING["on"] = True
        def warm():
            try:
                s = inv_fetch_stock()
                if s:
                    INV_CACHE.update(stock=s, ts=time.time())
                    print(f"INV WARM: {len(s)} yozuv keshga olindi", flush=True)
            except Exception as e:
                print("INV WARM ERR:", str(e)[:100], flush=True)
            finally:
                _INV_WARMING["on"] = False
        threading.Thread(target=warm, daemon=True).start()
    return None


def _promo_money(n):
    return f"{int(round(n)):,}".replace(",", " ")


def _promo_caption(name, old_price, new_price, until=None, plain=False):
    """Kanal uslubidagi (t.me/BonnuMarket/3928) yakuniy post matni.
    Narx/telefon/ish vaqti KODDAN qo'yiladi (AI raqamni buzmasin);
    Claude faqat sarlavha va afzalliklarni yozadi.

    `plain=True` — ODDIY post: «AKSIYA» sarlavhasi ham, «Aksiya narxi»
    qatori ham YOZILMAYDI. Faqat mahsulot va narxi."""
    head = None
    try:
        if plain:
            prompt = (
                "Sen «Bonnu Market» supermarketining Telegram kanali uchun "
                "mahsulot posti BOSHINI yozasan. O'zbek tilida. QUYIDAGI "
                "TUZILISHDA, boshqa hech narsa yozma:\n"
                "1-qator: mahsulotga mos bitta emoji + «" + name +
                " endi BONNU MARKETda!»\n"
                "2-qator: 💚 bilan qisqa kirish gap\n"
                "So'ng 3-4 qator: ✅ bilan mahsulotning halol, ishonarli "
                "afzalliklari (yolg'on va'da yozma).\n"
                "⛔ MUHIM: «AKSIYA», «chegirma», «super narx», «arzon», "
                "«shoshiling» kabi so'zlarni ISHLATMA — bu oddiy post, "
                "chegirma yo'q.\n"
                "NARX YOZMA, telefon/manzil YOZMA — ular keyin qo'shiladi. "
                "FAQAT shu qatorlarni qaytar.")
        else:
            prompt = (
                "Sen «Bonnu Market» supermarketining Telegram kanali uchun aksiya "
                "posti BOSHINI yozasan. O'zbek tilida. QUYIDAGI TUZILISHDA, "
                "boshqa hech narsa yozma:\n"
                "1-qator: 🔥 AKSIYA! AKSIYA! AKSIYA! 🔥\n"
                "2-qator: mahsulotga mos bitta emoji + «" + name +
                " endi BONNU MARKETda super narxda!»\n"
                "3-qator: 💚 bilan qisqa kirish gap\n"
                "So'ng 3-4 qator: ✅ bilan mahsulotning halol, ishonarli "
                "afzalliklari (yolg'on va'da yozma).\n"
                "NARX YOZMA, telefon/manzil YOZMA — ular keyin qo'shiladi. "
                "FAQAT shu qatorlarni qaytar.")
        headers = {"x-api-key": ANTHROPIC_API_KEY,
                   "anthropic-version": "2023-06-01",
                   "content-type": "application/json"}
        r = requests.post("https://api.anthropic.com/v1/messages",
                          headers=headers,
                          json={"model": "claude-sonnet-4-6",
                                "max_tokens": 400,
                                "messages": [{"role": "user",
                                              "content": prompt}]},
                          timeout=60)
        r.raise_for_status()
        head = "".join(b.get("text", "") for b in r.json().get("content", [])
                       if b.get("type") == "text").strip()
    except Exception as e:
        print("PROMO CAPTION ERR:", str(e)[:120], flush=True)
    if not head:
        head = (f"🛒 {name} endi BONNU MARKETda!" if plain else
                f"🔥 AKSIYA! AKSIYA! AKSIYA! 🔥\n"
                f"🛒 {name} endi BONNU MARKETda super narxda!")
    tail = []
    if plain:
        # 📄 Oddiy post: chegirma qatorlari va shoshilish turtkisi yo'q
        tail.append(f"💰 Narxi: {_promo_money(new_price)} so'm")
    else:
        if old_price:
            tail.append(f"💰 Oddiy narxi: {_promo_money(old_price)} so'm")
        tail += [f"🔥 Aksiya narxi: {_promo_money(new_price)} so'm",
                 (f"⏳ Shoshiling! Aksiya {until}gacha amal qiladi."
                  if until else
                  "⏳ Shoshiling! Aksiya mahsuloti soni cheklangan.")]
    tail += ["",
             f"📍 BONNU MARKET 🕗 Ish vaqti: {CFG.PROMO_HOURS}",
             "🚚 Yetkazib berish xizmati mavjud",
             f"📞 Buyurtma uchun: {CFG.PROMO_PHONE}",
             "📲 Telegram: @BonnuMarket",
             "💚 BONNU MARKET – Sifat va Ishonch!"]
    cap = head + "\n\n" + "\n".join(tail)
    return cap[:1020]  # Telegram caption 1024 chegarasi


def _promo_poster_run_safe(chat_id, uid, row_id):
    try:
        _promo_poster_run(chat_id, uid, row_id)
    except Exception as e:
        import traceback
        print("POSTER RUN CRASH:", traceback.format_exc()[:600], flush=True)
        try:
            bot.send_message(chat_id, f"⚠️ Poster yasashda xato: {str(e)[:120]}")
        except Exception:
            pass


def _promo_poster_run(chat_id, uid, row_id):
    """Manba rasmdan yakuniy poster: OpenAI sahna + narx/panel montaji.
    Natija «Yoqdi / Boshqasi» tugmalari bilan yuboriladi."""
    st = W_PROMO_IMG.get(uid) or {}
    src_bytes = st.get("src")
    if not src_bytes:
        bot.send_message(chat_id, "Rasm topilmadi — /post ni qayta yuboring.")
        return
    bot.send_message(chat_id, "🎨 OpenAI to'liq posterni tayyorlayapti "
                              "(30-90 soniya)...")
    row = qone("SELECT name, kind FROM promo_posts WHERE id=?", (row_id,))
    pname = row[0] if row else "Mahsulot"
    is_plain = bool((row and row[1] == "plain") or st.get("plain"))
    # 2026-08-08: montaj BITTA bosqichda — narx, lenta, panel hammasi
    # OpenAI ichida. PIL montaj faqat OpenAI ishlamaganda zaxira.
    head, bens = _promo_poster_texts(pname)
    poster, err = (openai_make_promo_poster(
        src_bytes, pname, st.get("old"), st.get("new") or 0,
        headline=head, benefits=bens, plain=is_plain)
        if OPENAI_API_KEY else (None, "OPENAI_API_KEY yo'q"))
    engine, note = "OpenAI", ""
    if not poster:
        print("PROMO POSTER: OpenAI yo'q, PIL zaxira:", (err or "")[:150],
              flush=True)
        try:
            poster = promo_compose_scene(src_bytes, st.get("old"),
                                         st.get("new") or 0,
                                         ribbon=("YANGI!" if is_plain else "AKSIYA!"))
            engine = "montaj-zaxira"
            note = f"\n⚠️ OpenAI ishlamadi ({(err or '')[:100]})."
        except Exception as e:
            bot.send_message(chat_id, f"⚠️ Poster chiqmadi: {(err or str(e))[:120]}")
            return
    st["poster"] = poster
    st["step"] = "review"
    W_PROMO_IMG[uid] = st
    # 2026-08-09: posterni DARHOL faylga saqlaymiz — «Yoqdi» kech
    # bosilsa/bot qayta ishga tushsa ham kanalga rasm bilan boradi
    try:
        with open(_promo_poster_path(row_id), "wb") as f:
            f.write(poster)
    except Exception as e:
        print("POSTER SAVE ERR:", str(e)[:100], flush=True)
    import io
    bio = io.BytesIO(poster); bio.name = "poster.jpg"
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(types.InlineKeyboardButton("✅ Yoqdi",
                                      callback_data=f"pfin:ok_{row_id}"),
           types.InlineKeyboardButton("🔁 Boshqasi",
                                      callback_data=f"pfin:re_{row_id}"))
    bot.send_photo(chat_id, bio,
                   caption=f"🖼 Tayyor poster ({engine}).{note}\n"
                           f"Yoqdimi yoki boshqa variant tayyorlaymi?",
                   reply_markup=kb)


import os as _os
def PROMO_POSTER_DIR():
    d = _os.path.join(_os.path.dirname(DB_PATH_FN()),
                      "posters", TEN.current())
    _os.makedirs(d, exist_ok=True)
    return d


def _promo_poster_path(row_id):
    return _os.path.join(PROMO_POSTER_DIR(), f"promo_poster_{row_id}.jpg")


def _promo_channel():
    return get_setting("promo_channel", "@BonnuMarket") or "@BonnuMarket"


def _promo_publish(row_id, by_uid, notify_chat=None):
    """Postni Telegram kanalga joylaydi (poster fayldan, matn bazadan) —
    deploy'larga chidamli. Xato bo'lsa sababi bilan qaytaradi."""
    row = qone("SELECT post_text, published_at FROM promo_posts WHERE id=?",
               (row_id,))
    if not row or not row[0]:
        return "Post matni topilmadi — /post qayta tayyorlang."
    if row[1]:
        return f"Bu post allaqachon joylangan ({row[1][:16]})."
    cap, chan = row[0], _promo_channel()
    try:
        ppath = _promo_poster_path(row_id)
        if _os.path.exists(ppath):
            with open(ppath, "rb") as f:
                bot.send_photo(chan, f, caption=cap)
        else:
            bot.send_message(chan, cap)
    except Exception as e:
        err = str(e)[:150]
        print(f"PROMO PUBLISH ERR: {err}", flush=True)
        if "chat not found" in err.lower() or "forbidden" in err.lower():
            return (f"Kanalga joylay olmadim: {err}\n\n"
                    f"Tekshiring: bot {chan} kanalida ADMIN bo'lishi va "
                    f"post joylash huquqi bo'lishi kerak.")
        return f"Kanalga joylashda xato: {err}"
    q("UPDATE promo_posts SET published_at=? WHERE id=?",
      (now_str(), row_id))
    print(f"PROMO PUBLISHED: row={row_id} by={by_uid} → {chan}", flush=True)
    return None


def _ig_creds():
    return (os.getenv("IG_USER_ID", "") or get_setting("ig_user_id", ""),
            os.getenv("IG_ACCESS_TOKEN", "") or get_setting("ig_token", ""))


def _promo_publish_ig(row_id, by_uid):
    """Instagram'ga joylash (Graph API, 2 bosqich: media → publish).
    Rasm botning o'z /poster/<id>.jpg ochiq manzilidan olinadi."""
    ig_user, ig_token = _ig_creds()
    if not ig_user or not ig_token:
        return ("Instagram ulanmagan. Railway Variables'ga IG_USER_ID va "
                "IG_ACCESS_TOKEN qo'shing (yo'riqnoma: botdagi xabarga "
                "qarang).")
    row = qone("SELECT post_text FROM promo_posts WHERE id=?", (row_id,))
    if not row or not row[0]:
        return "Post matni topilmadi."
    if not _os.path.exists(_promo_poster_path(row_id)):
        return "Poster rasmi topilmadi — Instagram matnsiz rasm talab qiladi."
    img_url = f"{_public_base_url()}/poster/{row_id}.jpg"
    try:
        r1 = requests.post(
            f"https://graph.facebook.com/v21.0/{ig_user}/media",
            data={"image_url": img_url, "caption": row[0][:2200],
                  "access_token": ig_token}, timeout=60)
        j1 = r1.json()
        print(f"IG MEDIA: HTTP {r1.status_code} {str(j1)[:150]}", flush=True)
        cid = j1.get("id")
        if not cid:
            err = (j1.get("error") or {}).get("message", str(j1)[:150])
            return f"Instagram media xatosi: {err[:180]}"
        r2 = requests.post(
            f"https://graph.facebook.com/v21.0/{ig_user}/media_publish",
            data={"creation_id": cid, "access_token": ig_token}, timeout=60)
        j2 = r2.json()
        print(f"IG PUBLISH: HTTP {r2.status_code} {str(j2)[:150]}", flush=True)
        if not j2.get("id"):
            err = (j2.get("error") or {}).get("message", str(j2)[:150])
            return f"Instagram publish xatosi: {err[:180]}"
    except Exception as e:
        return f"Instagram xatosi: {str(e)[:150]}"
    print(f"IG PUBLISHED: row={row_id} by={by_uid}", flush=True)
    return None


def _send_post_preview(to_chat, row_id):
    """Ruxsat so'rovidan oldin postning O'ZI (rasm+matn) yuboriladi —
    boshliq nimaga ruxsat berayotganini ko'rishi shart (2026-08-09)."""
    row = qone("SELECT post_text FROM promo_posts WHERE id=?", (row_id,))
    cap = (row[0] if row else "") or ""
    try:
        pp = _promo_poster_path(row_id)
        if _os.path.exists(pp):
            with open(pp, "rb") as f:
                bot.send_photo(to_chat, f, caption=cap[:1020])
        elif cap:
            bot.send_message(to_chat, cap[:4000])
    except Exception as e:
        print("PREVIEW ERR:", str(e)[:100], flush=True)


