def _sched_dt_str(dt):
    return dt.strftime("%Y-%m-%d %H:%M")


def _sched_human(dt):
    return f"{dt.day}-{UZ_MONTHS[dt.month-1]} {dt.strftime('%H:%M')}"


def _promo_schedule(uid, chat_id, row_id, dest, when_dt):
    """Rejaga qo'yish: admin — to'g'ridan; boshqalar — boshliq ruxsati."""
    dname = "Telegram kanal" if dest == "tg" else "Instagram"
    ws = _sched_dt_str(when_dt)
    if uid == CFG.SUPER_ADMIN_ID:
        q("INSERT INTO promo_schedule (row_id,dest,when_at,status,"
          "requested_by,created_at) VALUES (?,?,?,?,?,?)",
          (row_id, dest, ws, "pending", uid, now_str()))
        bot.send_message(chat_id, f"⏰ Post {_sched_human(when_dt)} da "
                                  f"{dname}ga avtomatik joylanadi.")
        return
    q("INSERT INTO promo_schedule (row_id,dest,when_at,status,"
      "requested_by,created_at) VALUES (?,?,?,?,?,?)",
      (row_id, dest, ws, "await", uid, now_str()))
    sid = qone("SELECT last_insert_rowid()")[0]
    _w = qone("SELECT full_name FROM users WHERE tg_id=?", (uid,))
    who = (_w[0] if _w and _w[0] else str(uid))
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(types.InlineKeyboardButton("✅ Ruxsat",
                                      callback_data=f"psch:ok_{sid}"),
           types.InlineKeyboardButton("❌ Rad",
                                      callback_data=f"psch:no_{sid}"))
    try:
        _send_post_preview(CFG.SUPER_ADMIN_ID, row_id)
        bot.send_message(CFG.SUPER_ADMIN_ID,
                         f"🔐 <b>{h(who)}</b> YUQORIDAGI postni "
                         f"{_sched_human(when_dt)} da {dname}ga joylashga "
                         f"ruxsat so'rayapti:",
                         parse_mode="HTML", reply_markup=kb)
        bot.send_message(chat_id, f"🔐 {_sched_human(when_dt)} uchun "
                                  f"boshliqdan ruxsat so'raldi.")
    except Exception as e:
        bot.send_message(chat_id, f"So'rov yuborilmadi: {str(e)[:80]}")


