@bot.callback_query_handler(func=lambda c: c.data.startswith("psc:"))
def promo_sched_cb(call):
    """Vaqt tanlash: psc:{t|i}{n|l|a60|h18|h21|m09|ow}_{row}"""
    if not _promo_allowed(call.from_user.id):
        return
    _ack(call)
    uid, chat_id = call.from_user.id, call.message.chat.id
    code, _, row_id = call.data.replace("psc:", "").partition("_")
    row_id = int(row_id or 0)
    dest, act = code[0], code[1:]
    dest = "tg" if dest == "t" else "ig"
    dname = "Telegram kanal" if dest == "tg" else "Instagram"
    import datetime as _dt
    now = now_dt()
    if act == "n":     # hozir
        (_tg_publish_request if dest == "tg" else _ig_publish_request)(
            uid, chat_id, row_id)
        return
    if act == "l":     # keyinroq — vaqt menyusi
        d = "t" if dest == "tg" else "i"
        kb = types.InlineKeyboardMarkup(row_width=2)
        kb.add(types.InlineKeyboardButton("⏱ 1 soatdan keyin",
                                          callback_data=f"psc:{d}a60_{row_id}"),
               types.InlineKeyboardButton("🌆 Bugun 18:00",
                                          callback_data=f"psc:{d}h18_{row_id}"),
               types.InlineKeyboardButton("🌙 Bugun 21:00",
                                          callback_data=f"psc:{d}h21_{row_id}"),
               types.InlineKeyboardButton("🌅 Ertaga 09:00",
                                          callback_data=f"psc:{d}m09_{row_id}"))
        kb.add(types.InlineKeyboardButton("✍️ Vaqtni o'zim yozaman",
                                          callback_data=f"psc:{d}ow_{row_id}"))
        bot.send_message(chat_id, f"⏰ {dname}ga qachon joylansin?",
                         reply_markup=kb)
        return
    if act == "ow":    # qo'lda vaqt
        W_PROMO_WHEN[uid] = {"row_id": row_id, "dest": dest}
        bot.send_message(chat_id,
                         "Vaqtni yozing: <b>18:30</b> (bugun/ertaga) yoki "
                         "<b>12.08 18:30</b> (sana bilan). Bekor: /bekor",
                         parse_mode="HTML")
        return
    if act == "a60":
        when = now + _dt.timedelta(hours=1)
    elif act.startswith("h"):
        when = now.replace(hour=int(act[1:]), minute=0, second=0,
                           microsecond=0)
        if when <= now:
            when += _dt.timedelta(days=1)
    elif act.startswith("m"):
        when = (now + _dt.timedelta(days=1)).replace(
            hour=int(act[1:]), minute=0, second=0, microsecond=0)
    else:
        return
    _promo_schedule(uid, chat_id, row_id, dest, when)


W_PROMO_WHEN = TDict()


@bot.message_handler(func=lambda m: m.from_user.id in W_PROMO_WHEN
                     and not (m.text or "").startswith("/"))
def promo_when_msg(message):
    import re as _re, datetime as _dt
    uid = message.from_user.id
    t = (message.text or "").strip()
    now = now_dt()
    m1 = _re.fullmatch(r"([01]?\d|2[0-3]):([0-5]\d)", t)
    m2 = _re.fullmatch(r"(\d{1,2})\.(\d{1,2})\s+([01]?\d|2[0-3]):([0-5]\d)", t)
    if m1:
        when = now.replace(hour=int(m1.group(1)), minute=int(m1.group(2)),
                           second=0, microsecond=0)
        if when <= now:
            when += _dt.timedelta(days=1)
    elif m2:
        try:
            when = now.replace(month=int(m2.group(2)), day=int(m2.group(1)),
                               hour=int(m2.group(3)), minute=int(m2.group(4)),
                               second=0, microsecond=0)
            if when <= now:
                when = when.replace(year=now.year + 1)
        except ValueError:
            bot.send_message(message.chat.id, "Sana noto'g'ri. Masalan: "
                                              "12.08 18:30")
            return
    else:
        bot.send_message(message.chat.id, "Format: 18:30 yoki 12.08 18:30")
        return
    st = W_PROMO_WHEN.pop(uid)
    _promo_schedule(uid, message.chat.id, st["row_id"], st["dest"], when)


def promo_sched_thread():
    """⏰ Rejalashtirilgan postlarni vaqti kelganda joylaydi (30 soniyada
    bir tekshiradi; baza orqali — deploy'ga chidamli)."""
    time.sleep(25)
    while True:
        try:
            now = now_dt().strftime("%Y-%m-%d %H:%M")
            rows = qall("SELECT id,row_id,dest,requested_by FROM "
                        "promo_schedule WHERE status='pending' AND "
                        "when_at<=?", (now,))
            for sid, row_id, dest, req_by in (rows or []):
                q("UPDATE promo_schedule SET status='done' WHERE id=?",
                  (sid,))  # takror urinishdan oldin qulf
                err = (_promo_publish(row_id, req_by) if dest == "tg"
                       else _promo_publish_ig(row_id, req_by))
                dname = ("Telegram kanal" if dest == "tg" else "Instagram")
                if err:
                    q("UPDATE promo_schedule SET status='failed' WHERE id=?",
                      (sid,))
                msg = (f"⏰ Rejali post: {dname} — "
                       + ("✅ joylandi!" if not err else f"❌ xato: {err}"))
                for rid in {req_by, CFG.SUPER_ADMIN_ID}:
                    try:
                        bot.send_message(rid, msg)
                    except Exception:
                        pass
                print(f"SCHED: id={sid} row={row_id} {dest} "
                      f"{'OK' if not err else err[:80]}", flush=True)
        except Exception as e:
            print("SCHED THREAD ERR:", str(e)[:120], flush=True)
        time.sleep(30)


