def _promo_send_final(chat_id, uid, row_id):
    """Yoqdi bosilgach: kanal-uslub matn + poster birga (forwardga tayyor)."""
    st = W_PROMO_IMG.get(uid) or {}
    if not st.get("new"):
        pr = qone("SELECT old_price, new_price, promo_until FROM promo_posts "
                  "WHERE id=?", (row_id,))
        if pr and pr[1]:
            st.update(old=pr[0], new=pr[1], until=pr[2])
    row = qone("SELECT name, kind FROM promo_posts WHERE id=?", (row_id,))
    name = row[0] if row else "Mahsulot"
    is_plain = bool((row and row[1] == "plain") or st.get("plain"))
    bot.send_message(chat_id, "✍️ Post matni yozilmoqda...")
    cap = _promo_caption(name, st.get("old"), st.get("new") or 0,
                         until=st.get("until"), plain=is_plain)
    q("UPDATE promo_posts SET status='ok', post_text=? WHERE id=?",
      (cap, row_id))
    poster = st.get("poster")
    if not poster:
        # holat yo'qolgan (deploy/qayta bosish) — fayldan tiklaymiz
        try:
            pp = _promo_poster_path(row_id)
            if _os.path.exists(pp):
                with open(pp, "rb") as f:
                    poster = f.read()
        except Exception as e:
            print("POSTER LOAD ERR:", str(e)[:100], flush=True)
    W_PROMO_IMG.pop(uid, None)
    q("UPDATE promo_posts SET created_by=? WHERE id=?", (uid, row_id))
    if poster:
        try:
            with open(_promo_poster_path(row_id), "wb") as f:
                f.write(poster)
        except Exception as e:
            print("POSTER SAVE ERR:", str(e)[:100], flush=True)
    kb = types.InlineKeyboardMarkup(row_width=1)
    sfx = "" if uid == CFG.SUPER_ADMIN_ID else " (ruxsat so'raladi)"
    kb.add(types.InlineKeyboardButton(f"📢 Telegram kanalga{sfx}",
                                      callback_data=f"ppub:req_{row_id}"),
           types.InlineKeyboardButton(f"📸 Instagram'ga{sfx}",
                                      callback_data=f"pig:req_{row_id}"))
    bot.send_message(chat_id, "✅ Tayyor!")
    if poster:
        import io
        bio = io.BytesIO(poster); bio.name = "poster.jpg"
        try:
            bot.send_photo(chat_id, bio, caption=cap, reply_markup=kb)
            return
        except Exception as e:
            print("PROMO FINAL ERR:", str(e)[:120], flush=True)
    bot.send_message(chat_id, cap, reply_markup=kb)


@bot.callback_query_handler(func=lambda c: c.data.startswith("pfin:"))
def promo_fin_cb(call):
    if not _promo_allowed(call.from_user.id):
        return
    _ack(call)
    uid, chat_id = call.from_user.id, call.message.chat.id
    action, _, row_id = call.data.replace("pfin:", "").partition("_")
    row_id = int(row_id or 0)
    if action == "ok":
        threading.Thread(target=_promo_send_final,
                         args=(chat_id, uid, row_id), daemon=True).start()
    elif action == "re":
        threading.Thread(target=_promo_poster_run,
                         args=(chat_id, uid, row_id), daemon=True).start()


UZ_MONTHS = ["yanvar", "fevral", "mart", "aprel", "may", "iyun", "iyul",
             "avgust", "sentabr", "oktabr", "noyabr", "dekabr"]


def _promo_until_str(days=None, eom=False):
    import datetime as _dt
    d = now_dt().date()
    if eom:
        nxt = (d.replace(day=28) + _dt.timedelta(days=4)).replace(day=1)
        d = nxt - _dt.timedelta(days=1)
    else:
        d = d + _dt.timedelta(days=days or 7)
    return f"{d.day}-{UZ_MONTHS[d.month-1]}"


