def _promo_dead_list():
    """Qotgan pul ro'yxati (tasdiqlanganlari chiqarilgan)."""
    s = INV_CACHE.get("sum")
    if not s or time.time() - INV_CACHE.get("ts", 0) > 7200:
        stock = inv_fetch_stock()
        if not stock:
            return []
        sold = inv_fetch_sold(30)
        s = inv_summarize(stock, sold, days=30)
        INV_CACHE.update(stock=stock, sold=sold, sum=s, ts=time.time())
    # ⛔ Qayta taklif qilinmaydiganlar (2026-08-03 foydalanuvchi so'rovi):
    #   'ok'      — tasdiqlangan: BUTUNLAY chiqadi (post allaqachon bor)
    #   'offered' — javob kutilmoqda: yana taklif qilib spam qilmaymiz
    #   bugun har qanday holatda taklif qilinganlar — shu kun qaytarilmaydi
    #   ('rejected' ertaga qaytishi mumkin — «boshqa mahsulot» degani
    #    «bu mahsulot umuman kerak emas» degani emas)
    skip = {r[0] for r in qall(
        "SELECT product_id FROM promo_posts "
        "WHERE status IN ('ok','offered') OR day=?", (today_str(),))}
    return [p for p in s.get("qotgan_pul", []) if p["id"] not in skip]


def _promo_offer(chat_id, p, replace_id=None, plain=False):
    """Post tayyorlab, tasdiqlash tugmalari bilan yuboradi.
    `plain=True` — oddiy (chegirmasiz) post."""
    try:
        avoid = None
        if replace_id:
            row = qone("SELECT post_text, kind FROM promo_posts WHERE id=?",
                       (replace_id,))
            avoid = row[0] if row else None
            if row and row[1] == "plain":
                plain = True
        text = _promo_ai_post(p, avoid_text=avoid, plain=plain)
    except Exception as e:
        print("PROMO AI ERR:", str(e)[:200], flush=True)
        bot.send_message(chat_id, f"⚠️ Post tayyorlanmadi: {str(e)[:120]}")
        return
    if replace_id:
        q("UPDATE promo_posts SET post_text=?, status='offered' WHERE id=?",
          (text, replace_id))
        pid_row = replace_id
    else:
        cur = q("INSERT INTO promo_posts (product_id, name, post_text, day, created_at, kind) "
                "VALUES (?,?,?,?,?,?)",
                (p["id"], p["name"], text, today_str(), now_str(),
                 "plain" if plain else "sale"))
        pid_row = cur.lastrowid if cur else 0
    kb = types.InlineKeyboardMarkup(row_width=2)
    kb.add(types.InlineKeyboardButton("✅ Bo'ladi", callback_data=f"promo:ok_{pid_row}"),
           types.InlineKeyboardButton("🔁 Bo'lmaydi", callback_data=f"promo:no_{pid_row}"))
    kb.add(types.InlineKeyboardButton("🔄 Boshqa mahsulot",
                                      callback_data=f"promo:other_{pid_row}"))
    amt = f"{p['amount']:g} {p.get('unit') or 'dona'}"
    head = "📄 Oddiy post" if plain else "📣 Aksiya posti"
    bot.send_message(chat_id,
                     f"{head} — <b>{h(p['name'])}</b> "
                     f"(omborda {amt}):\n\n"
                     f"<i>{h(text)}</i>\n\n"
                     f"Qanday, bo'ladimi?",
                     parse_mode="HTML", reply_markup=kb)


def _promo_product_by_row(row_id):
    row = qone("SELECT product_id, name FROM promo_posts WHERE id=?", (row_id,))
    if not row:
        return None
    for p in (INV_CACHE.get("stock") or []):
        if p["id"] == row[0]:
            return p
    return {"id": row[0], "name": row[1], "amount": 0, "unit": "dona"}


@bot.callback_query_handler(func=lambda c: c.data.startswith("promo:"))
def promo_cb(call):
    if not _promo_allowed(call.from_user.id):
        return
    _ack(call)
    chat_id = call.message.chat.id
    action, _, row_id = call.data.replace("promo:", "").partition("_")

    if action == "pick":
        # row_id bu yerda product_id
        p = next((x for x in (INV_CACHE.get("stock") or [])
                  if x["id"] == row_id), None)
        if not p:
            bot.send_message(chat_id, "Mahsulot keshda topilmadi — /inventar yuboring.")
            return
        threading.Thread(target=_promo_offer, args=(chat_id, p), daemon=True).start()
        bot.send_message(chat_id, "✍️ Post tayyorlanmoqda...")
        return

    row_id = int(row_id or 0)
    if action == "ok":
        row = qone("SELECT product_id, name FROM promo_posts WHERE id=?", (row_id,))
        if not row:
            return
        q("UPDATE promo_posts SET status='ok' WHERE id=?", (row_id,))
        # 💰 2026-08-08 yangi oqim: avval NARX (Bito'dan avtomatik) →
        # chegirma → rasm → AI poster → yoqdi/boshqasi → kanal matni
        uid = call.from_user.id
        def price_stage():
            pid, name = row[0], row[1]
            sale = _promo_sale_price(pid)
            cost = _promo_cost_price(pid)
            lines = [f"💰 <b>{h(name)}</b>"]
            lines.append(f"Sotuv narxi: <b>{_promo_money(sale)} so'm</b>"
                         if sale else "Sotuv narxi: Bito'da topilmadi")
            lines.append(f"Kelish narxi: <b>{_promo_money(cost)} so'm</b>"
                         if cost else "Kelish narxi: aniqlanmadi")
            if sale and cost:
                marj = (sale - cost) / sale * 100
                lines.append(f"(marja ~{marj:.0f}%)")
            kindrow = qone("SELECT kind FROM promo_posts WHERE id=?", (row_id,))
            is_plain = bool(kindrow and kindrow[0] == "plain")
            W_PROMO_IMG[uid] = {"row_id": row_id, "sale": sale,
                                "cost": cost, "step": "disc",
                                "plain": is_plain}
            # 📄 ODDIY POST: chegirma bosqichi o'tkazib yuboriladi —
            # Bito'dagi sotuv narxi to'g'ridan-to'g'ri ishlatiladi
            if is_plain and sale:
                q("UPDATE promo_posts SET old_price=NULL, new_price=? WHERE id=?",
                  (sale, row_id))
                W_PROMO_IMG[uid].update(old=None, new=sale, step="pick")
                lines.append("\n📄 Oddiy post — chegirmasiz, shu narx bilan.")
                bot.send_message(chat_id, "\n".join(lines), parse_mode="HTML")
                promo_image_stage(chat_id, uid, row_id)
                return
            if is_plain and not sale:
                W_PROMO_IMG[uid]["step"] = "await_price2"
                lines.append("\nNarxni yozing (masalan: 12000):")
                bot.send_message(chat_id, "\n".join(lines), parse_mode="HTML")
                return
            if sale:
                kb = types.InlineKeyboardMarkup(row_width=3)
                kb.add(*[types.InlineKeyboardButton(
                    f"-{pc}% ({_promo_money(int(round(sale*(100-pc)/100/500)*500))})",
                    callback_data=f"pd2:{pc}_{row_id}") for pc in (10, 15, 20)])
                kb.add(types.InlineKeyboardButton(
                    "✍️ O'zim yozaman", callback_data=f"pd2:own_{row_id}"))
                lines.append("\nChegirmani tanlang:")
                bot.send_message(chat_id, "\n".join(lines),
                                 parse_mode="HTML", reply_markup=kb)
            else:
                W_PROMO_IMG[uid]["step"] = "await_price2"
                lines.append("\nAksiya narxini yozing (masalan: 84000):")
                bot.send_message(chat_id, "\n".join(lines), parse_mode="HTML")
        threading.Thread(target=price_stage, daemon=True).start()
        return

    if action == "no":
        p = _promo_product_by_row(row_id)
        if not p:
            return
        bot.send_message(chat_id, "🔁 Yangi variant tayyorlanmoqda...")
        threading.Thread(target=_promo_offer, args=(chat_id, p),
                         kwargs={"replace_id": row_id}, daemon=True).start()
        return

    if action == "other":
        q("UPDATE promo_posts SET status='rejected' WHERE id=?", (row_id,))
        dead = _promo_dead_list()[:8]
        if not dead:
            bot.send_message(chat_id, "Qotgan pul ro'yxati bo'sh yoki kesh eski — "
                                      "/inventar yuboring.")
            return
        kb = types.InlineKeyboardMarkup(row_width=1)
        for p in dead:
            kb.add(types.InlineKeyboardButton(
                f"{p['name'][:40]} · {inv_money(p['value'])} so'm",
                callback_data=f"promo:pick_{p['id']}"))
        bot.send_message(chat_id, "Qaysi mahsulotga post kerak?",
                         reply_markup=kb)
        return


