@bot.callback_query_handler(func=lambda c: c.data.startswith("pmenu:"))
def promo_menu_cb(call):
    if not _promo_allowed(call.from_user.id):
        return
    _ack(call)
    uid, chat_id = call.from_user.id, call.message.chat.id
    action = call.data.replace("pmenu:", "")
    if action == "stale":
        bot.send_message(chat_id, "✍️ Qotgan pul ro'yxati o'qilmoqda...")
        def run():
            dead = _promo_dead_list()
            if not dead:
                bot.send_message(chat_id, "Qotgan pul ro'yxati bo'sh yoki "
                                          "kesh eski — /inventar yuboring.")
