# 🖼 POST RASMI — internetdan qidirish / o'zi yuklash
#
# Oqim: matn tasdiqlangach (✅ Bo'ladi) rasm bosqichi boshlanadi:
# DuckDuckGo'dan 3 nomzod rasm → tanlash / 🖼 o'zim yuklayman / 🚫 rasmsiz.
# Yakuniy post = rasm + matn BIRGA (kanalga forward qilishga tayyor).
# DDG tanlandi chunki API kaliti talab qilmaydi; ishlamay qolsa
# foydalanuvchi o'z rasmini yuklash yo'li har doim ochiq.
# ──────────────────────────────────────────────────────────────────

W_PROMO_IMG = TDict()   # uid -> {"row_id", "urls": [...], "step": "pick"/"await_upload"}

_DDG_UA = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                         "AppleWebKit/537.36 (KHTML, like Gecko) "
                         "Chrome/124.0 Safari/537.36"}


def ddg_image_search(query, n=3):
    """DuckDuckGo rasm qidiruvi (norasmiy, kalitsiz). Xatoda bo'sh ro'yxat."""
    try:
        s = requests.Session()
        r = s.get("https://duckduckgo.com/", params={"q": query},
                  headers=_DDG_UA, timeout=15)
        import re as _re
        m = (_re.search(r"vqd=([\d-]+)&", r.text)
             or _re.search(r"vqd='([\d-]+)'", r.text)
             or _re.search(r'vqd="([\d-]+)"', r.text))
        if not m:
            print("DDG IMG: vqd topilmadi", flush=True)
            return []
        r2 = s.get("https://duckduckgo.com/i.js",
                   params={"l": "wt-wt", "o": "json", "q": query,
                           "vqd": m.group(1), "p": "1"},
                   headers=_DDG_UA, timeout=15)
        results = (r2.json() or {}).get("results", [])
        urls = []
        for x in results:
            u = x.get("image") or ""
            if u.startswith("http"):
                urls.append(u)
            if len(urls) >= n:
                break
        return urls
    except Exception as e:
        print("DDG IMG ERR:", str(e)[:150], flush=True)
        return []


