def _promo_poster_texts(name):
    """Poster uchun QISQA matnlar: ko'rgazmali sarlavha + 3 afzallik
    (har biri 2-3 so'z, lotin). AI rasmda uzun matnni buzadi — qisqa
    va aniq bo'lsa toza chiqadi. Xato bo'lsa universal zaxira."""
    try:
        headers = {"x-api-key": ANTHROPIC_API_KEY,
                   "anthropic-version": "2023-06-01",
                   "content-type": "application/json"}
        prompt = (
            f'Mahsulot: "{name}". Supermarket aksiya posteri uchun FAQAT '
            f'JSON qaytar (boshqa hech narsa yozma):\n'
            f'{{"headline": "mahsulotning qisqa ko\'rgazmali nomi '
            f'(2-4 so\'z, LOTIN harfda, katta harflar)", '
            f'"benefits": ["3 ta afzallik, har biri 2-3 so\'z, lotin, '
            f'halol va ishonarli"]}}')
        r = requests.post("https://api.anthropic.com/v1/messages",
                          headers=headers,
                          json={"model": "claude-sonnet-4-6",
                                "max_tokens": 200,
                                "messages": [{"role": "user",
                                              "content": prompt}]},
                          timeout=45)
        r.raise_for_status()
        txt = "".join(b.get("text", "") for b in r.json().get("content", [])
                      if b.get("type") == "text")
        import json as _json, re as _re
        m = _re.search(r"\{.*\}", txt, _re.S)
        d = _json.loads(m.group(0)) if m else {}
        head = (d.get("headline") or "").strip()[:40]
        bens = [str(b).strip()[:28] for b in (d.get("benefits") or [])][:3]
        if head and len(bens) == 3:
            return head, bens
    except Exception as e:
        print("POSTER TEXTS ERR:", str(e)[:100], flush=True)
    return (name[:34].upper(),
            ["Sifat kafolati", "Halol mahsulot", "Yetkazib berish bor"])


