def ai_make_poster(image_bytes, mime="image/jpeg"):
    """Rasm-sahna: avval OpenAI (kalit bo'lsa), bo'lmasa Gemini.
    2026-08-07: zaxiraga o'tishда OpenAI xatosi faqat logda qolib,
    foydalanuvchi Gemini 429 ni ko'rib chalg'igan — endi HAMMA
    urinishlar xatosi birga qaytadi."""
    errors = []
    if not OPENAI_API_KEY:
        errors.append("OpenAI: OPENAI_API_KEY bot muhitida KO'RINMAYAPTI "
                      "(Railway'da qo'shilgan bo'lsa — redeploy kutilmagan)")
    else:
        img, err = openai_make_poster(image_bytes, mime)
        if img:
            return img, None, "OpenAI"
        errors.append(f"OpenAI: {err}")
        print(f"IMG: OpenAI ishlamadi ({err}), Gemini sinaladi", flush=True)
    if GEMINI_API_KEY:
        img, err = gemini_make_poster(image_bytes, mime)
        if img:
            return img, None, "Gemini (zaxira)"
        errors.append(f"Gemini: {err}")
    return None, "\n\n".join(errors), "AI"


