@api.route("/webapp/maqsad/save", methods=["POST"])
def webapp_maqsad_save():
    try:
        data = request.get_json(force=True, silent=True) or {}
        uid = int(data.get("uid") or 0)
        ok, uid = _webapp_user_ok(str(uid), data.get("token") or "", maqsad_token_ok)
        if not ok:
            return jsonify({"ok": False, "error": "Havola eskirgan"}), 200
        incoming = data.get("goals") or []
        existing = {(g["code"], g["title"]): g for g in goals_all()}
        need_strategy = []
        for g in incoming:
            code = g.get("code") or "custom"
            title = g.get("title") or ""
            on = 1 if g.get("on") else 0
            old = existing.get((code, title))
            if old:
                q("UPDATE goals SET is_active=?, target_value=?, deadline=?, "
                  "target_unit=?, updated_at=? WHERE id=?",
                  (on, float(g.get("target") or 0), g.get("deadline") or "",
                   g.get("unit") or "%", now_str(), old["id"]))
                gid = old["id"]
                # daraja/muddat o'zgargan bo'lsa strategiya qayta yoziladi
                changed = (abs((old["target_value"] or 0) - float(g.get("target") or 0)) > 0.001
                           or (old["deadline"] or "") != (g.get("deadline") or ""))
                if on and (not old["strategy"] or changed):
                    need_strategy.append(gid)
            else:
                cur = q("INSERT INTO goals (code, title, is_active, target_value, "
                        "target_unit, deadline, created_at, updated_at) "
                        "VALUES (?,?,?,?,?,?,?,?)",
                        (code, title, on, float(g.get("target") or 0),
                         g.get("unit") or "%", g.get("deadline") or "",
                         now_str(), now_str()))
                gid = cur.lastrowid if cur else None
                if on and gid:
                    need_strategy.append(gid)
        print(f"MAQSAD SAVE: {len(incoming)} maqsad, {len(need_strategy)} ta strategiya kerak",
              flush=True)

        def run():
            if not need_strategy:
                bot.send_message(uid, "✅ Maqsadlar saqlandi.")
                return
            bot.send_message(uid, f"⏳ {len(need_strategy)} ta maqsad uchun strategiya "
                                  f"tayyorlanmoqda...")
            base = goal_baselines()
            for gid in need_strategy:
                g = next((x for x in goals_all() if x["id"] == gid), None)
                if g:
                    build_goal_strategy(uid, g, base)
        threading.Thread(target=run, daemon=True).start()
        return jsonify({"ok": True}), 200
    except Exception as ex:
        print("MAQSAD SAVE ERR:", repr(ex)[:200], flush=True)
        return jsonify({"ok": False, "error": str(ex)[:120]}), 200


