@api.route("/webapp/firmalar/save", methods=["POST"])
def webapp_firmalar_save():
    try:
        data = request.get_json(force=True, silent=True) or {}
        uid = int(data.get("uid") or 0)
        ok, uid = _webapp_user_ok(str(uid), data.get("token") or "", firma_token_ok)
        if not ok:
            return jsonify({"ok": False, "error": "Havola eskirgan"}), 200
        firms = data.get("firms") or []
        expenses = data.get("expenses") or []
        for f in firms:
            supplier_plan_save(f["id"], f.get("name") or "", f.get("visit_days") or "",
                               f.get("pay_term_days") or 0,
                               (f.get("pay_term_days") or 0) == 0 and not f.get("takes_credit"),
                               "", f.get("takes_credit") or 0, f.get("debt_swap") or 0)
            if f.get("due_date"):
                debt_due_save(f["id"], f.get("name") or "", f["due_date"], f.get("debt") or 0)
        # Xarajatlar to'liq almashtiriladi — o'chirilganlar ham yo'qolsin
        q("DELETE FROM fixed_expense")
        for e in expenses:
            q("""INSERT INTO fixed_expense
                 (name, amount, payee, period, day_of_month, day_of_week,
                  once_date, is_active, bito_type_id, employee_tg_id,
                  auto_percent, percent_base, created_at)
                 VALUES (?,?,?,?,?,?,?,1,?,?,?,?,?)""",
              (e.get("name") or "", float(e.get("amount") or 0), e.get("payee") or "",
               e.get("period") or "monthly", int(e.get("day_of_month") or 1),
               int(e.get("day_of_week") or 1), e.get("once_date") or "",
               e.get("bito_type_id") or "", int(e.get("employee_tg_id") or 0),
               float(e.get("auto_percent") or 0), e.get("percent_base") or "",
               now_str()))
        print(f"FIRMA SAVE: {len(firms)} firma, {len(expenses)} xarajat", flush=True)
        try:
            bot.send_message(uid, f"✅ Saqlandi: <b>{len(firms)}</b> ta firma jadvali, "
                                  f"<b>{len(expenses)}</b> ta majburiy xarajat.",
                             parse_mode="HTML")
        except Exception:
            pass
        return jsonify({"ok": True}), 200
    except Exception as ex:
        print("FIRMA SAVE ERR:", str(ex)[:200], flush=True)
        return jsonify({"ok": False, "error": str(ex)[:120]}), 200


@api.route("/webapp/plu", methods=["GET"])
def webapp_plu():
    """⚖️ PLU taxminini tekshirish oynasi. Har qatorda: mahsulot nomi,
    taklif qilingan raqam (tahrirlanadi) va belgilash katagi."""
