def _nak_price_item(product_id, product_name):
    """Bitta mahsulotning sotuv narx-ro'yxatidagi yozuvini qaytaradi: (amount, entry_id).

    ⚠️ Nega alohida funksiya: `_promo_sale_price` mahsulot NOMINI promo_posts jadvali
    yoki INV_CACHE'dan qidiradi — nakladnoyda bog'langan mahsulot ularning hech qaysida
    yo'q. Nomsiz so'rov esa ro'yxatning birinchi 50 tasini qaytarib, "narx topilmadi"
    deb xulosa chiqarardi. Bu yerda nom TASHQARIDAN (Bito qidiruv natijasidan) beriladi.
    `_get_bito_sale_prices` esa butun ro'yxatni sahifalab o'qiydi — sahifa uchun juda sekin."""
    if not product_id or not product_name:
        return None, ""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    price_id = tenant_setting("bito_sale_price_id", "694250a9c9b42022084696f6")
    body = {"price_id": price_id, "page": 1, "limit": 50, "search": str(product_name)[:60]}
    cached = tenant_setting("bito_price_items_path", "")
    candidates = ([cached] if cached else []) + [
        "price-items/get-paging", "price-item/get-paging",
        "price/items/get-paging", "price/get-items-paging"]
    seen = set()
    for path in candidates:
        if not path or path in seen:
            continue
        seen.add(path)
        try:
            r = requests.post(BITO_BASE_URL + path, json=body, headers=headers, timeout=15)
            if r.status_code != 200:
                continue
            d = (r.json() or {}).get("data") or {}
            rows = d.get("data", []) if isinstance(d, dict) else (d if isinstance(d, list) else [])
            if not isinstance(rows, list):
                continue
            if path != cached:
                set_setting("bito_price_items_path", path)
            for it in rows:
                if (it.get("product") or {}).get("_id") == product_id and it.get("amount"):
                    return float(it["amount"]), str(it.get("_id") or "")
            return None, ""   # yo'l ishladi, bu mahsulotda narx yo'q
        except Exception as e:
            print(f"NAK PRICE ITEM [{path}] ERR:", str(e)[:110], flush=True)
    return None, ""


@api.route("/webapp/nakladnoy/product-info", methods=["POST"])
def webapp_nakladnoy_product_info():
    """Bog'langan mahsulotning QOLGAN ma'lumotlarini qaytaradi: joriy sotuv narxi
    (+ uni yangilash uchun entry_id), o'lchov birligi va bot xotirasidagi blok hajmi.
    Qidiruv natijasida bularning hammasi bo'lmaydi — bog'langandan keyin alohida olinadi,
    aks holda katak "tanlanmagan / narx kiritilmagan" bo'lib qolardi."""
    try:
        data = request.get_json(force=True, silent=True) or {}
        uid = int(data.get("uid", 0) or 0)
        token = str(data.get("token", "") or "")
        if not nak_webapp_valid(uid, token):
            return jsonify({"ok": False, "error": "Sessiya eskirgan"}), 403
        pid = str(data.get("product_id", "") or "").strip()
        if not pid:
            return jsonify({"ok": False, "error": "product_id yo'q"}), 400
        out = {"sale_price": None, "price_entry_id": "", "measure_id": "",
               "measure_name": "", "block_size": None}
        # 🏷 Joriy sotuv narxi.
        # ⚠️ `_get_bito_sale_prices` BUTUN narx ro'yxatini sahifalab o'qiydi (65 sahifagacha) —
        # narxi yo'q mahsulotda u o'nlab soniya ketadi va sahifa qotib qolardi.
        # `_promo_sale_price` esa nom bo'yicha QIDIRIB, bitta so'rovda javob beradi.
        bname = str(data.get("bito_name", "") or "").strip()
        try:
            amt, entry = _nak_price_item(pid, bname)
            if amt:
                out["sale_price"] = amt
                out["price_entry_id"] = entry
        except Exception as e:
            print("NAK INFO PRICE ERR:", str(e)[:120], flush=True)
        # 📏 O'lchov birligi — lokal katalog keshidan
        try:
            cat_p = next((p for p in (NAK_CATALOG_CACHE.get("products") or [])
                          if p.get("id") == pid), None)
            if cat_p:
                out["measure_id"] = cat_p.get("measure_id") or ""
                out["measure_name"] = cat_p.get("measure_name") or ""
        except Exception:
            pass
        # 🧊 Blok hajmi — shu mahsulot uchun avval eslab qolingan bo'lsa
        try:
            al = nak_get_alias(str(data.get("name", "") or ""))
            if al and al.get("product_id") == pid and al.get("block_size"):
                out["block_size"] = al["block_size"]
        except Exception:
            pass
        return jsonify({"ok": True, "info": out})
    except Exception as e:
        print("NAK WEBAPP INFO ERR:", str(e)[:150], flush=True)
        return jsonify({"ok": False, "error": "Server xatosi"}), 500


@api.route("/webapp/nakladnoy/save", methods=["POST"])
def webapp_nakladnoy_save():
    """Web App'dan tahrirlangan itemlarni qabul qiladi (inline tugma uchun yagona ishonchli yo'l).
    Token tekshiriladi — faqat botdan olingan havola egasi saqlay oladi."""
    try:
        data = request.get_json(force=True, silent=True) or {}
        uid = int(data.get("uid", 0) or 0)
        token = str(data.get("token", "") or "")
        entry = nak_webapp_valid(uid, token)  # oxirgi 8 ta tugma amal qiladi
        if not entry:
            return jsonify({"ok": False, "error": "Sessiya eskirgan. Botga qaytib tugmani qayta bosing."}), 403
        raw_items = data.get("items", [])
        if not isinstance(raw_items, list):
            return jsonify({"ok": False, "error": "Noto'g'ri format"}), 400
        # ⚠️ MUHIM: eski tokenni APPLY'DAN OLDIN bekor qilamiz. Chunki apply ichida
        # yangi tugma uchun YANGI token yaratiladi — uni o'chirib yubormasligimiz kerak.
        nak_webapp_invalidate(uid)  # barcha tokenlar bekor qilinadi
        want_upload = bool(data.get("upload", False))
        ok, msg = _nak_apply_webapp_items(uid, raw_items, silent_summary=want_upload)
        # 🚀 "Bito'ga yuklash" tugmasi — saqlab, darhol yuklashni ham boshlaymiz.
        # Shu bilan nakladnoy bo'yicha BARCHA harakat shu sahifada tugaydi.
        if ok and want_upload:
            st_now = nak_session_restore(uid)
            if st_now:
                nak_start_upload(uid, uid, st_now)
            else:
                return jsonify({"ok": False, "error": "Sessiya topilmadi"})
        return jsonify({"ok": ok, "error": None if ok else msg})
    except Exception as e:
        print("NAK WEBAPP SAVE ERR:", str(e)[:150], flush=True)
        return jsonify({"ok": False, "error": "Server xatosi"}), 500

