@api.route("/api/attendance/checkin", methods=["POST"])
@require_auth
def api_checkin():
    tg_id = request.current_user[0]; name = request.current_user[1]
    open_sess = qone("SELECT id FROM attendance WHERE tg_id=? AND checkout_time IS NULL "
                      "ORDER BY id DESC LIMIT 1", (tg_id,))
    if open_sess:
        return jsonify({"error": "Siz allaqachon kelgansiz, avval ketishni belgilang"}), 400
    q("INSERT INTO attendance (tg_id,employee_name,checkin_time,work_date) VALUES (?,?,?,?)",
      (tg_id, name, now_str(), today_str()))
    score = apply_checkin_scoring(tg_id, name, now_dt())
    if score is None:
        add_points(tg_id, name, 1)
        score = ("none", 1, None)
    return jsonify({"ok": True, "time": now_dt().strftime("%H:%M"),
                     "status": score[0], "points": score[1], "expected": score[2]})

@api.route("/api/attendance/checkout", methods=["POST"])
@require_auth
def api_checkout():
    tg_id = request.current_user[0]; name = request.current_user[1]
    sess = qone("SELECT id, checkin_time FROM attendance WHERE tg_id=? AND checkout_time IS NULL "
                "ORDER BY id DESC LIMIT 1", (tg_id,))
    if not sess:
        return jsonify({"error": "Avval kelishni belgilang"}), 400
    ci_dt = datetime.strptime(str(sess[1]), "%Y-%m-%d %H:%M:%S").replace(tzinfo=UZT)
    diff = (now_dt() - ci_dt).total_seconds()
    if diff < 0: diff += 86400
    mins = max(0, int(diff / 60))
    salary = salary_for_minutes(tg_id, mins)
    q("UPDATE attendance SET checkout_time=?,work_minutes=? WHERE id=?", (now_str(), mins, sess[0]))
    score = apply_checkout_scoring(tg_id, name, now_dt(), ci_dt=ci_dt)
    return jsonify({"ok": True, "time": now_dt().strftime("%H:%M"),
                     "work_minutes": mins, "salary": salary,
                     "status": score[0] if score else "none",
                     "points": score[1] if score else 0,
                     "expected": score[2] if score else None})

@api.route("/api/voice", methods=["POST"])
@require_auth
def api_voice():
    """Mobil ilova uchun ovozli buyruq: audio fayl qabul qiladi (multipart 'audio'
    maydoni, m4a/ogg/mp3), transkripsiya + intent aniqlanadi. Natijalar Telegram'ga
    EMAS, to'g'ridan-to'g'ri JSON javobda qaytariladi (ilova ko'rsatishi uchun).
    Og'ir intentlar (zakaz, stale) uchun natija Telegram orqali yuboriladi (chunki
    ular uzoq davom etadi) — javobda shunday deb aytiladi."""
    tg_id = request.current_user[0]
    file = request.files.get("audio")
    if not file:
        return jsonify({"error": "audio fayl kerak (multipart 'audio' maydoni)"}), 400
    mime = file.mimetype or "audio/ogg"
    transcript, err = transcribe_audio(file.read(), mime, file.filename or "voice.m4a")
    if err:
        return jsonify({"error": err}), 500
    intent_data = route_voice_intent(tg_id, transcript)
    intent = intent_data["intent"]
    print(f"[VOICE-API] {tg_id}: '{transcript[:60]}' -> {intent}", flush=True)

    if intent == "chat":
        return jsonify({"transcript": transcript, "intent": intent,
                         "reply": intent_data.get("reply", "")})
    if intent == "my_report":
        pts = get_points(tg_id); pv = get_point_value()
        bmap = get_bito_map(); bname = bmap.get(tg_id)
        gross = 0
        if bname:
            df, dt_ = bito_period_utc(today_str())
            sd = get_bito_sales_dict(df, dt_)
            item = sd.get(bname) if sd else None
            gross = (item.get("gross_sales", 0) if item else 0) or 0
        rate = get_bito_bonus_rate()
        reply = (f"Bugungi savdongiz: {fmt_money(int(gross))}. "
                 f"Bonus: {fmt_money(round(gross*rate))}. "
                 f"Ballaringiz: {pts} ({fmt_money(round(pts*pv))}).")
        return jsonify({"transcript": transcript, "intent": intent, "reply": reply})
    # Og'ir intentlar — Telegram orqali yuboriladi
    execute_voice_intent(tg_id, tg_id, intent_data, transcript)
    return jsonify({"transcript": transcript, "intent": intent,
                     "reply": "So'rov qabul qilindi — natija Telegram botga yuboriladi (1-2 daqiqa)."})


