DASH_COOKIE = "dash_session"

def _dash_make_cookie(tg_id):
    payload = {"tg_id": tg_id, "purpose": "dashboard", "iat": datetime.utcnow().timestamp()}
    return pyjwt.encode(payload, APP_JWT_SECRET, algorithm="HS256")

def _dash_current_user():
    """Cookie'dan foydalanuvchini oladi. Faqat boss/manager ruxsat etiladi.
    Qaytaradi: get_user() natijasi yoki None."""
    token = request.cookies.get(DASH_COOKIE, "")
    if not token:
        return None
    try:
        payload = pyjwt.decode(token, APP_JWT_SECRET, algorithms=["HS256"])
        if payload.get("purpose") != "dashboard":
            return None
    except Exception:
        return None
    u = get_user(payload.get("tg_id"))
    if not u or u[2] not in ("boss", "manager"):
        return None
    return u

