def _app_page(title, body_html, extra_css=""):
    """Ilova sahifalari uchun umumiy qolip — bir xil ko'rinish bo'lsin."""
    return """<!DOCTYPE html>
<html lang="uz"><head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
<meta name="theme-color" content="#2481cc">
<title>__TITLE__</title>
<style>
  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
  body { font-family: -apple-system, "Segoe UI", Roboto, sans-serif; margin: 0;
         background: #eef1f6; color: #16181d; padding-bottom: 30px; }
  .wrap { max-width: 900px; margin: 0 auto; padding: 12px; }
  .backbar { position: sticky; top: 0; z-index: 50;
             background: rgba(238,241,246,.92); backdrop-filter: blur(8px);
             padding: 10px 12px; border-bottom: 1px solid #dfe3ea; }
  .dots { display: flex; gap: 7px; justify-content: center; }
  .dots span { width: 11px; height: 11px; border-radius: 50%; background: #2481cc;
               animation: bounce 1.3s infinite ease-in-out; }
  .dots span:nth-child(2) { animation-delay: .16s; }
  .dots span:nth-child(3) { animation-delay: .32s; }
  @keyframes bounce { 0%,80%,100% { transform: scale(.55); opacity: .45; }
                      40% { transform: scale(1); opacity: 1; } }
  .backbar a { display: inline-block; padding: 8px 14px; border-radius: 8px;
      background: #fff; color: inherit; text-decoration: none; font-size: 14px;
      font-weight: 600; box-shadow: 0 1px 2px rgba(0,0,0,.06); }
  h2 { font-size: 19px; margin: 12px 0 10px; }
  .card { background: #fff; border-radius: 12px; padding: 14px; margin-bottom: 10px;
          box-shadow: 0 1px 3px rgba(0,0,0,.07); }
  .big { font-size: 24px; font-weight: 700; margin: 4px 0; }
  .lbl { font-size: 13px; color: #777; }
  .row { display: flex; justify-content: space-between; gap: 10px;
         padding: 7px 0; border-bottom: 1px solid #f0f1f3; font-size: 14px; }
  .row:last-child { border-bottom: none; }
  .red { color: #c0392b; } .green { color: #1e8449; } .orange { color: #b35c00; }
  .warn { background: #fdecea; border-left: 4px solid #c0392b; }
  .muted { font-size: 12px; color: #888; line-height: 1.5; margin-top: 10px; }
  .spin { text-align: center; padding: 40px 12px; color: #777; }
  .bar2 { height: 8px; background: #e8ebf0; border-radius: 6px; margin: 10px 0 4px;
          overflow: hidden; }
  .bar2 div { height: 100%; background: linear-gradient(90deg,#2b6fd6,#1e8449); }
  .mini { border: none; border-radius: 8px; background: #1e8449; color: #fff;
          padding: 7px 12px; font-size: 15px; margin-left: 5px; }
  .mini.red2 { background: #c0392b; }
  .mini:disabled { opacity: .6; }
__EXTRA_CSS__
</style></head><body>
<div class="backbar"><a href="/app">← Orqaga</a></div>
<div class="wrap">__BODY__</div>
</body></html>""".replace("__TITLE__", title).replace("__BODY__", body_html) \
                 .replace("__EXTRA_CSS__", extra_css)


def _loader_html(data_url, title, subtitle):
    """Yuklanish ko'rsatkichi: sahifa darhol ochiladi, ma'lumot fonda keladi."""
    return """<h2>__TITLE__</h2>
<div id="box">
  <div class="card" style="text-align:center;padding:34px 16px">
    <div class="dots"><span></span><span></span><span></span></div>
    <div style="margin-top:16px;font-weight:600">Ma'lumotlar yuklanmoqda</div>
    <div class="lbl" style="margin-top:6px">__SUB__</div>
    <div class="lbl" id="tick" style="margin-top:12px">0 soniya</div>
    <div class="lbl" style="margin-top:10px">Bu 30–60 soniya olishi mumkin —
      Bito'dan 10 000 dan ortiq mahsulot o'qilyapti.</div>
  </div>
</div>
<script>
let sec = 0;
const timer = setInterval(() => {
  sec++;
  const el = document.getElementById("tick");
  if (el) el.textContent = sec + " soniya";
}, 1000);
fetch("__URL__", {credentials: "same-origin"})
  .then(r => r.text())
  .then(html => { clearInterval(timer); document.getElementById("box").innerHTML = html; })
  .catch(e => {
    clearInterval(timer);
    document.getElementById("box").innerHTML =
      '<div class="card warn">⚠️ Yuklab bo\\'lmadi: ' + e.message +
      '<br><br><a href="">Qayta urinish</a></div>';
  });
</script>""".replace("__TITLE__", title).replace("__SUB__", subtitle) \
            .replace("__URL__", data_url)


@api.route("/app/maqsad", methods=["GET"])
def app_maqsad_view():
    """🎯 Maqsadlar — strategiya, bosqichlar va bugungi reja bir sahifada."""
    u = _dash_current_user()
    if not u:
        return make_response('<html><head><meta http-equiv="refresh" '
                             'content="0;url=/dashboard/login"></head></html>')
    return make_response(_app_page("Maqsadlar", _loader_html(
        "/app/maqsad/data", "🎯 Maqsadlar",
        "Bosqichlar va joriy qoldiqlar tekshirilmoqda")))


@api.route("/app/maqsad/data", methods=["GET"])
def app_maqsad_data():
    u = _dash_current_user()
    if not u:
        return make_response("<div class='card warn'>Sessiya tugagan.</div>")
    gs = [g for g in goals_all() if g["is_active"]]
    if not gs:
        return make_response(
            '<div class="card">Hali maqsad belgilanmagan.<br><br>'
            '<a href="/webapp/maqsad" style="font-weight:600;color:#2481cc;'
            'text-decoration:none">➕ Maqsad belgilash →</a></div>')
    try:
        by_name, units = _stock_index()
    except Exception:
        by_name, units = {}, {}
    today = now_dt().strftime("%Y-%m-%d")
    b = []
    for g in gs:
        steps = goal_steps(g["id"])
        done = sum(1 for s in steps if s["status"] == "done")
        pct = int(done * 100 / len(steps)) if steps else 0
        b.append(f'<div class="card"><b>🎯 {h(g["title"])}</b><br>'
                 f'<span class="lbl">{g["target_value"]}{g["target_unit"]}'
                 + (f", {g['deadline']} gacha" if g["deadline"] else "") + '</span>')
        if not g["approved"]:
            b.append('<div class="row orange">⏳ Strategiya tasdiqlanmagan — '
                     'botda tasdiqlang</div>')
        if g["strategy"]:
            b.append(f'<div class="lbl" style="margin-top:8px">{h(g["strategy"])}</div>')
        if steps:
            b.append(f'<div class="bar2"><div style="width:{pct}%"></div></div>'
                     f'<div class="lbl">{pct}% ({done}/{len(steps)})</div>')
        for s in steps:
            icon = {"done": "✅", "skipped": "⏭"}.get(s["status"], "⬜")
            b.append(f'<div class="row"><span>{icon} <b>{s["step_no"]}. '
                     f'{h(s["title"])}</b><br><span class="lbl">{h(s["detail"])}</span>')
            live = _live_stock_note(s["title"] + " " + s["detail"], by_name, units)
            if live:
                b.append('<br><span class="lbl green">📊 Hozir: '
                         + ", ".join(f"{h(n)} — {round(q,1)} {u}" for n, q, u in live)
                         + '</span>')
            b.append('</span>')
            if s["status"] == "pending":
                b.append(f'<span><button class="mini" onclick="mark({s["id"]},this)">'
                         f'✓</button></span>')
            b.append('</div>')
        # bugungi reja
        rows = daily_rows(g["id"], today)
        if rows:
            b.append('<div class="lbl" style="margin-top:12px"><b>📅 Bugungi vazifalar</b></div>')
            for r in rows:
                ic = {"done": "✅", "failed": "❌"}.get(r["status"], "⬜")
                b.append(f'<div class="row"><span>{ic} <b>{h(r["task"])}</b><br>'
                         f'<span class="lbl">{h(r["detail"])}</span></span>')
                if r["status"] == "pending":
                    b.append(f'<span><button class="mini" onclick="dmark({r["id"]},1,this)">✓</button>'
                             f'<button class="mini red2" onclick="dmark({r["id"]},0,this)">✗</button></span>')
                b.append('</div>')
        b.append('</div>')
    b.append('<div class="card"><a href="/webapp/maqsad" style="font-weight:600;'
             'color:#2481cc;text-decoration:none">⚙️ Maqsadlarni o\'zgartirish →</a></div>')
    b.append("""
<script>
function mark(id, el) {
  el.disabled = true; el.textContent = "…";
  fetch("/app/maqsad/step/" + id, {method: "POST", credentials: "same-origin"})
    .then(r => r.json()).then(d => { el.textContent = d.ok ? "✅" : "✗"; })
    .catch(() => { el.disabled = false; el.textContent = "✓"; });
}
function dmark(id, ok, el) {
  const p = el.parentNode; p.innerHTML = "…";
  fetch("/app/maqsad/daily/" + id + "/" + ok, {method: "POST", credentials: "same-origin"})
    .then(r => r.json()).then(d => { p.innerHTML = d.ok ? (ok ? "✅" : "❌") : "✗"; })
    .catch(() => { p.innerHTML = "✗"; });
}
</script>""")
    return make_response("\n".join(b))


@api.route("/app/maqsad/step/<int:sid>", methods=["POST"])
def app_maqsad_step_done(sid):
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False}), 200
    q("UPDATE goal_steps SET status='done', done_at=? WHERE id=?", (now_str(), sid))
    return jsonify({"ok": True}), 200


@api.route("/app/maqsad/daily/<int:did>/<int:ok>", methods=["POST"])
def app_maqsad_daily_mark(did, ok):
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False}), 200
    q("UPDATE goal_daily SET status=? WHERE id=?", ("done" if ok else "failed", did))
    return jsonify({"ok": True}), 200


NAK_MATCH_STATE = TDict()


def _run_nak_match(uid):
    """Ilovadan moslashtirishni ishga tushiradi.

    ⚠️ Mantiq TAKRORLANMAYDI: botning o'z `nak_callbacks` ishlovchisi chaqiriladi
    (soxta callback bilan). Shu tufayli xotira, katalog va AI moslashtirish
    aynan bir xil ishlaydi — ikki xil kod yuritish xatolarga olib kelardi.
    Natija botga xabar bo'lib boradi, ilova esa tayyor bo'lishini kutadi."""
    NAK_MATCH_STATE[uid] = {"msg": "Xotira va katalog tekshirilmoqda"}

    class _FakeUser:
        def __init__(self, i): self.id = i

    class _FakeMsg:
        def __init__(self, i):
            self.chat = _FakeUser(i)
            self.message_id = 0

    class _FakeCall:
        def __init__(self, i):
            self.data = "nak_match"
            self.from_user = _FakeUser(i)
            self.message = _FakeMsg(i)
            self.id = "app"

    try:
        nak_callbacks(_FakeCall(uid))
    except Exception as e:
        print("APP NAK MATCH ERR:", repr(e)[:200], flush=True)
        NAK_MATCH_STATE[uid] = {"error": str(e)[:150]}
        return

    # nak_callbacks fon oqimida ishlaydi — natijani kutamiz
    import time as _time
    for _ in range(180):                    # 6 daqiqagacha
        _time.sleep(2)
        st = nak_session_restore(uid) or W_NAK.get(uid) or {}
        if st.get("matches"):
            matched = sum(1 for m in st["matches"] if m and m.get("product_id"))
            NAK_MATCH_STATE[uid] = {"msg": f"{matched} ta mahsulot moslashtirildi"}
            ent = nak_webapp_load(uid)
            if ent and ent.get("token"):
                missing = len(st["matches"]) - matched
                # ⚠️ Topilmaganlar bo'lsa avval QO'LDA QIDIRISH sahifasiga o'tamiz —
                # aks holda ular tahrirlash oynasida bog'lanmagan holda qolib ketardi
                # va Bito'ga yuklashda muammo bo'lardi (amalda ko'rilgan).
                url = ("/app/nakladnoy/fix" if missing > 0
                       else f"/webapp/nakladnoy?uid={uid}&t={ent['token']}"
                            f"&v={int(_time.time()*1000)}")
                NAK_MATCH_STATE[uid] = {"done": True, "url": url}
                print(f"APP NAK: moslashtirish tugadi — {matched} ta mos, "
                      f"{missing} ta topilmadi", flush=True)
                return
    NAK_MATCH_STATE[uid] = {"error": "Moslashtirish juda uzoq davom etdi. "
                                     "Botdagi xabarlarni tekshiring."}


@api.route("/app/nakladnoy", methods=["GET"])
def app_nakladnoy():
    """📥 Nakladnoy — ilovadan rasm/fayl yuklash.

    Bot bilan bir xil zanjirni ishlatadi (nak_extract → moslashtirish →
    tahrirlash oynasi), lekin Telegram orqali emas, to'g'ridan-to'g'ri."""
    u = _dash_current_user()
    if not u:
        return make_response('<html><head><meta http-equiv="refresh" '
                             'content="0;url=/dashboard/login"></head></html>')
    body = """<h2>📥 Nakladnoy yuklash</h2>
<div class="card">
  <div class="lbl">Nakladnoy rasmini, PDF yoki Excel faylini tanlang.
  Rasm aniq va yorug' bo'lsin — mahsulot nomlari o'qilishi kerak.</div>
  <label class="pick" id="pick">
    <input type="file" id="f" accept="image/*,application/pdf,.xlsx,.xls" hidden
           onchange="go(this)">
    <span class="ic">📷</span>
    <span>Rasm olish yoki fayl tanlash</span>
  </label>
  <div id="st"></div>
</div>
<div class="muted">Yuklangandan keyin mahsulotlar Bito katalogidan
qidiriladi va tahrirlash oynasi ochiladi.</div>
<script>
function go(inp) {
  const file = inp.files && inp.files[0];
  if (!file) return;
  const st = document.getElementById("st");
  document.getElementById("pick").style.display = "none";
  st.innerHTML = '<div style="text-align:center;padding:26px 8px">'
    + '<div class="dots"><span></span><span></span><span></span></div>'
    + '<div style="margin-top:14px;font-weight:600">Nakladnoy o\\'qilmoqda</div>'
    + '<div class="lbl" id="tk" style="margin-top:6px">0 soniya</div>'
    + '<div class="lbl" style="margin-top:8px">30–60 soniya olishi mumkin</div></div>';
  let sec = 0;
  const tm = setInterval(() => { sec++;
    const e = document.getElementById("tk"); if (e) e.textContent = sec + " soniya"; }, 1000);
  const fd = new FormData();
  fd.append("file", file);
  fetch("/app/nakladnoy/upload", {method: "POST", body: fd, credentials: "same-origin"})
    .then(r => r.json())
    .then(d => {
      clearInterval(tm);
      if (d.ok && d.url) { location.href = d.url; return; }
      st.innerHTML = '<div class="card warn">⚠️ ' + (d.error || "O\\'qib bo\\'lmadi")
        + '</div><div style="margin-top:10px"><a href="">Qayta urinish</a></div>';
    })
    .catch(e => {
      clearInterval(tm);
      st.innerHTML = '<div class="card warn">⚠️ Tarmoq xatosi: ' + e.message
        + '</div><div style="margin-top:10px"><a href="">Qayta urinish</a></div>';
    });
}
</script>"""
    css = """  .pick { display: flex; flex-direction: column; align-items: center; gap: 10px;
      padding: 30px 16px; margin-top: 14px; border: 2px dashed #b9c2d0;
      border-radius: 16px; cursor: pointer; font-weight: 600; }
  .pick:active { background: #f1f4f9; }
  .pick .ic { font-size: 40px; }
"""
    return make_response(_app_page("Nakladnoy", body, css))


@api.route("/app/nakladnoy/upload", methods=["POST"])
def app_nakladnoy_upload():
    """Faylni qabul qilib, bot bilan BIR XIL zanjirdan o'tkazadi."""
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False, "error": "Sessiya tugagan"}), 200
    uid = u[0]
    f = request.files.get("file")
    if not f:
        return jsonify({"ok": False, "error": "Fayl kelmadi"}), 200
    raw = f.read()
    if not raw:
        return jsonify({"ok": False, "error": "Fayl bo'sh"}), 200
    if len(raw) > 20 * 1024 * 1024:
        return jsonify({"ok": False, "error": "Fayl juda katta (20MB dan ortiq)"}), 200

    name = (f.filename or "").lower()
    import base64
    try:
        if name.endswith((".xlsx", ".xls")):
            data, err = nak_extract(nak_excel_to_text(raw), is_text=True)
        elif name.endswith(".pdf"):
            blocks = [{"type": "document", "source": {"type": "base64",
                       "media_type": "application/pdf",
                       "data": base64.b64encode(raw).decode()}}]
            data, err = nak_extract(blocks)
        else:
            mt = "image/png" if name.endswith(".png") else "image/jpeg"
            blocks = [{"type": "image", "source": {"type": "base64",
                       "media_type": mt, "data": base64.b64encode(raw).decode()}}]
            data, err = nak_extract(blocks)
    except Exception as e:
        print("APP NAK UPLOAD ERR:", repr(e)[:200], flush=True)
        return jsonify({"ok": False, "error": str(e)[:150]}), 200

    if err or not data or not data.get("items"):
        return jsonify({"ok": False,
                        "error": err or "Mahsulotlar topilmadi. Aniqroq rasm yuboring."}), 200

    # Bot bilan bir xil holat — keyingi qadamlar o'zgarmaydi
    W_NAK[uid] = {"step": "confirm_supplier", **data}
    print(f"APP NAK: uid={uid} {len(data['items'])} ta mahsulot o'qildi", flush=True)
    st = W_NAK[uid]
    st["supplier_cands"] = _nak_supplier_search(st.get("supplier") or "")
    try:
        nak_session_save(uid)
    except Exception as e:
        print("APP NAK SAVE ERR:", str(e)[:150], flush=True)
    return jsonify({"ok": True, "url": "/app/nakladnoy/ok",
                    "count": len(data["items"])}), 200


@api.route("/app/nakladnoy/ok", methods=["GET"])
def app_nakladnoy_ok():
    """Firma tanlash — ilovada, botga o'tmasdan."""
    u = _dash_current_user()
    if not u:
        return make_response('<html><head><meta http-equiv="refresh" '
                             'content="0;url=/dashboard/login"></head></html>')
    uid = u[0]
    st = nak_session_restore(uid) or W_NAK.get(uid) or {}
    items = st.get("items") or []
    if not items:
        return make_response(_app_page("Nakladnoy",
            '<div class="card">Nakladnoy topilmadi — qaytadan yuklang.<br><br>'
            '<a href="/app/nakladnoy" style="font-weight:600;color:#2481cc;'
            'text-decoration:none">📥 Yuklash →</a></div>'))
    guess = st.get("supplier") or ""
    qtext = (request.args.get("q") or "").strip()
    if qtext:
        cands = _nak_supplier_search(qtext)
        guess = qtext
    else:
        cands = st.get("supplier_cands") or _nak_supplier_search(guess)
    st["supplier_cands"] = cands
    W_NAK[uid] = st
    nak_session_save(uid)

    b = [f'<h2>📥 {len(items)} ta mahsulot o\'qildi</h2>']
    b.append('<div class="card"><div class="lbl">Nakladnoyda o\'qilgan firma</div>'
             f'<div class="big">{h(guess) or "aniqlanmadi"}</div></div>')
    b.append('<div class="card"><div class="lbl" style="margin-bottom:8px">'
             'Bito ro\'yxatidan tasdiqlang:</div>')
    if cands:
        for i, c in enumerate(cands[:10]):
            b.append(f'<div class="row"><span>{h(c["name"])}</span>'
                     f'<span><button class="mini" onclick="pick({i},this)">'
                     f'Tanlash</button></span></div>')
    else:
        b.append('<div class="lbl">Hech narsa topilmadi.</div>')
    b.append('<div class="fld2"><input id="q" placeholder="Boshqa nom bilan qidirish...">'
             '<button class="mini" onclick="srch()">🔍</button></div></div>')
    b.append("""
<script>
function pick(i, el) {
  el.disabled = true; el.textContent = "…";
  fetch("/app/nakladnoy/supplier/" + i, {method: "POST", credentials: "same-origin"})
    .then(r => r.json())
    .then(d => { if (d.ok && d.url) location.href = d.url;
                 else { el.disabled = false; el.textContent = "Tanlash";
                        alert(d.error || "Xatolik"); } })
    .catch(e => { el.disabled = false; el.textContent = "Tanlash"; alert(e.message); });
}
function srch() {
  const v = document.getElementById("q").value.trim();
  if (!v) return;
  location.href = "/app/nakladnoy/ok?q=" + encodeURIComponent(v);
}
document.getElementById("q").addEventListener("keydown", e => {
  if (e.key === "Enter") srch();
});
</script>""")
    css = """  .fld2 { display: flex; gap: 8px; margin-top: 12px; }
  .fld2 input { flex: 1; padding: 10px; font-size: 15px; border: 1px solid #ccd2dc;
                border-radius: 8px; }
"""
    return make_response(_app_page("Firma tanlash", "\n".join(b), css))


@api.route("/app/nakladnoy/supplier/<int:idx>", methods=["POST"])
def app_nakladnoy_supplier(idx):
    """Firmani tasdiqlaydi va tahrirlash oynasiga o'tkazadi."""
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False, "error": "Sessiya tugagan"}), 200
    uid = u[0]
    st = nak_session_restore(uid) or W_NAK.get(uid)
    if not st:
        return jsonify({"ok": False, "error": "Nakladnoy topilmadi"}), 200
    cands = st.get("supplier_cands") or []
    if not cands:
        # 🛡 Nomzodlar sessiyada yo'q bo'lsa (deploy yoki kesh tozalangan) —
        # qaytadan qidiramiz, aks holda "Firma topilmadi" chiqib qolardi.
        cands = _nak_supplier_search(st.get("supplier") or "")
        st["supplier_cands"] = cands
    if idx >= len(cands):
        return jsonify({"ok": False, "error": "Firma topilmadi — sahifani yangilang"}), 200
    chosen = cands[idx]
    st["supplier_id"] = chosen["id"]
    st["supplier_confirmed_name"] = chosen["name"]
    nak_save_supplier_alias(st.get("supplier") or "", chosen["id"], chosen["name"])
    st["step"] = "review"
    W_NAK[uid] = st
    nak_session_save(uid)
    print(f"APP NAK: firma tanlandi — {chosen['name']}", flush=True)
    # ⚠️ MUHIM: to'g'ridan-to'g'ri tahrirlash oynasiga o'tmaymiz. Avval MOSLASHTIRISH
    # bosqichi bajarilishi kerak — aks holda mahsulotlar Bito katalogi bilan
    # bog'lanmay qoladi va nomlar hujjatdagidek ("70-Chortoq...") qolib ketadi
    # (amalda ko'rilgan). Moslashtirish botdagi bilan BIR XIL kod orqali ketadi.
    threading.Thread(target=lambda: _run_nak_match(uid), daemon=True).start()
