@api.route("/app/nakladnoy/search", methods=["GET"])
def app_nak_search():
    """Bito katalogidan mahsulot qidirish (ilova uchun)."""
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False, "error": "Sessiya tugagan"}), 200
    qtext = (request.args.get("q") or "").strip()
    if len(qtext) < 2:
        return jsonify({"ok": False, "error": "Kamida 2 harf"}), 200
    # ⚠️ Botdagi bilan BIR XIL funksiya ishlatiladi. Ilgari bito_search_products
    # chaqirilardi, u esa javobni bir qavatli o'qiydi va Bito'ning ikki qavatli
    # javobida (data.data) doim BO'SH qaytarardi (amalda ko'rilgan).
    try:
        res = _nak_search_products(qtext, limit=12) or []
    except Exception as e:
        print("APP NAK SEARCH ERR:", str(e)[:150], flush=True)
        return jsonify({"ok": False, "error": str(e)[:120]}), 200
    out = [{"id": p.get("id"), "name": (p.get("name") or "")[:70]}
           for p in res if p.get("id")]
    print(f"APP NAK SEARCH: '{qtext}' → {len(out)} ta", flush=True)
    return jsonify({"ok": True, "items": out}), 200


@api.route("/app/nakladnoy/fix/<int:idx>", methods=["POST"])
def app_nak_fix_set(idx):
    """Tanlangan mahsulotni qatorga biriktiradi va xotiraga yozadi."""
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False, "error": "Sessiya tugagan"}), 200
    uid = u[0]
    st = nak_session_restore(uid) or W_NAK.get(uid)
    if not st or not st.get("matches"):
        return jsonify({"ok": False, "error": "Sessiya topilmadi"}), 200
    data = request.get_json(force=True, silent=True) or {}
    pid = data.get("product_id")
    if not pid or idx >= len(st["matches"]):
        return jsonify({"ok": False, "error": "Noto'g'ri so'rov"}), 200
    # katalogdan nomni olamiz
    name = ""
    for p in (NAK_CATALOG_CACHE.get("products") or []):
        if p.get("id") == pid:
            name = p.get("name") or ""
            break
    it = st["items"][idx] if idx < len(st["items"]) else {}
    st["matches"][idx] = {"product_id": pid, "found_name": name or "?",
                          "item": it, "source": "app"}
    W_NAK[uid] = st
    nak_session_save(uid)
    try:
        # 🧠 Xotiraga yozamiz — keyingi safar avtomatik topiladi
        nak_save_alias(it.get("name") or "", pid, name or "?", it.get("price"),
                       block_size=it.get("block_size"), measure_id=it.get("measure_id"))
    except Exception as e:
        print("APP NAK ALIAS ERR:", str(e)[:120], flush=True)
    # tahrirlash oynasi ma'lumotini yangilaymiz
    try:
        ent = nak_webapp_load(uid) or {}
        if ent.get("token"):
            nak_webapp_store(uid, st["items"], ent["token"])
    except Exception:
        pass
    print(f"APP NAK FIX: {idx+1}-qator → {name}", flush=True)
    return jsonify({"ok": True}), 200


