@api.route("/app/zakaz/data", methods=["GET"])
def app_zakaz_data():
    u = _dash_current_user()
    if not u:
        return make_response("<div class='card warn'>Sessiya tugagan. "
                             "<a href='/dashboard/login'>Qayta kiring</a></div>")
    try:
        orders = order_recommendation()
        days, cal = cash_calendar(30)
        bal_by_day = {r["date"]: r["balance"] for r in days}
    except Exception as e:
        print("APP ZAKAZ ERR:", repr(e)[:200], flush=True)
        return make_response(f'<div class="card warn">⚠️ Xatolik: {h(str(e)[:200])}</div>')

    if not orders:
        return make_response(
            '<div class="card">Tavsiya chiqmadi.<br><br>'
            '• firmalarga kelish kunlari kiritilmagan, yoki<br>'
            '• mahsulotlar Bito\'da firmaga biriktirilmagan</div>')

    b = ['<h2>🛒 Zakaz tavsiyasi</h2>']
    for o in orders:
        bal = bal_by_day.get(o["date"], cal["cash"])
        hafta = WEEKDAY_NAMES[o["date"].weekday()]
        b.append(f'<div class="card"><b>🏢 {h(o["supplier"])}</b> — '
                 f'{o["date"].strftime("%d-%m")} ({hafta})<br>'
                 f'<span class="lbl">{o["cover"]} kunlik zaxira, '
                 f'{len(o["items"])} ta mahsulot</span>')
        for it in o["items"][:20]:
            un = it.get("unit") or "dona"
            b.append(f'<div class="row"><span>{h(it["name"])}<br>'
                     f'<span class="lbl">qoldiq {it["have"]} {un}, '
                     f'kuniga {it["rate"]}</span></span>'
                     f'<span><b>{it["qty"]} {un}</b><br>'
                     f'<span class="lbl">{fmt_money(it["sum"])}</span></span></div>')
        if len(o["items"]) > 20:
            b.append(f'<div class="lbl">... va yana {len(o["items"])-20} ta</div>')
        b.append(f'<div class="row"><b>Zakaz summasi</b>'
                 f'<b>{fmt_money(o["total"])}</b></div>')
        if o["scheme"] == "qarz almashish":
            b.append('<div class="row"><span>🔄 Qarz almashish — o\'sha kuni eski qarz '
                     f'to\'lanadi</span><span class="orange">'
                     f'{fmt_money(o["debt"])}</span></div>')
        elif o["scheme"] == "qarzga":
            b.append('<div class="row"><span>📝 Qarzga olinadi</span>'
                     '<span class="green">naqd kerak emas</span></div>')
            if o["pay_term"]:
                due = o["date"] + timedelta(days=int(o["pay_term"]))
                b.append(f'<div class="row"><span>📅 Qaytarish</span>'
                         f'<span>{due.strftime("%d-%m")}</span></div>')
        if o["cash_need"] > 0:
            cls = "red" if bal < o["cash_need"] else "green"
            b.append(f'<div class="row"><b>💰 Kerak bo\'lgan naqd</b>'
                     f'<b class="{cls}">{fmt_money(o["cash_need"])}</b></div>')
            if bal < o["cash_need"]:
                b.append(f'<div class="row red">O\'sha kuni kassada ~{fmt_money(bal)} '
                         f'bo\'ladi — {fmt_money(o["cash_need"] - bal)} kam</div>')
        b.append('</div>')
    b.append(f'<div class="card"><div class="row"><b>Jami zakaz</b>'
             f'<b>{fmt_money(sum(o["total"] for o in orders))}</b></div>'
             f'<div class="row"><b>Shundan naqd kerak</b>'
             f'<b>{fmt_money(sum(o["cash_need"] for o in orders))}</b></div></div>')
    b.append('<div class="muted">Miqdor oxirgi 30 kunlik sotuv tezligidan '
             'hisoblangan, ustiga 20% zaxira qo\'shilgan. Sotilmayotgan mahsulot '
             'zakazga kirmaydi.</div>')
    return make_response("\n".join(b))


