@api.route("/app/inventar/qidiruv", methods=["GET"])
def app_inventar_qidiruv():
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False, "err": "Sessiya tugagan"}), 200
    query = (request.args.get("q") or "").strip().lower()
    stock = INV_CACHE.get("stock") or []
    if not stock:
        return jsonify({"ok": False,
                        "err": "Kesh bo'sh — sahifani qayta oching"}), 200
    hits = sorted([p for p in stock if query in p["name"].lower()],
                  key=lambda p: -p["value"])[:8]
    return jsonify({"ok": True, "items": [
        {"id": p["id"], "name": p["name"], "amount": p["amount"],
         "unit": p["unit"]} for p in hits]}), 200


@api.route("/app/inventar/sanash", methods=["POST"])
def app_inventar_sanash():
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False, "err": "Sessiya tugagan"}), 200
    d = request.get_json(silent=True) or {}
    pid = d.get("product_id")
    try:
        counted = float(str(d.get("counted", "")).replace(",", "."))
        if counted < 0 or counted > 1_000_000:
            raise ValueError
    except ValueError:
        return jsonify({"ok": False, "err": "Son noto'g'ri"}), 200
    p = next((x for x in (INV_CACHE.get("stock") or []) if x["id"] == pid), None)
    if not p:
        return jsonify({"ok": False, "err": "Mahsulot keshda topilmadi"}), 200
    q("INSERT INTO inv_counts (product_id, name, unit, expected, cost, counted, counted_at) "
      "VALUES (?,?,?,?,?,?,?) "
      "ON CONFLICT(product_id) DO UPDATE SET "
      "expected=excluded.expected, cost=excluded.cost, "
      "counted=excluded.counted, counted_at=excluded.counted_at",
      (p["id"], p["name"], p["unit"], p["amount"], p["cost"],
       counted, now_dt().strftime("%Y-%m-%d %H:%M")))
    return jsonify({"ok": True}), 200


@api.route("/app/inventar/hisobot", methods=["GET"])
def app_inventar_hisobot():
    u = _dash_current_user()
    if not u:
        return make_response("")
    rows = qall("SELECT name, unit, expected, cost, counted "
                "FROM inv_counts ORDER BY ABS((counted-expected)*cost) DESC")
    if not rows:
        return make_response("")
    total = 0.0
    L = [f'<div class="card"><b>📋 Sanaldi: {len(rows)} ta</b>']
    for name, unit, exp, cost, cnt in rows:
        diff = (cnt or 0) - (exp or 0)
        total += diff * (cost or 0)
        mark = "✅" if abs(diff) < 0.001 else ("🔺" if diff > 0 else "🔻")
        cls = "green" if abs(diff) < 0.001 else ("orange" if diff > 0 else "red")
        L.append(f'<div class="row"><div style="flex:1">{mark} {h(name[:40])}'
                 f'<div class="lbl">Bito {exp:g} → sanaldi {cnt:g} {h(unit)}'
                 f'</div></div><b class="{cls}">'
                 f'{"+" if diff > 0 else ""}{diff:g}</b></div>')
    sign = "+" if total > 0 else ""
    L.append(f'<div class="row"><span>Jami farq</span>'
             f'<b>{sign}{inv_money(total)} so\'m</b></div>')
    L.append('<button class="mini" onclick="invYubor()" '
             'style="margin-top:8px">📤 Bito\'ga yozish</button>'
             '<button class="mini red2" onclick="invTozala()" '
             'style="margin-top:8px">🗑 Tozalash</button></div>')
    return make_response("".join(L))


@api.route("/app/inventar/yubor", methods=["POST"])
def app_inventar_yubor():
    """📤 Farqlarni Bito'ga yozish. confirm=false → oldindan ko'rish."""
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False, "err": "Sessiya tugagan"}), 200
    d = request.get_json(silent=True) or {}
    if not d.get("confirm"):
        ok, txt = inv_apply_confirm_text()
        if not ok:
            return jsonify({"ok": False, "err": txt}), 200
        plain = txt.replace("<b>", "").replace("</b>", "")
        return jsonify({"ok": True, "preview": plain}), 200
    try:
        res = inv_apply_to_bito()
    except Exception as e:
        print("APP INV YUBOR ERR:", repr(e)[:250], flush=True)
        return jsonify({"ok": False, "err": str(e)[:200]}), 200
    return jsonify({"ok": True, "result": res}), 200


@api.route("/app/inventar/tozalash", methods=["POST"])
def app_inventar_tozalash():
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False}), 200
    q("DELETE FROM inv_counts")
    return jsonify({"ok": True}), 200


