@api.route("/dashboard/refresh-advice", methods=["POST"])
def dashboard_refresh_advice():
    u = _dash_current_user()
    if not u:
        return jsonify({"ok": False, "error": "Sessiya tugagan"}), 401
    advice = regenerate_boss_advice()
    if advice:
        return jsonify({"ok": True})
    return jsonify({"ok": False, "error": "Ma'lumot yetarli emas yoki AI xatosi"}), 500

# ══════════════════════════════════════════════════════════════════
# 🏪 KO'P MIJOZ (multi-tenant) SOZLAMASI
# ══════════════════════════════════════════════════════════════════
# Bu bot har bir do'konga ALOHIDA deploy qilinadi. Quyidagi ID'lar esa har
# bir Bito tenantida boshqacha bo'ladi. Ilgari ular Bonnu Market qiymatlari
# bilan hardcode qilingan edi — yangi mijoz sozlamasa, bot jimgina noto'g'ri
# (mavjud bo'lmagan) ID'larga murojaat qilardi.
#
# Yechim: ishga tushganda ID'lar Bito'ning O'ZIDAN aniqlanadi. Faqat
# ISHLASHI TASDIQLANGAN endpointlar ishlatiladi (uom/get-all kabilari 404
# qaytargani uchun taxminiy manzillarga tayanmaymiz):
#   purchase/get-paging          → organization_id, currency_id, responsible_id
#   product-warehouse/get-paging → warehouse_id
#   product/get-paging           → o'lchov birliklari, Kilogram id, narx ro'yxati id
_TENANT_WARNED = TSet()


def tenant_setting(key, bonnu_default=""):
    """Sozlamani oladi. Bo'sh bo'lsa Bonnu qiymatiga qaytadi, LEKIN bu haqda
    bir marta ogohlantirish chiqaradi — boshqa mijozda bu xato bo'ladi."""
    v = get_setting(key, "")
    if v:
        return v
    if bonnu_default and key not in _TENANT_WARNED:
        _TENANT_WARNED.add(key)
        print(f"⚠️ TENANT: '{key}' sozlanmagan — Bonnu Market qiymati ishlatilyapti "
              f"({bonnu_default}). Boshqa do'konda bu XATO. /sozlama bilan tekshiring.",
              flush=True)
    return bonnu_default


def _bito_rows(payload):
    """Bito javobidan yozuvlar RO'YXATini ajratib oladi.

    ⚠️ Javob shakli endpointga qarab FARQ QILADI (jonli tekshirilgan, 2026-07-31):
      product/get-paging          → {"data": [ ... ]}            (bir qavat)
      purchase/get-paging         → {"data": {"data": [...], "total": N}}
      reports/.../credit/paging   → {"data": {"data": [...], "total": N}}
    Ilgari faqat bir qavatli shakl hisobga olingan edi va ikki qavatlilarda
    hech narsa topilmasdi — "sozlama aniqlanmadi" muammosining sababi shu.
    """
    d = payload.get("data") if isinstance(payload, dict) else payload
    for _ in range(3):                      # ehtiyot uchun chuqurlik chegarasi
        if isinstance(d, list):
            return [x for x in d if isinstance(x, dict)]
        if isinstance(d, dict) and "data" in d:
            d = d["data"]
            continue
        break
    return [d] if isinstance(d, dict) else []


def _bito_first(path, headers, body=None):
    """Berilgan endpointdan bitta yozuvni oladi (yo'q bo'lsa None)."""
    try:
        r = requests.post(BITO_BASE_URL + path,
                          json=body if body is not None else {"limit": 1, "page": 1},
                          headers=headers, timeout=20)
        if r.status_code != 200:
            print(f"TENANT: {path} → HTTP {r.status_code}: {(r.text or '')[:200]}", flush=True)
            return None
        rows = _bito_rows(r.json() or {})
        if not rows:
            print(f"TENANT: {path} → 200, lekin yozuv yo'q", flush=True)
            return None
        print(f"TENANT: {path} → 200, maydonlar: {sorted(rows[0].keys())[:25]}", flush=True)
        return rows[0]
    except Exception as e:
        print(f"TENANT: {path} → xato: {str(e)[:150]}", flush=True)
        return None
    except Exception as e:
        print(f"TENANT: {path} → xato: {str(e)[:150]}", flush=True)
        return None


def bito_autodetect_config():
    """Bito'dan tenant sozlamalarini aniqlab, bazaga yozadi.

    Faqat BO'SH sozlamalar to'ldiriladi — qo'lda kiritilganiga tegilmaydi.
    Qaytaradi: {kalit: (qiymat, manba)}"""
    headers = {"api-key": CFG.BITO_API_KEY, "Content-Type": "application/json"}
    found = {}

    def remember(key, val, src):
        if not val:
            print(f"TENANT: '{key}' topilmadi ({src})", flush=True)
            return
        found[key] = (val, src)
        if not get_setting(key, ""):
            set_setting(key, val)
            print(f"🏪 TENANT: {key} = {val}  ({src})", flush=True)

    def pick(doc, *names):
        """Bir nechta ehtimoliy maydon nomini sinaydi, ichma-ich lug'atni ham.
        ⚠️ Bito REST javobida nomlar MCP'dagidan farq qilishi mumkin."""
        if not isinstance(doc, dict):
            return None
        for n in names:
            v = doc.get(n)
            if isinstance(v, str) and v:
                return v
            if isinstance(v, dict) and v.get("_id"):
                return v["_id"]
        return None

    # 1) Oxirgi kirim hujjatidan — organizatsiya, valyuta, mas'ul
    pur = _bito_first("purchase/get-paging", headers,
                      {"limit": 1, "page": 1, "sort": "-created_at"})
    if pur:
        remember("bito_org_id",
                 pick(pur, "organization_id", "organization", "org_id"), "purchase")
        remember("bito_currency_id",
                 pick(pur, "currency_id", "currency"), "purchase")
        remember("bito_responsible_id",
                 pick(pur, "responsible_id", "responsible"), "purchase")

    # 2) Ombor
    pw = _bito_first("product-warehouse/get-paging", headers)
    if pw:
        remember("bito_warehouse_id",
                 pick(pw, "warehouse_id", "warehouse"), "product-warehouse")

    # 3) Mahsulotlardan — narx ro'yxati va o'lchov birliklari.
    #    ⚠️ uom/get-all 404 qaytaradi, shuning uchun birliklarni mahsulotlarning
    #    o'zidan yig'amiz — bu manba ishlashi tasdiqlangan.
    try:
        r = requests.post(BITO_BASE_URL + "product/get-paging",
                          json={"limit": 200, "page": 1}, headers=headers, timeout=30)
        items = _bito_rows(r.json() or {}) if r.status_code == 200 else []
    except Exception:
        items = []
    measures, price_id, plu_ids = {}, None, {}
    for p in items:
        if not isinstance(p, dict):
            continue          # ⚠️ Bito ba'zan ro'yxatda matn qaytaradi
        m = p.get("measure") or {}
        if not isinstance(m, dict):
            m = {}
        if m.get("_id") and m.get("name"):
            measures[m["_id"]] = m["name"]
        for o in (p.get("organizations") or []):
            for pr in (o.get("prices") or []):
                if not isinstance(pr, dict):
                    continue
                price_id = price_id or pick(pr, "price_id", "price", "_id")
        for cf in (p.get("custom_fields") or []):
            if cf.get("_id"):
                plu_ids[cf["_id"]] = plu_ids.get(cf["_id"], 0) + 1
    remember("bito_sale_price_id", price_id, "product/get-paging")
    if measures:
        # ⚠️ Bu faylda `re` modul darajasida import qilinmagan — mavjud kod
        # har funksiya ichida `import re as _re` qiladi. Shu uslubga amal
        # qilamiz, aks holda NameError chiqadi.
        import re as _re
        kg = [i for i, n in measures.items() if _re.search(r"kilo|kg", str(n), _re.I)]
        if kg:
            remember("bito_kg_measure_id", kg[0], "mahsulot o'lchov birliklari")
        dona = [i for i, n in measures.items() if _re.search(r"dona|шт|piece", str(n), _re.I)]
        if dona:
            remember("bito_default_uom_id", dona[0], "mahsulot o'lchov birliklari")
        try:
            import json as _j
            ms = [{"id": i, "name": n} for i, n in measures.items()]
            if not get_setting("bito_measures_json", ""):
                set_setting("bito_measures_json", _j.dumps(ms, ensure_ascii=False))
                print(f"🏪 TENANT: {len(ms)} ta o'lchov birligi aniqlandi", flush=True)
        except Exception:
            pass
    # PLU maydoni: mahsulotlarda faqat BITTA maxsus maydon uchrasa — o'sha PLU
    if len(plu_ids) == 1:
        remember("bito_plu_field_id", next(iter(plu_ids)), "mahsulot custom_fields")
    elif len(plu_ids) > 1:
        print(f"⚠️ TENANT: {len(plu_ids)} ta maxsus maydon topildi — PLU'ni qo'lda "
              f"tanlash kerak: {list(plu_ids)}", flush=True)
    _apply_tenant_globals()
    return found



def _apply_tenant_globals():
    """Eskirgan — sozlamalar endi markaziy bazadan (CFG) olinadi."""
    return None


@bot.message_handler(commands=['sozlama'])
def tenant_config_cmd(message):
    """🏪 Shu deploy qaysi Bito hisobiga ulanganini ko'rsatadi.
    Yangi mijozga o'rnatgandan keyin BIRINCHI tekshiriladigan narsa."""
    if message.from_user.id != CFG.SUPER_ADMIN_ID:
        return
    chat_id = message.chat.id

    def run():
        bot.send_message(chat_id, "⏳ Bito sozlamalari aniqlanmoqda...")
        found = bito_autodetect_config()
        BONNU = {"bito_org_id": "693fea06ff2118868c955b6c",
                 "bito_warehouse_id": "69424f36a3a3cc43da908320",
                 "bito_currency_id": "69424f34f461a9f6fd61972d",
                 "bito_sale_price_id": "694250a9c9b42022084696f6",
                 "bito_plu_field_id": "69426b2ec75f38c3f5d9e91e",
                 "bito_kg_measure_id": "693fea08ff2118868c955d18"}
        out = ["🏪 <b>Bito sozlamalari</b>", ""]
        risk = 0
        for k, bonnu in BONNU.items():
            cur = get_setting(k, "") or "—"
            src = found.get(k, (None, "bazadan"))[1]
            mark = "✅"
            if cur == "—":
                mark, risk = "❌", risk + 1
            elif cur == bonnu and k != "bito_org_id":
                mark = "⚠️"
            out.append(f"{mark} <code>{k}</code>\n   {cur} <i>({src})</i>")
        out.append("")
        if get_setting("bito_org_id", "") == BONNU["bito_org_id"]:
            out.append("🏪 Do'kon: <b>Bonnu Market</b> (asl nusxa)")
        else:
            out.append("🏪 Do'kon: <b>yangi mijoz</b>")
            same = [k for k, v in BONNU.items() if get_setting(k, "") == v]
            if same:
                out.append(f"⚠️ <b>{len(same)} ta sozlama hali ham Bonnu qiymatida!</b> "
                           f"Bu ishlamaydi: {', '.join(same)}")
        if risk:
            out.append(f"❌ {risk} ta sozlama aniqlanmadi — Bito'da ma'lumot yo'q "
                       f"yoki API kalitida ruxsat yetarli emas.")
        send_long_message(chat_id, "\n".join(out), parse_mode="HTML")
    threading.Thread(target=run, daemon=True).start()


def run_api_server():
    port = int(os.getenv("PORT", "8080"))
    try:
        from waitress import serve
        serve(api, host="0.0.0.0", port=port)
    except ImportError:
        api.run(host="0.0.0.0", port=port)

def _build_banner():
    """🧩 Ishga tushishda QAYSI versiya ishlayotganini logga yozadi.

    Sabab: bir necha marta 'buyruq javob bermayapti' holati bo'ldi va deploy
    eskimi yoki kodda xatomi — ajratib bo'lmadi. Endi log o'zi aytadi:
    ro'yxatdan o'tgan buyruqlar va fayl nusxasi (sha) ko'rsatiladi."""
    try:
        import hashlib
        try:
            with open(__file__, "rb") as fh:
                sha = hashlib.sha256(fh.read()).hexdigest()[:10]
        except Exception:
            sha = "?"
        # Qaysi buyruqlar HAQIQATAN ro'yxatdan o'tganini o'qiymiz
        want = ["firmalar", "pul", "maqsad", "bugun", "inv_test", "inventar"]
        handlers = getattr(bot, "message_handlers", None)
        if not isinstance(handlers, list):
            handlers = []
        live = set()
        for h in handlers:
            if not isinstance(h, dict):
                continue
            filt = h.get("filters")
            if not isinstance(filt, dict):
                continue
            for f in filt.values():
                if isinstance(f, (list, tuple, set)):
                    for c in f:
                        if isinstance(c, str):
                            live.add(c)
        have = [c for c in want if c in live]
        miss = [c for c in want if c not in live]
        print(f"🧩 BUILD sha={sha} | handlerlar={len(handlers)}", flush=True)
        print(f"🧩 Buyruqlar BOR: {', '.join('/' + c for c in have) or '—'}", flush=True)
        if miss:
            print(f"🧩 Buyruqlar YO'Q: {', '.join('/' + c for c in miss)} "
                  f"← eski build deploy qilingan bo'lishi mumkin", flush=True)
    except Exception as e:
        print("BUILD BANNER ERR:", str(e)[:150], flush=True)


_build_banner()

_boot_thread(run_api_server)

# 🏪 Tenant sozlamalarini ishga tushishda aniqlaymiz. Fon rejimida —
# botning ishga tushishini kechiktirmasligi uchun.
def _tenant_boot():
    try:
        time.sleep(2)  # baza tayyor bo'lsin
        bito_autodetect_config()
    except Exception as e:
        print("TENANT AUTODETECT ERR:", str(e)[:200], flush=True)
_boot_thread(_tenant_boot)
